window.__D("text/zohar-hebrew-translation/c029",{"p":[[9522012233,"<p>וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר אִישׁ אִישׁ כִּי יְקַלֵּל אֱלֹהָיו וְנָשָׂא חֶטְאוֹ. רַבִּי יְהוּדָה אָמַר, הֲרֵי פֵּרְשׁוּהָ, אֲבָל כִּי יְקַלֵּל אֱלֹהָיו סָתוּם. וּמִשּׁוּם שֶׁאָמַר אֱלֹהָיו סְתָם, לְכָךְ וְנָשָׂא חֶטְאוֹ. שֶׁהֲרֵי אֵין יוֹדְעִים מִי הוּא אֱלֹהָיו, מִי הַיִּרְאָה שֶׁלּוֹ, אִם אֶחָד מִן הַשָּׂרִים, אוֹ אֶחָד מִן הַכּוֹכָבִים, אוֹ אֶחָד מִמַּנְהִיגֵי הָעוֹלָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אִם הוּא צַדִּיק גָּמוּר, לֹא יְעוֹרֵר (דבר) אֶת הַכֹּחַ שֶׁלָּהֶם, וְכֵיוָן שֶׁעוֹרֵר הַדָּבָר הַזֶּה, חוֹשְׁשִׁים שֶׁנִּזְרְקָה בּוֹ מִינוּת, וְלֹא יָמוּת (אמר רבי יוסי, אפלו צדיק גמור לא ימות) עַל זֶה, מִשּׁוּם שֶׁהוּא דָּבָר סָתוּם.</p>\n<p>רַבִּי יְהוּדָה אָמַר, דָּנִים אוֹתוֹ לְטוֹב בָּזֶה, שֶׁאִם אָמַר אֱלֹהַי, יָכוֹל לִטְעֹן: אֱלֹהַי שֶׁהָיָה עַד עַכְשָׁו, שֶׁנִּמְשַׁכְתִּי אַחֲרָיו בְּלִבִּי, וְעַכְשָׁו חָזַרְתִּי כְּנֶגֶד הָאֱמוּנָה הָעֶלְיוֹנָה. אֲבָל אִם אָמַר יְיָ אֱלֹהִים, אוֹ יְיָ, וְנָקַב אוֹתוֹ בִּשְׁמוֹ - לָזֶה אֵין לִטְעֹן בָּזֶה, מִשּׁוּם שֶׁזּוֹהִי אֱמוּנַת הַכֹּל, וְכָל אוֹת וְאוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ הַזֶּה עוֹלֶה לַשֵּׁם הַשָּׁלֵם (לשבח).</p>\n<p>דָּבָר אַחֵר וַיִּקֹּב בֶּן הָאִשָּׁה הַיִּשְׂרְאֵלִית אֶת הַשֵּׁם וַיְקַלֵּל - רַבִּי יִצְחָק אָמַר, וַיִּקֹּב בֶּן הָאִשָּׁה, לָמָּה? אֶלָּא כְּמוֹ שֶׁבֵּאֲרוּהָ. אֲבָל הָאִישׁ הַיִּשְׂרְאֵלִי, בַּעְלָהּ שֶׁל שְׁלוֹמִית הָיָה. רַבִּי יְהוּדָה אָמַר, בְּנוֹ שֶׁל בַּעְלָהּ שֶׁל שְׁלוֹמִית מֵאִשָּׁה אַחֶרֶת הָיָה. אָמַר רַבִּי יִצְחָק, רָבוּ כְאֶחָד, וְאָמַר לוֹ דָּבָר עַל אִמּוֹ, וְכִי אָבִיו הָיָה שֶׁנֶּהֱרַג בַּשֵּׁם הַקָּדוֹשׁ, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁכָּתוּב (שמות ב) הַלְהָרְגֵנִי אַתָּה אֹמֵר, שֶׁזֶּה בַּשֵּׁם הַקָּדוֹשׁ הָרַג אוֹתוֹ מֹשֶׁה, וְעַל כֵּן הוֹשִׁיט דִּבּוּר כְּנֶגְדּוֹ.</p>\n<p>וְזְהִוּ שֶׁכָּתוּב, וַיִּקֹּב בֶּן הָאִשָּׁה הַיִּשְׂרְאֵלִית אֶת הַשֵּׁם וַיְקַלֵּל וַיָּבִיאוּ אֹתוֹ אֶל מֹשֶׁה. לָמָּה? (אל משה, ' משום שהרג את אביו וכו') מִשּׁוּם שֶׁהִגִּיעַ אֶל מֹשֶׁה עַל שֶׁהָרַג אֶת אָבִיו בַּשֵּׁם הַקָּדוֹשׁ. מִשּׁוּם כָּךְ וַיָּבִיאוּ אֹתוֹ אֶל מֹשֶׁה. כֵּיוָן שֶׁרָאָה מֹשֶׁה, מִיָּד וַיַּנִּיחֻהוּ בַּמִּשְׁמָר, וְהָאָב וְהַבֵּן נָפְלוּ בִּידֵי מֹשֶׁה.</p>\n<p>אִישׁ אִישׁ כִּי יְקַלֵּל אֱלֹהָיו וְנָשָׂא חֶטְאוֹ. רַבִּי יִצְחָק פָּתַח, (תהלים פא) שְׁמַע עַמִּי וְאָעִידָה בָּךְ יִשְׂרָאֵל אִם תִּשְׁמַע לִי לֹא יִהְיֶה בְךְ אֵל זָר וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר. כֵּיוָן שֶׁכָּתוּב לֹא יִהְיֶה בְךְ אֵל זָר, מַה זֶּה וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר? אֶלָּא לֹא יִהְיֶה בְךְ אֵל זָר, שֶׁלֹּא יַכְנִיס אָדָם אֶת הַיֵּצֶר הָרָע לְתוֹכוֹ. שֶׁכָּל מִי שֶׁבָּא לְהִתְחַבֵּר עִמּוֹ, אֵל זָר שָׁרוּי בְּתוֹכוֹ, שֶׁהֲרֵי כְּשֶׁמִּתְחַבֵּר בּוֹ אָדָם, מִיָּד בָּא לַעֲבֹר עַל דִּבְרֵי תוֹרָה, וּבָא לַעֲבֹר עַל אֱמוּנַת הַשֵּׁם הַקָּדוֹשׁ, וּבָא אַחַר כָּךְ לְהִשְׁתַּחֲווֹת לֶאֱלִילִים אֲחֵרִים, וְעַל זֶה כָּתוּב לֹא יִהְיֶה בְךְ אֵל זָר. כֵּיוָן שֶׁלֹּא יִהְיֶה בְךְ אֵל זָר, לֹא תָבֹא לְהִשְׁתַּחֲווֹת לֶאֱלִילִים אֲחֵרִים וְלַעֲבֹר עַל אֱמוּנַת הַשֵּׁם הַקָּדוֹשׁ. זֶהוּ שֶׁכָּתוּב וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר, וְזוֹהִי אֱמוּנָה רָעָה שֶׁל הָאָדָם.</p>\n<p>וְעַל זֶה, כִּי יְקַלֵּל אֱלֹהָיו, שֶׁיָּכוֹל לִטְעֹן שֶׁהוּא קִלֵּל אֶת אוֹתוֹ אֵל זָר, יֵצֶר הָרָע שֶׁלִּפְעָמִים שׁוֹרֶה עָלָיו, וְאָנוּ אֵינֶנּוּ יוֹדְעִים אִם דְּבָרָיו אֱמֶת אוֹ לֹא. וְעַל זֶה, וְנָשָׂא חֶטְאוֹ. אֲבָל וְנֹקֵב שֵׁם ה' מוֹת יוּמָת.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, לָמָּה וְנָשָׂא חֶטְאוֹ? וְנִסְלַח חֶטְאוֹ הָיָה צָרִיךְ לִהְיוֹת! (אלא) אָמַר לוֹ, כְּמוֹ שֶׁאָמַר אֱלֹהַי, כְּמוֹ שֶׁבֵּאַרְנוּ סְתָם, וְלֹא פֵרַשׁ. רַבִּי חִיָּיא אָמַר, כִּי יְקַלֵּל אֱלֹהָיו סְתָם, וְלֹא פֵרַשׁ, וְזֶה וַדַּאי וְנָשָׂא חֶטְאוֹ. אֲבָל וְנֹקֵב שֵׁם ה' מוֹת יוּמָת, שֶׁהֲרֵי כָּאן תְּלוּיָה אֱמוּנַת הַכֹּל, וְאֵין לוֹ רְשׁוּת לִטְעֹן עָלָיו כְּלָל.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּךְ זֶה וַדַּאי, שֶׁהֲרֵי הַשֵּׁם הַזֶּה הִנּוֹ אֱמוּנַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וְעַל זֶה עוֹמְדִים כָּל הָעוֹלָמוֹת, בְּאוֹת זְעִירָה אַחַת תְּלוּיִים אֶלֶף אֲלָפִים וְרִבּוֹא רִבְבוֹת עוֹלָמוֹת שֶׁל תְּשׁוּקוֹת, וְעַל זֶה שָׁנִינוּ, הָאוֹתִיּוֹת הַלָּלוּ קְשׁוּרוֹת אֵלּוּ בְאֵלּוּ, וְכַמָּה אֶלֶף רְבָבוֹת עֶלְיוֹנִים (עולמות) תְּלוּיִים בְּכָל אוֹת וָאוֹת, וְעוֹלוֹת וְנִקְשָׁרוֹת בָּאֱמוּנָה (בגלוי), וְנִסְתָּר בָּהֶם מַה שֶּׁלֹּא הִשִּׂיגוּ הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, הַתּוֹרָה תְלוּיָה בָהֶם, הָעוֹלָם הַזֶּה וְהָעוֹלָם הַבָּא, הוּא וּשְׁמוֹ אֶחָד. וְעַל כֵּן כָּתוּב, (תהלים לט) אָמַרְתִּי אֶשְׁמְרָה דְרָכַי מֵחֲטוֹא בִלְשׁוֹנִי. וְכָתוּב, (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ.</p>\n<p>רַבִּי חִזְקִיָּה פָּתַח, (שמותיט) לֹא תִגַּע בּוֹ יָד כִּי סָקוֹל יִסָּקֵל אוֹ יָרֹה יִיָּרֶה אִם בְּהֵמָה אִם אִישׁ לֹא יִחְיֶה בִּמְשֹׁךְ הַיֹּבֵל. וּמַה הַר סִינַי, שֶׁהוּא הַר כִּשְׁאָר הָרֵי הָעוֹלָם, מִשּׁוּם שֶׁנִּרְאָה עָלָיו כְּבוֹד הַמֶּלֶךְ הַקָּדוֹשׁ כָּתוּב לֹא תִגַּע בּוֹ יָד כִּי סָקוֹל יִסָּקֵל אוֹ יָרֹה יִיָּרֶה - מִי שֶׁקָּרֵב לַמֶּלֶךְ לֹא כָּל שֶׁכֵּן. וּמַה הַר סִינַי, שֶׁיָּכוֹל אָדָם לְהוֹשִׁיט בּוֹ יָד דֶּרֶךְ כָּבוֹד בְּיִרְאָה, כָּתוּבּ בּוֹ לֹא תִגַּע בּוֹ יָד סְתָם, וַאֲפִלּוּ בְּדֶרֶךְ כָּבוֹד - מִי שֶׁמּוֹשִׁיט יָדוֹ בְּדֶרֶךְ קָלוֹן כְּנֶגֶד הַמֶּלֶךְ לֹא כָּל שֶׁכֵּן.</p>\n<p>רַבִּי יֵיסָא פָּתַח וְאָמַר, (שם ג) אַל תִּקְרַב הֲלֹם שַׁל נְעָלֶיךְ מֵעַל רַגְלֶיךְ כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא. וּמַה מֹּשֶׁה, מִיּוֹם שֶׁנּוֹלַד, לֹא סָר מִמֶּנּוּ הַזֹּהַר הַקָּדוֹשׁ הָעֶלְיוֹן, כָּתוּב בּוֹ אַל תִּקְרַב הֲלֹם. אָמַר לוֹ, מֹשֶׁה, עַד כָּאן אֵינְךְ כְּדַאי לְהִשְׁתַּמֵּשׁ בִּכְבוֹדִי שַׁל נְעָלֶיךְ. וּמַה מֹּשֶׁה כָּךְ, שֶׁהָיָה מִתְקָרֵב בְּיִרְאָה בִּקְדֻשָּׁה כָּתוּב בּוֹ כָּךְ - מִי שֶׁקָּרֵב בְּאֹרַח שֶׁל קָלוֹן אֶל הַמֶּלֶךְ עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>רַבִּי אַבָּא אָמַר, אִישׁ אִישׁ כִּי יְקַלֵּל אֱלֹהָיו וְנָשָׂא חֶטְאוֹ. בֹּא רְאֵה, כְּשֶׁהָיוּ יִשְׂרָאֵל בְּמִצְרַיִם, הָיוּ מַכִּירִים אֶת אוֹתָם הַגְּדוֹלִים שֶׁל הָעוֹלָם שֶׁמְּמֻנִּים עַל שְׁאָר הָעַמִּים, וּלְכָל אֶחָד וְאֶחָד הָיָה לוֹ פַּחַד לְבַדּוֹ מֵהֶם. כֵּיוָן שֶׁנִּקְשְׁרוּ בְּקֶשֶׁר הָאֱמוּנָה, וְקֵרַב אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲבוֹדָתוֹ, נִפְרְדוּ מֵהֶם וְקָרְבוּ לָאֱמוּנָה הָעֶלְיוֹנָה הַקְּדוֹשָׁה. וּמִשּׁוּם כָּךְ כָּתוּב אִישׁ אִישׁ כִּי יְקַלֵּל אֱלֹהָיו, וְאַף עַל גַּב שֶׁזּוֹהִי עֲבוֹדָה זָרָה, כֵּיוָן שֶׁאֲנִי הִפְקַדְתִּי לָהֶם מְמֻנֶּה לְהַנְהִיג אֶת הָעוֹלָם, מִי שֶׁמְּקַלֵּל וּמְבַזֶּה אוֹתָם, וַדַּאי וְנָשָׂא חֶטְאוֹ, שֶׁהֲרֵי בִּרְשׁוּתִי עוֹמְדִים וְהוֹלְכִים וּמַנְהִיגִים אֶת בְּנֵי הָעוֹלָם. אֲבָל וְנֹקֵב שֵׁם ה' מוֹת יוּמָת, לֹא וְנָשָׂא חֶטְאוֹ כְּמוֹ לְאֵלּוּ, אֶלָּא מוֹת יוּמָת. מוֹת בָּעוֹלָם הַזֶּה, יוּמָת בָּעוֹלָם הבָּא. לְאֵלֶּה וְנָשָׂא חֶטְאוֹ, מִשּׁוּם שֶׁמְּבַזֶּה מַעֲשֵׂי יָדָיו, מְבַזֶּה אֶת הַשַּׁמָּשִׁים שֶׁלִּי שֶׁאֲנִי הִפְקַדְתִּי, וְאָסוּר הוּא, אֲבָל מִיתָה לֹא הִתְחַיְּבָה בָהֶם.</p>\n<p>רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיוּ עִמּוֹ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְרַבִּי חִיָּיא וְרַבִּי יוֹסֵי וְרַבִּי יְהוּדָה. הִגִּיעוּ לְחָרִיץ מַיִם אֶחָד. הֶחֱלִיק רַבִּי יוֹסֵי בִּבְגָדָיו לְתוֹךְ הַמַּיִם, אָמַר, הַלְוַאי שֶׁחֲרִיצֵי הַמַּיִם לֹא הָיוּ נִמְצָאִים. אָמַר לוֹ רַבִּי שִׁמְעוֹן, אָסוּר לְךְ! שַׁמָּשׁ שֶׁל הָעוֹלָם הוּא, וְאָסוּר לִנְהֹג קָלוֹן בְּשַׁמָּשׁוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל שֶׁכֵּן כְּשֶׁהֵם מַעֲשִׂים שֶׁל אֱמֶת שֶׁנִּמְצָאִים בְּהַנְהָגוֹת הַהַשְׁגָּחָה הָעֶלְיוֹנָה.</p>\n<p>פָּתַח וְאָמַר, (בראשיתא) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה - סְתָם, אֲפִלּוּ נְחָשִׁים וְעַקְרַבִּים וְיַתּוּשִׁים, וַאֲפִלּוּ אוֹתָם שֶׁנִּרְאִים מְחַבְּלֵי הָעוֹלָם, בְּכֻלָּם כָּתוּב וְהִנֵּה טוֹב מְאֹד, כֻּלָּם שַׁמָּשֵׁי הָעוֹלָם, מַנְהִיגֵי הָעוֹלָם, וּבְנֵי אָדָם אֵין יוֹדְעִים.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ נָחָשׁ אֶחָד הוֹלֵךְ לִפְנֵיהֶם. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי זֶה הוֹלֵךְ לְהַרְחִישׁ לָנוּ נֵס. רָץ אוֹתוֹ נָחָשׁ לִפְנֵיהֶם וְנִקְשַׁר בְּאֶפְעֶה אֶחָד בְּקֶשֶׁר הַדֶּרֶךְ, הֵסִיטוּ (נלחמו) זֶה אֶת זֶה וּמֵתוּ. כְּשֶׁהִגִּיעוּ, רָאוּ אֶת שְׁנֵיהֶם שׁוֹכְבִים בַּדֶּרֶךְ. אָמַר רַבִּי שִׁמְעוֹן, בָּרוּךְ הָרַחֲמָן שֶׁהִרְחִישׁ לָנוּ נֵס, שֶׁהֲרֵי כָּל מִי שֶׁמִּסְתַּכֵּל בָּזֶה כְּשֶׁהוּא בְּקִיּוּמוֹ, אוֹ שֶׁהוּא מִסְתַּכֵּל בָּאָדָם, לֹא יִנָּצֵל בְּוַדַּאי. כָּל שֶׁכֵּן אִם יִקְרַב אֵלָיו. קָרָא עָלָיו, (תהלים צא) לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. וּבַכֹּל עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת שְׁלִיחוּתוֹ, וְאֵין לָנוּ לִנְהֹג בִּזָּיוֹן בְּכָל מַה שֶּׁהוּא עוֹשֶׂה. וְעַל זֶה כָּתוּב, (שם קמה) טוֹב ה' לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו, וְכָתוּב, יוֹדוּךְ ה' כָּל מַעֲשֶׂיךְ.</p>"],[9522012234,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (שיר ב) אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן שׁוֹשַׁנַּת הָעֲמָקִים. כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ אוֹתָהּ, וְהִיא מְשַׁבַּחַת אוֹתוֹ תָּמִיד. וְכַמָּה שְׁבָחִים וּזְמִירוֹת מַתְקִינָה לַמֶּלֶךְ תָּמִיד. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁאֲחוּזִים בְּגוֹרַל הַחֵלֶק הַקָּדוֹשׁ, כַּכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת חֲבַצֶּלֶת, שֶׁעוֹמֶדֶת בְּיֹפִי שֶׁל נוֹי בְּגַן עֵדֶן לְהִנָּטֵעַ. הַשָּׁרוֹן, שֶׁהִיא (שומרת נ\"א שרה) וּמְשַׁבַּחַת אֶת הַמֶּלֶךְ הָעֶלְיוֹן. דָּבָר אַחֵר אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן - שֶׁצְּרִיכָה לִהְיוֹת מֻשְׁקָה מֵהַשְׁקָאַת הַנַּחַל הֶעָמֹק, מַעְיַן הַנְּחָלִים, כְּמוֹ שֶׁנֶּאֱמַר הָיָה הַשָּׁרוֹן (כערבה). (לאגם מים) שׁוֹשַׁנַּת הָעֲמָקִים, שֶׁעוֹמֵד בָּעֹמֶק שֶׁל הַכֹּל.</p>\n<p>שׁוֹשַׁנַּת הָעֲמָקִים, מִי הֵם הָעֲמָקִים? כְּמוֹ שֶׁנֶּאֱמַר (תהלים קל) מִמַּעֲמַקִּים קְרָאתִיךְ ה'. חֲבַצֶּלֶת הַשָּׁרוֹן, מֵאוֹתוֹ מָקוֹם שֶׁהַשְׁקָאַת הַנְּחָלִים הָעֲמֻקִּים יוֹצְאִים וְלֹא פוֹסְקִים לְעוֹלָמִים. שׁוֹשַׁנַּת הָעֲמָקִים, הַשּׁוֹשַׁנָּה שֶׁל אוֹתוֹ מָקוֹם שֶׁנִּקְרָא עֹמֶק הַכֹּל, נִסְתָּר מִכָּל הַצְּדָדִים.</p>\n<p>בֹּא רְאֵה, בָּרִאשׁוֹנָה חֲבַצֶּלֶת יְרֻקָּה עִם עָלִים יְרֻקִּים, אַחַר כָּךְ שׁוֹשַׁנָּה בִּשְׁנֵי גְוָנִים - אָדם וְלָבָן. שׁוֹשַׁנַּת - בְּשִׁשָּׁה עָלִים. שׁוֹשַׁנַּת - שֶׁשִּׁנְּתָה אֶת גְּוָנֶיהָ, וּמִשְׁתַּנָּה מִגָּוֶן לְגָוֶן. שׁוֹשַׁנַּת, בָּרִאשׁוֹנָה חֲבַצֶּלֶת. בִּזְמַן שֶׁרוֹצָה לְהִזְדַּוֵּג עִם הַמֶּלֶךְ, נִקְרֵאת חֲבַצֶּלֶת. אַחַר שֶׁנִּדְבְּקָה עִם הַמֶּלֶךְ עִם אוֹתָן נְשִׁיקוֹת, נִקְרֵאת שׁוֹשַׁנָּה, מִשּׁוּם שֶׁכָּתוּב (שיר ה) שִׂפְתוֹתָיו שׁוֹשַׁנִּים. שׁוֹשַׁנַּת הָעֲמָקִים. שֶׁהִיא מִשְׁתַּנָּה וּמְשַׁנָּה אֶת גְּוָנֶיהָ, לִפְעָמִים לְטוֹב, וְלִפְעָמִים לְרָע. לִפְעָמִים לְדִין, וְלִפְעָמִים לְרַחֲמִים.</p>"],[9522012235,"<p>וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעֵינַיִם וְגוֹ' (בראשית ב). בֹּא רְאֵה, שֶׁהֲרֵי בְּנֵי אָדָם לֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים וְלֹא מַשְׁגִּיחִים, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם וְכִבֵּד אוֹתוֹ בְּכָבוֹד עֶלְיוֹן, רָצָה מִמֶּנּוּ לְהִדָּבֵק בּוֹ, כְּדֵי שֶׁיִּמָּצֵא יְחִידִי, וּבַלֵּב יְחִידִי, וּבְמָקוֹם שֶׁל דְּבֵקוּת יְחִידָה, שֶׁלֹּא יִשְׁתַּנֶּה וְלֹא יִתְהַפֵּךְ לְעוֹלָמִים בְּאוֹתוֹ קֶשֶׁר הָאֱמוּנָה הַיְחִידָה, שֶׁהַכֹּל נִקְשָׁר בּוֹ. זֶהוּ שֶׁכָּתוּב וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן.</p>\n<p>וְאַחַר כָּךְ סָטוּ מִדֶּרֶךְ הָאֱמוּנָה, וְעָזְבוּ אֶת הָעֵץ הַיָּחִיד הָעֶלְיוֹן מִכָּל הָעֵצִים, וּבָאוּ לְהִדָּבֵק בְּמָקוֹם שֶׁמִּשְׁתַּנֶּה וּמִתְהַפֵּךְ מִגָּוֶן לְגָוֶן, וּמִטּוֹב לְרָע, וּמֵרָע לְטוֹב, וְיָרְדוּ מִמַּעְלָה לְמַטָּה, וְנִדְבְּקוּ לְמַטָּה בְּשִׁנּוּיִים רַבִּים, וְעָזְבוּ אֶת הָעֶלְיוֹן שֶׁל הַכֹּל, שֶׁהוּא אֶחָד, וְלֹא מִשְׁתַּנֶּה לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (קהלת ז) אֲשֶׁר עָשָׂה הָאֱלֹהִים אֶת הָאָדָם יָשָׁר וְהֵמָּה בִקְשׁוּ חִשְּׁבנוֹת רַבִּים. וְהֵמָּה בִקְשׁוּ חִשְּׁבֹנוֹת רַבִּים וַדַּאי, אָז הִתְהַפֵּךְ לִבָּם לְאוֹתוֹ צַד מַמָּשׁ, לִפְעָמִים לְטוֹב, לִפְעָמִים לְרָע, לִפְעָמִים לְרַחֲמִים, לִפְעָמִים לְדִין. כְּמוֹ אוֹתוֹ הַדָּבָר שֶׁנִּדְבְּקוּ בוֹ וַדַּאי. וְהֵמָּה בִקְשׁוּ חִשְּׁבֹנוֹת רַבִּים, וְנִדְבְּקוּ בָהֶם.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אָדָם, עָזַבְתָּ אֶת הַחַיִּים וְדָבַקְתָּ בַּמָּוֶת. חַיִּים, שֶׁכָּתוּב וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן, הָעֵץ שֶׁנִּקְרָא חַיִּים, שֶׁמִּי שֶׁאוֹחֵז בּוֹ לֹא טוֹעֵם טַעַם הַמָּוֶת לְעוֹלָמִים, וְנִדְבַּקְתָּ בְּעֵץ אַחֵר - הֲרֵי וַדַּאי מָוֶת הוּא כְּנֶגְדְּךְ. זֶהוּ שֶׁכָּתוּב (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת וְגוֹ'. וְכָתוּב (קהלת ז) וּמוֹצֶא אֲנִי מַר מִמָּוֶת אֶת הָאִשָּׁה. וַדַּאי שֶׁנִּדְבַּק לְמָקוֹם שֶׁל מָוֶת, וְעָזַב אֶת הַמָּקוֹם שֶׁל חַיִּים, מִשּׁוּם כָּךְ נִגְזַר עָלָיו וְעַל כָּל הָעוֹלָם מָוֶת.</p>\n<p>אִם הוּא חָטָא, מֶה חָטְאוּ כָּל הָעוֹלָם? אִם תֹּאמר שֶׁכָּל הַבְּרִיּוֹת בָּאוּ וְאָכְלוּ מֵהָעֵץ הַזֶּה וְנִלְקַח מִכֻּלָּם - לֹא כָּךְ. אֶלָּא בְּשָׁעָה שֶׁאָדָם עָמַד עַל רַגְלָיו, רָאוּ אוֹתוֹ כָּל הַבְּרִיּוֹת וּפָחֲדוּ מִפָּנָיו, וְהָיוּ נוֹסְעִים אַחֲרָיו כְּמוֹ עֲבָדִים לִפְנֵי הַמֶּלֶךְ, וְהוּא אוֹמֵר לָהֶם: אֲנִי וְאַתֶּם, (תהלים צה) בּוֹאוּ נִשְׁתַּחֲוֶה וְנִכְרָעָה נִבְרְכָה לִפְנֵי ה' עוֹשֵׂנוּ. וְכֻלָּם בָּאוּ אַחֲרָיו. כֵּיוָן שֶׁרָאוּ שֶׁאָדָם מִשְׁתַּחֲוֶה לַמָּקוֹם הַזֶּה וְנִדְבָּק בּוֹ, כֻּלָּם נִמְשְׁכוּ אַחֲרָיו, וְגָרַם מָוֶת לוֹ וּלְכָל הָעוֹלָם.</p>\n<p>אָז הִשְׁתַּנָּה הָאָדָם לְכַמָּה גְוָנִים, לִפְעָמִים לְטוֹב לִפְעָמִים לְרָע. לִפְעָמִים רֹגֶז, לִפְעָמִים נַחַת. לִפְעָמִים דִּין, וְלִפְעָמִים רַחֲמִים. לִפְעָמִים חַיִּים, לִפְעָמִים מָוֶת. וְלֹא עוֹמֵד בְּקִיּוּם תְּמִידִי בְּאֶחָד מֵהֶם, מִשּׁוּם שֶׁאוֹתוֹ מָקוֹם גָּרַם לוֹ. וְלָכֵן נִקְרָא לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, מִצַּד זֶה לְצַד זֶה, מִטּוֹב לְרַע, מֵרַחֲמִים לְדִין, מִשָּׁלוֹם לִקְרָב, הִיא מִתְהַפֶּכֶת לַכֹּל. וְנִקְרָא טוֹב וָרָע, שֶׁכָּתוּב וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ.</p>\n<p>וְהַמֶּלֶךְ הָעֶלְיוֹן, הַמְרַחֵם עַל מַעֲשֵׂי יָדָיו, הוֹכִיחַ אוֹתוֹ וְאָמַר לוֹ, וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, וְהוּא לֹא קִבֵּל מִמֶּנּוּ, וְנִמְשַׁךְ אַחַר אִשְׁתּוֹ וְנִתְגָּרֵשׁ לְעוֹלָמִים. שֶׁהֲרֵי הָאִשָּׁה עוֹלָה לַמָּקוֹם הַזֶּה, וְלֹא יוֹתֵר. וְהָאִשָּׁה גָרְמָה מָוֶת לַכֹּל.</p>\n<p>בֹּא רְאֵה, לָעוֹלָם הַבָּא כָּתוּב, (ישעיה סה) כִּי כִימֵי הָעֵץ יְמֵי עַמִּי. כִימֵי הָעֵץ - אוֹתוֹ עֵץ שֶׁנּוֹדָע. בְּאוֹתוֹ זְמַן כָּתוּב, (שם כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן יִמְלֹךְ ה' לְעוֹ, לם אָמֵן וִאָמֵן.</p>"],[9522012236,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּהַר סִינַי לֵאמֹר. דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם כִּי תָבֹאוּ אֶל הָאָרֶץ וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (ויקראו) זֹּאת תּוֹרַת הָעֹלָה הִיא הָעֹלָה וְגוֹ'. פָּסוּק זֶה בִּכְנֶסֶת יִשְׂרָאֵל בֵּאַרְנוּ, שֶׁהִיא עוֹלָה וּמִתְחַבֶּרֶת עִם הַמֶּלֶךְ הַקָּדוֹשׁ בְּזִוּוּג שָׁלֵם.</p>\n<p>הִיא הָעֹלָה עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה וְגוֹ'. בֹּא רְאֵה, כֵּיוָן שֶׁנִּכְנָס הַלַּיְלָה וְהַשְּׁעָרִים סְתוּמִים, הַדִּינִים הַתַּחְתּוֹנִים מִתְעוֹרְרִים בָּעוֹלָם, וְהוֹלְכִים וּמְשׁוֹטְטִים חֲמוֹרִים וַאֲתוֹנוֹת וּכְלָבִים. חֲמוֹרִים הֲרֵי בֵּאַרְנוּ, וּכְלָבִים וַאֲתוֹנוֹת לֹא מְשׁוֹטְטִים וְלֹא הוֹלְכִים, אֶלָּא בָּהֶם עוֹשִׂים כְּשָׁפִים לִבְנֵי אָדָם, כְּמוֹ בִּלְעָם, וּפֵרְשׁוּהָ. אָז כָּל בְּנֵי הָעוֹלָם יְשֵׁנִים, וְהַמִּזְבֵּחַ הַתַּחְתּוֹן הַחִיצוֹן שׂוֹרֵף.</p>\n<p>בַּחֲצוֹת הַלַּיְלָה מִתְעוֹרֶרֶת רוּחַ צָפוֹן, וּמֵאוֹתוֹ הַמִּזְבֵּחַ הַתַּחְתּוֹן יוֹצֵאת שַׁלְהֶבֶת אֵשׁ, וְהַשְּׁעָרִים נִפְתָּחִים, וְהַדִּינִים הַתַּחְתּוֹנִים מִתְכַּנְּסִים לַנְּקָבִים שֶׁלָּהֶם, וְאוֹתָהּ שַׁלְהֶבֶת הוֹלֶכֶת וּמְשׁוֹטֶטֶת, וְשַׁעֲרֵי גַּן עֵדֶן נִפְתָּחִים, עַד שֶׁמַּגִּיעָה (הבקר) אוֹתָהּ הַשַּׁלְהֶבֶת, וּמִתְחַלֶּקֶת לְכַמָּה צְדָדִים שֶׁל הָעוֹלָם, וְנִכְנֶסֶת תַּחַת כַּנְפֵי הַתַּרְנְגוֹל, וְהוּא קוֹרֵא.</p>\n<p>אָז הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בֵּין הַצַּדִּיקִים, וּכְנֶסֶת יִשְׂרָאֵל מְשַׁבַּחַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁמַּגִּיעַ הַבֹּקֶר. כֵּיוָן שֶׁמַּגִּיעַ הַבֹּקֶר נִמְצָאִים מְסַפְּרִים בְּסוֹד אֶחָד, וְיֵשׁ לָהּ נַחַת עִם בַּעְלָהּ. זֶהוּ שֶׁכָּתוּב עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה וְגוֹ'. עַד הַבֹּקֶר, שֶׁהֲרֵי בַּבֹּקֶר הַדִּינִים וְהַשַּׁלְהָבוֹת שׁוֹכְכִים, וְאָז מִתְעוֹרֵר אַבְרָהָם בָּעוֹלָם, וּמְנוּחָה הִיא שֶׁל הַכֹּל.</p>"],[9522012237,"<p>בֹּא רְאֵה, כֵּיוָן שֶׁנִּכְנְסוּ יִשְׂרָאֵל לָאָרֶץ, לֹא נִמְצְאוּ בָהּ הַדִּינִים הַתַּחְתּוֹנִים, וּכְנֶסֶת יִשְׂרָאֵל הָיְתָה בָּהּ בִּמְנוּחָה עַל פְּנֵי הַכְּרוּבִים, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (ישעיה א) צֶדֶק יָלִין בָּהּ. אָז הָיָה לָהּ נַחַת מֵהַכֹּל, שֶׁהֲרֵי יִשְׂרָאֵל לֹא יְשֵׁנִים עַד שֶׁמַּקְרִיבִים אֶת הַקָּרְבָּן שֶׁל בֵּין הָעַרְבַּיִם, וּמִסְתַּלְּקִים הַדִּינִים. וְהָעוֹלָה הָיְתָה בּוֹעֶרֶת עַל הַמִּזְבֵּחַ, וְאָז הָיָה לָהּ נַחַת מֵהַכֹּל, וְלֹא נִמְצָא אֶלָּא אִשָּׁה עִם בַּעְלָהּ. זֶהוּ שֶׁכָּתוּב כִּי תָבֹאוּ וְגוֹ' וְשָׁבְתָה הָאָרֶץ, מְנוּחָה בְּוַדַּאי. וְשָׁבְתָה הָאָרֶץ שַׁבָּת לַה', שַׁבָּת לַה' מַמָּשׁ.</p>\n<p>עוֹד פָּתַח רַבִּי אֶלְעָזָר, (שמות כא) כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד וְגוֹ'. מִשּׁוּם שֶׁכָּל בֶּן יִשְׂרָאֵל שֶׁנִּמּוֹל, שֶׁיֵּשׁ בּוֹ רֹשֶׁם קָדוֹשׁ, יֵשׁ לוֹ מְנוּחָה בַּשְּׁמִטָּה, שֶׁהֲרֵי שֶׁלּוֹ הִיא אוֹתָהּ שְׁמִטָּה, לָנוּחַ בָּהּ. וְזוֹ נִקְרֵאת שַׁבַּת הָאָרֶץ, וַדַּאי חֵרוּת יֵשׁ בָּהּ. מְנוּחָה בָּהּ. כְּמוֹ שֶׁשַּׁבָּת הִיא מְנוּחַת הַכֹּל, כָּךְ גַּם הַשְּׁמִטָּה הִיא מְנוּחַת הַכֹּל, מְנוּחָה הִיא שֶׁל רוּחַ וְגוּף.</p>\n<p>בֹּא רְאֵה, ה' הִיא מְנוּחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. מִשּׁוּם כָּךְ, ה' עֶלְיוֹנָה, ה' תַּחְתּוֹנָה. מְנוּחַת הָעֶלְיוֹנִים, מְנוּחַת הַתַּחְתּוֹנִים. ה' עֶלְיוֹנָה, שֶׁבַע שָׁנִים שֶׁבַע פְּעָמִים. ה' תַּחְתּוֹנָה שֶׁבַע שָׁנִים בִּלְבַדָּן. זוֹ שְׁמִטָּה, וְזֶה יוֹבֵל.</p>\n<p>וּכְשֶׁמִּסְתַּכְּלִים בִּדְבָרִים הַכֹּל אֶחָד. מִשּׁוּם כָּךְ וְשָׁבְתָה הָאָרֶץ, בְּאוֹתָהּ מְנוּחַת הָאָרֶץ צְרִיכִים הָעֲבָדִים מְנוּחָה. וּמִשּׁוּם כָּךְ, וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם. חִנָּם, מַה זֶּה חִנָּם? שֶׁלֹּא נוֹתֵן לַאֲדוֹנוֹ כְּלוּם.</p>"],[9522012238,"<p>אֶלָּא סוֹד זֶה כָּאן לָמַדְנוּ, כָּתוּב (במדבר יא) זָכַרְנוּ אֶת הַדָּגָה אֲשֶׁר נֹאכַל בְּמִצְרַיִם חִנָּם, בְּלִי בְרָכָה. שֶׁלֹּא הָיָה עָלֵינוּ בְּמִצְרַיִם הָעֹל שֶׁלְּמַעְלָה. בֹּא וּרְאֵה, עֲבָדִים פְּטוּרִים מֵעֹל הַמַּלְכוּת שֶׁלְּמַעְלָה, וְלָכֵן פְּטוּרִים מִן הַמִּצְווֹת. מַה זֶּה עֹל מַלְכוּת שָׁמַיִם? אֶלָּא כְּאוֹתוֹ שׁוֹר שֶׁנּוֹתְנִים עָלָיו עֹל בַּהַתְחָלָה כְּדֵי לְהוֹצִיא מִמֶּנּוּ טוֹב לְעוֹלָם. וְאִם לֹא מְקַבֵּל עָלָיו אוֹתוֹ עֹל, לֹא עוֹשֶׂה דָבָר. כָּךְ גַּם צָרִיךְ לְאָדָם לְקַבֵּל עָלָיו עֹל בַּהַתְחָלָה, וְאַחַר כָּךְ שֶׁיַּעֲבֹד בּוֹ בְּכָל מַה שֶּׁצָּרִיךְ. וְאִם לֹא יְקַבֵּל עָלָיו אֶת זֶה בַּהַתְחָלָה, לֹא יוּכַל לַעֲבֹד.</p>\n<p>זְהִוּ שֶׁכָּתוּב, (תהלים ב) עִבְדוּ אֶת ה' בְּיִרְאָה. מַה זֶּה בְּיִרְאָה? כְּמוֹ שֶׁנֶּאֱמַר (שם קיא) רֵאשִׁית חָכְמָה יִרְאַת ה', וְזוֹ מַלְכוּת שָׁמַיִם. וּמִשּׁוּם כָּךְ, עֹל מַלְכוּת שָׁמַיִם. וְעַל כָּךְ זוֹ הִיא הָרֵאשִׁית שֶׁל הַכֹּל. מִי מוֹכִיחַ? תְּפִלָּה, בַּהַתְחָלָה שֶׁל יָד, מִשּׁוּם שֶׁבָּזֶה הוּא נִכְנָס לִשְׁאָר הַקְּדֻשָּׁה. וְאִם זֶה לֹא נִמְצָא אֶצְלוֹ, לֹא שׁוֹרָה עָלָיו קְדֻשָּׁה לְמַעְלָה, מִשּׁוּם זֶה כָּתוּב, (ויקרא טז) בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ וְגוֹ'.</p>\n<p>וְהָעֹל הַזֶּה לֹא שׁוֹרֶה בְּמִי שֶׁכָּפוּת לְאַחֵר, וְעַל כֵּן עֲבָדִים פְּטוּרִים מֵעֹל מַלְכוּת שָׁמַיִם. וְאִם מֵהָעֹל הַזֶּה הֵם פְּטוּרִים, מִכָּל הַשְּׁאָר הֵם פְּטוּרִים, שֶׁהֲרֵי הַשְּׁאָר לֹא שׁוֹרֶה עַל הָאָדָם, עַד שֶׁנִּמְצָא עִמּוֹ הָעֹל הַזֶּה, וּמִשּׁוּם זֶה הָיוּ אוֹכְלִים יִשְׂרָאֵל בְּמִצְרַיִם חִנָּם. אַף כָּאן יֵצֵא לַחָפְשִׁי חִנָּם, שֶׁהֲרֵי עֶבֶד הָיָה, וְכָל מַה שֶּׁעָשָׂה - חִנָּם הוּא, בְּלִי עֹל מַלְכוּת שָׁמַיִם. וְאַף עַל גַּב שֶׁחִנָּם הָיוּ מַעֲשָׂיו - יֵצֵא לַחָפְשִׁי, וְתִהְיֶה לוֹ מְנוּחָה.</p>"],[9522012239,"<p>לְאַחַר שֶׁהוּא בְחֵרוּת וְנִמְצֵאת בּוֹ מְנוּחָה, נוֹתְנִים עָלָיו עֹל, מֵאוֹתוֹ מָקוֹם שֶׁהוֹצִיא אוֹתוֹ לַחֵרוּת. וְאִם בֶּן אָדָם יְסָרֵב לָצֵאת לַחֵרוּת, כְּמוֹ שֶׁנֶּאֱמַר וְאִם אָמֹר יֹאמַר הָעֶבֶד אָהַבְתִּי אֶת אֲדנִי וְגוֹ', הֲרֵי בְּוַדַּאי פָּגַם אֶת אוֹתוֹ מָקוֹם, שֶׁעָזַב עֹל מַלְכוּת שֶׁלְּמַעְלָה וְלָקַח אֶת עֹל אֲדוֹנוֹ. וְעַל זֶה מַה כָּתוּב? וְהִגִּישׁוֹ אֲדנָיו אֶל הָאֱלֹהִים וְהִגִּישׁוֹ אֶל הַדֶּלֶת וְגוֹ'. וְהִגִּישׁוֹ אֲדנָיו אֶל הָאֱלֹהִים, אֶל הָאֱלֹהִים סְתָם, אֶל אוֹתוֹ הַמָּקוֹם שֶׁפָּגַם אוֹתוֹ שֶׁגַּם כֵּן נִקְרָא אֱלֹהִים.</p>\n<p>וּלְאֵיזְהִ מָקוֹם יִקְרַב אֵלָיו? אֶל הַדֶּלֶת אוֹ אֶל הַמְּזוּזָה. מִשּׁוּם שֶׁהַמָּקוֹם הַזֶּה הוּא הַפֶּתַח שֶׁלְּמַעְלָה, וְנִקְרָא מְזוּזָה, וַהֲרֵי נִתְבָּאֵר. וְכֵיוָן שֶׁהוּא הִתְכַּוֵּן לִפְגֹּם אֶת הַמָּקוֹם הַזֶּה, אוֹתוֹ פְּגָם נִשְׁאָר עִמּוֹ בּוֹ בְּגוּפוֹ. זֶהוּ שֶׁכָּתוּב וְרָצַע אֲדנָיו אֶת אָזְנוֹ בַּמַּרְצֵעַ וַעֲבָדוֹ לְעֹלָם. יִהְיֶה עֶבֶד תַּחַת רַגְלֵי אֲדוֹנוֹ עַד שְׁנַת הַיּוֹבֵל.</p>\n<p>לָמָּה אֶת אָזְנוֹ? הֲרֵי פֵּרְשׁוּהָ. אֲבָל שְׁמִיעָה תְלוּיָה בַּמָּקוֹם הַזֶּה, עֲשִׂיָּה לְמַעְלָה. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל, כְּשֶׁקָּרְבוּ לְהַר סִינַי וְהָיוּ בְּאַהֲבַת לִבָּם לְהִתְקָרֵב לַקָּדוֹשׁ בָּרוּךְ הוּא, הִקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה, שֶׁהֲרֵי בָּרִאשׁוֹנָה הַשְּׁמִיעָה, וְאַחַר כָּךְ עֲשִׂיָּה. הַשְּׁמִיעָה תְלוּיָה בַּשְּׁמִטָּה הַזּוֹ. וְעַל זֶה שֶׁהוּא פָּגַם אֶת הַשְּׁמִיעָה הַזּוֹ, תִּפָּגֵם שְׁמִיעָתוֹ וְיִשָּׁאֵר בּוֹ פְּגָם, וְהוּא לֹא יִשָּׁאֵר עֶבֶד לַאֲדוֹנוֹ, עַד שֶׁיִּתְקָרֵב לְאוֹתוֹ מָקוֹם שֶׁפָּגַם, וְיִפָּגֵם הוּא לְפָנָיו, וְיִשָּׁאֵר בּוֹ אוֹתוֹ פְּגָם. וּמִשּׁוּם זֶה, וְהִגִּישׁוֹ אֲדנָיו אֶל הָאֱלֹהִים סְתָם, כְּמוֹ שֶׁבֵּאַרְנוּ. וְעַל זֶה, וְשָׁבְתָה הָאָרֶץ שַׁבָּת לַה'.</p>\n<p>שֵׁשׁ שָׁנִים תִּזְרַע שָׂדֶךְ וְגוֹ', וּבַשָּׁנָה הַשְּׁבִיעִת שַׁבָּת שַׁבָּתוֹן יִהְיֶה לָאָרֶץ שַׁבָּת לַה'. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (שמות כג) וְהַשְּׁבִיעִת תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ וְגוֹ'. מָה הַטַּעַם וְאָכְלוּ אֶבְיֹנֵי עַמֶּךְ? מִשּׁוּם שֶׁהָעֲנִיִּים תְּלוּיִים בַּמָּקוֹם הַזֶּה, וּמִשּׁוּם זֶה תַּשְׁאִיר אוֹתָם לֶאֱכֹל. וְעַל זֶה, מִי שֶׁמְּרַחֵם עַל הֶעָנִי, נוֹתֵן שָׁלוֹם בִּכְנֶסֶת יִשְׂרָאֵל, וּמוֹסִיף בְּרָכָה לָעוֹלָם, וְנוֹתֵן שִׂמְחָה וְכֹחַ לַמָּקוֹם שֶׁנִּקְרָא צְדָקָה, לְהוֹרִיק בְּרָכָה לִכְנֶסֶת יִשְׂרָאֵל, וּבֵאַרְנוּ.</p>"],[9522012240,"<p>וּבַשָּׁנָה הַשְּׁבִיעִת שַׁבָּת שַׁבָּתוֹן וְגוֹ'. מִצְוָה זוֹ לִשְׁבּת בַּשָּׁנָה הַשְּׁבִיעִית, וּלְאַחֲרֶיהָ לִשְׁבֹּת בַּשְּׁבִיעִי, וְאַחֲרֶיהָ לְהַשְׁמִיט כְּסָפִים בַּשְּׁבִיעִית, וְאַחֲרֶיהָ לִמְנוֹת שֶׁבַע שָׁנִים שֶׁבַע פְּעָמִים וְהָיוּ לְךְ יְמֵי שֶׁבַע שַׁבְּתֹת הַשָּׁנִים תֵּשַׁע וְאַרְבָּעִים שָׁנָה. כָּאן הַסּוֹד שֶׁל כָּל הַשְּׁבִיעִיּוֹת, מִצַּד הַשְּׁכִינָה שֶׁנִּמְצֵאת שֶׁבַע, מִצַּד הַצַּדִּיק שֶׁהוּא שְׁבִיעִי לַבִּינָה, וְהִיא בַּת שֶׁבַע, מִצַּד הָאֵם הָעֶלְיוֹנָה, שֶׁנֶּאֱמַר בָּהּ (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ.</p>\n<p>שֶׁבַע שֵׁמוֹת הֵם אבגית\"ץ, וּבָהֶם אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת, כְּלַל הָאוֹתִיּוֹת וְהַתֵּבוֹת הֵם תֵּשַׁע וְאַרְבָּעִים, הָאֵם הָעֶלְיוֹנָה שְׁנַת הַחֲמִשִּׁים שָׁנָה, שֶׁבָּהּ וּקְרָאתֶם דְּרוֹר. בָּהּ תִּהְיֶה שְׁכִינָה תַחְתּוֹנָה, דְּרוֹר פְּדוּת וּשְׁבִיתָה לְיִשְׂרָאֵל, שֶׁנֶּאֱמַר בָּהֶם וְהָיָה זַרְעֲךְ כַּעֲפַר הָאָרֶץ.</p>\n<p>לְכָל סְפִירָה מֵהַשֶּׁבַע הַלָּלוּ שֵׁשׁ כְּנָפַיִם, שֶׁהֵן שֵׁשׁ אוֹתִיּוֹת לְכָל אַחַת. וּבָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא (ושכינתו) בְּכָל סְפִירָה מֵהַשֶּׁבַע הַלָּלוּ, (ישעיה ו) בִּשְׁתַּיִם יְכַסֶּה פָנָיו וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו וּבִשְׁתַּיִם יְעוֹפֵף, וּבִינָה הִיא אַחַת, וְהַשְּׁכִינָה הַתַּחְתּוֹנָה הִיא שֶׁבַע, וּלְמַעְלָה מִבִּינָה אַחַת וְאַחַת - הֲרֵי עֶשֶׂר סְפִירוֹת. שְׁתַּיִם, ג', וְד', וְה', וְו', וְז'.</p>\n<p>כָּאן וַיֵּלֶךְ הָלוֹךְ וְגָדֵל. מִצַּד זָר - וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר, מָתַי? בְּמָקוֹם שֶׁהַשְּׁכִינָה הַתַּחְתּוֹנָה שׁוֹרָה בְז'. זֶהוּ שֶׁכָּתוּב (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי, זוֹ הַשְּׁכִינָה הַתַּחְתּוֹנָה. בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ, הִיא הַשְּׁבִיעִית וְהָעֲשִׂירִית.</p>\n<p>שֶׁעוֹלֶה בָהֶם אֶהְיֶה, שֶׁהִיא בִּינָה, שְׁנַת הַיּוֹבֵל, הִיא אֶהְיֶה אֲשֶׁר אֶהְיֶה, פַּעֲמַיִם אֶהְיֶה חֶשְׁבּוֹן מ\"ב, וּשְׁמוֹנֶה אוֹתִיּוֹת בָּהֶם חֲמִשִּׁים, שֶׁבָּהֶם מִצְוָה לְחַשֵּׁב שְׁנַת הַיּוֹבֵל. וּבוֹ מִצְוָה לַחֲזֹּר לַאֲחֻזָּתוֹ בַּיּוֹבֵל, בִּשְׁנַת הַיּוֹבֵל הַזֹּאת תָּשֻׁבוּ וְגוֹ'. כָּל אֶחָד יַחֲזֹר בּוֹ לַדַּרְגָּה שֶׁלּוֹ, שֶׁנִּשְׁמָתוֹ אֲחוּזָה מִשָּׁם, כְּמוֹ שֶׁבֵּאֲרוּהָ (קהלתיב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים וְגוֹ'.</p>\n<p>שְׁמִטָה - שְׁכִינָה תַחְתּוֹנָה, שֶׁהִיא מִשֶּׁבַע שָׁנִים. יוֹבֵל - הָאֵם הָעֶלְיוֹנָה, בִּינָה, הִיא לַחֲמִשִּׁים שָׁנִים, וּבָהּ מִתְיַחֲסִים יִשְׂרָאֵל בִּיצִיאָתָם מֵהַגָּלוּת. זֶהוּ שֶׁכָּתוּב וְאִישׁ אֶל מִשְׁפַּחְתּוֹ תָּשֻׁבוּ. כְּגוֹן שֶׁיְּצִיאַת מִצְרַיִם שֶׁאוֹתָם בַּעֲלֵי תוֹרָה בָּהּ, נֶאֱמַר בָּהֶם (שמות יג) וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל, וּפֵרְשׁוּהָ אֶחָד מֵחֲמִשִּׁים.</p>\n<p>וּשְׁכִינָה תַחְתּוֹנָה הִיא גְּאֻלַּת בָּתֵּי עָרֵי חוֹמָה נֶאֱמַר בָּהּ, וּבָתֵּי עָרֵי הַחֲצֵרִים. שֶׁשְּׁנֵי בָתִּים יֵשׁ בַּלֵּב: אִם הֵם מִבַּעֲלֵי תוֹרָה, הֵם נִקְרָאִים בָּתֵּי עָרֵי חוֹמָה, כְּמוֹ שֶׁנֶּאֱמַר בִּיצִיאַת מִצְרַיִם, (שם יד) וְהַמַּיִם לָהֶם חוֹמָה מִימִינָם וּמִשְּׂמֹאלָם. לַאֲחֵרִים שֶׁאֵינָם בַּעֲלֵי תוֹרָה, נִקְרְאוּ בָּתֵי הַחֲצֵרִים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וַהֲרֵי מָצָאנוּ חֲצֵרִים שֶׁנֶּאֱמַר בּוֹ (אסתר ה) וַתַּעֲמֹד בַּחֲצַר בֵּית הַמֶּלֶךְ הַפְּנִימִית נֹכַח בֵּית הַמֶּלֶךְ. וּבְכָל מָקוֹם הַמֶּלֶךְ סְתָם, זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וַתַּעֲמֹד, אֵין עֲמִידָה אֶלָּא תְּפִלָּה. נֹכַח בֵּית הַמֶּלֶךְ, נֹכַח בֵּית הַמִּקְדָּשׁ, שֶׁכָּל יִשְׂרָאֵל צְרִיכִים לְהִתְפַּלֵּל תְּפִלָּתָם לְשָׁם וְלִהְיוֹת נֹכַח בֵּית הַמִּקְדָּשׁ. מִי זוֹ כָּאן חָצֵר הַפְּנִימִית? וַדַּאי שְׁנַיִם הֵם חַצְרוֹת בֵּית ה'.</p>\n<p>אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, שְׁנֵי חֲצֵרִים, הֵם הַחִיצוֹנִיִּים שֶׁל הַלֵּב, וְהֵם שְׁנֵי אָזְנַיִם שֶׁל הַלֵּב. וּשְׁנֵי בָתִּים פְּנִימִיִּים, שְׁנֵי בָּתֵּי הַלֵּב. וּשְׁנַיִם הֵם הַבָּתִּים הַפְּנִימִיִּים, וּשְׁנַיִם הֵם בָּתִּים חִיצוֹנִיִּים. וּבִזְמַן שֶׁיִּהְיֶה פֻרְקָן, תִּהְיֶה גְאֻלָּה לְכֻלָּם, לְאוֹתָם הַקְּרוֹבִים לַלֵּב, שֶׁהִיא הַשְּׁכִינָה, וּלְאֵלֶּה הָרְחוֹקִים שֶׁהִתְקָרְבוּ. זֶהוּ שֶׁכָּתוּב (ישעיה נז) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב. וּפֵרְשׁוּהָ, לָרָחוֹק מֵעֲבֵרָה, וְלַקָּרוֹב מִמִּצְוָה.</p>"],[9522012241,"<p>בְּאוֹתוֹ זְמַן מִצְוָה לִתְקֹעַ בַּשּׁוֹפָר בַּיּוֹבֵל. זֶהוּ שֶׁכָּתוּב (שם יח) כִּנְשֹׂא נֵס הָרִים תִּרְאוּ וְכִתְקֹעַ שׁוֹפָר תִּשְׁמָעוּ. כְּמוֹ שֶׁבִּתְקִיעַת שׁוֹפַר הַיּוֹבֵל כָּל הָעֲבָדִים יוֹצְאִים לְחֵרוּת, כָּךְ בַּגְּאֻלָּה הָאַחֲרוֹנָה בִּתְקִיעַת שׁוֹפָר מִתְכַּנְּסִים כָּל יִשְׂרָאֵל מֵאַרְבַּעַת צִדְדֵי הָעוֹלָם, שֶׁהֵם עַבְדֵי הַיּוֹבֵל. שֶׁבְּבַעֲלֵי תוֹרָה, יֵשׁ בָּהֶם עֲבָדִים עַל מְנָת לְקַבֵּל פְּרָס, וְנִקְרָאִים עַבְדֵי הַמֶּלֶךְ וְהַגְּבִירָה. אֲבָל בְּנֵי הַמֶּלֶךְ הַקָּדוֹשׁ - (שמות יט) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וָאָבִא אֶתְכֶם אֵלָי, שֶׁהֵם כַּנְפֵי חַיּוֹת הַמֶּרְכָּבָה.</p>\n<p>מִצְוָה אַחַר זוֹ - לָתֵת לַלְוִיִּם עָרִים לָשֶׁבֶת. וּמִשּׁוּם שֶׁהֵם לֹא הִשְׁתַּתְּפוּ בָעֵגֶל, הַקָּדוֹשׁ בָּרוּךְ הוּא חָלַק אוֹתָם אֵלָיו, שֶׁיִּהְיוּ מְנַגְּנִים לוֹ בְּכַמָּה מִינֵי נִגּוּן. שֶׁכֹּהֲנִים בַּעֲבוֹדָתָם, וּלְוִיִּם לְשִׁירָם וּלְזִמְרָם, וְיִשְׂרָאֵל לִנְוֵיהֶם. כֹּהֲנִים בַּעֲבוֹדָתָם, שֶׁיֵּשׁ שָׁם כַּמָּה מִצְווֹת.</p>\n<p>מִצְוָה אַחַת - לַעֲשׂוֹת שֶׁמֶן הַמִּשְׁחָה. ב' - לְוִיִּם שׁוֹמְרִים בַּמִּקְדָּשׁ. ג' - יִשְׂרָאֵל לִירָא מִן הַמִּקְדָּשׁ. ד' - עֲבוֹדַת הַלְוִיִּם בְּבֵית הַמִּקְדָּשׁ. ה' - לְהַקְטִיר קְטֹרֶת פַּעֲמַיִם. ו' - כֹּהֲנִים תּוֹקְעִים בַּחֲצוֹצְרוֹת בַּמִּקְדָּשׁ. ז' - לְקַדֵּשׁ זֶרַע אַהֲרֹן בַּמִּקְדָּשׁ. ח' - לִלְבֹּשׁ בִּגְדֵי כְהֻנָּה בַּמִּקְדָּשׁ. ט' - רְחִיצַת יָדַיִם וְרַגְלַיִם לַעֲבֹד בַּמִּקְדָּשׁ.</p>\n<p>י' - לִהְיוֹת הַכֹּהֲנִים עוֹשִׂים קָרְבָּנוֹת בַּמִּקְדָּשׁ. י\"א - לִפְדּוֹת פְּסוּלֵי הַמֻּקְדָּשִׁים. י\"ב - קָרְבַּן הַיּוֹלֶדֶת בַּיּוֹם הַשְּׁמִינִי. י\"ג - לִמְלֹחַ קָרְבָּנוֹת בַּמִּקְדָּשׁ. י\"ד - לַעֲשׂוֹת הָעוֹלָה כְּמִשְׁפָּטָהּ. ט\"ו - לַעֲשׂוֹת הַחַטָּאת כְּמִשְׁפָּטוֹ. ט\"ז - אֲכִילַת קָדָשִׁים כַּמִּשְׁפָּט לַכֹּהֲנִים. י\"ז - אֲכִילַת שְׁיָרֵי מְנָחוֹת. ח\"י - לַעֲשׂוֹת מְנָחוֹת כְּמִצְוָתָן. י\"ט - לְהָבִיא קָרְבָּנוֹת לְבֵית הַמִּקְדָּשׁ. כ' - לְהָבִיא נֶדֶר אוֹ נְדָבָה לְבֵית הַמִּקְדָּשׁ. כ\"א - לְהָבִיא קָרְבְּנוֹת קָדָשִׁים, תְּמוּרוֹת וּוְלָדוֹת. כ\"ב - לְהַקְרִיב שְׁנֵי תְמִידִין כְּהִלְכָתָן. כ\"ג - לְהַדְלִיק אֵשׁ תָּמִיד עַל הַמִּזְבֵּחַ.</p>\n<p>כ\"ד - לַעֲשׂוֹת תְּרוּמַת הַדֶּשֶׁן. כ\"ה - לְהַדְלִיק נֵרוֹת הַמְּנוֹרָה. כ\"ו - לְהַקְרִיב מִנְחָה בְּכָל יוֹם. כ\"ז - לְהַקְרִיב מוּסָף בְּשַׁבָּת. כ\"ח - לְהַסְדִּיר לֶחֶם וּלְבוֹנָה. כ\"ט - לְהַקְרִיב קָרְבַּן מוּסָף בְּרֹאשׁ חֹדֶשׁ. ל' - לְהַקְרִיב בְּשִׁבְעַת יְמֵי הַפֶּסַח. ל\"א - לְהַקְרִיב בְּיוֹם הָעֹמֶר כֶּבֶשׂ לְעוֹלָה. ל\"ב - לְהַקְרִיב (קרבן) הָעֹמֶר (הינו ספירת העמר). ל\"ג - לְהַקְרִיב קָרְבַּן מוּסָף בְּשָׁבוּעוֹת. ל\"ד - לְהַקְרִיב שְׁתֵּי הַלֶּחֶם בְּשָׁבוּעוֹת. ל\"ה - לְהַקְרִיב מוּסָף בְּרֹאשׁ הַשָּׁנָה. ל\"ו - לְהַקְרִיב מוּסָף בְּיוֹם הַכִּפּוּרִים. ל\"ז - לְהַקְרִיב מוּסָף בְּשִׁבְעַת יְמֵי הֶחָג. ל\"ח - לְהַקְרִיב מוּסָף בִּשְׁמִינִי עֲצֶרֶת. ט\"ל - לִשְׂרֹף אֶת הַנּוֹתָר בָּאֵשׁ. מ' - לִשְׂרֹף קָדָשִׁים שֶׁנִּטְמְאוּ. מ\"א - לַעֲבֹד כֹּהֵן גָּדוֹל בְּיוֹם הַכִּפּוּרִים.</p>\n<p>מ\"ב - הַמּוֹעֵל בַּהֶקְדֵּשׁ, קֶרֶן וְחֹמֶשׁ. מ\"ג - (להביא החוטא קרבן חטאת על חטאו) קָרְבַּן חַטָּאת. מ\"ד - אָשָׁם תָּלוּי עַל סְפֵקוֹ. מ\"ה - קָרְבַּן אָשָׁם וַדַּאי, עַל הַיָּדוּעַ. מ\"ו - קָרְבָּן עוֹלֶה וְיוֹרֵד. מ\"ז - קָרְבַּן סַנְהֶדְרִין גְּדוֹלָה שֶׁטָּעוּ. מ\"ח - לְהַקְרִיב הַזָּב אַחַר שֶׁיִּטָּהֵר. מ\"ט - קָרְבַּן זָבָה אַחַר שֶׁתִּטָּהֵר. נ' - קָרְבַּן יוֹלְדוֹת. נ\"א - קָרְבַּן מְצֹרָעִים. מִשָּׁם וְאֵילָךְ שְׁאָר הַמִּצְווֹת.</p>"],[9522012242,"<p>בַּעָלֵי הַיְשִׁיבוֹת, בִּשְׁבוּעָה עֲלֵיכֶם, אַל תָּזוּזוּ מִמֶּנִּי עַד שֶׁאַתְקִין קָרְבָּנוֹת לַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהַשְּׁכִינָה הִיא קָרְבָּן לַה' בְּכָל אֵיבָר וְאֵיבָר שֶׁל הַמֶּלֶךְ, בְּחִבּוּר שָׁלֵם, בְּזָכָר וּנְקֵבָה. בְּכָל הָאֵיבָרִים, שֶׁהֵם: מֵהֶם בָּרֹאשׁ, עֵינַיִם בָּעֵינַיִם, אָזְנַיִם לְגַבֵּי אָזְנַיִם, חֹטֶם בְּחֹטֶם, פָּנִים בְּפָנִים, פֶּה בְּפֶה, כְּגוֹן (מלכים בד) וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו. וּבָזֶה הָיָה מְחַיֶּה אֶת הַיֶּלֶד. וְכָךְ יְדֵי הַמֶּלֶךְ עִם יְדֵי הַגְּבִירָה, גּוּף בְּגוּף, בְּכָל אֵיבָרָיו. קָרְבָּן שָׁלֵם.</p>\n<p>שֶׁבֶּן אָדָם בְּלִי אִשָּׁה הוּא חֲצִי גוּף, וְאֵין הַשְּׁכִינָה שׁוֹרָה עָלָיו. כָּךְ (כאשר) הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא אֵינֶנּוּ בְּקָרְבָּן עִם הַשְּׁכִינָה, בְּכָל יִשְׂרָאֵל, שֶׁהֵם אַנְשֵׁי מִדּוֹת, שֶׁהֵם הָאֵיבָרִים שֶׁלָּהּ. עִלַּת הָעִלּוֹת לֹא שׁוֹרֶה שָׁם, וּכְאִלּוּ לֹא הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶחָד, מֵאַחַר שֶׁהוּא אֵינוֹ עִם שְׁכִינָתוֹ. וּבְחוּצָה לָאָרֶץ, שֶׁהַשְּׁכִינָה מְרֻחֶקֶת מִבַּעְלָהּ, נֶאֱמַר, כָּל הַדָּר בְּחוּץ לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ. מִשּׁוּם שֶׁאֵין שָׁם קָרְבָּנוֹת בְּחוּצָה לָאָרֶץ. וּבִזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְקָרֵב עִם שְׁכִינָתוֹ, יִתְקַיֵּם בּוֹ הַפָּסוּק הַזֶּה, (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. וְעִלַּת הָעִלּוֹת שׁוֹרֶה עֲלֵיהֶם.</p>\n<p>אַף עַל גַּב שֶׁתִּקְּנוּ הָאָבוֹת תְּפִלּוֹת בִּמְקוֹם קָרְבָּנוֹת, זֶה הוּא לְקָרֵב נְפָשׁוֹת וְרוּחוֹת וּנְשָׁמוֹת, שֶׁהֵם שִׂכְלִיִּים לַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ כְּאֵיבָרִים לְגַבֵּי הַגּוּף. אֲבָל מִצַּד הַכִּסְאוֹת וְהַמַּלְאָכִים, שֶׁהֵם גּוּפִים וְאֵיבָרִים שֶׁמִּחוּץ לַמֶּלֶךְ וּמֵהַגְּבִירָה, אֵין שָׁם קָרְבָּן. וְלָכֵן נֶאֱמַר בַּכִּסֵּא, (שמות יז) וַיֹּאמֶר כִּי יָד עַל כֵּס יָהּ. (כס, חסר מכס א') (ה\"ו חסר משם) (ירמיה יז) כִּסֵּא כָּבוֹד מָרוֹם מֵרִאשׁוֹן מְקוֹם מִקְדָּשֵׁנוּ. וְהָאֵיבָרִים בְּפֵרוּד מֵהַגּוּף. הוּא בִּפְנִים, וְהֵם בַּחוּץ. זֶהוּ שֶׁכָּתוּב הֶן אֶרְאֶלָּם צָעֲקוּ חֻצָה, חֻצָה וַדַּאי.</p>\n<p>יְהִי רָצוֹן שֶׁלְּךְ, לְהַחֲזִירֵנוּ לְבֵית הַמִּקְדָּשׁ, לְקַיֵּם הַתְּפִלָּה שֶׁבֵּאֲרוּהָ הַקַּדְמוֹנִים: יְהִי רָצוֹן מִלְּפָנֶיךְ ה' אֱלֹקֵינוּ וֵאלֹקֵי אֲבוֹתֵינוּ, שֶׁתַּעֲלֵנוּ בְשִׂמְחָה לְאַרְצֵנוּ, וְתִטָּעֵנוּ בִגְבוּלֵנוּ, וְשָׁם נַעֲשֶׂה לְפָנֶיךְ אֶת קָרְבְּנוֹת חוֹבוֹתֵינוּ תְּמִידִין כְּסִדְרָן, כָּל אֶחָד בְּסִדּוּרוֹ, וּמוּסָפִים כְּהִלְכָתָם. שֶׁכָּעֵת מִחוּץ לָאָרֶץ אֵין שָׁם קָרְבָּנוֹת, כְּמוֹ הַגּוּפִים שֶׁל הַבְּרִיאָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, מִצַּד הָאֲצִילוּת שֶׁלּוֹ, אֵין שָׁם פֵּרוּד וְהַפְרָדָה. שֶׁהַשְּׁכִינָה הִיא יִחוּדוֹ וּבִרְכָתוֹ וּקְדֻשָּׁתוֹ, וְלֹא נִקְרֵאת גּוּף אֶלָּא כְּשֶׁהִתְגַּשְּׁמוּ בַכִּסְאוֹת. וּמַלְאֲכֵי הַבְּרִיאָה כְּמוֹ נְשָׁמָה שֶׁמִּתְלַבֶּשֶׁת בְּגוּף שָׁפָל. וְלָכֵן, כְּשֶׁהַשְּׁכִינָה הִיא מִחוּץ לְהֵיכַל בֵּית הַמִּקְדָּשׁ וּמִחוּץ לְכִסְאוֹתֶיהָ, כִּבְיָכוֹל כְּאִלּוּ לֹא הָיְתָה אֶחָד עִמּוֹ.</p>\n<p>מִצַד הַכִּסֵּא הָעֶלְיוֹן שֶׁהוּא גּוּף לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַמַּלְאָכִים שֶׁתְּלוּיִים מִמֶּנּוּ, כְּמוֹ אֵיבָרִים שֶׁתְּלוּיִים מִן הַגּוּף, שֶׁהֵם זְכָרִים. וְהַנְּשָׁמוֹת שֶׁנִּגְזְרוּ מִמֶּנּוּ זְכָרִים. הַכִּסֵּא הַשֵּׁנִי גּוּף הַשְּׁכִינָה, וְכָל הַנְּשָׁמוֹת שֶׁתְּלוּיִים מִמֶּנּוּ נְקֵבוֹת, וְהַמַּלְאָכִים שֶׁתְּלוּיִים מֵאוֹתוֹ כִּסֵּא נְקֵבוֹת, וְקִרְבָתָם לַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ.</p>\n<p>כָּךָ יִחוּד הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, אַף עַל גַּב שֶׁהֵם כִּנְשָׁמוֹת לְגַבֵּי הַכִּסֵּא וְהַמַּלְאָכִים, כָּךְ הֵם לְגַבֶּיךְ עִלַּת הָעִלּוֹת, כְּגוּף, שֶׁאַתָּה הוּא שֶׁמְּיַחֵד אוֹתָם וּמְקָרֵב אוֹתָם, וְלָכֵן אֱמוּנָתְךְ בָּהֶם, וְאַתָּה אֵין נְשָׁמָה עָלֶיךְ, שֶׁתִּהְיֶה אַתָּה כְּגוּף אֵלֶיהָ, שֶׁאַתָּה הוּא נְשָׁמָה לַנְּשָׁמוֹת, וְאֵין נְשָׁמָה עָלֶיךְ, וְלֹא אֱלוֹהַּ עָלֶיךְ. אַתָּה מִחוּץ לַכֹּל, וּבְתוֹךְ הַכֹּל, וּלְכָל צַד, וּלְמַעְלָה מֵהַכֹּל, וּלְמַטָּה מֵהַכֹּל. וְאֵין אֱלוֹהַּ אַחֵר לְמַעְלָה וּלְמַטָּה וּמִכָּל צַד, וּמִתּוֹךְ עֶשֶׂר הַסְּפִירוֹת, שֶׁמֵּהֶם הַכֹּל, וּבָהֶם הַכֹּל תָּלוּי, וְאַתָּה בְּכָל סְפִירָה, בְּאָרְכָּהּ וְרָחְבָּהּ, לְמַעְלָה וּלְמַטָּה, וּבֵין כָּל סְפִירָה וּסְפִירָה, וּבָעֳבִי כָּל סְפִירָה וּסְפִירָה.</p>\n<p>וְאַתָּה הוּא שֶׁמְּקָרֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁכִינָתוֹ בְּכָל סְפִירָה וּסְפִירָה, וּבְכָל הָעֲנָפִים שֶׁל הַמְּאוֹרוֹת שֶׁתְּלוּיִים מֵהֶם, כַּעֲצָמוֹת, וְגִידִים, וְעוֹר, וּבָשָׂר, הַתְּלוּיִים מִן הַגּוּף. וְאַתָּה אֵין לְךְ גּוּף, וְלֹא אֵיבָרִים, וְאֵין לְךְ נְקֵבָה. אֶלָּא אֶחָד בְּלִי שֵׁנִי. יְהִי רָצוֹן שֶׁלְּךְ, שֶׁתְּקָרֵב אַתָּה אֶת הַשְּׁכִינָה לַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל הַדְּרָגוֹת שֶׁהֵן אֲצִילוּת שֶׁלָּהּ, שֶׁהֵן נְשָׁמוֹת שֶׁל בַּעֲלֵי מִדּוֹת. נְשִׂיאֵי יִשְׂרָאֵל. חֲכָמִים. נְבוֹנִים. חֲסִידִים. גִּבּוֹרִים. אַנְשֵׁי אֱמֶת. נְבִיאִים. צַדִּיקִים. מְלָכִים. כֻּלָּם מֵאֲצִילוּת, שֶׁיֵּשׁ אֲחֵרִים שֶׁל בְּרִיאָה.</p>\n<p>שֶׁהַשְּׁכִינָה הִיא קָרְבָּן, שֶׁמֶן הַמִּשְׁחָה. מִיָּמִין שֶׁמֶן לַמָּאוֹר, כְּגוֹן (בראשית א) אֶת הַמָּאוֹר הַגָּדל. שֶׁמֶן מִשְׁחַת קֹדֶשׁ הוּא מִצַּד הַשְּׂמֹאל, שֶׁנֶּאֱמַר בּוֹ וְקִדַּשְׁתָּ אֶת הַלְוִיִּם. שֶׁמֶן כָּתִית הוּא מִצַּד שֶׁל צַדִּיק, שֶׁהוּא כּוֹתֵשׁ כְּתִישׁוֹת מֵאֵיבָרִים, שֶׁהֵם זֵיתִים, לְהוֹרִיד שֶׁמֶן לְגַבֵּי פְתִילָה, פְּתִיל תְּכֵלֶת. וְהַגְּבוּרָה מִשָּׁם הִיא יִרְאָה, וּלְוִיִּם שׁוֹמְרִים הַמִּקְדָּשׁ.</p>\n<p>וּמִשָּׁם מִצְוָה לִירָא מִן הַמִּקְדָּשׁ, וְהִיא מִצְוַת עֲבוֹדַת הַלְוִיִּם בַּמִּקְדָּשׁ בְּעֶשְׂרִים וְאַרְבַּע מִשְׁמְרוֹת לְוִיִּם שֶׁבָּהֶן הָיוּ מְזַמְּרִים לְוִיִּים בְּשִׁירָה וּבְזִמְרָה לְפָנֶיךְ לְהַעֲלוֹת שְׁכִינָה, שֶׁהִיא שִׁירָה וְזִמְרָה, בָּהֶם לַה'. כ\"ד עִם שִׁירָה וְזִמְרָה - כ\"ו, כְּחֶשְׁבּוֹן יְהֹוָ\"ה. וּלְאַחֲרֶיהָ מִצְוָה, הִיא מִצְוַת קְטֹרֶת תָּמִיד לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַקְּטֹרֶת כְּקָרְבָּן.</p>\n<p>וְהִפְשִׁיט אֶת הָעֹלָה וְנִתַּח אֹתָהּ לִנְתָחֶיהָ. וְאֵמוּרִים וּפְרָדִים שֶׁהֵם מִתְעַכְּלִים כָּל הַלַּיְלָה, הֵם כַּפָּרַת אֵיבְרֵי הַגּוּף שֶׁלּוֹ וְנַפְשׁוֹ שֶׁלֹּא יִשָּׂרְפוּ בַגֵּיהִנֹּם, וְלֹא יִמָּסְרוּ בְּיַד מַלְאַךְ הַמָּוֶת. וּמִשּׁוּם שֶׁבֶּן אָדָם חָטָא בַּיֵּצֶר הָרָע, שֶׁהוּא צְפוֹנִי, כָּךְ שְׁחִיטָתוֹ בַּצָּפוֹן, לְהַצִּילוֹ מֵאוֹתוֹ צְפוֹנִי.</p>\n<p>וּבַקָּרְבָּנוֹת, קַח בָּהֶם קַל וָחֹמֶר מִנְּבִיאִים. שֶׁאַף עַל גַּב שֶׁהַתּוֹרָה הִיא שֵׁם יְהֹוָ\"ה, וְהַנְּבוּאָה שֶׁנֶּאֱמַר בָּהּ (ישעיה סג) רוּחַ ה' תְּנִיחֶנּוּ - עִם כָּל זֶה, לֹא כָּל בַּעֲלֵי תוֹרָה שְׁקוּלִים, וְלֹא כָּל הַנְּבִיאִים שְׁקוּלִים, שֶׁיֵּשׁ נְבִיאִים שֶׁנְּבוּאָתָם בִּלְבוּשֵׁי הַמֶּלֶךְ, וְכָךְ הִיא תּוֹרָה שֶׁבְּעַל פֶּה, כַּמָּה בַּעֲלֵי סְפֵקוֹת וּפֵרוּקִים בִּלְבוּשׁ הַמֶּלֶךְ.</p>\n<p>וְיִשִׁ אֲחֵרִים שֶׁעוֹלִים יוֹתֵר בְּאֵיבְרֵי גּוּף הַמֶּלֶךְ, שֶׁנֶּאֱמַר בָּהֶם וָאֶרְאֶה, וְרָאִיתִי, בַּמַּרְאֶה - בָּעֵינַיִם. (חבקוק ג) ה' שָׁמַעְתִּי שִׁמְעֲךְ יָרֵאתִי - בִּשְׁמִיעָה. יְחֶזְקֵאל, הִסְתַּכְּלוּתוֹ וּנְבוּאָתוֹ מֵהָעֵינַיִם. חֲבַקּוּק מֵהָאָזְנַיִם, בִּשְׁמִיעָה. וְלָכֵן רָאָה יְחֶזְקֵאל כָּל מַרְאוֹת הַמֶּרְכָּבָה הָאֵלֶּה בִּרְאִיָּה, בְּעֵין הַשֵּׂכֶל. חֲבַקּוּק בִּשְׁמִיעָה. וְיֵשׁ נָבִיא שֶׁנְּבוּאָתוֹ בַּפֶּה, זֶהוּ שֶׁכָּתוּב וַיִּגַּע עַל פִּי. נְבוּאָה אַחֶרֶת מֵרֵיחַ הַחֹטֶם, זֶהוּ שֶׁכָּתוּב (יחזקאלב) וַתָּבֹא בִי הָרוּחַ. וְיֵשׁ שֶׁנְּבוּאָתוֹ בַּיָּד, זֶהוּ שֶׁכָּתוּב (הושע יב) וּבְיַד הַנְּבִיאִים אֲדַמֶּה. וַאֲחֵרִים לִפְנִים בְּחַיֵּי הַמֵּלֶךְ, וַאֲחֵרִים לִפְנַי וְלִפְנִים.</p>\n<p>וְכָךָֹ בַּתּוֹרָה, פְּשָׁטִי\"ם, רְאָיוֹ\"ת, דְּרָשׁוֹ\"ת, סוֹדוֹ\"ת שֶׁל סִתְרֵי תורָה, וּלְמַעְלָה סִתְרֵי סְתָרִים לַה'. כָּךְ בְּקָרְבָּנות, אַף עַל גַּב שֶׁקָּרְבָּנוֹת כֻּלָּם לַיהֹוָ\"ה, הוּא לוֹקֵחַ הַכֹּל וּמְחַלֵּק אֶת הַקָּרְבָּנוֹת לְמַחֲנוֹתָיו. מֵהֶם מְחַלֵּק לַכְּלָבִים, אוֹתָם קָרְבָּנוֹת פְּסוּלִים, שֶׁנּוֹתֵן אוֹתָם לְסָמָאֵ\"ל הַכֶּלֶב וּלְמַחֲנוֹתָיו, וְלָכֵן הָיְתָה יוֹרֶדֶת דְּמוּת כֶּלֶב. וּמֵהֶם לַשֵּׁדִים, שֶׁיֵּשׁ בָּהֶם כַּבְּהֵמוֹת, וּמֵהֶם כְּמַלְאֲכֵי הַשָּׁרֵת, וּמֵהֶם כִּבְנֵי אָדָם. לְאוֹתָם שֶׁמַּעֲשֵׂיהֶם כְּשֵׁדִים, מְחַלֵּק קָרְבְּנוֹתֵיהֶם לַשֵּׁדִים.</p>\n<p>אֵלֶּה שֶׁמַּעֲשֵׂיהֶם כְּמַלְאָכִים, מְחַלֵּק אֶת קָרְבְּנוֹתֵיהֶם לַמַּלְאָכִים. זֶהוּ שֶׁכָּתוּב, (במדבר כח) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. שֶׁאוֹתָם קָרְבְּנוֹתֵיהֶם לֹא תְלוּיִים בַּבְּהֵמוֹת. שֶׁקָּרְבָּנוֹת שֶׁל בְּהֵמוֹת הֵם שֶׁל עַמֵּי הָאָרֶץ. אוֹתָם קָרְבָּנוֹת (של מלאכים) שֶׁל בְּנֵי אָדָם - תְּפִלּוֹת וּמַעֲשִׂים טוֹבִים. הַקָּרְבָּנוֹת שֶׁל תַּלְמִידֵי חֲכָמִים, בַּעֲלֵי מִדּוֹת, אֵלֶּה בַּעֲלֵי סוֹדוֹת תּוֹרָה וְהַסְּתָרִים הַגְּנוּזִים שֶׁבָּהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד בְּעַצְמוֹ לְקַבֵּל אֶת קָרְבְּנוֹתֵיהֶם, שֶׁהִיא תּוֹרַת ה' תְּמִימָה, שְׁכִינָה קְדוֹשָׁה, מֵעֶשֶׂר מִדּוֹת.</p>\n<p>וְתַלְמִידֵי רַבּוֹתֵינוּ, אוֹתָם הַדְּבָרִים שֶׁלָּהֶם כְּמוֹ אֲכִילַת שְׁיָרֵי מְנָחוֹת. וְיֵשׁ אֲחֵרִים שֶׁמִּתְגַּבְּרִים עֲלֵיהֶם, שֶׁתּוֹרָתָם כַּאֲכִילַת מְנָחוֹת עַצְמָן, וְלֹא שְׁיָרֵי מְנָחוֹת. וְיֵשׁ אֲחֵרִים שֶׁתּוֹרָתָם אֲכִילַת קָדָשִׁים, מַאֲכָלִים מִכַּמָּה מִינִים לַמֶּלֶךְ. וְאֶת כָּל הַמְּנָחוֹת שֶׁל מַאֲכָלִים שֶׁל קָרְבָּנוֹת צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַקְרִיב לוֹ כֻּלָּם בְּבֵיתוֹ, שֶׁהִיא הַשְּׁכִינָה. וְזוֹהִי הַמִּצְוָה לְהַקְרִיב קָרְבָּנוֹת בְּבֵית הַבְּחִירָה, לְקַיֵּם (ירמיה ט) כִּי אִם בְּזֹּאת יִתְהַלֵּל הַמִּתְהַלֵּל וְגוֹ'.</p>\n<p>לְמֶלֶךָ שֶׁעֲבָדָיו וְשָׂרָיו וְשַׁלִּיטֵי מַלְכוּתוֹ שׁוֹלְחִים לוֹ כַּמָּה דוֹרוֹנוֹת. אָמַר: מִי שֶׁרוֹצֶה לִשְׁלֹחַ לִי דּוֹרוֹן, לֹא יִשְׁלַח, רַק בִּידֵי הַגְּבִירָה, לְקַיֵּם בָּהּ (תהלים קג) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. וּמִשּׁוּם זֶה נִקְרֵאת הַשְּׁכִינָה קָרְבָּן לַה', עֹלָה לַה', אָשָׁם לַה', וַאֲפִלּוּ קָרְבַּן נִדּוֹת וְיוֹלְדוֹת וּמְצֹרָעִים וְזָבִים וְזָבוֹת, הַכֹּל צָרִיךְ לְהַקְרִיב לַה' וּשְׁכִינָתוֹ, וְאַחַר כָּךְ הִיא מְחַלֶּקֶת לַכֹּל. זֶהוּ שֶׁכָּתוּב (משלי לא) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. וַאֲפִלּוּ מְזוֹן הַחַיּוֹת, כְּגוֹן קָרְבַּן שְׂעוֹרִים מַאֲכַל הַבְּהֵמוֹת, וּמַאֲכַל עֲבָדִים וּשְׁפָחוֹת שֶׁל בֵּית הַמֶּלֶךְ, וַאֲפִלּוּ שֶׁל כְּלָבִים וְשֶׁל חֲמוֹרִים וּגְמַלִּים, לְקַיֵּם בָּהּ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. וּמִנַּיִן לָנוּ שֶׁעַל יָדֶיהָ מִתְחַלֵּק הַכֹּל? שֶׁכָּתוּב וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ.</p>\n<p>מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בֶּן י\"ה, ו' בֶּן י\"ה, כּוֹלֵל יה\"ו. וּשְׁלֵמוּתוֹ ה', הִיא עוֹלָה לַיהֹוָ\"ה. קָרְבָּן לַיהֹוָ\"ה. שְׁלָמִים לַה'. קְרֵבוּתוֹ, שְׁלֵמוּתוֹ, שֶׁבּוֹ הִשְׁלִים יה\"ו, לִהְיוֹת יְהֹוָ\"ה.</p>\n<p>וְהַכֹּל חוֹזֵר בּוֹ, וְלָכֵן (שמות כב) זֹּבֵחַ לָאֱלֹהִים יָחֳרָם בִּלְתִּי לַה' לְבַדּוֹ, שֶׁלֹּא נוֹתֵן שִׁלְטוֹן לַצַּד הָאַחֵר בַּקָּרְבָּן, שֶׁכָּל אֱלֹהִים אֲחרִים הֵם עוֹלַם הַפֵּרוּד, וְאֵין לָהֶם קִרְבָה וְיִחוּד, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִפְרִידָם מִשְּׁמוֹ כְּמוֹ שֶׁהִפְרִיד חֹשֶׁךְ מֵאוֹר. זֶהוּ שֶׁכָּתוּב (בראשית א) וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ. וּמִי שֶׁמְּקָרֵב לַקָּדוֹשׁ בָּרוּךְ הוּא מַה שֶּׁהִפְרִיד, כְּמִי שֶׁקֵּרַב טֻמְאַת הַנִּדָּה לְבַעְלָהּ, וְזֶהוּ סוֹד (ויקרא יח) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ.</p>\n<p>וְלֹא תְגַלֶּה עֶרְוָתָהּ הַזֶּה - קֵרוּב, שֶׁכָּל הָעֲרָיוֹת שְׁקוּלִים לַעֲבוֹדָה זָרָה שֶׁל כָּל הַצְּדָדִים הָאֲחֵרִים, עֲלֵיהֶם נֶאֱמַר (בראשית י) מֵאֵלֶּה נִפְרְדוּ אִיֵּי הַגּוֹיִם בְּאַרְצֹתָם. וְכָתוּב, לִלְֹשנֹתָם בְּאַרְצֹתָם בְּגוֹיֵהֶם. כִּי שָׁם בָּלַל ה' שְׂפַת כָּל הָאָרֶץ וּמִשָּׁם הֱפִיצָם ה'. וְכָל מִי שֶׁמַּקְרִיב שׁוּם קָרְבָּן לַצְּדָדִים הָאֲחֵרִים, הַקָּדוֹשׁ בָּרוּךְ הוּא מַפְרִישׁוֹ מִשְּׁמוֹ, וְאֵין לוֹ חֵלֶק בִּשְׁמוֹ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּחַר בְּיִשְׂרָאֵל מִכָּל שְׁאָר אֻמּוֹת, זֶהוּ שֶׁכָּתוּב וּבְךְ בָּחַר ה'. וְחִלְּקָם מֵהֶם לְחֶלְקוֹ, זֶהוּ שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ.</p>\n<p>וְלָכֵן נָתַן לָהֶם תּוֹרָה מִשְּׁמוֹ. (שמות ג) זֶה שְּׁמִי לְעֹלָם וְזֶה זִכְרִי לְדֹר דֹּר, וַהֲרֵי פֵּרְשׁוּהָ, י\"ה עִם שְׁמִי - שס\"ה. ו\"ה עִם זִכְרִי - רמ\"ח. בְּכָל מִצְוָה וּמִצְוָה קוֹשֵׁר אֶת יִשְׂרָאֵל בִּשְׁמוֹ, לִהְיוֹת כָּל אֵיבָר וְאֵיבָר שֶׁלָּהֶם חֵלֶק גּוֹרָלוֹ וִירֻשָּׁתוֹ, וְלָכֵן זֹּבֵחַ לָאֱלֹהִים יָחֳרָם וְכוּ'.</p>\n<p>צְרִיכִים יִשְׂרָאֵל לְשַׁתֵּף אֶת ה' בַּהֲלִיכָתָם, בִּיקִיצָתָם. זֶהוּ שֶׁכָּתוּב (משלי ו) בְּהִתְהַלֶּכְךְ תַּנְחֶה אֹתָךְ בְּשָׁכְבְּךְ תִּשְׁמֹר עָלֶיךְ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ. קָם אוֹתוֹ תַּלְמִיד וְהִשְׁתַּטַּח לְפָנָיו וְאָמַר: אַשְׁרֵי הוּא חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה לִשְׁמֹעַ דְּבָרִים אֵלֶּה, כֻּלָּם שֵׁם ה' בְּכָל צַד, וְלֹא יוֹצֵא מִמֶּנּוּ הַחוּצָה בְּכָל צְדָדָו. (ע\"כ רעיא מהימנא).</p>"],[9522012243,"<p>וְכִי תֹאמְרוּ מַה נֹּאכַל וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (תהלים לז) בְּטַח בַּה' וַעֲשֵׂה טוֹב שְׁכָן אֶרֶץ וּרְעֵה אֱמוּנָה. לְעוֹלָם יִהְיֶה בֶּן אָדָם זָהִיר בְּרִבּוֹנוֹ, וִידַבֵּק לִבּוֹ בָּאֱמוּנָה הָעֶלְיוֹנָה כְּדֵי שֶׁיִּהְיֶה שָׁלֵם עִם רִבּוֹנוֹ. שֶׁכְּשֶׁיִּהְיֶה שָׁלֵם עִמּוֹ, לֹא יוּכְלוּ לְהַזִּיקוֹ כָּל בְּנֵי הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, בְּטַח בַּה' וַעֲשֵׂה טוֹב, מַה זֶּה וַעֲשֵׂה טוֹב? אֶלָּא כָּךְ שָׁנִינוּ, בַּמַּעֲשֶׂה שֶׁלְּמַטָּה מִתְעוֹרֵר מַעֲשֶׂה שֶׁלְּמַעְלָה. וַהֲרֵי פֵּרְשׁוּהָ, וַעֲשִׂיתֶם אֹתָם - כִּבְיָכוֹל אַתֶּם תַּעֲשׂוּ אוֹתָם, מִשּׁוּם שֶׁבְּאוֹתָהּ הִתְעוֹרְרוּת שֶׁלָּכֶם שֶׁאַתֶּם עוֹשִׂים לְמַטָּה, מִתְעוֹרֵר לְמַעְלָה, וְעַל זֶה כָּתוּב וַעֲשֵׂה טוֹב, וְאֵין טוֹב אֶלָּא צַדִּיק, שֶׁכָּתוּב (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב. כֵּיוָן שֶׁאַתֶּם עוֹשִׂים אֶת זֶה, וַדַּאי שֶׁהַטּוֹב הַזֶּה יִתְעוֹרֵר, וְאָז שְׁכָן אֶרֶץ וּרְעֵה אֱמוּנָה, וְהַכֹּל אֶחָד.</p>\n<p>שְׁכָן אֶרֶץ, אֶרֶץ הָעֶלְיוֹנָה, שֶׁהֲרֵי אֵין לְךְ בָּעוֹלָם שֶׁיָּכוֹל לִשְׁרוֹת עִמָּהּ עַד שֶׁיִּתְעוֹרֵר הַטּוֹב הַזֶּה אֵלֶיהָ. כֵּיוָן שֶׁמְּעוֹרֵר אוֹתוֹ, כִּבְיָכוֹל הוּא עוֹשֶׂה אוֹתוֹ, וְאָז שְׁכָן אֶרֶץ, שְׁרֵה בְתוֹכָהּ וֶאֱכֹל פִּרְיָהּ, הִשְׁתַּעֲשֵׁעַ עִמָּהּ. וּרְעֵה אֱמוּנָה, זוֹ אֶרֶץ, וְהַכֹּל אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צב) וֶאֱמוּנָתְךְ בַּלֵּילוֹת. וּרְעֵה אֱמוּנָה, הַנְהִיגָהּ בְּכָל רְצוֹנְךְ.</p>\n<p>וְאִם לֹא תִתְעוֹרֵר כְּנֶגְדָּהּ, הַטּוֹב הַזֶּה מִתְרַחֵק מִמֶּנָּה, וְאַל תִּתְקָרֵב אֵלֶיהָ, אַל תִּתְקָרֵב לְתוֹךְ כִּבְשַׁן אֵשׁ יוֹקֶדֶת. וְאִם תִּקְרַב אֵלֶיהָ - בְּפַחַד, כְּמִי שֶׁפּוֹחֵד מִן הַמָּוֶת, שֶׁהֲרֵי אָז הָאֵשׁ דּוֹלֶקֶת וְשׂוֹרֶפֶת אֶת הָעוֹלָם בְּשַׁלְהֲבוֹתֶיהָ. וְכֵיוָן שֶׁמִּתְעוֹרֵר כְּנֶגְדָּהּ הַטּוֹב הַזֶּה, אָז הוּא שׁוֹרֶה בְתוֹכָהּ, וְאַתָּה אַל תִּפְחַד מִמֶּנָּה. אָז - (איוב כב) וְתִגְזַר אֹמֶר וְיָקָם לָךְ וְעַל דְּרָכֶיךְ נָגַהּ אוֹר.</p>\n<p>בֹּא רְאֵה, בְּנֵי הָאֱמוּנָה מַנְהִיגִים אֶת זֹּאת לִרְצוֹנָם בְּכָל יוֹם. מִי הֵם בְּנֵי הָאֱמוּנָה? אוֹתָם שֶׁמְּעוֹרְרִים הַטּוֹב הַזֶּה כְּנֶגְדּוֹ, וְלֹא חָס עַל שֶׁלּוֹ, וְיוֹדְעִים שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא יִתֵּן לוֹ יוֹתֵר, כְּמוֹ שֶׁנֶּאֱמַר (משלי יא) יֵשׁ מְפַזֵּר וְנוֹסָף עוֹד. מָה הַטַּעַם? מִשּׁוּם שֶׁזֶּה מְעוֹרֵר בְּרָכוֹת כְּנֶגְדּוֹ, וְלֹא יֹאמַר: אִם אֶתֵּן אֶת זֶה עַכְשָׁו, מָה אֶעֱשֶׂה לְמָחָר? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ בְּרָכוֹת עַד בְּלִי דַּי, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>וּמִשּׁוּם כָּךְ, וְכִי תֹאמְרוּ מַה נֹּאכַל בַּשָּׁנָה הַשְּׁבִיעִת וְגוֹ', מַה כָּתוּב? וְצִוִּיתִי אֶת בִּרְכָתִי לָכֶם בַּשָּׁנָה הַשִּׁשִּׁית וְעָשָׂת אֶת הַתְּבוּאָה לִשְׁלֹשׁ הַשָּׁנִים. וְעָשָׂת?! וְעָשְׂתָה הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה וְעָשָׂת? אֶלָּא לְהוֹצִיא ה', שֶׁיֵּשׁ לָהּ שְׁמִטָּה וּמְנוּחָה וְלֹא עוֹשָׂה מַעֲשֶׂה. כָּתוּב (שמות טז) רְאוּ כִּי ה' וְגוֹ', נֹתֵן לָכֶם בַּיּוֹם הַשִּׁשִּׁי לֶחֶם יוֹמָיִם וְגוֹ'. כְּגוֹן זֶה, וְצִוִּיתִי אֶת בִּרְכָתִי לָכֶם בַּשָּׁנָה הַשִּׁשִּׁית וְגוֹ'.</p>"],[9522012244,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ, פָּגְעוּ בְּאוֹתוֹ הַר, מָצְאוּ שְׁנֵי גְבָרִים שֶׁהָיוּ הוֹלְכִים. בֵּין כָּךְ רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא, וְאָמַר לָהֶם: בְּבַקָּשָׁה מִכֶּם, תְּנוּ לִי מְזוֹן פַּת לֶחֶם, שֶׁשְּׁנֵי יָמִים אֵלֶּה שֶׁתָּעִיתִי בַמִּדְבָּר וְלֹא אָכַלְתִּי דָבָר. נִשְׁמַט אֶחָד מֵאוֹתָם שְׁנֵי גְבָרִים, וְהוֹצִיא מְזוֹנוֹ שֶׁהוּא הֵבִיא לַדֶּרֶךְ, וְנָתַן לוֹ וְהֶאֱכִיל וְהִשְׁקָה אוֹתוֹ. אָמַר לוֹ חֲבֵרוֹ: מַה תַּעֲשֶׂה עִם הַמָּזוֹן, שֶׁהֲרֵי אֲנִי אֶת שֶׁלִּי אֲנִי אוֹכֵל? אָמַר לוֹ: וּמָה עַל שֶׁלְּךְ אֲנִי הוֹלֵךְ? יָשַׁב אֶצְלוֹ אוֹתוֹ עָנִי, עַד שֶׁאָכַל כָּל מַה שֶּׁהָיָה אֶצְלוֹ, וְאוֹתוֹ לֶחֶם שֶׁנִּשְׁאַר נָתַן לוֹ לַדֶּרֶךְ, וְהָלַךְ לוֹ.</p>\n<p>אָמַר רַבִּי חִיָּיא, לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁדָּבָר זֶה יֵעָשֶׂה עַל יָדֵינוּ. אָמַר רַבִּי יוֹסֵי, אוּלַי נִגְזַר דִּין עַל אוֹתוֹ אִישׁ, וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַזְמִין לְפָנָיו אֶת זֶה כְּדֵי לְהַצִּילוֹ. בְּעוֹד שֶׁהָלְכוּ, הִתְעַיֵּף אוֹתוֹ אִישׁ בַּדֶּרֶךְ. אָמַר לוֹ חֲבֵרוֹ: וְלֹא אָמַרְתִּי לְךְ שֶׁלֹּא תִתֵּן לֶחֶם לָאַחֵר? אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, הֲרֵי מָזוֹן עִמָּנוּ, נִתֵּן לוֹ לֶאֱכֹל. אָמַר רַבִּי יוֹסֵי, הֲתִרְצֶה לְהוֹצִיא מִמֶּנּוּ אֶת הַזְּכוּת? נֵלֵךְ וְנִרְאֶה, שֶׁהֲרֵי בְּוַדַּאי בְּצוּרַת פָּנָיו שֶׁל זֶה, הַדְּפוּס שֶׁל הַמָּוֶת נֶאֱחָז, וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְזַמֵּן זְכוּתוֹ כְּדֵי לְהַצִּילוֹ.</p>\n<p>בֵּין כָּךְ יָשַׁב אוֹתוֹ הָאִישׁ וְיָשַׁן תַּחַת אִילָן אֶחָד, וַחֲבֵרוֹ הִתְרַחֵק מִמֶּנּוּ וְיָשַׁב בְּדֶרֶךְ אַחֶרֶת. אָמַר רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, כָּעֵת נֵשֵׁב וְנִרְאֶה, שֶׁוַּדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהַרְחִישׁ לוֹ נֵס. קָמוּ וְחִכּוּ. בֵּין כָּךְ רָאוּ צוּרָה אַחַת שֶׁל שַׁלְהָבוֹת עוֹמֶדֶת לְפָנָיו. אָמַר רַבִּי חִיָּיא, אוֹי עַל אוֹתוֹ הָאִישׁ, שֶׁעַכְשָׁו יָמוּת. אָמַר רַבִּי יוֹסֵי, אַשְׁרֵי אוֹתוֹ הָאִישׁ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַרְחִישׁ לוֹ נֵס. בֵּין כָּךְ יָרַד מֵאִילָן אֶחָד נָחָשׁ אֶחָד וְרָצָה לְהָרְגוֹ. קָמָה אוֹתָהּ צוּרָה עָלָיו וַהֲרָגַתּוּ. סוֹבְבָה הַצּוּרָה בְּרֹאשָׁהּ, וְהָלְכָה לָהּ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וְלֹא אָמַרְתִּי לְךְ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהַרְחִישׁ לוֹ נֵס, וְלֹא תוֹצִיא זְכוּתוֹ מִמֶּנּוּ? בֵּין כָּךְ הִתְעוֹרֵר אוֹתוֹ הָאִישׁ, וְקָם וְהָלַךְ לוֹ. אָחֲזוּ בּוֹ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי, וְנָתְנוּ לוֹ לֶאֱכֹל. אַחַר שֶׁאָכַל, הֶרְאוּ לוֹ הַנֵּס שֶׁהִרְחִישׁ לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (תהלים לז) בְּטַח בַּה' וַעֲשֵׂה טוֹב שְׁכָן אֶרֶץ וּרְעֵה אֱמוּנָה. אַשְׁרֵי חֶלְקוֹ שֶׁל הָאִישׁ שֶׁעוֹשֶׂה טוֹב מִשֶּׁלּוֹ, שֶׁהֲרֵי מְעוֹרֵר טוֹב עִם כְּנֶסֶת יִשְׂרָאֵל, וּבַמֶּה? בִּצְדָקָה. שֶׁכְּשֶׁצְּדָקָה מִתְעוֹרֶרֶת, הוּא טוֹב, אָז מִתְעוֹרֵר אֶל כְּנֶסֶת יִשְׂרָאֵל, וְעַל זֶה כָּתוּב (משלי י) וּצְדָקָה תַּצִּיל מִמָּוֶת. מָה הַטַּעַם? מִשּׁוּם שֶׁצְּדָקָה הִיא עֵץ הַחַיִּים, וּמִתְעוֹרֶרֶת עַל אוֹתוֹ עֵץ הַמָּוֶת, וְלוֹקֵחַ אוֹתָם שֶׁאֲחוּזִים בּוֹ וּמַצִּילָם מֵהַמָּוֶת. מִי גָרַם לְאוֹתוֹ עֵץ חַיִּים שֶׁיִּתְעוֹרֵר לָזֶה? הֱוֵה אוֹמֵר, אוֹתָהּ צְדָקָה שֶׁהוּא עוֹשֶׂה, כִּבְיָכוֹל הוּא עָשָׂה אוֹתוֹ לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קו) עֹשֵׂה צְדָקָה צְדָקָה בְכָל עֵת. וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012245,"<p>וְהִתְנַחַלְתֶּםֹ אֹתָם לִבְנֵיכֶם וְגוֹ', לְעֹלָם בָּהֶם תַּעֲבֹדוּ וְגוֹ'. מִצְוָה זוֹ לַעֲבֹד בְּעֶבֶד כְּנַעֲנִי, שֶׁכָּתוּב לְעֹלָם בָּהֶם תַּעֲבֹדוּ, וְהֵם מֵהַצַּד שֶׁל חָם שֶׁגִּלָּה עֲרָיוֹת, שֶׁנֶּאֱמַר עָלָיו (בראשית ט) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. לָמָּה עֶבֶד עֲבָדִים? אֶלָּא עֶבֶד לְאוֹתוֹ עֶבֶד עוֹלָם, שֶׁהוּא עוֹלָמוֹ שֶׁל יוֹבֵל. וְאִם תֹּאמַר שֶׁהֵי אֲחִיהֶם שֶׁל שֵׁם וְיֶפֶת הָיָה, לָמָּה לֹא הָיָה כָּךְ כְּמוֹתָם? וְכֵן, מֵהַזֶּרַע שֶׁל חָם הָיָה אֱלִיעֶזֶר עֶבֶד אַבְרָהָם, לָמָּה לֹא הָיָה כְּמוֹתוֹ, שֶׁיָּצָא צַדִּיק, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹדָה בְּבִרְכָתוֹ כְּשֶׁבֵּרַךְ אוֹתוֹ לָבָן?</p>"],[9522012246,"<p>אֶלָּא וַדַּאי כָּאן בְּסוֹד הַגִּלְגּוּל, גּוֹלֵל אוֹר מִפְּנֵי חֹשֶׁךְ - עֶבֶד אַבְרָהָם שֶׁיָּצָא מֵהַחֹשֶׁךְ, וְזֶה הַזֶּרַע שֶׁל חָם, דַּיּוֹ לְעֶבֶד לִהְיוֹת כְּרַבּוֹ, שֶׁהוּא אַבְרָהָם, שֶׁיָּצָא מִתֶּרַח עוֹבֵד עֲבוֹדָה זָרָה, וְחֹשֶׁךְ מִפְּנֵי אוֹר - זֶה יִשְׁמָעֵאל שֶׁיָּצָא מֵאַבְרָהָם, וְעֵשָׂו מִיִּצְחָק.</p>\n<p>וְסוֹד תַּעֲרֹבֶת טִפּוֹת בְּמָקוֹם שֶׁאֵינוֹ שֶׁלּוֹ גָּרַם אֶת זֶה. מִי שֶׁמְּעָרֵב טִפָּה שֶׁלּוֹ בְּשִׁפְחָה מַחֲלַת בַּת יִשְׁמָעֵאל, אוֹ בְּבַת אֵל נֵכָר, שֶׁהֵם רָע חֹשֶׁךְ, וְהַטִּפָּה שֶׁלּוֹ טוֹב אוֹר, (שם א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, מְעָרֵב טוֹב עִם רָע, עוֹבֵר עַל מַאֲמַר רִבּוֹנוֹ שֶׁאָמַר, (שם ב) וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ.</p>\n<p>הַקָּדוֹשׁ בָּרוּךָ הוּא מַרְכִּיב אוֹתוֹ בְּאוֹתוֹ שֶׁעֵרַב (רב), וּמְבִיאוֹ בְגִלְגּוּל לְקַבֵּל עָנְשׁוֹ. אִם חָזַר בִּתְשׁוּבָה, הִתְעַסֵּק בַּתּוֹרָה וְהִפְרִיד טוֹב מֵרָע, שֶׁהֵם אִסּוּר וְהֶתֵּר, טֻמְאָה וְטָהֳרָה, כָּשֵׁר וּפָסוּל - בָּזֶה נִפְרַד הָרָע מֵהַטּוֹב, שֶׁנֶּאֱמַר בּוֹ וַיִּיצֶר, יְצִירָה לְטוֹב וִיצִירָה לְרָע. בַּתּוֹרָה הִפְרִיד אוֹתָם. הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִישׁ לוֹ נְשָׁמָה מִמֶּנּוּ, שֶׁיִּהְיֶה שׁוֹלֵט עַל שְׁנֵיהֶם, בְּאֶחָד שֶׁהוּא אוֹר - הָעוֹלָם הַבָּא, וּבְאֶחָד שֶׁהוּא חֹשֶׁךְ - הָעוֹלָם הַזֶּה. זֶהוּ שֶׁכָּתוּב וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים.</p>\n<p>וּכְפִי זְכֻיּוֹת וְחוֹבוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ, הָעוֹשֶׂה מִצְוָה אַחַת מֵיטִיבִין לוֹ. בֵּינוֹנִי - זְכֻיּוֹת וְחוֹבוֹת שְׁקוּלִים, חֲצִי זְכֻיּוֹת לְמַעְלָה (וחצי למטה) וַחֲצִי חֲטָאָיו לְמַטָּה, וְזֶה סוֹד (אסתר ה) מַה שְּׁאֵלָתֵךְ וְיִנָּתֶן לָךְ וּמַה בַּקָּשָׁתֵךְ עַד חֲצִי הַמַּלְכוּת וְתֵעָשׂ. צַדִּיק גָּמוּר - כָּל זְכֻיּוֹתָיו לְמַעְלָה, וְחוֹבוֹתָיו לְמַטָּה. רָשָׁע גָּמוּר - חוֹבוֹתָיו לְמַעְלָה, וּזְכֻיּוֹתָיו לְמַטָּה.</p>\n<p>וּבֶן אָדָם שֶׁחָטָא בְגָלוּי, הוּא בִּשְׁנֵי דְרָגוֹת: אִם חָזַר בִּתְשׁוּבָה בְּגָלוּי - בֵּין צַדִּיקִים, מִשּׁוּם שֶׁיּוֹדְעִים דִּינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹמְרִים עַצְמָם מִלַּחֲטֹא. וּבִמְכֻסֶּה - בֵּין רְשָׁעִים, לְקַיֵּם בָּהֶם (איוב יא) וְעֵינֵי רְשָׁעִים תִּכְלֶינָה.</p>\n<p>וּמִשּׁוּם זֶה הַחֵטְא שֶׁאָדָם עָבַר עַל (בראשית ב) וַיְצַו ה' אֱלֹהִים, וּפֵרְשׁוּהָ אֵין צַו אֶלָּא עֲבוֹדָה זָרָה, עָבַר עָלָיו, הִרְכִּיב אוֹתוֹ בְּטִפַּת תֶּרַח, שֶׁבּוֹ הִרְגִּיז אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁעָבַר עַל צַו מֵעֲבוֹדָה זָרָה. חָזַר בִּתְשׁוּבָה, וְשָׁבַר צַלְמֵי עֲבוֹדָה זָרָה וְכָל מְזוֹנוֹ. הוּא תִּקֵּן בְּמַה שֶּׁחָטָא, וְשָׁבַר אֶת הַחֵטְא וְאֶת הַבִּנְיָן הָרָע שֶׁבָּנָה, וְהִמְלִיךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ עַל הָעוֹלָם.</p>"],[9522012247,"<p>בַּמֶּה, ? מִשּׁוּם שֶׁקִּדֵּשׁ שְׁמוֹ יִתְבָּרַךְ בָּרַבִּים וְנִכְנַס לָאֵשׁ לִשְׂרֹף אֶת עַצְמוֹ, לְקַיֵּם בּוֹ (דברים ז) פְּסֵילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ. וְלֹא עוֹד, אֶלָּא שֶׁאֶת אָבִיו תֶּרַח הֶחֱזִיר בִּתְשׁוּבָה, וְהִכְנִיס אוֹתוֹ וְאֶת אִמּוֹ וְאֶת כָּל פַּרְנְסֵי אוֹתוֹ דוֹר לְגַן עֵדֶן, וְכָךְ הִתְלַבֵּן בָּאֵשׁ כַּכֶּסֶף, שֶׁהִיא מַטְבֵּעַ הַמֶּלֶךְ, וְזִיֵּף אוֹתָהּ בְּעֹפֶרֶת, הִכְנִיס אוֹתָהּ לָאֵשׁ, וְיָצְאָה הָעֹפֶרֶת הַחוּצָה, יִשְׁמָעֵאל. וּלְפִיכָךְ יָצָא מְצַחֵק בַּעֲבוֹדָה זָרָה. וְנִשְׁאַר אָדָם מְלֻבָּן, וְזֶהוּ שִׁנּוּי הַשֵּׁם. שֶׁכְּשֶׁמִּתְגַּלְגֵּל אָדָם, צָרִיךְ לַעֲשׂוֹת לוֹ שִׁנּוּי הַשֵּׁם, שִׁנּוּי מָקוֹם, וְשִׁנּוּי מַעֲשֶׂה.</p>\n<p>אַחַר כָּךְ בָּא יִצְחָק, וְהִתְחַזֵּק בּוֹ מֵהַחֵטְא הַשֵּׁנִי שֶׁנֶּאֱמַר בּוֹ עַל הָאָדָם, שֶׁזֶּה שְׁפִיכוּת דָּמִים, וְזֶה גָרַם אֶת הַנִּסָּיוֹן שֶׁל יִצְחָק בְּסַכִּין, וְהִתְבָּרֵר בּוֹ, כְּמִי שֶׁבּוֹרֵר אֹכֶל מִתּוֹךְ פְּסֹלֶת, וְיָצְאָה הַפְּסֹלֶת הַחוּצָה, עֵשָׂו שׁוֹפֵךְ דָּמִים.</p>\n<p>אַחַר כָּךְ בָּא יַעֲקֹב וְהִרְכִּיב אוֹתוֹ בְּלָבָן, וְנַעֲשָׂה עֶבֶד אֵלָיו, זֶהוּ שֶׁכָּתוּב (בראשית כט) אֶעֱבָדְךְ שֶׁבַע שָׁנִים בְּרָחֵל. וּבְאוֹתָהּ סִבָּה שֶׁהֱחֱלִיפָהּ בַּאֲחוֹתָהּ, עָשָׂה שֶׁבַע שָׁנִים אֲחֵרוֹת, לְהוֹצִיא שְׁתֵּי טִפּוֹת שֶׁזָּרַק אָדָם בְּמָקוֹם נָכְרִי, וְזֶה גִּלּוּי עֲרָיוֹת, וְזֶהוּ לֵאמֹר. וְהוֹצִיאָם מִלָּבָן הָאֲרַמִּי, נָחָשׁ.</p>\n<p>וּבִשְׁלֹשֶת אֵלֶּה הָיָה לְאָדָם שִׁנּוּי הַשֵּׁם, וְשִׁנּוּי מָקוֹם, וְשִׁנּוּי מַעֲשֶׂה. שִׁנּוּי הַשֵּׁם - בְּאַבְרָהָם. וְשִׁנּוּי מָקוֹם - בְּיִצְחָק. וְשִׁנּוּי מַעֲשֶׂה - בְּיַעֲקֹב. וְאִם לְזֶה שֶׁנֶּאֱמַר בּוֹ (איוב כח) אָז רָאָהּ וַיְסַפְּרָהּ קִבֵּל בִּתְשׁוּבָה, כָּל שֶׁכֵּן לַאֲחֵרִים.</p>\n<p>וּמִשּׁוּם זֶה, עֶבֶד טוֹב הַמָּקוֹם גּוֹרֵם, וְעֶבֶד רָע גַּם כֵּן. אֲבָל שְׁאָר עֲבָדִים, לְעֹלָם בָּהֶם תַּעֲבֹדוּ. קָמוּ בַּעֲלֵי הַיְשִׁיבָה וְאָמְרוּ, (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ, שֶׁכָּכָ\"ה בְּגִימַטְרִיָּא מֹשֶׁה. קָם הָרוֹעֶה הַנֶּאֱמָן וְאָמַר, אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו. (ע\"כ רעיא מהימנא).</p>"],[9522012248,"<p>כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים וְגוֹ'. מִצְוָה לַעֲבֹד בְּכָל מִינֵי עֲבוֹדָה בַּמִּקְדָּשׁ, וּמִחוּץ לַמִּקְדָּשׁ בְּכָל אוֹתָן עֲבוֹדוֹת שֶׁנִּקְרָאוֹת עֲבוֹדָה, בִּתְפִלָּה, לְהִשְׁתַּדֵּל אַחַר מִצְווֹת הַתּוֹרָה, שֶׁהַכֹּל נִקְרָא עֲבוֹדָה, כְּעֶבֶד שֶׁמִּשְׁתַּדֵּל אַחַר רַבּוֹ בְּכָל מַה שֶּׁצָּרִיךְ.</p>\n<p>מִשּׁוּם שֶׁיִּשְׂרָאֵל קָרָא לָהֶם עֲבָדִים, שֶׁכָּתוּב (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים עֲבָדַי הֵם. מָה הַטַּעַם הֵם עֲבָדִים? מִשּׁוּם שֶׁכָּתוּב אֲשֶׁר הוֹצֵאתִי אוֹתָם מֵאֶרֶץ מִצְרָיִם. וּמִשּׁוּם כָּךְ כָּתוּב בַּעֲשֶׂרֶת הַדִּבְּרוֹת אַחַר כָּךְ, שֶׁכָּתוּב אָנֹכִי ה' אֱלֹהֶיךְ אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם, לַעֲבֹד אוֹתוֹ כְּעֶבֶד שֶׁעוֹבֵד אֶת רַבּוֹ שֶׁפָּדָה אוֹתוֹ מִמָּוֶת, וְשֶׁפָּדָה אוֹתוֹ מִכָּל הָרָעוֹת שֶׁל הָעוֹלָם.</p>\n<p>בִּשְׁנֵי סוּגִים (שמות אלו) נִקְרָאִים יִשְׂרָאֵל לַקָּדוֹשׁ בָּרוּךְ הוּא עֲבָדִים, שֶׁכָּתוּב עֲבָדַי הֵם (שם), וְנִקְרָאִים בָּנִים, שֶׁכָּתוּב (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. בִּזְמַן שֶׁמַּכִּיר הָאָדָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדֶרֶךְ כְּלָל, אָז הוּא נִקְרָא עֶבֶד שֶׁעוֹשֶׂה מִצְוַת רַבּוֹ, וְאֵין לוֹ רְשׁוּת לְחַפֵּשׂ בִּגְנָזָיו וּבְסוֹדוֹת בֵּיתוֹ. בִּזְמַן שֶׁמַּכִּיר אוֹתוֹ הָאָדָם בְּדֶרֶךְ פְּרָט, אָז נִקְרָא בֵּן, אָהוּב שֶׁלּוֹ, כְּמוֹ בֵּן שֶׁמְּחַפֵּשׂ בִּגְנָזָיו, בְּכָל סוֹדוֹת בֵּיתוֹ.</p>\n<p>וְאַף עַל גַּב שֶׁנִּקְרָא בֵּן, בֵּן בְּכוֹר לַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, אַל יוֹצִיא אֶת עַצְמוֹ מִכְּלָל שֶׁל עֶבֶד, לַעֲבֹד אֶת אָבִיו בְּכָל הָעֲבוֹדוֹת שֶׁהֵן כְּבוֹד אָבִיו. וְכָךְ צָרִיךְ לְכָל בֶּן אָדָם לִהְיוֹת בֵּן לְגַבֵּי אָבִיו, לְחַפֵּשׂ בִּגְנָזָיו וְלָדַעַת סוֹדוֹת בֵּיתוֹ וּלְהִשְׁתַּדֵּל אַחֲרֵיהֶם, וְלִהְיוֹת עֶבֶד לְגַבֵּי אָבִיו.</p>"],[9522012249,"<p>וְסוֹד הַדָּבָר - שְׁתֵּי דְרָגוֹת הֵן לְמַעְלָה שֶׁצָּרִיךְ בֶּן אָדָם לְהִתְעַטֵּר בָּהֶן, וְהֵן סוֹד הָאֱמוּנָה, וְהֵן אַחַת. אַחַת סוֹד שֶׁל עֶבֶד, וְאַחַת סוֹד שֶׁל בֵּן. וְהָעֶבֶד הַזֶּה נִקְרָא אֲדוֹן כָּל הָאָרֶץ. בֵּן, כְּמוֹ שֶׁבֵּאַרְנוּ, בְּנִי בְכֹרִי יִשְׂרָאֵל, וְהַכֹּל סוֹד אֶחָד שֶׁל הָאֱמוּנָה. וְצָרִיךְ בֶּן אָדָם לְהִתְעַטֵּר בַּדְּרָגוֹת הַלָּלוּ, לְהִכָּלֵל בְּסוֹד הָאֱמוּנָה.</p>\n<p>עָבֶד, לַעֲבֹד בְּכָל מִינֵי עֲבוֹדָה, בִּתְפִלָּה שֶׁנִּקְרֵאת עֲבוֹדָה, כְּמוֹ אוֹתוֹ עֶבֶד שֶׁהוּא סוֹד עֶלְיוֹן, שֶׁלֹּא שׁוֹכֵךְ לְעוֹלָמִים תָּמִיד, וּמְשַׁבֵּחַ וּמְנַגֵּן תָּמִיד. וַהֲרֵי נִתְבָּאֵר בַּעֲבוֹדוֹת אֲחֵרוֹת, שֶׁכָּל הָעֲבוֹדוֹת וְדִבְרֵי הָעוֹלָמוֹת, כֻּלָּם הוּא עוֹשֶׂה וְעוֹבֵד. וּמִשּׁוּם זֶה נִקְרָא אָדוֹן, מִשּׁוּם שֶׁהוּא עֶבֶד לַעֲבד, נִקְרָא אֲדוֹן כָּל הָאָרֶץ. בֶּן אָדָם שֶׁמִּתְעַטֵּר בַּסּוֹד הַזֶּה, לִהְיוֹת עֶבֶד לַעֲבֹד עֲבוֹדַת רַבּוֹ, הוּא עוֹלֶה וּמִתְעַטֵּר לִהְיוֹת בַּדַּרְגָּה הַזּוֹ, וְנִקְרָא אַף כָּאן אָדוֹן, שֶׁהֲרֵי הוּא מְבָרֵךְ בְּכָל הָעֲבוֹדוֹת הָאֵלֶּה אֶת הָעוֹלָם הַזֶּה וּמַעֲמִידוֹ, וְעַל זֶה נִקְרָא אָדוֹן. (אדוני הארץ).</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל הַבֵּן הַזֶּה, שֶׁזּוֹכֶה לְהִשְׁתַּדֵּל לָדַעַת בְּגִנְזֵי אָבִיו וּבְכָל סוֹדוֹת בֵּיתוֹ, כְּמוֹ בֵּן יְחִידִי שֶׁהִשְׁלִיטוֹ אָבִיו בְּכָל גְּנָזָיו, וְזֶהוּ הַכָּבוֹד, שֶׁשּׁוֹלֵט עַל הַכֹּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לָדַעַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וּבְאוֹתָם הַגְּנָזִים שֶׁלּוֹ נִקְרָא בֵּן לַקָּדוֹשׁ בָּרוּךְ הוּא, בְּכָל כֹּחוֹת הַשָּׁמַיִם אֵין מִי שֶׁיִּמְחֶה בְיָדוֹ, בְּכָל שָׁעָה שֶׁמִּצְטָרֵךְ לְהִכָּנֵס אֶל אָבִיו. אַשְׁרֵי חֶלְקוֹ בְּכָל הָעוֹלָמוֹת. וּמִשּׁוּם זֶה, כְּשֶׁמִּשְׁתַּדֵּל לְהַכִּירוֹ בְּדֶרֶךְ פְּרָט, בִּסוֹד הַחָכְמָה, אָז נִקְרָא בֵּן.</p>\n<p>בָּעָֹבוֹדָה שֶׁבֶּן אָדָם עוֹבֵד לַקָּדוֹשׁ בָּרוּךְ הוּא יֵשׁ עֲבוֹדָה שֶׁצָּרִיךְ אָדָם לְהִכָּלֵל בִּשְׁנֵיהֶם, לִהְיוֹת עֶבֶד וּבֵן, לְהִתְעַטֵּר בַּקָּדוֹשׁ בָּרוּךְ הוּא. וּמַהוּ? זוֹ עֲבוֹדַת הַתְּפִלָּה, שֶׁצָּרִיךְ לִהְיוֹת בָּהּ עֶבֶד וּבֵן, לְהִכָּלֵל בַּדְּרָגוֹת הָעֶלְיוֹנוֹת הַלָּלוּ. לַעֲבֹד וּלְהַתְקִין תְּפִלָּה בְּסוֹד שֶׁל עֶבֶד, לַעֲבֹד אֶת הָעֲבוֹדָה שֶׁל תִּקּוּן הָעוֹלָמוֹת, וּלְהַדְבִּיק רְצוֹנוֹ בְּסוֹדוֹת הַחָכְמָה, לְהִתְדַּבֵּק בְּרַבּוֹ בִּגְנָזִים עֶלְיוֹנִים כָּרָאוּי.</p>\n<p>בֵּן נִדְבָּק תָּמִיד בְּאָבִיו לְלֹא פֵרוּד כְּלָל, אֵין מִי שֶׁיִּמְחֶה בְיָדוֹ. הָעֶבֶד עוֹשֶׂה עֲבוֹדַת רַבּוֹ וּמַתְקִין תִּקּוּנֵי הָעוֹלָם. מִי שֶׁיִּהְיֶה שְׁנֵיהֶם בִּכְלָל אֶחָד, בְּחִבּוּר אֶחָד, זֶהוּ אָדָם שֶׁמַּתְקִין אֶת סוֹד כָּל הָאֱמוּנָה בִּכְלָל אֶחָד, לְלֹא פֵרוּד כְּלָל, וּמְחַבֵּר אֶת הַכֹּל כְּאֶחָד. זֶהוּ בֶּן אָדָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז עָלָיו בְּכָל אוֹתָם חֲיָלוֹת וּמַחֲנוֹת שֶׁל כָּל הָעוֹלָמוֹת וּבְכָל אוֹתָם הָרְקִיעִים: הִזָּהֲרוּ בִּפְלוֹנִי נֶאֱמַן בֵּית הַמֶּלֶךְ, שֶׁכָּל גִּנְזֵי רַבּוֹ בְּיָדוֹ. אַשְׁרָיו בָּעוֹלָם הַזֶּה, וְאַשְׁרָיו בָּעוֹלָם הַבָּא.</p>\n<p>מֵאוֹתוֹ יוֹם וָהָלְאָה נוֹדָע הָאָדָם וְנִרְשָׁם בְּכָל הָעוֹלָמוֹת. בְּשָׁעָה שֶׁצָּרִיךְ, כָּל הַחֲיָלוֹת וְהַמַּחֲנוֹת, כֻּלָּם מֻזְהָרִים לִהְיוֹת אֶצְלוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה אֶלָּא אוֹתוֹ בִּלְבַדּוֹ. וְקוֹל מִתְעוֹרֵר: רָאוּי הוּא לְיָחִיד לִהְיוֹת אֵצֶל הַיָּחִיד וּלְהִתְעַסֵּק יָחִיד בְּיָחִיד.</p>\n<p>וְהַסּוֹד שֶׁל שְׁתֵּי הַדְּרָגוֹת הָאֵלּוּ מָצָאנוּ בְּפָסוּק אֶחָד, שֶׁכָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. וַיֹּאמֶר לִי עַבְדִּי אָתָּה - הֲרֵי עֶבֶד. יִשְׂרָאֵל - הֲרֵי בֵּן. שֶׁכַּאֲשֶׁר הֵם כְּלָל אֶחָד, אָז כָּתוּב אֲשֶׁר בְּךְ אֶתְפָּאָר. בָּרוּךָ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012250,"<p>אִם בְּחֻקֹּתַי תֵּלֵכוּ וְֹגוֹ'. רַבִּי חִיָּיא פָּתַח, (מיכה ו) עַמִּי זְכָר נָא מַה יָּעַץ בָּלָק מֶלֶךְ מוֹאָב וּמֶה עָנָה אֹתוֹ בִּלְעָם בֶּן בְּעוֹר וְגוֹ'. עַמִּי זְכָר נָא, אַשְׁרֵי חֶלְקוֹ שֶׁל הָעָם הַזֶּה שֶׁרִבּוֹנָם מוֹכִיחַ אוֹתָם כָּךְ. עַמִּי זְכָר נָא, אַף עַל גַּב שֶׁאַתֶּם סוֹטִים מִדַּרְכִּי - עַמִּי אַתֶּם, שֶׁאֵינִי רוֹצֶה לַעֲשׂוֹת לָכֶם כְּמַעֲשֵׂיכֶם.</p>\n<p>רַבִּי יִצְחָק אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל הָעָם שֶׁרִבּוֹנָם אוֹמֵר לָהֶם: עַמִּי מֶה עָשִׂיתִי לָךְ וּמָה הֶלְאֵתִיךְ עֲנֵה בִּי. מַה יָּעַץ בָּלָק מֶלֶךְ מוֹאָב. בְּכַמָּה דְבָרִים וּמַעֲשִׂים אָמַר לְהַשְׁמִיד אֶתְכֶם מֵהָעוֹלָם, וְכַמָּה כְשָׁפִים עוֹרֵר כְּנֶגְדְּכֶם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל: זְכָר נָא. אוֹי שֶׁאָנוּ צוֹוְחִים בְּכָל יוֹם, וְגוֹעִים וּבוֹכִים, (איכה ה) זְכֹר ה' מֶה הָיָה לָנוּ, (תהלים קלז) זְכֹר ה' לִבְנֵי אֱדוֹם, וְלֹא רוֹצֶה לְהַשְׁגִּיחַ עָלֵינוּ, הוּא אָמַר לָנוּ: בְּבַקָּשָׁה זְכָר נָא. אֵין נָא אֶלָּא לְשׁוֹן בַּקָּשָׁה, וְאָנוּ לֹא הִשְׁגַּחְנוּ בּוֹ. כְּמוֹ כֵן אָנוּ צוֹוְחִים: זְכֹר ה' מֶה הָיָה לָנוּ, זְכֹר ה' לִבְנֵי אֱדֹם, (שם עד) זְכֹר עֲדָתְךְ קָנִיתָ קֶּדֶם, (שם קו) זָכְרֵנִי ה' בִּרְצוֹן עַמֶּךְ, וְלֹא רוֹצֶה לְהַשְׁגִּיחַ עָלֵינוּ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ עָלֵינוּ תָּמִיד וְזוֹכֵר אוֹתָנוּ, שֶׁאִם הוּא לֹא יַשְׁגִּיחַ עַל יִשְׂרָאֵל וְזוֹכֵר אוֹתָם, לֹא יַעַמְדוּ יוֹם אֶחָד בַּגָּלוּת. זֶהוּ שֶׁכָּתוּב (ויקרא כו) וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹ'. הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ עוֹשֶׂה לָנוּ כְמַעֲשֵׂינוּ.</p>\n<p>בֹּא רְאֵה, בָּלָק חָכָם הָיָה, וּגְדוֹל הַמְּכַשְּׁפִים בְּמַעֲשֵׂי יָדָיו יוֹתֵר מִבִּלְעָם. וְכָךְ לָמַדְנוּ, כָּל מַה שֶּׁרוֹצֶה בֶּן אָדָם בָּעוֹלָם הַזֶּה בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, צָרִיךְ לְעוֹרֵר בַּמַּעֲשֶׂה לְמַטָּה. שֶׁבַּמַּעֲשֶׂה שֶׁלְּמַטָּה מִתְעוֹרֵר מַעֲשֶׂה לְמַעְלָה, וְהַמַּעֲשֶׂה הַזֶּה צָרִיךְ בִּקְדֻשָּׁה, וַהֲרֵי פֵּרְשׁוּהָ. וּבְמָקוֹם שֶׁאֵין מַעֲשֶׂה, יֵשׁ דִּבּוּר. וּבְדִבּוּר הַפֶּה תָּלוּי הַמַּעֲשֶׂה, לְעוֹרֵר לְמַעְלָה. כְּמוֹ שֶׁצְּרִיכִים לְעוֹרֵר קְדֻשָּׁה עֶלְיוֹנָה בְּמַעֲשֶׂה וּבְדִבּוּר, כָּךְ גַּם אוֹתָם שֶׁבָּאִים מִצַּד הַטֻּמְאָה צְרִיכִים לְעוֹרֵר אֶת הַצַּד שֶׁלָּהֶם בְּמַעֲשֶׂה וּבְדִבּוּר הַפֶּה.</p>\n<p>וְאַף עַל גַּב שֶׁבִּלְעָם הָיָה הַגָּדוֹל מִכָּל מְכַשְּׁפֵי הָעוֹלָם - מְכַשֵּׁף עֶלְיוֹן מִמֶּנּוּ הָיָה בָּלָק. בְּקֶסֶם הָיָה בָּלָק גָּדוֹל מִכָּל הַחֲכָמִים, וּבִלְעָם בְּנַחַשׁ (והרי פרשוה). קֶסֶם וְנַחַשׁ שְׁתֵּי דְרָגוֹת הֵן. קֶסֶם תָּלוּי בְּמַעֲשֶׂה, נַחַשׁ לֹא תָלוּי בְּמַעֲשֶׂה, אֶלָּא בְּהִסְתַּכְּלוּת וּבְדִבּוּר הַפֶּה, וְאָז מְעוֹרְרִים עָלָיו רוּחַ טֻמְאָה לְהִתְלַבֵּשׁ בָּהֶם, וְעוֹשֶׂה מַה שֶּׁעוֹשֶׂה.</p>\n<p>וְיִשְׂרָאֵל הַקְּדוֹשִׁים לֹא כָּךְ, אֶלָּא כֻּלָּם קְדוֹשִׁים, וְכָל מַעֲשֵׂיהֶם לְעוֹרֵר עֲלֵיהֶם רוּחַ קְדוֹשָׁה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לב) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם. וְעַל זֶה כָּתוּב, (במדבר כג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל, שֶׁהֲרֵי הֵם אֲחוּזִים בְּצַד הַקְּדֻשָּׁה הָעֶלְיוֹנָה. וּמַעֲשֵׂיהֶם בִּקְדֻשָׁה בָּאִים, וּקְדֻשָּׁה מִתְעוֹרֶרֶת עֲלֵיהֶם וּמִתְלַבְּשִׁים בָּהּ.</p>\n<p>וּבֹא רְאֵה, בְּקֶסֶם הָיָה בָּלָק גָּדוֹל מִכָּל הַחֲכָמִים, וּבִלְעָם בְּנַחַשׁ. וְעַל זֶה, בְּשָׁעָה שֶׁרָצָה בָּלָק לְהִתְחַבֵּר עִמּוֹ, מַה כָּתוּב? (שם כב) וַיֵּלְכוּ זִקְנֵי מוֹאָב וְזִקְנֵי מִדְיָן וּקְסָמִים בְּיָדָם. (ובלעם מעשיו בנחש) בֹּא רְאֵה, בְּדִבּוּר הַפֶּה הָיָה בִּלְעָם גָּדוֹל מִכָּל הַמְּכַשְּׁפִים שֶׁל הָעוֹלָם, וּבְהִסְתַּכְּלוּת אוֹתוֹ נָחָשׁ הָיָה יוֹדֵעַ לְכַוֵּן אֶת הַשָּׁעָה, וְעַל זֶה רָצָה בָּלָק לְהַשְׁלִים דָּבָר (הכל) קֶסֶם וְנַחַשׁ.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע, הֲרֵי קִדְּמוּךְ בָּנַי. מַעֲשֶׂה יֵשׁ בְּתוֹכָם שֶׁכָּל הַצְּדָדִים הָרָעִים וְהַמִּינִים הָרָעִים וְכִשְׁפֵי הָעוֹלָם לֹא יְכוֹלִים לְהִתְקָרֵב אֲלֵיהֶם, שֶׁכֻּלָּם בּוֹרְחִים מִלְּפָנָיו. וּמַהוּ? אֹהֶל מוֹעֵד, וּבִגְדֵי קֹדֶשׁ, וְשִׁמּוּשֵׁי הַמִּקְדָּשׁ, וּקְטֹרֶת הַבְּשָׂמִים, שֶׁמְּבַטֶּלֶת כָּל רִתְחָהּ וְרֹגֶז שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה וּלְמַטָּה, וְעוֹלוֹת וְקָרְבָּנוֹת בְּכָל יוֹם, וּשְׁנֵי מִזְבְּחוֹת, לַעֲשׂוֹת מַעֲשֵׂה מִזְבְּחוֹת, וְשֻׁלְחָן וְלֶחֶם הַפָּנִים, וְאֶת הַכִּיּוֹר וְאֶת כַּנּוֹ, וְכַמָּה שִׁמּוּשִׁים לַמַּעֲשֶׂה, לְדִבּוּר הַפֶּה, הָאָרוֹן וּשְׁנֵי לוּחוֹת הַתּוֹרָה, וְאַהֲרֹן לְכַפֵּר עַל הָעָם בִּתְפִלָּה בְּכָל יוֹם. כֵּיוָן שֶׁהִשְׁגִּיחַ אוֹתוֹ רָשָׁע בָּזֶה, אָמַר כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. מָה הַטַּעַם? ה' אֱלֹהָיו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ. וְעַל זֶה עַמִּי זְכָר נָא, בְּבַקָּשָׁה מִכֶּם, זִכְרוּ אוֹתוֹ זְמַן שֶׁהִתְחַבְּרוּ בָּלָק וּבִלְעָם לְהַשְׁמִידְכֶם וְלֹא יָכְלוּ, שֶׁאֲנִי אָחַזְתִּי בָכֶם כְּמוֹ אָב שֶׁאוֹחֵז אֶת בְּנוֹ וְלֹא מַשְׁאִיר אוֹתוֹ בְּיַד אַחֵר. מִן הַשִּׁטִּים עַד הַגִּלְגָּל, מַה זֶּה לְעֻמַּת זֶה? אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יִשְׂרָאֵל, בְּבַקָּשָׁה מִכֶּם, תִּהְיוּ זוֹכְרִים כָּל זְמַן שֶׁהֱיִיתֶם אֲחוּזִים בִּי, וְלֹא יָכֹל אוֹתוֹ רָשָׁע בִּכְשָׁפָיו וּקְסָמָיו לִשְׁלֹט עֲלֵיכֶם. כֵּיוָן שֶׁעֲזַבְתֶּם אֶת יְדֵיכֶם מִלֶּאֱחֹז בִּי וִהְיִיתֶם בַּשִּׁטִּים, מַה כָּתוּב? וַיֹּאכַל הָעָם וַיִּשְׁתַּחֲווּ לֵאלֹהֵיהֶן. בַּגִּלְגָּל, כְּמוֹ שֶׁנֶּאֱמַר (הושע יב) בַּגִּלְגָּל שְׁוָרִים זִבֵּחוּ, וְאָז שָׁלְטוּ בָכֶם שׂוֹנְאֵיכֶם.</p>\n<p>וְכָל זֶה לָמָּה? לְמַעַן דַּעַת צִדְקוֹת ה'. כָּל אוֹתָן צְדָקוֹת שֶׁעָשִׂיתִי לָכֶם בִּזְמַן שֶׁאַתֶּם אֲחוּזִים בִּי, וְלֹא הִשְׁאַרְתִּי דָבָר בָּעוֹלָם לִשְׁלֹט בָכֶם, וְהָרֹגֶז שֶׁלְּמַעְלָה וּלְמַטָּה וְהַמִּינִים הָרָעִים לֹא יְכוֹלִים לִקְרַב לָכֶם.</p>"],[9522012251,"<p>וַיֹּאמֶר אֲלֵיהֶם לִינוּ פֹה הַלַּיְלָה וַהֲשִׁבֹתִי אֶתְכֶם דָּבָר כַּאֲשֶׁר יְדַבֵּר ה' אֵלָי. בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּכְנָס הַשֶּׁמֶשׁ, וְכָל הַשְּׁעָרִים נִסְתָּמִים, וְנִכְנָס הַלַּיְלָה וּמַחֲשִׁיךְ, כַּמָּה קְבוּצוֹת מֻתָּרִים מִשַּׁלְשְׁלוֹתֵיהֶם, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְכַמָּה מְמֻנִּים גְּדוֹלִים עֲלֵיהֶם שֶׁמַּנְהִיגִים אוֹתָם. וְיֵשׁ מְמֻנֶּה גָּדוֹל עַל הַכֹּל מִצַּד הַשְּׂמֹאל, וְאוֹתוֹ רָשָׁע הָיָה מָצוּי אֵצֶל אוֹתוֹ הַמְמֻנֶּה הָעֶלְיוֹן מֵהַכֹּל בִּכְשָׁפָיו. וְהוּא הָיָה אוֹמֵר בִּכְשָׁפָיו בַּלַּיְלָה, בִּזְמַן שֶׁהוּא שׁוֹלֵט בְּכָל סִיעָתוֹ, וְהוּא הָיָה בָּא לְהִמָּצֵא אֶצְלוֹ, וּמוֹדִיעַ לוֹ מַה שֶּׁהוּא רוֹצֶה.</p>\n<p>כְּגוֹן זֶה, (בראשית לא) וַיָּבֹא אֱלֹהִים אֶל לָבָן הָאֲרַמִּי, אוֹתוֹ שֶׁמָּצוּי אֶצְלוֹ. (שם כ) וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ, כֻּלָּם כְּגוֹן זֶה. בְּכָל מָקוֹם קוֹרְאִים לוֹ בְּאוֹתָם כְּשָׁפִים, וְעַל זֶה הָיָה מָצוּי בַּלַּיְלָה יוֹתֵר מֵאֲשֶׁר בַּיּוֹם, וַהֲרֵי פֵּרְשׁוּהָ. וְכָל הַמְּכַשְּׁפִים וְהַחֲכָמִים הָאֵלּוּ הָיוּ לַאֲבִימֶלֶךְ, שֶׁכָּתוּב (שם כו) וַיַּשְׁקֵף אֲבִימֶלֶךְ מֶלֶךְ פְּלִשְׁתִּים בְּעַד הַחַלּוֹן. כָּתוּב כָּאן בְּעַד הַחַלּוֹן, וְכָתוּב שָׁם, (שופטים ה) בְּעַד הַחַלּוֹן נִשְׁקְפָה וַתְּיַבֵּב אֵם סִיסְרָא. לָבָן הֲרֵי פֵּרְשׁוּהָ, בִּלְעָם כְּמוֹ זֶה.</p>\n<p>וְעַל זֶה כָּתוּב בְּכֻלָּם אֱלֹהִים; וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם, וַיָּבֹא אֱלֹהִים אֶל לָבָן, וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ. הוּא בָּא אֲלֵיהֶם, וְלֹא הֵם אֵלָיו, שֶׁהֲרֵי אֵין לָהֶם מָקוֹם זָמִין. וְאִם תֹּאמַר, הֲרֵי כָּתוּב אֱלֹהִים! אֶלָּא שֶׁהַשֵּׁם הַזֶּה מִשְׁתַּתֵּף בַּכֹּל, וַאֲפִלּוּ עֲבוֹדָה זָרָה גַּם נִקְרֵאת אֱלֹהִים, אֱלֹהִים אֲחֵרִים, וּבִכְלַל שֶׁל אֱלֹהִים אֲחֵרִים אֵלֶּה מְמֻנִּים, וּבִכְלַל זֶה הָיוּ, וְלָכֵן נִקְרָא כָּךְ. וְאוֹתוֹ רָשָׁע הָיָה אוֹמֵר בִּכְשָׁפָיו וְקוֹרֵא לוֹ, וּבָא אֵלָיו. וּמִשּׁוּם כָּךְ כָּתוּב, לִינוּ פֹה הַלַּיְלָה וַהֲשִׁבתִי אֶתְכֶם דָּבָר כַּאֲשֶׁר יְדַבֵּר ה' אֵלָי. אוֹתוֹ רָשָׁע מְשַׁבֵּחַ אֶת עַצְמוֹ, שֶׁהֲרֵי לֹא כָתוּב בּוֹ, אֶלָּא וַיָּבֹא אֱלֹהִים.</p>"],[9522012252,"<p>דָּבָר אַחֵר כַּאֲשֶׁר יְדַבֵּר ה' אֵלָי - עַל יְדֵי אוֹתוֹ שָׁלִיחַ שֶׁל הַצַּד הָאַחֵר. וְאִם תֹּאמַר, הֲרֵי בַּיּוֹם נִמְצָא אֶצְלוֹ (כשהיה אצל בלק. אלא) - אֶלָּא וַדַּאי בְּנַחַשׁ הַהִתְבּוֹנְנוּת הָיְתָה בּוֹ, וּבְאוֹתוֹ זְמַן הָיָה מִסְתַּכֵּל לְכַוֵּן אֶת הַשָּׁעָה. זֶהוּ שֶׁכָּתוּב וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים. וַיַּרְא בִּלְעָם כִּי טוֹב בְּעֵינֵי ה' לְבָרֵךְ אֶת יִשְׂרָאֵל. אֶלָּא שֶׁאוֹתוֹ יוֹם הִסְתַּכֵּל לְכַוֵּן אֶת הַשָּׁעָה, וְלֹא נִמְצָא כִּשְׁאָר הַיָּמִים, וְאָז רָאָה שֶׁאֵין רֹגֶז גָּדוֹל נִמְצָא בָעוֹלָם, אָז יָדַע כִּי טוֹב בְּעֵינֵי ה' לְבָרֵךְ אֶת יִשְׂרָאֵל. בְּאוֹתוֹ זְמַן הֶעֱזִיב אֶת עַצְמוֹ מִכָּל הַנְּחָשִׁים שֶׁל הָעוֹלָם, וְלֹא הִסְתַּכֵּל בָּהֶם. זֶהוּ שֶׁכָּתוּב וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים.</p>\n<p>בֹּא רְאֵה, בְּאוֹתָהּ שָׁעָה שֶׁהָרֹגֶז נִמְצָא, אָז הַשְּׂמֹאל מִתְעוֹרֵר, וְהָיָה יוֹדֵעַ אוֹתוֹ הָרָשָׁע אֶת הַמָּקוֹם לֶאֱחֹז בְּצַד הַשְּׂמֹאל לְקַלֵּל. וְהִתְבּוֹנֵן בְּאוֹתוֹ הַזְּמַן, וְלֹא מָצָא. וְאָז מַה כָּתוּב? (במדבר כג) מָה אֶקֹּב לֹא קַבּה אֵל וּמָה אֶזְעֹם לֹא זָעַם ה'. וּמִשּׁוּם כָּךְ, (מיכה ו) עַמִּי זְכָר נָא מַה יָּעַץ בָּלָק וְגוֹ' וּמֶה עָנָה אֹתוֹ בִּלְעָם בֶּן בְּעוֹר. אַשְׁרֵיהֶם יִשְׂרָאֵל, אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (שרבונם הוכיח להם כך).</p>"],[9522012253,"<p>אִם בְּחֻקֹּתַי תֵּלֵכוּ. אִם בְּחֻקֹּתַי - זֶה מָקוֹם שֶׁגְּזֵרוֹת הַתּוֹרָה תְּלוּיוֹת בְּאוֹתוֹ מָקוֹם, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא יט) אֶת חֻקֹּתַי תִּשְׁמֹרוּ. חֹק הוּא שֶׁנִּקְרָא כָּךְ, וּגְזֵרוֹת הַתּוֹרָה בּוֹ נִכְלָלוֹת. (שם כה) וְאֶת מִשְׁפָּטַי תִּשְׁמְרוּ. מִשְׁפָּטַי - זֶהוּ מָקוֹם אַחֵר עֶלְיוֹן שֶׁאוֹתָהּ חֻקָּה אֲחוּזָה בּוֹ, וּמִתְחַבְּרִים זֶה בָּזֶה, שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים, וְכָל מִצְווֹת הַתּוֹרָה, וְכָל גְּזֵרוֹת הַתּוֹרָה, וְכָל קְדֻשּׁוֹת הַתּוֹרָה בָּזֶה אֲחוּזִים, מִשּׁוּם שֶׁזּוֹ תּוֹרָה שֶׁבִּכְתָב, וְזוֹ תּוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>וְעַל זֶה אִם בְּחֻקֹּתַי. כָּל אוֹתָם גְּזֵרוֹת וְדִינִים וָעֳנָשִׁים וּמִצְווֹת, שֶׁהֵם בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא תּוֹרָה שֶׁבְּעַל פֶּה - חֻקָּה. וְאֶת מִשְׁפָּטַי תִּשְׁמְרוּ, בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא תּוֹרָה שֶׁבִּכְתָב, כְּמוֹ שֶׁנֶּאֱמַר מִשְׁפָּט לֵאלֹהֵי יַעֲקֹב. וְזֶה אָחוּז בָּזֶה וְזֶה בָּזֶה, וְהַכֹּל אֶחָד. וְזֶהוּ כְּלַל הַשֵּׁם הַקָּדוֹשׁ. וּמִי שֶׁעוֹבֵר עַל דִּבְרֵי הַתּוֹרָה, כְּאִלּוּ פָּגַם אֶת הַשֵּׁם הַקָּדוֹשׁ, מִשּׁוּם שֶׁחֹק וּמִשְׁפָּט זֶהוּ הַשֵּׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל זֶה, אִם בְּחֻקֹּתַי תֵּלֵכוּ - זוֹ תּוֹרָה שֶׁבְּעַל פֶּה. וְאֶת מִשְׁפָּטַי תִּשְׁמְרוּ - זוֹ תּוֹרָה שֶׁבִּכְתָב, וְזֶהוּ כְּלַל הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>וַעָשִׂיתֶם אֹתָם. מַה זֶּה וַעֲשִׂיתֶם אֹתָם? כֵּיוָן שֶׁאָמַר תֵּלְכוּ וְתִשְׁמְרוּ, לָמָּה וַעֲשִׂיתֶם? אֶלָּא מִי שֶׁעוֹשֶׂה מִצְווֹת הַתּוֹרָה וְהוֹלֵךְ בִּדְרָכֶיהָ, כִּבְיָכוֹל כְּאִלּוּ עָשָׂה אוֹתוֹ לְמַעְלָה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּאִלּוּ עֲשָׂאַנִי, וּפֵרְשׁוּהָ. וְעַל זֶה וַעֲשִׂיתֶם אֹתָם. וַעֲשִׂיתֶם אַתֶּם כָּתוּב וַדַּאי, וְהוֹאִיל וּמִתְעוֹרְרִים עֲלֵיכֶם לְהִתְחַבֵּר זֶה בָּזֶה, שֶׁיִּמָּצֵא הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, וַעֲשִׂיתֶם אַתֶּם וַדַּאי.</p>\n<p>כְּמוֹ זֶה אָמַר רַבִּי שִׁמְעוֹן, (שמואל ב ח) וַיַּעַשׂ דָּוִד שֵׁם, וְכִי דָּוִד עָשָׂה אוֹתוֹ? אֶלָּא מִשּׁוּם שֶׁהָלַךְ בְּדַרְכֵי הַתּוֹרָה וְעָשָׂה מִצְווֹת הָתּוֹרָה וְהִנְהִיג אֶת הַמַּלְכוּת כָּרָאוּי, כִּבְיָכוֹל עָשָׂה שֵׁם לְמַעְלָה, וְלֹא הָיָה מֶלֶךְ בָּעוֹלָם שֶׁזָּכָה לָזֶה כְּמוֹ דָוִד, שֶׁהָיָה קָם בַּחֲצוֹת הַלַּיְלָה וְהָיָה מְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁעוֹלֶה הַשֵּׁם הַקָּדוֹשׁ בַּכִּסֵּא, בְּשָׁעָה שֶׁעוֹלֶה הַיּוֹם. כִּבְיָכוֹל הוּא עָשָׂה שֵׁם מַמָּשׁ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כד) וַיִּקֹּב בֶּן הָאִשָּׁה הַיִּשְׂרְאֵלִית אֶת הַשֵּׁם וַיְקַלֵּל. וּמִשּׁוּם כָּךְ, וַיַּעַשׂ דָּוִד שֵׁם. וְעַל זֶה כָּתוּב וַעֲשִׂיתֶם אֹתָם, וְאִם אַתֶּם תִּשְׁתַּדְּלוּ לַעֲשׂוֹת אוֹתָם, לְהַתְקִין אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, כָּל אוֹתָן בְּרָכוֹת שֶׁלְּמַעְלָה יִמָּצְאוּ אֶצְלְכֶם בְּתִקּוּנֵיהֶן כָּרָאוּי.</p>"],[9522012254,"<p>וְנָתַתִּי גִשְׁמֵיכֶם בְּעִתָּם וְגוֹ'. כָּל אֶחָד וְאֶחָד יִתֵּן כֹּחוֹ עֲלֵיכֶם. מִי הֵם? אוֹתוֹ תִקּוּן שֶׁעֲשִׂיתֶם שֶׁל אוֹתוֹ הַשֵּׁם הַקָּדוֹשׁ, כְּמוֹ זֶה כָּתוּב (בראשית יח) וְשָׁמְרוּ דֶּרֶךְ ה' לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט. וְכִי כֵּיוָן שֶׁכָּתוּב וְשָׁמְרוּ דֶּרֶךְ ה', לָמָּה לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט? אֶלָּא מִי שֶׁשּׁוֹמֵר דַּרְכֵי הַתּוֹרָה, כִּבְיָכוֹל הוּא עוֹשֶׂה צְדָקָה וּמִשְׁפָּט. וּמַה זֶּה צְדָקָה וּמִשְׁפָּט? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, אוֹי לָהֶם לִבְנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בִּכְבוֹד רִבּוֹנָם. מִי עוֹשֶׂה הַשֵּׁם הַקָּדוֹשׁ בְּכָל יוֹם? הֱוֵה אוֹמֵר, מִי שֶׁנּוֹתֵן צְדָקָה לָעֲנִיִּים.</p>"],[9522012255,"<p>בֹּא רְאֵה, הֲרֵי פֵּרְשׁוּהָ כָּךְ הוּא, שֶׁהֶעָנִי אָחוּז בַּדִּין, וְכָל מַאֲכָלוֹ הוּא בְּדִין, הַמָּקוֹם שֶׁנִּקְרָא צֶדֶק, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קב) תְּפִלָּה לְעָנִי כִי יַעֲטֹף. תְּפִלָּה, זוֹ תְפִלָּה שֶׁל יָד, וּבֵאַרְנוּ. וּמִי שֶׁנּוֹתֵן צְדָקָה לֶעָנִי, הוּא עוֹשֶׂה לְמַעְלָה שֵׁם קָדוֹשׁ שָׁלֵם כָּרָאוּי. כִּי צְדָקָה זֶה עֵץ הַחַיִּים, וּצְדָקָה נוֹתֵן לְצֶדֶק. וּכְשֶׁנּוֹתֵן לְצֶדֶק, אָז מִתְחַבֵּר זֶה עִם זֶה, וְהַשֵּׁם הַקָּדוֹשׁ נִמְצָא שָׁלֵם. מִי שֶׁעוֹשֶׂה זוֹ הַהִתְעוֹרְרוּת (שעושה התעוררות זו) שֶׁלְּמַטָּה, בְּוַדַּאי כְּאִלּוּ עָשָׂה אֶת הַשֵּׁם הַקָּדוֹשׁ בִּשְׁלֵמוּת. כְּמוֹ שֶׁהוּא עוֹשֶׂה לְמַטָּה, כָּךְ מִתְעוֹרֵר לְמַעְלָה. וְעַל זֶה כָּתוּב, (שם קו) אַשְׁרֵי שֹׁמְרֵי מִשְׁפָּט עֹשֵׂה צְדָקָה בְכָל עֵת. עֹשֵׂה צְדָקָה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כִּבְיָכוֹל הוּא עוֹשֶׂה אוֹתוֹ.</p>\n<p>בֹּא רְאֵה, הֶעָנִי הֲרֵי נִתְבָּאֵר מִיהוּ מְקוֹמוֹ. מָה הַטַּעַם? כִּי הֶעָנִי אֵין לוֹ מִשֶּׁלּוֹ כְּלוּם אֶלָּא מַה שֶּׁנּוֹתְנִים לוֹ, וְהַלְּבָנָה אֵין לָהּ אוֹר מִשֶּׁלָּהּ אֶלָּא מַה שֶּׁהַשֶּׁמֶשׁ נוֹתֵן לָהּ.</p>\n<p>בֹּא רְאֵה, לָמָּה עָנִי חָשׁוּב כְּמֵת? מָה הַטַּעַם? כִּי אוֹתוֹ מָקוֹם גּוֹרֵם לוֹ, שֶׁהֲרֵי בִּמְקוֹם הַמָּוֶת הוּא מָצוּי, וְלָכֵן נִקְרָא מֵת. אוֹתוֹ שֶׁחָס עָלָיו הוּא נוֹתֵן לוֹ צְדָקָה, עֵץ הַחַיִּים שׁוֹרֶה עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר (משלי י) וּצְדָקָה תַּצִּיל מִמָּוֶת. וּכְמוֹ שֶׁעוֹשֶׂה אָדָם לְמַטָּה, כָּךְ גַּם הוּא עוֹשֶׂה לְמַעְלָה מַמָּשׁ. אַשְׁרֵי חֶלְקוֹ שֶׁל הַזּוֹכֶה לַעֲשׂוֹת שֵׁם קָדוֹשׁ לְמַעְלָה, מִשּׁוּם כָּךְ הַצְּדָקָה עוֹלָה עַל הַכֹּל.</p>\n<p>וְהַדְּבָרִים הָאֵלֶּה, כְּשֶׁהַצְּדָקָה לִשְׁמָהּ, שֶׁהֲרֵי מְעוֹרֵר צְדָקָה לְצֶדֶק לְחַבְּרָם כְּאֶחָד, וְשֶׁיִּהְיֶה הַכֹּל שֵׁם קָדוֹשׁ כָּרָאוּי. שֶׁהֲרֵי צֶדֶק לֹא מִתְתַּקֵּן וְלֹא נִשְׁלָם אֶלָּא בִּצְדָקָה, שֶׁכָּתוּב (ישעיה נד) בִּצְדָקָה תִּכּוֹנָנִי. וְלִכְנֶסֶת יִשְׂרָאֵל נֶאֱמַר, וּמִשּׁוּם כָּךְ וַעֲשִׂיתֶם אֹתָם וְגוֹ'.</p>"],[9522012256,"<p>וְנָתַתִּי שָׁלוֹם בָּאָרֶץ וּשְׁכַבְתֶּם וְאֵין מַחֲרִיד וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (תהלים ד) רִגְזוּ וְאַל תֶּחֱטָאוּ וְגוֹ'. רִגְזוּ וְאַל תֶּחֱטָאוּ, פָּסוּק זֶה פֵּרְשׁוּהוּ, שֶׁצָּרִיךְ בֶּן אָדָם לְהַרְגִּיז יֵצֶר טוֹב עַל יֵצֶר הָרָע, וְיָפֶה. אֲבָל בְּשָׁעָה שֶׁיּוֹרֵד הַלַּיְלָה וּבֶן אָדָם שׁוֹכֵב עַל מִטָּתוֹ, כַּמָּה מְמֻנִּים עַל הַחֻקִּים מִתְעוֹרְרִים בָּעוֹלָם, וְהוֹלְכִים וּמְשׁוֹטְטִים, וּבְנֵי אָדָם צְרִיכִים לְהֵחָרֵד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלִפְחֹד מִמֶּנּוּ, בִּשְׁבִיל שֶׁלֹּא תִמָּצֵא נַפְשׁוֹ בְתוֹכָם וְיִנָּצֵל מֵהֶם, וְיִצְטָרֵךְ לוֹ לְבֶן אָדָם שֶׁלֹּא יוֹצִיא מִלָּה בְּפִיו מֵהֶם, כְּדֵי שֶׁלֹּא יְעוֹרֵר אוֹתָם אֵלָיו וְלֹא יִמָּצְאוּ עִמּוֹ. זֶהוּ שֶׁכָּתוּב אִמְרוּ בִלְבַבְכֶם עַל מִשְׁכַּבְכֶם וְדמּוּ סֶלָה. שֶׁלֹּא יוֹצִיא מֵהֶם דִּבּוּר בְּפִיו.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּמְצָאִים יִשְׂרָאֵל צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מַה כָּתוּב? וְנָתַתִּי שָׁלוֹם בָּאָרֶץ. זֶה לְמַעְלָה. שֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל. אָז, וּשְׁכַבְתֶּם וְאֵין מַחֲרִיד. מָה הַטַּעַם? מִשּׁוּם וְהִשְׁבַּתִּי חַיָּה רָעָה מִן הָאָרֶץ. זוֹ חַיָּה שֶׁל מִין רַע לְמַטָּה. וּמַהִי? אַגְרַת בַּת מַחֲלַת, הִיא וְכָל סִיעָתָהּ. זֶה בַּלּיְלָה. בַּיּוֹם, בְּנֵי אָדָם שֶׁבָּאִים מִצִּדָּהּ, זֶהוּ שֶׁכָּתוּב (ויקרא כו) וְחֶרֶב לֹא תַעֲבֹר בְּאַרְצְכֶם.</p>\n<p>רַבִּי אַבָּא אָמַר, הֲרֵי פֵּרְשׁוּהָ שֶׁאֲפִלּוּ חֶרֶב שֶׁל שָׁלוֹם, כְּמוֹ פַּרְעֹה נְכֹה. אֲבָל וְחֶרֶב לֹא תַעֲבֹר, זוֹ הַסִּיעָה שֶׁלָּהּ. וְהִשְׁבַּתִּי חַיָּה רָעָה, שֶׁלֹּא תִשְׁלֹט בָּאָרֶץ, וַאֲפִלּוּ הַעֲבָרָה בְּעָלְמָא לֹא תַעֲבֹר עֲלֵיכֶם, וַאֲפִלּוּ חֶרֶב שֶׁל שְׁאָר הָעַמִּים, וַאֲפִלּוּ בֶּן אָדָם מְזֻיָּן לֹא יַעֲבֹר עֲלֵיכֶם.</p>\n<p>וְאֶת זֶה דָּרַשׁ יֹאשִׁיָּהוּ הַמֶּלֶךְ, וּפֵרְשׁוּהָ שֶׁהוּא נִתְפַּס בַּחֲטָאֵי יִשְׂרָאֵל, כְּמוֹ שֶׁכָּתוּב (איכה ד) רוּחַ אַפֵּינוּ מְשִׁיחַ ה' נִלְכַּד בִּשְׁחִיתוֹתָם וְגוֹ'. כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי שָׁנִינוּ, אִם רֹאשׁ הָעָם הוּא טוֹב, כָּל הָעָם נִצּוֹלִים בִּגְלָלוֹ. וְאִם רֹאשׁ הָעָם לֹא כָשֵׁר, כָּל הָעָם נִתְפָּסִים בְּחֶטְאוֹ. וַהֲרֵי יֹאשִׁיָּהוּ רֹאשׁ כָּשֵׁר הָיָה וּמַעֲשָׂיו כְּשֵׁרִים, לָמָּה נִתְפַּס בַּחֲטָאֵי יִשְׂרָאֵל?</p>\n<p>אֶלָּא עַל שֶׁלֹּא הֶאֱמִין בְּיִרְמְיָהוּ וְלֹא יִסֵּר אֶת יִשְׂרָאֵל, שֶׁחָשַׁב שֶׁכֻּלָּם צַדִּיקִים כְּמוֹתוֹ. וְיִרְמְיָה הָיָה אוֹמֵר לוֹ, וְלֹא הֶאֱמִין בּוֹ, וְלָכֵן נִתְפַּס בַּחֲטָאֵיהֶם. וְעוֹד, שֶׁהַלְּבָנָה הִנְמִיכָה אֶת אוֹרָהּ, וְרָצְתָה לְהִסָּתֵם.</p>"],[9522012257,"<p>וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכֲכֶם וְגוֹ'. וְנָתַתִּי מִשְׁכָּנִי - זוֹ הַשְּׁכִינָה. מִשְׁכָּנִי - מַשְׁכּוֹנִי, שֶׁהִתְמַשְׁכְּנָה בַּחֲטָאֵי יִשְׂרָאֵל. וְנָתַתִּי מִשְׁכָּנִי, מַשְׁכּוֹנִי בְּוַדַּאי. מָשָׁל לְבֶן אָדָם שֶׁהָיָה אוֹהֵב אֶחָד אַחֵר, אָמַר לוֹ: וַדַּאי בְּאַהֲבָה עֶלְיוֹנָה שֶׁיֵּשׁ לִי אֵלֶיךְ אֲנִי רוֹצֶה לָדוּר עִמְּךְ. אָמַר, אֵיךְ אֵדַע שֶׁתָּדוּר אֶצְלִי? לָקַח כָּל חֶמְדַּת בֵּיתוֹ וְהֵבִיא אֵלָיו. אָמַר, הִנֵּה הַמַּשְׁכּוֹן אֶצְלְךְ שֶׁלֹּא אֶפָּרֵד מִמְּךְ לְעוֹלָמִים.</p>\n<p>כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לָדוּר עִם יִשְׂרָאֵל, מֶה עָשָׂה? לָקַח אֶת חֶמְדָּתוֹ וְהוֹרִיד לָהֶם לְיִשְׂרָאֵל. אָמַר לָהֶם: יִשְׂרָאֵל, הִנֵּה מַשְׁכּוֹנִי אֶצְלְכֶם כְּדֵי שֶׁלֹּא אֶפָּרֵד מִכֶּם לְעוֹלָמִים. וְאַף אַף גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַחֵק מֵאִתָּנוּ, אֶת הַמַּשְׁכּוֹן הִשְׁאִיר בְּיָדֵינוּ, וְאָנוּ שׁוֹמְרִים אֶת אוֹתָהּ חֶמְדָּתוֹ. מִי שֶׁיִּרְצֶה אֶת מַשְׁכּוֹנוֹ, יָבא לָדוּר אֶצְלֵנוּ. לָכֵן וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכֲכֶם, מַשְׁכּוֹן אֶתֵּן בְּיֶדְכֶם כְּדֵי שֶׁאָדוּר עִמָּכֶם. וְאַף עַל גַּב שֶׁיִּשְׂרָאֵל כָּעֵת בַּגָּלוּת, מַשְׁכּוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶצְלָם, וְלֹא עָזְבוּ אוֹתוֹ לְעוֹלָמִים.</p>\n<p>וְלֹא תִגְעַל נַפְשִׁי אֶתְכֶם. לְאָדָם שֶׁאוֹהֵב אֶת חֲבֵרוֹ וְרוֹצֶה לָדוּר עִמּוֹ, מֶה עָשָׂה? לָקַח מִטָּתוֹ וֶהֱבִיאָהּ לְבֵיתוֹ. אָמַר, זוֹ מִטָּתִי בְּבֵיתְךְ כְּדֵי שֶׁלֹּא אֶתְרַחֵק מִמְּךְ, מִמִּטָּתְךְ וּמִכֵּלֶיךְ. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכֲכֶם וְלֹא תִגְעַל נַפְשִׁי אֶתְכֶם. הִנֵּה מִטָּתִי בְּבֵיתְכֶם. כֵּיוָן שֶׁמִּטָּתִי עִמָּכֶם, תֵּדְעוּ שֶׁלֹּא אֶפָּרֵד מִכֶּם, וְלָכֵן וְלֹא תִגְעַל נַפְשִׁי אֶתְכֶם.</p>\n<p>וְהִתְהַלַּכְתִּי בְּתוֹכֲכֶם וְהָיִיתִי לָכֶם לֵאלֹהִים. כֵּיוָן שֶׁמִּשְׁכָּנִי אֶצְלְכֶם, בְּוַדַּאי תֵּדְעוּ שֶׁאֲנִי הוֹלֵךְ עִמָּכֶם, כְּמוֹ שֶׁנֶּאֱמַר (דברים כג) כִּי ה' אֱלֹהֶיךְ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךְ לְהַצִּילְךְ וְלָתֵת אֹיְבֶיךְ לְפָנֶיךְ וְהָיָה מַחֲנֶיךְ קָדוֹשׁ.</p>\n<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ מְצוּיִים לַיְלָה אֶחָד בִּכְפָר קָרוֹב לְיָם טְבֶרְיָה, קָמוּ בַּחֲצוֹת הַלַּיְלָה. אָמַר רַבִּי יִצְחָק לְרַבִּי יְהוּדָה, נֹאמַר בְּדִבְרֵי תוֹרָה, שֶׁאַף עַל גַּב שֶׁאָנוּ בְּמָקוֹם זֶה, לֹא צְרִיכִים לְהִפָּרֵד מֵעֵץ הַחַיִּים.</p>"],[9522012258,"<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, (שמות לג) וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה וְגוֹ'. וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל לָמָּה? אֶלָּא אָמַר מֹשֶׁה, הוֹאִיל וְיִשְׂרָאֵל מְשַׁקְּרִים בַּקָּדוֹשׁ בָּרוּךְ הוּא וְהֶחֱלִיפוּ אֶת כְּבוֹדוֹ, הֲרֵי מַשְׁכּוֹנוֹ יִהְיֶה בְּיָד שֶׁל נֶאֱמָן, עַד שֶׁנִּרְאֶה אֵצֶל מִי יִשָּׁאֵר.</p>\n<p>אָמַר לוֹ לִיהוֹשֻׁעַ, אַתָּה תִּהְיֶה הַנֶּאֱמָן בֵּין הַקָּדוֹשׁ בָּרוּךְ הוּא וּבֵין יִשְׂרָאֵל, וְיִשָּׁאֵר הַמַּשְׁכּוֹן בְּיָדֶיךְ בְּנֶאֱמָנוּת, וְנִרְאֶה אֵצֶל מִי יִשָּׁאֵר. מַה כָּתוּב? וְשָׁב אֶל הַמַּחֲנֶה וּמְשָׁרֲתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. מָה הַטַּעַם לִיהוֹשֻׁעַ? מִשּׁוּם שֶׁהוּא כַּלְּבָנָה לְגַבֵּי הַשֶּׁמֶשׁ, וְהוּא רָאוּי לִשְׁמֹר אֶת הַמַּשְׁכּוֹן, וְעַל זֶה לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: מֹשֶׁה, לֹא רָאוּי כָּךְ, שֶׁהֲרֵי מַשְׁכּוֹנִי נָתַתִּי בִידֵיהֶם. אַף עַל פִּי שֶׁהֵם חָטְאוּ אֵלַי, הַמַּשְׁכּוֹן יִהְיֶה אֶצְלָם, שֶׁלֹּא יִפָּרְדוּ מִמֶּנּוּ (שלא יפרד מהם). הֲתִרְצֶה שֶׁאֶפָּרֵד מִיִּשְׂרָאֵל, וְלֹא אָשׁוּב אֲלֵיהֶם לְעוֹלָמִים?! אֶלָּא הָשֵׁב אֶת מַשְׁכּוֹנִי אֲלֵיהֶם, וּבִגְלָלוֹ לֹא אֶעֱזֹּב אוֹתָם בְּכָל מָקוֹם.</p>\n<p>אַף עַל גַּב שֶׁיִּשְׂרָאֵל חָטְאוּ לַקָּדוֹשׁ בָּרוּךְ הוּא, אֶת הַמַּשְׁכּוֹן הַזֶּה שֶׁלּוֹ הֵם לֹא עָזְבוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא לוֹקֵחַ אוֹתוֹ מִבֵּינֵיהֶם. וְעַל זֶה, בְּכָל מָקוֹם שֶׁגָּלוּ יִשְׂרָאֵל, שְׁכִינָה עִמָּהֶם. וְעַל זֶה כָּתוּב וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכֲכֶם, וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522012259,"<p>פָּתַח רַבִּי יִצְחָק וְאָמַר, (שיר השירים ב) דּוֹמֶה דּוֹדִי לִצְבִי אוֹ לְעֹפֶר הָאַיָּלִים הִנֵּה זֶה וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁזָּכוּ שֶׁמַּשְׁכּוֹן זֶה יִהְיֶה אֶצְלָם מֵהַמֶּלֶךְ הָעֶלְיוֹן. שֶׁאַף עַל גַּב שֶׁהֵם בַּגָּלוּת, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא בְּכָל רֹאשׁ חֹדֶשׁ וְשַׁבָּתוֹת וּזְמַנִּים לְהַשְׁגִּיחַ עֲלֵיהֶם, וּלְהִסְתַּכֵּל בְּאוֹתוֹ מַשְׁכּוֹן שֶׁיֵּשׁ לוֹ אֵצְלָם, שֶׁהוּא חֶמְדָּתוֹ.</p>\n<p>לְמֶלֶךָֹ שֶׁסָּרְחָה הַגְּבִירָה, וְהוֹצִיאָהּ מֵהֵיכָלוֹ. מֶה עָשְׂתָה? לָקְחָה אֶת הַבֵּן שֶׁלּוֹ, חֶמְדַּת הַמֶּלֶךְ, אֲהוּבוֹ. וּמִשּׁוּם שֶׁדַּעַת הַמֶּלֶךְ עָלֶיהָ, הִשְׁאִירוֹ בְיָדֶיהָ. בְּשָׁעָה שֶׁעוֹלֶה רְצוֹן הַמֶּלֶךְ עַל הַגְּבִירָה וְעַל בְּנוֹ, הָיָה עוֹלֶה לַעֲלִיּוֹת וְיוֹרֵד מַדְרֵגוֹת, וְעוֹלֶה עַל הַכְּתָלִים, לְהִסְתַּכֵּל וּלְהַשְׁגִּיחַ בֵּין נִקְבֵי הַכֹּתֶל עֲלֵיהֶם. כֵּיוָן שֶׁרוֹאֶה אוֹתָם, הוּא מַתְחִיל לִבְכּוֹת מֵאֲחוֹרֵי חֲרַכֵּי הַכֹּתֶל, וְאַחַר כָּךְ הוֹלֵךְ לוֹ.</p>\n<p>כָּךָ יִשְׂרָאֵל, אַף עַל גַּב שֶׁיָּצְאוּ מֵהֵיכַל הַמֶּלֶךְ, אוֹתוֹ הַמַּשְׁכּוֹן הֵם לֹא עָזְבוּ, וּמִשּׁוּם שֶׁרְצוֹן הַמֶּלֶךְ עֲלֵיהֶם, הִשְׁאִיר אוֹתוֹ עִמָּהֶם. בְּשָׁעָה שֶׁעוֹלֶה רְצוֹן הַמֶּלֶךְ הַקָּדוֹשׁ עַל הַגְּבִירָה וְעַל יִשְׂרָאֵל, הוּא עוֹלֶה עֲלִיּוֹת (מקפץ על הגבעות), יוֹרֵד מַדְרֵגוֹת, וְעוֹלֶה עַל הַכְּתָלִים, לְהִסְתַּכֵּל וּלְהַשְׁגִּיחַ בֵּין חֲרַכֵּי הַכֹּתֶל עֲלֵיהֶם. כֵּיוָן שֶׁרוֹאֶה אוֹתָם, מַתְחִיל לִבְכּוֹת. זֶהוּ שֶׁכָּתוּב דּוֹמֶה דוֹדִי לִצְבִי אוֹ לְעֹפֶר הָאַיָּלִים, לְדַלֵּג מִכֹּתֶל לַעֲלִיָּה, וּמֵעֲלִיָּה לְכֹתֶל. הִנֵּה זֶה עוֹמֵד אַחַר כָּתְלֵנוּ, בְּבָתֵּי כְּנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת. מַשְׁגִּיחַ מִן הַחַלֹּנוֹת, (שבודאי בית הכנסת צריך חלונות). מֵצִיץ מִן הַחֲרַכִּים, לְהִסְתַּכֵּל וּלְהַשְׁגִּיחַ עֲלֵיהֶם. וְלָכֵן יִשְׂרָאֵל צְרִיכִים לִשְׂמֹחַ בְּאוֹתוֹ יוֹם, שֶׁהֵם יוֹדְעִים זֶה וְאוֹמְרִים, (תהלים קיח) זֶה הַיּוֹם עָשָׂה ה' נָגִילָה וְנִשְׂמְחָה בוֹ.</p>\n<p>וְאִם בְּחֻקֹּתַי תִּמְאָסוּ וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (משלי ג) מוּסַר ה' בְּנִי אַל תִּמְאָס וְאַל תָּקֹץ בְּתוֹכַחְתּוֹ. כַּמָּה חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהוֹכִיחַ אוֹתָם וּלְהַנְהִיגָם בְּדֶרֶךְ יְשָׁרָה, כְּמוֹ אָב שֶׁאוֹהֵב אֶת בְּנוֹ, וּמִתּוֹךְ אַהֲבָתוֹ אֵלָיו יֵשׁ בְּיָדוֹ שַׁרְבִיט תָּמִיד לְהַנְהִיגוֹ בְּדֶרֶךְ יְשָׁרָה, שֶׁלֹּא יִסְטֶה לְיָמִין וְלִשְׂמֹאל. זֶהוּ שֶׁכָּתוּב (שם) כִּי אֶת אֲשֶׁר יֶאֱהַב ה' יוֹכִיחַ וּכְאָב אֶת בֵּן יִרְצֶה. וּמִי שֶׁלֹּא אוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשׂוֹנֵא אוֹתוֹ, הוּא מְסַלֵּק מִמֶּנּוּ תּוֹכָחָה, וּמְסַלֵּק מִמֶּנּוּ אֶת הַשַּׁרְבִיט.</p>\n<p>כָּתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה' וְגוֹ'. מִתּוֹךְ אַהֲבָתוֹ יֵשׁ בְּיָדוֹ תָּמִיד שַׁרְבִיט לְהַנְהִיגוֹ. וְאֶת עֵשָׂו שָׂנֵאתִי, מִשּׁוּם כָּךְ סִלַּקְתִּי מִמֶּנּוּ אֶת הַשַּׁרְבִיט, סִלַּקְתִּי מִמֶּנּוּ תּוֹכָחָה, כְּדֵי שֶׁלֹּא אֶתֵּן לוֹ חֵלֶק בִּי. הוּא רִחוּק נַפְשִׁי, אֲבָל אַתֶּם - אָהַבְתִּי אֶתְכֶם וַדַּאי. וּמִשּׁוּם כָּךְ, מוּסַר ה' בְּנִי אַל תִּמְאָס וְאַל תָּקֹץ בְּתוֹכַחְתּוֹ. מַה זֶּה וְאַל תָּקֹץ? כְּמוֹ מִי שֶׁבּוֹרֵחַ מִתּוֹךְ קוֹצִים, שֶׁאוֹתָם דִּבּוּרִים כְּמוֹ קוֹצִים אֵלָיו בְּעַצְמוֹ.</p>"],[9522012260,"<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁמִּתְעוֹרֵר צֶדֶק בְּדִינָיו, כַּמָּה צִדְדֵי רוּחוֹת מִתְעוֹרְרִים מִיָּמִין וּמִשְּׂמֹאל, כַּמָּה שַׁרְבִיטִים יוֹצְאִים, מֵהֶם שַׁרְבִיטֵי אֵשׁ, שַׁרְבִיטֵי גֶחָלִים, שַׁרְבִיטֵי שַׁלְהֶבֶת, כֻּלָּם יוֹצְאִים וּמִתְעוֹרְרִים בָּעוֹלָם וּמַלְקִים בְּנֵי אָדָם. תַּחְתֵּיהֶם מְמֻנִּים אֲחֵרִים, בַּעֲלֵי חַבָּלָה, מְמֻנִּים שֶׁל אַרְבָּעִים חָסֵר אַחַת. מְשׁוֹטְטִים וְיוֹרְדִים, מַלְקִים וְעוֹלִים וְנוֹטְלִים רְשׁוּת, נִכְנָסִים לְנֶקֶב תְּהוֹם רַבָּה, מְצַבְּעִים צוּרוֹת, וְאֵשׁ שֶׁדּוֹלֶקֶת מִתְחַבֶּרֶת עִמָּהֶם, יוֹצְאִים הַגֶּחָלִים וּמְשׁוֹטְטִים וְיוֹרְדִים, וְנִמְצָאִים כְּנֶגֶד בְּנֵי אָדָם. וְהַיְנוּ מַה שֶּׁכָּתוּב, וְיָסַפְתִּי לְיַסְּרָה אֶתְכֶם. אֶתֵּן לְבַעֲלֵי הַדִּין תּוֹסֶפֶת עַל הַדִּין שֶׁלָּהֶם.</p>\n<p>כְּמוֹ שֶׁנֶּאֱמַר, (בראשית ח) לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. מַה זֶּה לֹא אֹסִף? לֹא אֶתֵּן תּוֹסֶפֶת לְבַעֲלֵי דִין לְהַשְׁמִיד אֶת הָעוֹלָם, אֶלָּא תּוֹסֶפֶת כְּמוֹ שֶׁהָעוֹלָם יָכוֹל לִסְבֹּל. וְעַל זֶה וְיָסַפְתִּי, אֶתֵּן תּוֹסֶפֶת וַדַּאי.</p>"],[9522012261,"<p>לָמָּה תּוֹסֶפֶת? כְּדֵי לְיַסֵּר אֶתְכֶם שֶׁבַע עַל חַטֹאתֵיכֶם. שֶׁבַע? וַהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אִם גּוֹבֶה אֶת שֶׁלּוֹ, אֵין הָעוֹלָם יָכוֹל לִסְבֹּל אֲפִלּוּ רֶגַע אֶחָד, זֶהוּ שֶׁכָּתוּב (תהלים קל) אִם עֲונוֹת תִּשְׁמָר יָהּ אֲדנָי מִי יַעֲמֹד, וְאַתָּה אָמַרְתָּ שֶׁבַע עַל חַטֹּאתֵיכֶם?!</p>\n<p>אֶלָּא מַה תַּלְמוּד לוֹמַר שֶׁבַע? אֶלָּא הֲרֵי שֶׁבַע כְּנֶגְדְּכֶם, וּמִי הִיא? זוֹ שְׁמִטָּה, שֶׁהִיא שֶׁבַע, שֶׁנִּקְרֵאת שֶׁבַע, כְּמוֹ שֶׁנֶּאֱמַר (דברים טז) מִקֵּץ שֶׁבַע שָׁנִים תַּעֲשֶׂה שְׁמִטָּה. וְעַל זֶה שֶׁבַע עַל חַטֹּאתֵיכֶם, וְנִקְרֵאת שֶׁבַע, וְנִקְרֵאת בַּת שֶׁבַע. מַה בֵּין זֶה לָזֶה? אֶלָּא שֶׁבַע לְבַדָּהּ, לַעֲשׂוֹת שְׁמִטָּה וְלַעֲשׂוֹת דִּינִים, לְהוֹצִיא חֵרוּת, שֶׁהַכֹּל בָּהּ. נִקְרֵאת בַּת שֶׁבַע, שֶׁהִתְחַבְּרָה עִם אַחֵר כְּאֶחָד, לְהָאִיר, לִשְׁלֹט בַּמַּלְכוּת, לְהוֹדִיעַ הַמַּלְכוּת בָּאָרֶץ וּבַכֹּל, בַּת שֶׁבַע נִקְרֵאת. כָּתוּב, עַל כֵּן שֵׁם הָעִיר בְּאֵר שֶׁבַע עַד הַיּוֹם הַזֶּה. בְּאֵר שֶׁבַע, בְּאֵרוֹ שֶׁל יִצְחָק הִיא, וְהַכֹּל הוּא דָּבָר אֶחָד.</p>\n<p>רַבִּי אַבָּא אָמַר, וְיִסַּרְתִּי אֶתְכֶם אַף אֲנִי שֶׁבַע עַל חַטֹּאתֵיכֶם. וְיִסַּרְתִּי אֶתְכֶם, עַל יְדֵי מְמֻנִּים אֲחֵרִים, כְּמוֹ שֶׁבֵּאֲרוּהָ. אַף אֲנִי, הֲרֵינִי מִתְעוֹרֵר כְּנֶגְדְּכֶם, וַהֲרֵי שֶׁבַע לְהִתְעוֹרֵר עֲלֵיכֶם.</p>"],[9522012262,"<p>בֹּא רְאֵה אֶת הָאַהֲבָה הָעֶלְיוֹנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל. לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן יְחִידִי, וְהָיָה חוֹטֵא לִפְנֵי הַמֶּלֶךְ. יוֹם אֶחָד סָרַח לִפְנֵי הַמֶּלֶךְ, אָמַר הַמֶּלֶךְ: כָּל הַיָּמִים הַלָּלוּ הִלְקֵיתִי אוֹתְךְ וְלֹא קִבַּלְתָּ. מִכָּאן וְאֵילָךְ רְאֵה מָה אֶעֱשֶׂה לְךְ; אִם אֲגָרֵשׁ אוֹתְךְ מִן הָאָרֶץ וְאוֹצִיא אוֹתְךְ מִן הַמַּלְכוּת, אוּלַי יָקוּמוּ עָלֶיךְ דֻּבֵּי הַשָּׂדֶה, אוֹ זְאֵבֵי הַשָּׂדֶה, אוֹ לִסְטִים, וְיַעֲבִירוּ אוֹתְךְ מִן הָעוֹלָם. מָה אֶעֱשֶׂה? אֶלָּא אֲנִי וְאַתָּה נֵצֵא מִן הָאָרֶץ.</p>\n<p>כָּךָ אַף אֲנִי, אֲנִי וְאַתָּה נֵצֵא מִן הָאָרֶץ (אף אני ואתה נלך בגלות ונצא יחד). כָּךְ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יִשְׂרָאֵל, מָה אֶעֱשֶׂה לָכֶם? הֲרֵי הִלְקֵיתִי אֶתְכֶם וְלֹא הִרְכַּנְתֶּם אָזְנֵיכֶם. הֲרֵי הֵבֵאתִי עֲלֵיהֶם בַּעֲלֵי מָגִנִּים, בַּעֲלֵי חַבָּלָה, לְהַלְקוֹת אֶתְכֶם, וְלֹא שְׁמַעְתֶּם. אִם אוֹצִיא אֶתְכֶם מִן הָאָרֶץ לְבַדְּכֶם, אֲנִי פּוֹחֵד עֲלֵיכֶם מִכַּמָּה דֻבִּים, מִכַּמָּה זְאֵבִים שֶׁיָּקוּמוּ עֲלֵיכֶם וְיַעֲבִירוּ אֶתְכֶם מִן הָעוֹלָם. אֲבָל מָה אֶעֱשֶׂה לָכֶם? אֶלָּא אֲנִי וְאַתֶּם נֵצֵא מִן הָאָרֶץ וְנֵלֵךְ לַגָּלוּת. זְהִוּ שֶׁכָּתוּב וְיִסַּרְתִּי אֶתְכֶם, לָלֶכֶת בַּגָּלוּת. וְאִם תֹּאמְרוּ שֶׁאֶעֱזֹּב אֶתְכֶם - אַף אֲנִי עִמָּכֶם. שֶׁבַע עַל חַטֹּאתֵיכֶם - זוֹ שֶׁבַע שֶׁתִּתְגָּרֵשׁ עִמָּכֶם. וְלָמָּה? עַל חַטֹּאתֵיכֶם. זֶהוּ שֶׁכָּתוּב (ישעיהנ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אַתֶּם גְּרַמְתֶּם שֶׁאֲנִי וְאַתֶּם לֹא נָדוּר (בארץ) בָּעוֹלָם (נגרש (מהָאָרץ) מהעולם), הֲרֵי הַגְּבִירָה יָצְאָה מֵהֵיכָלָהּ עִמָּכֶם. הֲרֵי הַכֹּל נֶחֱרַב, הַהֵיכָל שֶׁלִּי וְשֶׁלָּכֶם נֶחֱרַב. שֶׁהֲרֵי לְמֶלֶךְ לֹא רָאוּי הֵיכָל אֶלָּא כְּשֶׁהוּא נִכְנָס עִם הַגְּבִירָה. וְשִׂמְחַת הַמֶּלֶךְ אֵינָהּ נִמְצֵאת.</p>\n<p>אֶלָּא בְּשָׁעָה שֶׁנִּכְנָס לְהֵיכַל הַגְּבִירָה, וְנִמְצָא בְנָהּ עִמָּהּ בַּהֵיכָל, כֻּלָּם שְׂמֵחִים כְּאֶחָד. עַכְשָׁו שֶׁאֵין נִמְצָאִים הַבֵּן עִם הַגְּבִירָה, הֲרֵי הַהֵיכָל חָרֵב מֵהַכֹּל. אֶלָּא אֲנִי מָה אֶעֱשֶׂה? אַף אֲנִי עִמָּכֶם. וְעַכְשָׁו, אַף עַל גַּב שֶׁיִּשְׂרָאֵל הֵם בַּגָּלוּת, הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא עִמָּהֶם וְלֹא עוֹזֵב אוֹתָם. שֶׁכַּאֲשֶׁר יֵצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת, הַקָּדוֹשׁ בָּרוּךְ הוּא יָשׁוּב עִמָּם, שֶׁכָּתוּב (דברים ל) וְשָׁב ה' אֱלֹהֶיךְ, וְשָׁב ה' אֱלֹהֶיךְ וַדַּאי, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012263,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ, נִפְגְּשׁוּ בְּאוֹתָהּ מְעָרָה בַּשָּׂדֶה. אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, זֶה שֶׁכָּתוּב (שם כח) אֵלֶּה דִּבְרֵי הַבְּרִית וְגוֹ', מִלְּבַד הַבְּרִית. מַה זֶּה דִּבְרֵי הַבְּרִית? דִּבְרֵי גְבוּרָה (האלה) הָיָה צָרִיךְ לִהְיוֹת! אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ, הַלָּלוּ מִפִּי הַגְּבוּרָה, וְהַלָּלוּ מִפִּי עַצְמוֹ שֶׁל מֹשֶׁה, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, אֵלֶּה וְאֵלֶּה הָיוּ דִּבְרֵי הַבְּרִית. שֶׁאַף עַל גַּב שֶׁהַדְּבָרִים הָיוּ מִפִּי הַגְּבוּרָה - דִּבְרֵי בְרִית הָיוּ, שֶׁהֲרֵי טוֹב וָרָע תְּלוּיִים בּוֹ. הַטּוֹב שֶׁבָּא מִצַּדִּיק, וְהָרָע שֶׁבָּא מִן הַדִּין. הַדִּין מִמְּקוֹם הַדִּין, וְהַיְנוּ צֶדֶק. וְצַדִּיק וְצֶדֶק הֵם בְּרִית, וְנִקְרָאִים בְּרִית. וְלָכֵן מִלִּים אֵלּוּ דִּבְרֵי בְרִית הֵן, וְקֶשֶׁר הַבְּרִית כְּאֶחָד. וּמִשּׁוּם כָּךְ זָכוֹר וְשָׁמוֹר קְשׁוּרִים כְּאֶחָד. זָכוֹר בַּיּוֹם, שָׁמוֹר בַּלַּיְלָה. הֲרֵי בְּרִית כְּאֶחָד, וּמִשּׁוּם כָּךְ בְּרִית וַדַּאי, דִּבְרֵי הַבְּרִית הֵם. וּבְכָל מָקוֹם הַבְּרִית הִיא בַּמָּקוֹם הַזֶּה.</p>\n<p>אָמַר רַבִּי חִיָּיא, וַדַּאי כָּךְ זֶה, וּמִשּׁוּם כָּךְ שַׁבָּת, שֶׁהִיא זָכוֹר וְשָׁמוֹר, נִקְרֵאת בְּרִית, שֶׁכָּתוּב (שמות לח) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדֹרֹתָם בְּרִית עוֹלָם. וְהַכֹּל דָּבָר אֶחָד, וְהַמָּקוֹם הַזֶּה נִקְרָא בְּרִית בְּכָל מָקוֹם.</p>\n<p>בֹּא רְאֵה, כָּתוּב וְנָתַתִּי שָׁלוֹם בָּאָרֶץ, הוּא יְסוֹד, שֶׁהוּא שְׁלוֹם הָאָרֶץ, שְׁלוֹם הַבַּיִת, שְׁלוֹם הָעוֹלָם. וְיִסַּרְתִּי אֶתְכֶם אַף אֲנִי שֶׁבַע. מַה זֶּה שֶׁבַע? זֶה צֶדֶק. הֲרֵי וַדַּאי הַבְּרִית, וּמִשּׁוּם כָּךְ דִּבְרֵי הַבְּרִית הֵם.</p>"],[9522012264,"<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם וְגוֹ'. וְאַף גַּם זֹּאת, וְאַף - כְּמוֹ שֶׁנֶּאֱמַר אַף אָנִי. גַּם - לְרַבּוֹת כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת זֹּאת, שֶׁלֹּא עוֹזֶבֶת אוֹתָם לְעוֹלָמִים. בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם - בִּהְיוֹתָם הַכֹּל כְּאֶחָד. לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים - כְּדֵי שֶׁלֹּא אֶתְחַבֵּר עִמָּם. לְהָפֵר בְּרִיתִי אִתָּם - שֶׁאִם לֹא אֶפְדֶּה אוֹתָם, הֲרֵי בְּרִיתִי מִתְחַלֶּקֶת. וּמִשּׁוּם כָּךְ, לְהָפֵר בְּרִיתִי אִתָּם.</p>\n<p>אָמַר רַבִּי חִיָּיא, אֲנִי שָׁמַעְתִּי דָבָר חָדָשׁ, שֶׁאָמַר רַבִּי אֶלְעָזָר, לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים לְכַלֹּתָם, לֹא הִכִּיתִים וְלֹא הֲרַגְתִּים לְכַלֹּתָם הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים - מִי שֶׁשּׂוֹנֵא מִישֶׁהוּ אַחֵר, הוּא מָאוּס כְּנֶגְדּוֹ, וּמַגְעִיל בְּגֹעַל לְפָנָיו. אֲבָל כָּאן, לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים. מָה הַטַּעַם? מִשּׁוּם שֶׁחֲבִיבוּת נַפְשִׁי בֵּינֵיהֶם, וּבִגְלָלָהּ כֻּלָּם חֲבִיבִים עֲבוּרִי. זֶהוּ שֶׁכָּתוּב לְכַלֹּתָם. לְכַלֹּתָם כָּתוּב, חָסֵר וָי\"ו, בִּגְלָלָהּ לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים, מִשּׁוּם שֶׁהִיא אַהֲבַת נַפְשִׁי, אַהֲבָתִי אֶצְלָהּ.</p>\n<p>לְאָדָם שֶׁאוֹהֵב אִשָּׁה, וְהָיְתָה גָּרָה בְּשׁוּק שֶׁל בּוּרְסְקִים, אִם הִיא לֹא הָיְתָה שָׁם, לֹא הָיָה נִכְנַס לְשָׁם לְעוֹלָמִים. כֵּיוָן שֶׁהִיא שָׁם, דּוֹמֶה בְעֵינָיו כְּמוֹ שׁוּק שֶׁל רוֹכְלִים, שֶׁכָּל הָרֵיחוֹת שֶׁל עוֹלָמוֹת טוֹבִים נִמְצָאִים שָׁם.</p>\n<p>אַף כָּאן, וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם, שֶׁהוּא שׁוּק שֶׁל בּוּרְסְקִים, לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים, וְלָמָּה? לְכַלֹּתָם. בִּשְׁבִיל כַּלָּתָם, שֶׁאֲנִי אוֹהֵב אוֹתָהּ, שֶׁהִיא אֲהוּבַת נַפְשִׁי, שֶׁשּׁוֹרָה שָׁם, וְדוֹמֶה עָלַי כְּמוֹ כָּל הָרֵיחוֹת הַטּוֹבִים שֶׁל הָעוֹלָם מִשּׁוּם אוֹתָהּ הַכַּלָּה שֶׁבְּתוֹכָם. אָמַר רַבִּי יוֹסֵי, אִלּוּ לֹא בָאנוּ לְכָאן אֶלָּא לִשְׁמֹעַ אֶת זֶה - דַּי לִי.</p>"],[9522012265,"<p>פָּתַח וְאָמַר, (מלאכי א) בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדנָיו. בֵּן יְכַבֵּד אָב, כְּמוֹ שֶׁנֶּאֱמַר (שמותכ) כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ, וּפֵרְשׁוּהָ, בְּמַאֲכָל וּבְמִשְׁתֶּה וּבַכֹּל. זֶה בְּחַיָּיו שֶׁהִתְחַיֵּב בּוֹ. אַחַר שֶׁמֵּת, אִם תֹּאמַר הֲרֵי הוּא פָּטוּר מִמֶּנּוּ - לֹא כָּךְ. שֶׁאַף עַל גַּב שֶׁמֵּת, הִתְחַיֵּב בִּכְבוֹדוֹ יוֹתֵר, שֶׁכָּתוּב כַּבֵּד אֶת אָבִיךְ. שֶׁאִם אוֹתוֹ הַבֵּן הוֹלֵךְ בְּדֶרֶךְ עִקֶּשֶׁת, וַדַּאי שֶׁהוּא מְבַזֶּה אֶת אָבִיו, וַדַּאי שֶׁעוֹשֶׂה לו קָלוֹן. וְאִם אוֹתוֹ הַבֵּן הוֹלֵךְ בְּדֶרֶךְ יְשָׁרָה, וּמְתַקֵּן אֶת מַעֲשָׂיו, וַדַּאי שֶׁזֶּה מְכַבֵּד אֶת אָבִיו, מְכַבֵּד אוֹתוֹ בְּאוֹתוֹ הָעוֹלָם אֵצֶל בְּנֵי אָדָם, מְכַבֵּד אוֹתוֹ בְּאוֹתוֹ הָעוֹלָם אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו וּמוֹשִׁיב אוֹתוֹ בְּכִסֵּא כְבוֹדוֹ. וַדַּאי בֵּן יְכַבֵּד אָב.</p>\n<p>כְּמוֹ רַבִּי אֶלְעָזָר שֶׁמְּכַבֵּד אֶת אָבִיו בָּעוֹלָם הַזֶּה וּבְאוֹתוֹ הָעוֹלָם, עַכְשָׁו מִתְרַבֶּה כְבוֹדוֹ שֶׁל רַבִּי שִׁמְעוֹן בִּשְׁנֵי עוֹלָמוֹת - בָּעוֹלָם הַזֶּה, וּבְאוֹתוֹ הָעוֹלָם יוֹתֵר אֲשֶׁר בְּחַיָּיו. שֶׁזָּכָה לְבָנִים קְדוֹשִׁים וְלִגְזָעִים קְדוֹשִׁים. אַשְׁרֵי הַצַּדִּיקִים שֶׁזּוֹכִים לְבָנִים קְדוֹשִׁים, לִגְזָעִים קְדוֹשִׁים, שעליהם נאמר . כָּל רֹאֵיהֶם יַכִּירוּם כִּי הֵם זֶרַע בֵּרַךְ יְיָ' אָמֵן.</p>"],[9522012266,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּמִדְבַּר סִינַי בְּאֹהֶל מוֹעֵד וְגוֹ'. רַבִּי אַבָּא פָּתַח, (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ וְגוֹ'. הַפָּסוּק הַזֶּה נִתְבָּאֵר. בֹּא רְאֵה, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶת הָאָדָם, עָשָׂה אוֹתוֹ בִּדְמוּת שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהָיָה כָּלוּל מֵהַכֹּל, וְהָיָה אוֹרוֹ מֵאִיר מִסּוֹף הָעוֹלָם וְעַד סוֹפוֹ, וְהָיוּ פוֹחֲדִים מִמֶּנּוּ הַכֹּל.</p>\n<p>וְאַף עַל גַּב שֶׁהֲרֵי פֵּרְשׁוּהָ, יֵשׁ לְהִסְתַּכֵּל בַּפָּסוּק הַזֶּה. וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ, כֵּיוָן שֶׁאָמַר בְּצַלְמוֹ, מַה זֶּה בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ? אֶלָּא וַדַּאי שְׁתֵּי דְרָגוֹת שֶׁכְּלוּלוֹת זָכָר וּנְקֵבָה, אַחַת לְזָכָר וְאַחַת לִנְקֵבָה.</p>\n<p>וְלָכֵן שְׁנֵי פַרְצוּפִים הָיוּ בְּוַדַּאי, וְסוֹף הַפָּסוּק מוֹכִיחַ, שֶׁכָּתוּב זָכָר וּנְקֵבָה בָּרָא אֹתָם. וְכָלוּל הָיָה מִכָּל הַצְּדָדִים (משני צדדים). וְאַף עַל גַּב שֶׁהַנְּקֵבָה אֲחוּזָה בְּצִדּוֹ, הֲרֵי הִיא גַּם כְּלוּלָה מִשְּׁנֵי צְדָדִים, לִהְיוֹת שָׁלֵם בַּכֹּל.</p>\n<p>וְהָיָה מִסְתַּכֵּל בַּחָכְמָה לְמַעְלָה וּלְמַטָּה. כֵּיוָן שֶׁסָּרַח, הִתְמַעֲטוּ הַפַּרְצוּפִים, וְהַחָכְמָה הִסְתַּלְּקָה מִמֶּנּוּ, וְלֹא הָיָה מִסְתַּכֵּל אֶלָּא בְּדִבְרֵי גוּפוֹ. אַחַר כָּךְ הוֹלִיד בָּנִים מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, וְלֹא הִתְיַשְּׁבוּ זֶה וָזֶה בָּעוֹלָם עַד שֶׁהוֹלִיד בֵּן, וּמִמֶּנּוּ נִשְׁלַם (נשתל) הָעוֹלָם, שֶׁנִּקְרָא שֵׁת, וְכָךְ פֵּרְשׁוּהָ.</p>\n<p>וְעִם כָּל זֶה, הָעוֹלָם הַתַּחְתּוֹן לֹא הֻשְׁלַם וְלֹא הָיָה שָׁלֵם וְלֹא נִמְצָא בְקִיּוּמוֹ, עַד שֶׁבָּא אַבְרָהָם וְעָמַד הָעוֹלָם. אֲבָל לֹא הֻשְׁלַם עַד שֶׁאַבְרָהָם נִמְצָא בּוֹ בָּעוֹלָם, וְאָחַז בּוֹ בְּיָמִין כְּמִי שֶׁאוֹחֵז בִּימִינוֹ אֶת מִי שֶׁנּוֹפֵל. בָּא יִצְחָק וְאָחַז בִּידֵי הָעוֹלָם בִּשְׂמֹאל וְהִתְקַיֵּם יוֹתֵר. כֵּיוָן שֶׁבָּא יַעֲקֹב, אָחַז בְּאֶמְצַע הַגּוּף, וְנִכְלָל בִּשְׁנֵי צְדָדִים, עָמַד הָעוֹלָם וְלֹא הָיָה מִתְמוֹטֵט.</p>\n<p>וְעִם כָּל זֶה לֹא נִשְׁתַּל (נשלם) בְּשָׁרָשָׁיו עַד שֶׁהוֹלִיד שְׁנֵים עָשָׂר שְׁבָטִים וְשִׁבְעִים נֶפֶשׁ, וְנִשְׁתַּל (ונשלם) הָעוֹלָם. וְעִם כָּל זֶה לֹא הִשְׁתַּלֵּם עַד שֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה בְּהַר סִינַי וְהוּקַם הַמִּשְׁכָּן, וְאָז עָמְדוּ הָעוֹלָמוֹת וְנִשְׁלְמוּ, וְהִתְבַּשְּׂמוּ עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>כֵּיוָן שֶׁהַתּוֹרָה וְהַמִּשְׁכָּן הוּקְמוּ, רָצָה הַקָּדוֹשׁ-בָּרוּךְ-הוּא לִפְקֹד הַחֲיָלוֹת שֶׁל הַתּוֹרָה, כַּמָּה צְבָאוֹת הֵם שֶׁל הַתּוֹרָה, כַּמָּה צְבָאוֹת הֵם שֶׁל הַמִּשְׁכָּן. בֹּא רְאֵה, כָּל דָּבָר שֶׁצָּרִיךְ לְהִתְיַשֵּׁב בִּמְקוֹמוֹ, לֹא מִתְיַשֵּׁב עַד שֶׁנִּזְכָּר בַּפֶּה, וּמִתְמַנֶּה עָלָיו. אַף כָּאן - רָצָה הַקָּדוֹשׁ-בָּרוּךְ-הוּא לִפְקֹד חֵילוֹת הַתּוֹרָה וְחֵילוֹת הַמִּשְׁכָּן, וְכֻלָּם הָיוּ כְּאֶחָד וְלֹא נִפְרָדִים זֶה מִזֶּה, הַכֹּל כְּמוֹ לְמַעְלָה, שֶׁהֲרֵי הַתּוֹרָה וְהַמִּשְׁכָּן לֹא נִפְרָדִים זֶה מִזֶּה, וְהוֹלְכִים כְּאֶחָד.</p>\n<p>וּמִשּׁוּם זֶה חֵילוֹתֵיהֶם עוֹלִים בְּחֶשְׁבּוֹן לְהִוָּדַע אֲלֵיהֶם, פְּרָט לְאוֹתָם אֲחֵרִים שֶׁאֵין לָהֶם חֶשְׁבּוֹן. וְלָכֵן כָּתוּב, וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּמִדְבַּר סִינַי בְּאֹהֶל מוֹעֵד. אִם בְּאֹהֶל מוֹעֵד, לָמָּה בְּמִדְבַּר סִינַי? אֶלָּא אֶחָד לַתּוֹרָה וְאֶחָד לַמִּשְׁכָּן.</p>\n<p>וְזֶה וָזֶה - בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי בַּשָּׁנָה הַשֵּׁנִית, וְהַכֹּל אֶחָד, וְזֶה נִקְרָא חֹדֶשׁ זִיו, רֶמֶז לְאוֹתוֹ חֹדֶשׁ וְשָׁנָה שֶׁמֵּאִיר לַלְּבָנָה, שֶׁהֲרֵי אָז כָּל הָעוֹלָמוֹת נִמְצָאִים בִּשְׁלֵמוּת. לְצֵאתָם מֵאֶרֶץ מִצְרַיִם, לְהוֹדִיעַ שֶׁכְּשֶׁיָּצְאוּ מֵאֶרֶץ מִצְרַיִם, זֶה הָיָה בַּחֹדֶשׁ הָרִאשׁוֹן.</p>\n<p>רַבִּי יִצְחָק פָּתַח, (תהלים קטו) ה' זְכָרָנוּ יְבָרֵךְ יְבָרֵךְ אֶת בֵּית וְגוֹ'. ה' זְכָרָנוּ יְבָרֵךְ - אֵלֶּה הַגְּבָרִים, שֶׁהָיוּ עוֹלִים בַּחֶשְׁבּוֹן בַּמִּדְבָּר, וְהַקָּדוֹשׁ-בָּרוּךְ-הוּא מְבָרֵךְ אוֹתָם וּמוֹסִיף עֲלֵיהֶם בְּכָל זְמַן.</p>\n<p>בֹּא רְאֵה, מִי שֶׁאוֹמֵר שֶׁבַח חֲבֵרוֹ, שֶׁל בָּנָיו, אוֹ שֶׁל מָמוֹנוֹ - צָרִיךְ לְבָרְכוֹ וּלְהוֹדוֹת עָלָיו בִּבְרָכוֹת. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב (דברים א) וְהִנְּכֶם הַיּוֹם כְּכוֹכְבֵי הַשָּׁמַיִם לָרֹב. אַחַר כָּךְ מַה כָּתוּב? ה' אֱלֹהֵי אֲבוֹתֵכֶם יֹסֵף עֲלֵיכֶם כָּכֶם אֶלֶף פְּעָמִים וְגוֹ'. שְׁתֵּי בְרָכוֹת הָיוּ: אַחַת - ה' אֱלֹהֵי אֲבוֹתֵכֶם, הֲרֵי אַחַת. אַחַר כָּךְ - וִיבָרֵךְ אֶתְּכֶם כַּאֲשֶׁר דִּבֶּר לָכֶם. לְהוֹדוֹת עֲלֵיהֶם, בְּרָכוֹת עַל בְּרָכוֹת.</p>\n<p>וְאִם הוּא מוֹנֶה אֶת שֶׁבַח חֲבֵרוֹ וְלֹא מוֹדֶה עָלָיו בְּרָכוֹת - הוּא נִתְפָּס בַּתְּחִלָּה מִלְמַעְלָה. וְאִם הוּא מְבָרֵךְ אוֹתוֹ - הוּא מִתְבָּרֵךְ מִלְמַעְלָה. וְהַבְּרָכָה צָרִיךְ לְבָרֵךְ אוֹתָהּ בְּעַיִן טוֹבָה, וְלֹא בְּעַיִן רָעָה. וּבַכֹּל רוֹצֶה הַקָּדוֹשׁ-בָּרוּךְ-הוּא אַהֲבַת הַלֵּב. וּמַה מִּי שֶׁמְּבָרֵךְ אֶת חֲבֵרוֹ, רוֹצֶה הַקָּדוֹשׁ-בָּרוּךְ-הוּא שֶׁיְּבָרֵךְ אוֹתוֹ בְּעַיִן טוֹבָה, בְּלֵב טוֹב - מִי שֶׁמְּבָרֵךְ אֶת הַקָּדוֹשׁ-בָּרוּךְ-הוּא עַל אַחַת כַּמָּה וְכַמָּה שֶׁצָּרִיךְ עַיִן טוֹבָה וְלֵב טוֹב וְאַהֲבַת הַלֵּב. בִּגְלַל זֶה, (שם ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ בְּכָל לְבָבְךְ וְגוֹ'.</p>\n<p>בֹּא רְאֵה, הֲרֵי פֵּרְשׁוּהָ, אֵין הַבְּרָכָה שֶׁלְּמַעְלָה שׁוֹרָה עַל דָּבָר שֶׁנִּמְנֶה. וְאִם תֹּאמַר, יִשְׂרָאֵל אֵיךְ נִמְנוּ? אֶלָּא כֹּפֶר לָקַח מֵהֶם, וַהֲרֵי פֵּרְשׁוּהָ, וְהַחֶשְׁבּוֹן לֹא הָיָה עַד שֶׁנֶּאֱסַף כָּל אוֹתוֹ הַכֹּפֶר וְעָלָה לַחֶשְׁבּוֹן. וּבַתְּחִלָּה מְבָרְכִים אֶת יִשְׂרָאֵל, אַחַר כָּךְ מוֹנִים אוֹתוֹ כֹּפֶר, אַחַר כָּךְ חוֹזְרִים וּמְבָרְכִים אֶת יִשְׂרָאֵל. נִמְצָא שֶׁיִּשְׂרָאֵל מִתְבָּרְכִים בַּתְּחִלָּה וּבַסּוֹף, וְלֹא עוֹלָה בָהֶם מַגֵּפָה.</p>\n<p>לָמָּה הַמַּגֵּפָה עוֹלָה בְמִנְיָן? אֶלָּא מִשּׁוּם שֶׁבְּרָכָה לֹא שׁוֹרָה בְמִנְיָן. כֵּיוָן שֶׁמִּסְתַּלֶּקֶת הַבְּרָכָה, הַצַּד הָאַחֵר שׁוֹרֶה עָלָיו, וְיָכוֹל לְהִנָּזֵק. בִּגְלַל זֶה בְּמִנְיָן לוֹקְחִים כֹּפֶר וּפִדְיוֹן, לְסַלֵּק אוֹתוֹ מֵהֶם.</p>\n<p>יְבָרֵךָ אֶת בֵּית יִשְׂרָאֵל - אֵלּוּ הַנָּשִׁים, שֶׁלֹּא עוֹלוֹת בַּמִּנְיָן. יְבָרֵךְ אֶת בֵּית אַהֲרֹן - שֶׁהֵם מְבָרְכִים אֶת הָעָם בְּעַיִן טוֹבָה וּבְלֵב טוֹב וּבְאַהֲבַת הַלֵּב. אֶת בֵּית אַהֲרֹן - כָּךְ גַּם הַנָּשִׁים (שלהם), שֶׁמִּתְבָּרְכוֹת בַּבְּרָכָה (שלהם).</p>\n<p>יְבָרֵךָ יִרְאֵי ה' - אֵלֶּה הֵם הַלְוִיִּם, וְכֻלָּם מִתְבָּרְכִים, כִּי הֵם יְרֵאִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. הַקְּטַנִּים עִם הַגְּדלִים - אַף עַל גַּב שֶׁלֹּא עוֹלִים בַּמִּנְיָן.</p>\n<p>בֹּא רְאֵה, לֹא נִמְצָא מִנְיָן בְּיִשְׂרָאֵל שֶׁהִתְבָּרְכוּ בוֹ כְּמִנְיָן זֶה, שֶׁמִּנְיָן זֶה לְהִתְבָּרֵךְ הָיָה, וּלְהַשְׁלִים שְׁלֵמוּת הָעוֹלָמִים הָיָה, וּבְמָקוֹם שֶׁהַבְּרָכוֹת יוֹצְאוֹת נִמְנוּ, שֶׁכָּתוּב בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי, שֶׁהוּא זִיו בִּרְכוֹת הָעוֹלָם, שֶׁמִּמֶּנּוּ יוֹצֵא זִיו לָעוֹלָם. וְעַל זֶה נִקְרָא חֹדֶשׁ זִי\"ו, שֶׁהַזִּיו שֶׁל הַכֹּל יוֹצֵא מִמֶּנּוּ, וְעַל זֶה כָּתוּב (תהלים קלד) יְבָרֶכְךְ ה' מִצִּיּוֹן, וְהַכֹּל דָּבָר אֶחָד, וְכָתוּב (שם קלג) כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה וְגוֹ'.</p>\n<p>רַבִּי יְהוּדָה הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, יִשְׂרָאֵל, מֵאֵיזֶה מָקוֹם הֵם מִתְבָּרְכִים? אָמַר לוֹ, אוֹי לָעוֹלָם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא מִסְתַּכְּלִים בְּנֵי אָדָם בִּכְבוֹד הַמֶּלֶךְ הָעֶלְיוֹן. בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּמְצְאוּ יִשְׂרָאֵל צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהָעוֹלָמוֹת הָיוּ (עמו) מְצוּיִים בְּעֵץ אֶחָד עֶלְיוֹן קָדוֹשׁ, שֶׁהַמָּזוֹן שֶׁל הַכֹּל בּוֹ, הָיָה מִתְבָּרֵךְ מִמָּקוֹם שֶׁכָּל הַבְּרָכוֹת כְּנוּסוֹת בּוֹ, וּבוֹ נִנְטַע וְנִשְׁתְּלוּ שָׁרָשָׁיו.</p>\n<p>וְיִשְׂרָאֵל לְמַטָּה הָיוּ מִתְבָּרְכִים (ונשתלו שרשיו) מִמָּקוֹם שֶׁכָּל אוֹתָן בְּרָכוֹת יוֹצְאוֹת בּוֹ וְלֹא מִתְעַכְּבוֹת לָצֵאת. זֶהוּ שֶׁכָּתוּב יְבָרֶכְךְ ה' מִצִּיּוֹן, וְכָתוּב כְּטַל חֶרְמוֹן שֶׁיֹּרֵד עַל הַרְרֵי צִיּוֹן כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם. וְזֶהוּ אוֹר הָעוֹלָם, שֶׁכָּתוּב (תהלים נ) מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ. הוֹפִיעַ - הֵאִיר, כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) הוֹפִיעַ מֵהַר פָּארָן. (וזה אור) וּכְשֶׁמֵּאִיר, מֵאִיר לְכָל הָעוֹלָמוֹת.</p>\n<p>וּכְשֶׁאוֹר זֶה מִתְעוֹרֵר, הַכֹּל הוּא בַּחֲבֵרוּת (הכל הוא בחביבות), הַכֹּל הוּא בְּאַהֲבָה, הַכֹּל הוּא בִּשְׁלֵמוּת, וְאָז הוּא שְׁלוֹם הַכֹּל, שָׁלוֹם שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. זֶהוּ שֶׁכָּתוּב (תהלים קכב) יְהִי שָׁלוֹם בְּחֵילֵךְ שַׁלְוָה בְּאַרְמְנוֹתָיִךְ.</p>"],[9522012267,"<p>אִישׁ עַל דִּגְלוֹ יַחֲנוּ בְאֹתֹת לְבֵית אֲבֹתָם יַחֲנוּ בְּנֵי יִשְׂרָאֵל וְגוֹ' (במדבר א). רַבִּי אֶלְעָזָר פָּתַח, (ישעיה סו) שִׂמְחוּ אֶת יְרוּשָׁלם וְגִילוּ בָהּ כָּל אֹהֲבֶיהָ וְגוֹ'. כַּמָּה חֲבִיבָה הַתּוֹרָה לִפְנֵי הַקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁדִּבְרֵי תוֹרָה נִשְׁמָעִים, הַקָּדוֹשׁ-בָּרוּךְ-הוּא וְכָל חֵילוֹתָיו, כֻּלָּם מַקְשִׁיבִים לִדְבָרָיו, וְהַקָּדוֹשׁ-בָּרוּךְ-הוּא בָּא לָדוּר עִמּוֹ. זֶהוּ שֶׁכָּתוּב (שמות כ) בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי וְגוֹ'. וְלֹא עוֹד, אֶלָּא שֶׁשּׂוֹנְאָיו נוֹפְלִים לְפָנָיו, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, מִצְווֹת הַתּוֹרָה הֵן עֶלְיוֹנוֹת לְמַעְלָה. בָּא אָדָם וְעָשָׂה מִצְוָה אַחַת - אוֹתָהּ הַמִּצְוָה עוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ-בָּרוּךְ-הוּא, וּמִתְעַטֶּרֶת לְפָנָיו וְאוֹמֶרֶת: פְּלוֹנִי עָשָׂה אוֹתִי, וּמִפְּלוֹנִי אֲנִי. מִשּׁוּם שֶׁהוּא עוֹרֵר אוֹתָהּ לְמַעְלָה. כְּמוֹ שֶׁהוּא עוֹרֵר אוֹתָהּ לְמַטָּה, כָּךְ גַּם עוֹרֵר אוֹתָהּ לְמַעְלָה, וְעָשָׂה שָׁלוֹם לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כז) אוֹ יַחֲזֵק בְּמָעֻזִּי יַעֲשֶׂה שָׁלוֹם לִי שָׁלוֹם יַעֲשֶׂה לִּי. יַעֲשֶׂה שָׁלוֹם לִי - לְמַעְלָה. שָׁלוֹם יַעֲשֶׂה לִּי - לְמַטָּה. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁעוֹשֶׂה מִצְווֹת הַתּוֹרָה.</p>\n<p>שִׂמְחוּ אֶת יְרוּשָׁלם וְגוֹ', מִשּׁוּם שֶׁחֶדְוָה לֹא נִמְצֵאת אֶלָּא בִּזְמַן שֶׁיִּשְׂרָאֵל עוֹמְדִים בָּאָרֶץ הַקְּדוֹשָׁה, שֶׁשָּׁם מִתְחַבֶּרֶת אִשָּׁה בְּבַעְלָהּ, וְאָז זוֹהִי שִׂמְחַת הַכֹּל, הַשִּׂמְחָה שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. בִּזְמַן שֶׁיִּשְׂרָאֵל לֹא נִמְצָאִים בָּאָרֶץ הַקְּדוֹשָׁה, אָסוּר לָאָדָם לִשְׂמֹחַ וּלְהַרְאוֹת שִׂמְחָה, שֶׁכָּתוּב שִׂמְחוּ אֶת יְרוּשָׁלַם וְגִילוּ בָהּ וְגוֹ', וְגִילוּ בָהּ דַּוְקָא.</p>\n<p>רַבִּי אַבָּא רָאָה אִישׁ שֶׁהָיָה שָׂמֵחַ בְּבֵית טְרוֹנְיָא שֶׁבְּבָבֶל. הִכָּה בּוֹ וְאָמַר, שִׂמְחוּ אֶת יְרוּשָׁלם כָּתוּב (אמר רבי אבא), בִּזְמַן שֶׁיְּרוּשָׁלַיִם בְּשִׂמְחָה צָרִיךְ אָדָם לִשְׂמֹחַ. רַבִּי אֶלְעָזָר לְטַעְמוֹ, שֶׁאָמַר שִׂמְחוּ אֶת יְרוּשָׁלם, הַיְנוּ שֶׁכָּתוּב (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה.</p>\n<p>כָּתוּב אֶחָד אוֹמֵר, עִבְדוּ אֶת ה' בְּשִׂמְחָה. וְכָתוּב אֶחָד אוֹמֵר, (שם ב) עִבְדוּ אֶת ה' בְּיִרְאָה וְגִילוּ בִּרְעָדָה. מַה בֵּין זֶה לָזֶה? אֶלָּא, כָּאן בִּזְמַן שֶׁיִּשְׂרָאֵל שְׁרוּיִים בָּאָרֶץ הַקְּדוֹשָׁה - כָּאן בִּזְמַן שֶׁיִּשְׂרָאֵל שְׁרוּיִים בְּאֶרֶץ אַחֶרֶת. (ד\"א) עִבְדוּ אֶת ה' בְּיִרְאָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל בִּזְמַן שֶׁהִיא בַּגָּלוּת בֵּין הָעַמִּים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב (ישעיה נה) כִּי בְשִׂמְחָה תֵצֵאוּ, וְזוֹ הִיא כְּנֶסֶת יִשְׂרָאֵל. כֵּיוָן שֶׁאָמַר תֵּצֵאוּ, מֵהַגָּלוּת הוּא, וְנִקְרֵאת שִׂמְחָה. אָמַר לוֹ, וַדַּאי כָּךְ הוּא זֶה, שֶׁכָּל זְמַן שֶׁהִיא בַּגָּלוּת וְשׁוֹכֶבֶת לֶעָפָר, לֹא נִקְרֵאת שִׂמְחָה, עַד שֶׁהַקָּדוֹשׁ-בָּרוּךְ-הוּא יָבא אֵלֶיהָ, וִיקִימָהּ מֵהֶעָפָר וְיֹאמַר, (שם נב) הִתְנַעֲרִי מֵעָפָר קוּמִי וְגוֹ', (שם ס) קוּמִי אוֹרִי וְגוֹ', וְיִתְחַבְּרוּ כְאֶחָד, (ויקימה מעפרה) וְאָז חֶדְוָה נִקְרֵאת, חֶדְוַת הַכֹּל, וְאָז בְּשִׂמְחָה תֵצֵאוּ וַדַּאי. אָז כַּמָּה חֲיָלוֹת יֵצְאוּ מוּל הַגְּבִירָה לְחֶדְוַת הִלּוּלַת הַמֶּלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר (שם נה) הֶהָרִים וְהַגְּבָעוֹת יִפְצְחוּ וְגוֹ', וְכָתוּב (שם נב) כִּי הֹלֵךְ לִפְנֵיכֶם ה' וּמְאַסִּפְכֶם וְגוֹ'.</p>"],[9522012268,"<p>אִישׁ עַל דִּגְלוֹ בְאֹתֹת - אֵלּוּ אַרְבַּע מַחֲנוֹת שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהֵם שְׁנֵים עָשָׂר שְׁבָטִים, שְׁנֵים עָשָׂר תְּחוּמִים סָבִיב סָבִיב לָהּ. הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה, כָּתוּב (תהלים קכב) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ וְגוֹ'. שֶׁשָּׁם עָלוּ שְׁבָטִים - אֵלּוּ שְׁנֵים עָשָׂר שְׁבָטִים, שְׁנֵים עָשָׂר תְּחוּמִים שֶׁלְּמַטָּה.</p>\n<p>שִׁבְטֵי יָהּ - הֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁיָּ\"הּ עֵדוּת לְיִשְׂרָאֵל וַדַּאי. וְלָכֵן (במדבר כו) הָראוּבֵנִי, הַשִּׁמְעוֹנִי, יָ\"הּ בְּכָל אֶחָד וְאֶחָד. אֲבָל וַדַּאי כָּךְ הוּא, שֶׁהֲרֵי הָעֵץ הָעֶלְיוֹן הַקָּדוֹשׁ, בּוֹ חוֹתֵם בְּחוֹתָמוֹ. וּפֵרְשׁוּהָ שֶׁכָּתוּב, (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם וּפְנֵי אַרְיֵה אֶל הַיָּמִין וְגוֹ'. דְּמוּת אָדָם נִכְלֶלֶת בְּכֻלָּם, וְהַפָּנִים הָיוּ לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְנִפְרָדִים בִּדְמֻיּוֹתֵיהֶם, וְכֻלָּם כְּלוּלִים בּוֹ בָּאָדָם.</p>\n<p>מִיכָאֵל מִיָּמִין, גַּבְרִיאֵל מִשְּׂמֹאל, אוּרִיאֵל לִפְנֵיהֶם, רְפָאֵל לַאֲחוֹרֵיהֶם, הַשְּׁכִינָה מֵעֲלֵיהֶם. שְׁנַיִם מִכָּאן, וּשְׁנַיִם מִכָּאן, וְהִיא בָּאֶמְצַע. כְּמוֹ זֶה בָּאָרֶץ שֶׁלְּמַטָּה - שְׁנַיִם מִכָּאן, וּשְׁנַיִם מִכָּאן, וְיָ\"הּ בֵּינֵיהֶם.</p>\n<p>כֵּיוָן שֶׁלּוֹקְחִים שְׁנֵי דְגָלִים, מַה כָּתוּב? וְנָסַע אֹהֶל מוֹעֵד מַחֲנֵה הַלְוִיִּם וְגוֹ'. וְאַחַר כָּךְ אוֹתָם שְׁנַיִם אֲחֵרִים אַרְבַּע מַחֲנוֹת הֵן לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְנִמְצָאִים שְׁנֵים עָשָׂר. אַף כָּךְ לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>וְנָסַע בָּרִאשׁוֹנָה דֶּגֶל מַחֲנֵה יְהוּדָה מוּל מַחֲנֵה אוּרִיאֵל. וּמַחֲנֵה רְאוּבֵן מוּל מַחֲנֵה מִיכָאֵל. זֶה לַדָּרוֹם, וְזֶה לַמִּזְרָח. כָּךְ גַּם הַמִּזְבֵּחַ דְּרוֹמִית מִזְרָחִית. וּמַחֲנֵה דָן לַצָּפוֹן. מַחֲנֵה אֶפְרַיִם יָמָּה. מַחֲנֵה דָן מוּל מַחֲנֵה גַבְרִיאֵל. מַחֲנֵה אֶפְרַיִם לַמַּעֲרָב מוּל מַחֲנֵה רְפָאֵל. כָּךְ גַּם הַמִּזְבֵּחַ צְפוֹנִית מַעֲרָבִית. הַכֹּל אָחוּז זֶה בָּזֶה, עַד שֶׁהַכֹּל עוֹלֶה וְנֶאֱחָז בַּשֵּׁם הַקָּדוֹשׁ, שֶׁהוּא הָרֵאשִׁית שֶׁל הַכֹּל, הָעֶלְיוֹן שֶׁל הַכֹּל, הַקָּדוֹשׁ שֶׁל הַכֹּל, הַכֹּל כָּלוּל בּוֹ.</p>\n<p>י' מִזְרָח הוּא רֵאשִׁית הָאוֹר, הוֹלֵךְ וּמְשׁוֹטֵט וּמוֹצִיא לַדָּרוֹם, וְדָרוֹם יוֹצֵא וְתָלוּי בְּרֵאשִׁית הַמִּזְרָח. ה' דָּרוֹם, מִמֶּנּוּ יוֹצֵא דָרוֹם בָּעוֹלָם. וְנִכְנָס י' בְּרֵאשִׁית הַמִּזְרָח, וּמוֹצִיא אוֹתוֹ.</p>\n<p>וּמֵה' תְּלוּיִים דָּרוֹם וְצָפוֹן, וְאוֹתוֹ שֶׁבֵּינֵיהֶם, י' מִזְרָח, יָ\"הּ - דָּרוֹם וְצָפוֹן תְּלוּיִים בּוֹ. ו' בָּאֶמְצַע, וְזֶה הוּא בֵּן זָכָר. בִּגְלַל זֶה הוּא בֵּין צָפוֹן לְדָרוֹם. וְעַל זֶה שָׁנִינוּ, מִי שֶׁנּוֹתֵן מִטָּתוֹ בֵּין צָפוֹן לְדָרוֹם, יִהְיוּ לוֹ בָּנִים זְכָרִים. שֶׁהֲרֵי בֵּן זָכָר הוּא בֵּין צָפוֹן לְדָרוֹם. ה' עֶלְיוֹנָה, בָּהּ תָּלוּי צָפוֹן וְדָרוֹם, וּבֵן זָכָר בֵּינֵיהֶם, בְּסוֹד שֶׁל יו\"ה. ה' הָאַחֲרוֹנָה - מַעֲרָב.</p>\n<p>וְעַל זֶה הַדָּרוֹם אָחוּז בַּמִּזְרָח, שֶׁהוּא רֵאשִׁית הַשֶּׁמֶשׁ וְתָלוּי בּוֹ. וְעַל זֶה לָמַדְנוּ, מִצַּד אַבָּא אָחוּז וְתָלוּי הַחֶסֶד הָעֶלְיוֹן, מִצַּד הָאִמָּא תְּלוּיָה גְבוּרָה. כְּמוֹ זֶה אָחוּז הַכֹּל זֶה בָּזֶה.</p>\n<p>זָוִיּוֹת הַמִּזְבֵּחַ גַּם כֵּן מְסוֹבְבִים, וּבָא לוֹ לְקֶרֶן דְּרוֹמִית מִזְרָחִית. שֶׁהַדָּרוֹם כֹּחוֹ בַּמִּזְרָח, שֶׁהוּא רֵאשִׁית הַשֶּׁמֶשׁ, וְחֹזֶק הַשֶּׁמֶשׁ אֵן שׁוֹרֶה אֶלָּא בָּרֵאשִׁית. מִזְרָחִית צְפוֹנִית - כֵּיוָן שֶׁדָּרוֹם נוֹטֵל תָּקְפּוֹ שֶׁל הַמִּזְרָח, הוּא מֵאִיר לַצָּפוֹן, וְהַצָּפוֹן נִכְלָל בַּדָּרוֹם, שֶׁהֲרֵי שְׂמֹאל נִכְלָל בַּיָּמִין.</p>\n<p>צְפוֹנִית מַעֲרָבִית - שֶׁהֲרֵי הַמַּעֲרָב, שֶׁהוּא בְּה' אַחֲרוֹנָה, נוֹסֵעַ מֵהַצָּפוֹן. וְעַל זֶה הַצָּפוֹן נוֹסֵעַ לַמַּעֲרָב. מַעֲרָבִית דְּרוֹמִית - הִיא הוֹלֶכֶת (להתחבק) לְהִתְחַבֵּר בַּדָּרוֹם כְּמוֹ שֶׁדָּרוֹם תָּלוּי בַּמִּזְרָח, וְחָזְקוֹ הוֹלֵךְ בָּרֵאשִׁית. כָּךְ גַּם הַמַּעֲרָב הוֹלֵךְ (להתחבק) לְהֵאָחֵז בַּדָּרוֹם. זֶהוּ שֶׁכָּתוּב וִימִינוֹ תְּחַבְּקֵנִי. הַיָּמִין הַזֶּה הוּא הַדָּרוֹם, בִּגְלַל זֶה יוֹנֵק מִשְּׁנֵי צְדָדִים - מִצָּפוֹן וּמִדָּרוֹם. זֶהוּ שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. שְׂמֹאלוֹ - זֶהוּ צָפוֹן, וִימִינוֹ - זֶהוּ דָּרוֹם.</p>\n<p>וְסוֹד זֶה לָמַדְנוּ, שֶׁהַקָּדוֹשׁ-בָּרוּךְ-הוּא נוֹתֵן מִטָּתוֹ בֵּין צָפוֹן לְדָרוֹם, וְאוֹחֶזֶת הַבֵּן הַזֶּה בְּוַדַּאי, וְעַל זֶה יֵשׁ לִבְנֵי אָדָם לָתֵת מִטָּתָם בֵּין צָפוֹן לְדָרוֹם. וְזֶה לִמֵּד אוֹתִי אַבָּא, שֶׁנּוֹתְנִים לוֹ בָּנִים זְכָרִים. שֶׁהֲרֵי הוּא הִתְכַּוֵּן כְּלַפֵּי הָאֱמוּנָה הַשְּׁלֵמָה הָעֶלְיוֹנָה, בִּשְׁלֵמוּת הַכֹּל, לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא בֵּין צָפוֹן לְדָרוֹם, וּלְגַבֵּי כְּנֶסֶת יִשְׂרָאֵל שֶׁמְּאִירִים (שהיא) שֶׁהִיא בֵּין צָפוֹן לְדָרוֹם - וַדַּאי יִהְיו לוֹ בָּנִים זְכָרִים.</p>\n<p>וּבַכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה כְּמוֹ שֶׁלְּמַעְלָה. וּכְמוֹ שֶׁמַּרְאֶה מַעֲשֶׂה לְמַטָּה, כָּךְ מְעוֹרֵר לְמַעְלָה, וּפֵרְשׁוּהָ. שָׁמַע רַבִּי פִּנְחָס וְנָשַׁק לְרַבִּי אֶלְעָזָר, וּבָכָה וְצָחַק וְאָמַר, אַשְׁרֵי חֶלְקִי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522012269,"<p>פָּתַח וְאָמַר, (תהלים כז) ה' אוֹרִי וְיִשְׁעִי מִמִּי אִירָא וְגוֹ'. ה' אוֹרִי וְיִשְׁעִי, כֵּיוָן שֶׁאָדָם הִסְתַּכֵּל (נאחז) בָּאוֹר שֶׁלְּמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵאִיר עָלָיו, לֹא פוֹחֵד מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ס) וְעָלַיִךְ יִזְרַח ה' וּכְבוֹדוֹ עָלַיִךְ יֵרָאֶה. ה' מָעוֹז חַיַּי, כֵּיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹחֵז בָּאָדָם, לֹא יִפְחַד בְּאוֹתוֹ עוֹלָם מִכָּל בַּעֲלֵי הַדִּינִים. גַּם אֲנִי כְּמוֹ זֶה, כֵּיוָן שֶׁאָחַזְתִּי בְּאָבִיךְ וּבְךְ, לֹא אֶפְחַד בָּעוֹלָם הַזֶּה וּבָעוֹלָם הָאַחֵר.</p>\n<p>וְעָלֶיךָ כָּתוּב, (משלי כג) יִשְׂמַח אָבִיךְ וְגוֹ'. כֵּיוָן שֶׁכָּתוּב יִשְׂמַח אָבִיךְ וְאִמֶּךְ, מַה זֶּה וְתָגֵל יוֹלַדְתֶּךְ? שֶׁהֲרֵי בְּאִמֶּךְ מַסְפִּיק. אֶלָּא יִשְׂמַח אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְתָגֵל יוֹלַדְתֶּךְ - יוֹלַדְתְּךְ שֶׁלְּמַטָּה. אֵיפֹה שִׂמְחָתוֹ שֶׁל רַבִּי שִׁמְעוֹן אָבִיךְ? אֶלָּא פָּסוּק הוּא לְבַדּוֹ, שֶׁכָּתוּב (שם) גִּיל יָגִיל אֲבִי צַדִּיק - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְיוֹלֵד חָכָם יִשְׂמַח בּוֹ - זֶה אָבִיךְ שֶׁלְּמַטָּה. דָּבָר אַחֵר, גִּיל יָגִיל אֲבִי צַדִּיק - זֶה אָבִיךְ שֶׁלְּמַטָּה. וְיוֹלֵד חָכָם יִשְׂמַח בּוֹ, כָּתוּב בְּתוֹסֶפֶת וָא\"ו - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה.</p>"],[9522012270,"<p>אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (תהלים לא) בְּיָדְךְ אַפְקִיד רוּחִי פָּדִיתָה אוֹתִי ה' אֵל אֱמֶת. יֵשׁ לְהִסְתַּכֵּל בַּפָּסוּק הַזֶּה. רְאִיתֶם מִי שֶׁמַּפְקִיד דָּבָר בִּידֵי הַמֶּלֶךְ? אֶלָּא, וַדַּאי אַשְׁרֵי הָאִישׁ שֶׁהוֹלֵךְ בְּדַרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ וְלֹא חוֹטֵא לְפָנָיו. בֹּא רְאֵה, כֵּיוָן שֶׁנִּכְנָס הַלַּיְלָה, עֵץ הַמָּוֶת שׁוֹלֵט בָּעוֹלָם, וְעֵץ הַחַיִּים מִסְתַּלֵּק לְמַעְלָה לְמַעְלָה. וְכֵיוָן שֶׁעֵץ הַמָּוֶת שׁוֹלֵט בָּעוֹלָם לְבַדּוֹ, כָּל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם מָוֶת. מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתוֹ עֵץ גּוֹרֵם.</p>\n<p>וְהָאָדָם צָרִיךְ לְהַקְדִּים וּלְהַפְקִיד בְּיָדוֹ אֶת נַפְשׁוֹ בְּפִקָּדוֹן, כְּפִקָּדוֹן שֶׁל אָדָם שֶׁנּוֹתֵן פִּקָּדוֹן לְאַחֵר. שֶׁאַף עַל גַּב שֶׁהוּא הִתְחַיֵּב אֵלָיו יוֹתֵר מֵאוֹתוֹ פִּקָּדוֹן - לֹא כְּדַאי לְהֵאָחֵז בּוֹ, הוֹאִיל וְהַפִּקָּדוֹן נִמְסַר לוֹ, וְאִם יְסָרֵב בּוֹ - וַדַּאי נִבְדֹּק אַחֲרָיו, שֶׁאֵין הוּא מִזֶּרַע קֹדֶשׁ וְלֹא מִבְּנֵי הָאֱמוּנָה.</p>\n<p>כָּךְ אוֹתוֹ עֵץ, בְּנֵי אָדָם מַקְדִּימִים וְנוֹתְנִים לוֹ פִּקְדוֹן נַפְשָׁם, וְלוֹקֵחַ כָּל נִשְׁמוֹת בְּנֵי הָעוֹלָם. וְכֻלָּם טוֹעֲמִים טַעַם מָוֶת, מִשּׁוּם שֶׁזֶּה עֵץ הַמָּוֶת הוּא. וּמִשּׁוּם שֶׁכָּל נְפָשׁוֹת אֵלּוּ, אַף עַל גַּב שֶׁכֻּלָּם הִתְחַיְּבוּ לוֹ, וְלֹא כְּדַאי הוּא לְהָשִׁיב הַפִּקָּדוֹן לָאָדָם. אֶלָּא כֵּיוָן שֶׁכֻּלָּם נִמְסְרוּ לוֹ בְּפִקָּדוֹן, מַחֲזִיר כָּל הַפִּקְדוֹנוֹת לְבַעְלֵיהֶם.</p>\n<p>בֹּא רְאֵה, לֹא כְּדַאי לְעֵץ הַמָּוֶת הַזֶּה לְהַחֲזִיר פִּקְדוֹנוֹ לָאָדָם אֶלָּא בְּשָׁעָה שֶׁעֵץ הַחַיִּים מִתְעוֹרֵר בָּעוֹלָם. וּמָתַי מִתְעוֹרֵר אוֹתוֹ עֵץ חַיִּים? בְּשָׁעָה שֶׁעוֹלֶה הַבֹּקֶר. וְאָז, כֵּיוָן שֶׁזֶּה מִתְעוֹרֵר בָּעוֹלָם, כָּל בְּנֵי הָעוֹלָם חַיִּים, וּמַשְׁאִיר וּמַחֲזִיר אוֹתוֹ עֵץ הַמָּוֶת כָּל הַפִּקְדוֹנוֹת שֶׁהֻפְקְדוּ אֶצְלוֹ, וְהוֹלֵךְ לוֹ. מָה הַטַּעַם הֵם חַיִּים? מִשּׁוּם שֶׁאוֹתוֹ עֵץ הַחַיִּים גָּרַם.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי בְּנֵי אָדָם רַבִּים הֵם מִתְעוֹרְרִים בַּלַּיְלָה בְּעוֹד שֶׁעֵץ הַמָּוֶת שׁוֹלֵט? אֶלָּא וַדַּאי אוֹתוֹ עֵץ הַחַיִּים עוֹשֶׂה אֶת זֶה. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (תהלים יד) לִרְאוֹת הֲיֵשׁ מַשְׂכִּיל דֹּרֵשׁ אֶת אֱלֹהִים. וְלֹא יִהְיֶה פִּתְחוֹן פֶּה לְאָדָם שֶׁיֹּאמַר: אִלְמָלֵא שָׁלַטְתִּי בְנַפְשִׁי בַּלַּיְלָה, הָיִיתִי מִשְׁתַּדֵּל בַּתּוֹרָה. אָמַר רַבִּי יְהוּדָה, זֶה בְּיִשְׂרָאֵל בְּוַדַּאי, וְכָךְ הוּא! אֲבָל בְּאֻמּוֹת הָעוֹלָם שֶׁרָאִינוּ כָּזֶה, מָה הַטַּעַם? אָמַר לוֹ: יָפֶה מַה שֶּׁאָמַרְתָּ.</p>\n<p>פָּתַח וְאָמַר, (במדבר כג) מָה אֶקֹּב לֹא קַבֹּה אֵל וּמָה אֶזְעֹם לֹא זָעַם ה'. בּא רְאֵה, כְּמוֹ שֶׁיֵּשׁ לְמַעְלָה יֵשׁ לְמַטָּה. לְמַעְלָה יֵשׁ יָמִין וְיֵשׁ שְׂמֹאל - לְמַטָּה יִשְׂרָאֵל וְהָעַמִּים. יִשְׂרָאֵל אֲחוּזִים לְיָמִין בִּקְדֻשַּׁת הַמֶּלֶךְ הַקָּדוֹשׁ. הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לִשְׂמֹאל, לְצַד רוּחַ הַטֻּמְאָה. וְכֻלָּם לְמַטָּה מִכָּל דַּרְגוֹת הַשְּׂמֹאל. וְכָל הַדְּרָגוֹת אֲחוּזוֹת זוֹ בָּזוֹ עַד שֶׁתְּלוּיוֹת מֵהָרֹאשׁ. וּכְמוֹ שֶׁהָרֹאשׁ נוֹסֵעַ, בְּאוֹתוֹ הַגָּוֶן נוֹסֵעַ הַזָּנָב, שֶׁהוּא תַחְתּוֹן. מָה הַטַּעַם? מִשּׁוּם שֶׁאָחוּז בּוֹ. וּמִשּׁוּם זֶה הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, בְּאוֹתוֹ צַד הַטֵּמְאָה שֶׁלָּהֶם כָּךְ מֻנְהָגִים.</p>\n<p>בִּלְעָֹם הִשְׁתַּמֵּשׁ בְּכָל הַדְּרָגוֹת הַתַּחְתּוֹנוֹת, וְהוּא הָיָה רוֹאֶה בַּתַּחְתּוֹן הַזֶּה, שֶׁהוּא הַזָּנָב, שֶׁלֹּא יָכוֹל לְהִתְנַהֵג אֶלָּא בָּרֹאשׁ. מִשּׁוּם כָּךְ אָמַר מָה אֶקֹּב לֹא קַבּה אֵל, (שהוא הראש משום) שֶׁאוֹתוֹ הָרֹאשׁ הָעֶלְיוֹן אֵינוֹ נִמְצָא בְדִין בְּאוֹתָם הַיָּמִים.</p>\n<p>וְאַף עַל גַּב שֶׁהָאֵל הַזֶּה בֵּאַרְנוּ, הַמַּלְכוּת הַקְּדוֹשָׁה הַזּוֹ לוֹקַחַת שֵׁם כְּמוֹ הַכֹּל, וְהַטּוֹב וְהַחֶסֶד שֶׁל הָעוֹלָם הַזֶּה, (בארנו במקום אחר עליון, והוא טוב וחסד של העולם, המלכות הקדושה הזו לוקחת שם כמו שלמעלה) וּמִשּׁוּם זֶה נִקְרֵאת אֵל, אֶלָּא שֶׁהוּא זוֹעֵם בְּכָל יוֹם, שֶׁנִּמְצָא בּוֹ דִין.</p>\n<p>וּבֹא רְאֵה, אֵל שַׁדַּי בֵּאַרְנוּ שֶׁבּוֹ הֲנָאַת הָעוֹלָם, וְהוּא אָמַר לָעוֹלָם דַּי. שֶׁהֲרֵי הָאֵל זֶה הוּא שֶׁמִּזְדַּוֵּג עִמּוֹ, וּמִשּׁוּם כָּךְ נִקְרָא אֵל שַׁדַּי, אֵל שֶׁל שַׁדַּי. וְעַל זֶה מָה אֶקֹּב לֹא קַבֹּה אֵל. מִשּׁוּם כָּךְ, כְּמוֹ שֶׁמִּתְעוֹרֵר הָרֹאשׁ - כָּךְ מִתְעוֹרֵר הַתַּחְתּוֹן.</p>\n<p>בָּכָה רַבִּי אֶלְעָזָר, פָּתַח וְאָמַר, (ירמיה מו) קוֹלָהּ כַּנָּחָשׁ יֵלֵךְ וְגוֹ'. כָּעֵת (כמו זה) שֶׁיִּשְׂרָאֵל בַּגָּלוּת, הִיא וַדַּאי הוֹלֶכֶת כַּנָּחָשׁ. נָחָשׁ, כְּשֶׁהוּא (בדין) כּוֹפֵף רֹאשׁוֹ לֶעָפָר, עוֹלֶה הַזָּנָב, שׁוֹלֵט וּמַכֶּה אֶת כָּל אוֹתָם שֶׁנִּמְצָאִים לְפָנָיו. אַף כָּךְ כָּעֵת בַּגָּלוּת - כְּגוֹן זֶה הָרֹאשׁ כָּפוּף לֶעָפָר, וְהַזָּנָב שׁוֹלֵט. מִי עָשָׂה שֶׁהַזָּנָב יַעֲלֶה לְמַעְלָה, יִשְׁלֹט וְיַכֶּה? הָרֹאשׁ שֶׁמִּתְכּוֹפֵף לְמַטָּה. וְעִם כָּל זֶה, מִי מַנְהִיג אֶת הַזָּנָב וּמִי מַסִּיעוֹ לְמַסָּעָיו? זֶה הָרֹאשׁ. אַף עַל גַּב שֶׁהוּא כָּפוּף לֶעָפָר, הוּא מַנְהִיג אֶת מַסָּעָיו. בִּגְלַל זֶה, קוֹלָהּ כַּנָּחָשׁ יֵלֵךְ.</p>\n<p>וְעַכְשָׁו, שְׁאָר הָעַמִּים שֶׁהֵם אֲחוּזִים בַּזָּנָב, עוֹלִים לְמַעְלָה, וְשׁוֹלְטִים וּמַכִּים, וְהָרֹאשׁ כָּפוּף לֶעָפָר, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם וְגוֹ'. וְעִם כָּל זֶה, הָרֹאשׁ הַזֶּה מַנְהִיג אֶת הַזָּנָב וְשׁוֹמֵר (ומסיע) אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים א) שָׂמֻנִי נֹטֵרָה אֶת הַכְּרָמִים. אֵלֶּה עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, שֶׁהֵם הַזָּנָב. בָּא רַבִּי יְהוּדָה, וְנָשַׁק יָדָיו וְאָמַר, אִלְמָלֵא לֹא שָׁאַלְתִּי דָבָר בָּעוֹלָם, אֶלָּא שֶׁשָּׁאַלְתִּי זֶה וְהִרְוַחְתִּי אוֹתוֹ - דַּי לִי, שֶׁעַכְשָׁו יָדַעְתִּי עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת וְשִׁלְטוֹנָם אֵיךְ מֻנְהָג. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁעֲלֵיהֶם כָּתוּב (תהלים קלה) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ וְגוֹ'.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, מַה זֶּה לִסְגֻלָּתוֹ? אָמַר לוֹ, שְׁלֹשֶׁת הָאָבוֹת הַלָּלוּ נִקְרְאוּ סְגֻלָּה, בֵּין לְמַעְלָה בֵּין לְמַטָּה, כְּמוֹ זֶה כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים, וְהַכֹּל אֶחָד. וְאֵלֶּה סְגֻלָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּסְגֻלָּתוֹ לְמַטָּה, וְזֶהוּ שֶׁכָּתוּב (שמות יט) וִהְיִיתֶם לִי סְגֻלָּה מִכָּל הָעַמִּים.</p>"],[9522012271,"<p>וְנָסַע אֹהֶל מוֹעֵד מַחֲנֵה הַלְוִיִּם וְגוֹ'. אַחַר כָּךְ מַה כָּתוּב? (ונסע) דֶּגֶל מַחֲנֵה אֶפְרַיִם לְצִבְאֹתָם יָמָּה. הַיְנוּ שְׁכִינָה שְׁרוּיָה בַּמַּעֲרָב, וּפֵרְשׁוּהָ. כָּתוּב (בראשית מח) וַיְבָרֲכֵם בַּיּוֹם הַהוּא לֵאמוֹר בְּךְ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר וְגוֹ', וַיָּשֶׂם אֶת אֶפְרַיִם וְגוֹ'. בְּךְ יְבָרֵךְ יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. מַה מַּשְׁמִיעֵנוּ?</p>\n<p>אֶלָּא בְּךְ יִתְבָּרֵךְ יִשְׂרָאֵל לֹא כָתוּב, אוֹ בְּךְ יְבֹרַךְ יִשְׂרָאֵל. מַה זֶּה יְבָרֵךְ יִשְׂרָאֵל? אֶלָּא יִשְׂרָאֵל הַקָּדוֹשׁ לֹא יְבָרֵךְ אֶת הָעוֹלָם אֶלָּא בְּךְ, שֶׁאַתָּה בַּמַּעֲרָב, וְכָתוּב (שם לה) אֲנִי אֵל שַׁדַּי פְּרֵה וּרְבֵה. לָמַדְנוּ שֶׁרָאָה עִמּוֹ שְׁכִינָה, וְאָז אָמַר בְּךְ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר. בְּךְ יְבָרֵךְ אֶת הָעוֹלָם.</p>\n<p>וְאֵיךָ רָאָה? וַהֲרֵי כָּתוּב (שם) וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִזֹּקֶן וְגוֹ'? אֶלָּא כָּתוּב, שִׂכֵּל אֶת יָדָיו. מַה זֶּה שִׂכֵּל? אֶלָּא הַיָּמִין הָיָה זָקוּף, וְהַשְּׁכִינָה הֵסִיטָה כְּלַפֵּי אֶפְרַיִם, וְהֵרִיחַ רֵיחַ שְׁכִינָה עַל רֹאשׁוֹ, וְאָז אָמַר בְּךְ יְבָרֵךְ יִשְׂרָאֵל, וְרָאָה שֶׁהוּא בַּמַּעֲרָב.</p>\n<p>וַדַּאי שְׁכִינָה בַּמַּעֲרָב, וַהֲרֵי בֵּאַרְנוּ, כְּדֵי שֶׁיִּהְיֶה בֵּין צָפוֹן לְדָרוֹם, וּלְהִתְחַבֵּר בְּגוּף וְלִהְיוֹת בְּזִוּוּג אֶחָד. וְצָפוֹן מְקַבֵּל אוֹתָהּ תַּחַת הָרֹאשׁ, וְהַדָּרוֹם מְחַבֵּק אוֹתָהּ. זֶהוּ שֶׁכָּתוּב (שיר השירים ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וַהֲרֵי בֵּאַרְנוּ וַדַּאי, (שם ג) מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, בֵּין צָפוֹן לְדָרוֹם, וּלְהִתְחַבֵּר בְּגוּף, וְאָז כְּלָל אֶחָד לְהִתְבָּרֵךְ הָעוֹלָם. לָמַדְנוּ, כָּל הָאוֹמֵר תְּהִלָּה לְדָוִד שָׁלֹשׁ פְּעָמִים בְּכָל יוֹם, מֻבְטָח לוֹ שֶׁהוּא בֶּן הָעוֹלָם הַבָּא. וַהֲרֵי בֵּאַרְנוּ, כְּדֵי לְזַוֵּג אֶת הַתְּהִלָּה הַזּוֹ, וְשֶׁתִּמָּצֵא בְּכָל יוֹם בֵּין צָפוֹן לְדָרוֹם.</p>\n<p>בָּא אָדָם בַּבֹּקֶר - מְקַבֵּל עָלָיו עֹל מַלְכוּת שָׁמַיִם (כמו שנתבאר, מסדר שבח) בְּאוֹתָן תִּשְׁבָּחוֹת שֶׁאוֹמֵר תְּהִלָּה לְדָוִד, וְכָל הַהַלְלוּיָהּ, שֶׁהֵם סִדּוּר שֶׁל עֶשֶׂר תִּשְׁבָּחוֹת שֶׁל עֲשָׂרָה כְתָרִים קְדוֹשִׁים שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וּמִשּׁוּם זֶה עֲשָׂרָה הֵם הַלְלוּיָהּ. אַחַר כָּךְ סִיֵּם בְּעֶשֶׂר תִּשְׁבָּחוֹת, שֶׁהֵן: (תהלים קנ) הַלְלוּיָהּ הַלְלוּ אֵל בְּקָדְשׁוֹ וְגוֹ', הַלְלוּהוּ וְגוֹ'. מִי אֵלֶּה עֲשָׂרָה הַלְלוּיָהּ, וַהֲרֵי חֲמִשָּׁה הֵם? אֶלָּא מַתְחִיל שֶׁבַח בְּהַלְלוּיָהּ, וּמְסַיֵּם בְּהַלְלוּיָהּ.</p>\n<p>לְאַחַר הָעִלּוּי שֶׁל סִדּוּר הַשֶּׁבַח בְּאָז יָשִׁיר מֹשֶׁה, שֶׁיֵּשׁ בּוֹ הַכֹּל, וּבָזֶה מְקַבֵּל עָלָיו עֹל מַלְכוּת הַקְּדוֹשָׁה. אַחַר כָּךְ מַשְׁרֶה אוֹתָהּ בְּחֶסֶד בְּסוֹף הַתְּפִלָּה, לְהִתְקַדֵּשׁ בּוֹ. אַחַר כָּךְ בִּתְפִלַּת מִנְחָה, שֶׁהַגְּבוּרָה תְלוּיָה וְהַדִּין שׁוֹרֶה. נִמְצָא בְּכָל הַדָּרוֹם (היום) הַמִּטָּה הַזּוֹ שֶׁנְּתוּנָה בֵּין צָפוֹן לְדָרוֹם, לְהִתְחַבֵּר בְּזִוּוּג זֶה בַּגּוּף כָּרָאוּי. וּמִי שֶׁמְּסַדֵּר וּמְחַבֵּר אוֹתָהּ בְּכָל יוֹם כָּךְ, וַדַּאי הוּא בֶּן הָעוֹלָם הַבָּא.</p>\n<p>מִשּׁוּם כָּךְ דֶּגֶל שֶׁל מַחֲנֵה אֶפְרַיִם יָמָּה, וְהוּא בֵּין צָפוֹן לְדָרוֹם. דָּרוֹם רְאוּבֵן מִצַּד אֶחָד, שֶׁכָּתוּב דֶּגֶל מַחֲנֵה רְאוּבֵן תֵּימָנָה. צָפוֹן דָּן מִצַּד אַחֵר, שֶׁכָּתוּב דֶּגֶל מַחֲנֵה דָן צָפֹנָה. אֶפְרַיִם בֵּין זֶה לָזֶה. נִמְצָא מַעֲרָב, שֶׁהוּא אֶפְרַיִם, בֵּין צָפוֹן לְדָרוֹם, הַכֹּל כְּמוֹ לְמַעְלָה.</p>\n<p>סוֹד לְיוֹשְׁבֵי הַדָּרוֹם אַחֵינוּ. וְכָךְ שָׁלַח לָהֶם: אַחֵינוּ, מִצַּד הַמְּנוֹרוֹת (מסדרים מנורות) בְּסוֹדוֹת קְשׁוּרִים, שֶׁרְצִיתֶם לְיַחֵד יִחוּד בַּטֹּפֶס שֶׁל קֶשֶׁר עֶלְיוֹן, קַבְּלוּ עֲלֵיכֶם עֹל מַלְכוּת הַקְּדוֹשָׁה בְּכָל יוֹם בַּהַתְחָלָה, וּבָזֶה תַעֲלוּ (בקשר) בְּהֶעְלֵם (בהיכל) קָדוֹשׁ שֶׁל הַדָּרוֹם, וְסוֹבְבוּ צִדְדֵי הָעוֹלָם עַד שֶׁיִּתְקַשְּׁרוּ בְּקֶשֶׁר אֶחָד, וּבַדָּרוֹם (התחזקו) (תקבעו) מָקוֹם, וְשָׁם תִּהְיוּ.</p>"],[9522012272,"<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, סִימָן לְזִוּוּג הַיִּחוּד מִנַּיִן? אָמַר לוֹ, בְּנִי, אַף עַל גַּב שֶׁבֵּאַרְנוּ דְבָרִים לְכָל צַד וְצַד, וְהִתְפַּזְּרוּ כָּאן דָּבָר וְכָאן דָּבָר - סִימָן זֶה נְקֹט בְּיָדְךְ, וְכָךְ זֶה, כְּמוֹ סְבִיב הַמִּזְבֵּחַ. שֶׁלָּמַדְנוּ, וּבָא לוֹ לְקֶרֶן דְּרוֹמִית מִזְרָחִית, מִזְרָחִית צְפוֹנִית, צְפוֹנִית מַעֲרָבִית, מַעֲרָבִית דְּרוֹמִית. אָמַר לוֹ, וַהֲרֵי לֹא יָכוֹל עַד שֶׁמְּקַבֵּל עָלָיו אָדָם עֹל מַלְכוּת הַקְּדוֹשָׁה בַּתְּחִלָּה וְנוֹתֵן עָלָיו עֹל זֶה, וְאַתָּה אָמַרְתָּ שֶׁיָּבא לַדָּרוֹם בַּתְּחִלָּה?!</p>\n<p>אָמַר לוֹ, הַכֹּל אָמַרְתִּי לְךְ, שֶׁהֲרֵי וּבָא לוֹ לְקֶרֶן, אָמַרְתִּי בַּהַתְחָלָה, וַהֲרֵי יָדַעְתָּ סוֹד הַקֶּרֶן, וְזֶהוּ עֹל מַלְכוּת הַקְּדוֹשָׁה. אַחַר כָּךְ דְּרוֹמִית מִזְרָחִית, שֶׁשָּׁם הוּא עֵץ הַחַיִים, וְזֶה לְזַוֵּג אוֹתוֹ בַּמִּזְרָח, שֶׁהוּא הָאָב הָעֶלְיוֹן, שֶׁהֲרֵי הַבֵּן מִצַּד אַבָּא הוּא בָּא. וְלָכֵן מִדָּרוֹם לַמִּזְבֵּחַ, שֶׁכֹּחַ הַדָּרוֹם הוּא בַּמִּזְרָח, וְצָרִיךְ לְהִתְקַשֵּׁר כְּאֶחָד, דָּרוֹם בְּמִזְרָח.</p>\n<p>וְהַמִּזְרָח שֶׁמִּתְקַשֵּׁר בַּצָּפוֹן, (כמו שנאמר (תהלים יז) וצפונך תמלא בטנם) מִשּׁוּם שֶׁזֶּה מַשְׁלִים וּמְמַלֵּא נְחָלִים וּמַעְיָנוֹת, וְעַל זֶה מִזְרָחִית צְפוֹנִית, אֵלּוּ אַבָּא וְאִמָּא שֶׁלֹּא נִפְרָדִים לְעוֹלָם, וַהֲרֵי בֵּאַרְנוּ. וּמַה שֶּׁנֶּאֱמַר צְפוֹנִית, שֶׁהוּא סֵתֶר עֶלְיוֹן, וּמִצִּדָּהּ יוֹצֵא צָפוֹן, וּמִצִּדָּהּ מִתְעוֹרְרִים הַדִּינִים, אַף עַל גַּב שֶׁהִיא רַחֲמִים וְשִׂמְחָה. וַהֲרֵי בֵּאַרְנוּ. וּכְשֶׁהִיא יוֹצֵאת - צָפוֹן יוֹצֵא עִמָּהּ, שֶׁהוּא נִכְלָל וְנִקְשָׁר בַּדָּרוֹם.</p>\n<p>אַחַר כָּךְ צְפוֹנִית מַעֲרָבִית, שֶׁהֲרֵי מִצַּד הָאַבָּא יוֹצֵא בֵּן, וּמִצַּד הָאִמָּא יוֹצֵאת בַּת, וּמִשּׁוּם כָּךְ צְפוֹנִית מַעֲרָבִית, וְזוֹהִי קֶרֶן שֶׁל הַתְחָלָה, שֶׁכָּעֵת נִקְשֶׁרֶת בַּצָּפוֹן סְתָם. אַחַר כָּךְ צָרִיךְ לְקָשְׁרָהּ בַּדָּרוֹם, שֶׁשָּׁם הוּא קֶשֶׁר הַכֹּל, וְהַגּוּף בָּהּ נִמְצָא, וְעַל כָּךְ מַעֲרָבִית דְּרוֹמִית.</p>\n<p>נִמְצֵאת קֶרֶן זוֹ שָׁלֹשׁ פְּעָמִים: אַחַת לְקַבֵּל אוֹתָהּ אָדָם בַּתְּחִלָּה, אַחַר כָּךְ לְקָשְׁרָהּ בִּשְׁתֵּי זְרוֹעוֹת, לְהִתְחַבֵּר בַּגּוּף וְלִהְיוֹת הַכֹּל אֶחָד. וְזֶהוּ סִדּוּר שֶׁל הַיִּחוּד הַשָּׁלֵם. וְכָל צַד וְצַד בְּאוֹתוֹ קֶשֶׁר שֶׁרָאוּי לוֹ, וְלֹא יַחֲלִיף צַד בְּצַד אַחֵר שֶׁלֹּא רָאוּי לוֹ, כְּדֵי שֶׁלֹּא יֵעָנֵשׁ. מִי שֶׁעוֹשֶׂה יִחוּד זֶה כָּרָאוּי כְּפִי שֶׁאָמַרְנוּ, אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֲרֵי יוֹדֵעַ לְסַדֵּר שֶׁבַח רִבּוֹנוֹ וְיִחוּד רִבּוֹנוֹ, וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ. עָלָיו כָּתוּב, (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>"],[9522012273,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (תהלים כה) לְדָוִד אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא אֱלֹהַי בְּךְ בָטַחְתִּי וְגוֹ'. מָה רָאָה דָוִד לְסַדֵּר שֶׁבַח זֶה כָּכָה? וְכָל הַשְּׁבָחִים שֶׁהֵם בְּא\"ב, כֻּלָּם שְׁלֵמִים, וְזֶה חָסֵר, שֶׁאֵין בּוֹ ו'? וְלָמָּה סִדּוּר זֶה לִפֹּל עַל אַפַּיִם?</p>\n<p>אֶלָּא סוֹד עֶלְיוֹן הוּא גָּנוּז בֵּין הַחֲבֵרִים. בְּשָׁעָה שֶׁנִּכְנָס הַלַּיְלָה, (ושולט) הָעֵץ הַתַּחְתּוֹן שֶׁהַמָּוֶת תָּלוּי בּוֹ, פּוֹרֵשׂ עֲנָפָיו וּמְכַסֶּה הַכֹּל. וְעַל כָּךְ מַחְשִׁיךְ, וְכָל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם הַמָּוֶת, וּמַקְדִּים אָדָם וְנוֹתֵן פִּקְדוֹן נַפְשׁוֹ, וּמַפְקִיד בְּיָדוֹ בְּפִקָּדוֹן. וּמִשּׁוּם שֶׁלּוֹקֵחַ אוֹתָם בְּפִקָּדוֹן, חוֹזֵר הַפִּקָּדוֹן לִבְעָלָיו בְּשָׁעָה שֶׁמַּגִּיעַ הַבֹּקֶר. כְּשֶׁמַּגִּיעַ הַבֹּקֶר וְחוֹזֵר אֵלָיו פִּקְדוֹנוֹ, צָרִיךְ לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא הַנֶּאֱמָן הָעֶלְיוֹן.</p>\n<p>אַחֲרֵי שֶׁקָּם, נִכְנָס לְבֵית הַכְּנֶסֶת, מִתְעַטֵּר בִּתְפִלִּין, מִתְכַּסֶּה בְּכִסּוּי צִיצִית, נִכְנָס וּמְטַהֵר עַצְמוֹ בַּקָּרְבָּנוֹת בַּתְּחִלָּה, אַחַר כָּךְ מְקַבֵּל עָלָיו עֹל מַלְכוּת בַּסִּדּוּר שֶׁל שִׁבְחֵי דָוִד, שֶׁהֵם סִדּוּר שֶׁל עֹל מַלְכוּת. וּבְסִדּוּר שֶׁבַח זֶה מַשְׁרֶה עָלָיו אוֹתוֹ עֹל. אַחַר כָּךְ סִדּוּר תְּפִלַּת מִיֹּשֶׁב, וּתְפִלָּה מֵעֹמֶד, לְקָשְׁרָם כְּאֶחָד.</p>\n<p>בֹּא רְאֵה סוֹד הַדָּבָר, אַף עַל גַּב שֶׁתְּפִלָּה תְּלוּיָה בְּמֶלֶל וְדִבּוּר הַפֶּה - הַכֹּל תָּלוּי בְּעִקַּר הַמַּעֲשֶׂה בַּתְּחִלָּה, אַחַר כָּךְ בְּדִבּוּר וּבְמֶלֶל הַפֶּה. אֵיזֶה מַעֲשֶׂה? אֶלָּא אוֹתוֹ מַעֲשֶׂה שֶׁעוֹשֶׂה הָאָדָם בַּתְּחִלָּה כְּמוֹ תְּפִלָּה זוֹ. וְלֹא יִתְפַּלֵּל אָדָם תְּפִלָּה, עַד שֶׁיִּרְאֶה מַעֲשֶׂה בַּתְּחִלָּה כְּמוֹ הַתְּפִלָּה.</p>\n<p>מַעָשֶׂה רִאשׁוֹן (בראשונה מעשה) בְּשָׁעָה שֶׁאָדָם קָם - צָרִיךְ לְטַהֵר עַצְמוֹ בַּתְּחִלָּה, וְאַחַר כָּךְ יְקַבֵּל עָלָיו עֹל זֶה, יִפְרֹשׂ עַל רֹאשׁוֹ פְּרִיסַת מִצְוָה. אַחַר כָּךְ יִקָּשֵׁר קֶשֶׁר הַיִּחוּד, שֶׁהֵם תְּפִלִּין, (מהו תפלין, ') תְּפִלָּה שֶׁל רֹאשׁ וְשֶׁל יָד, וּלְתַקְּנָם בְּקֶשֶׁר אֶחָד בִּשְׂמֹאל וְעַל הַלֵּב, כְּפִי שֶׁבֵּאַרְנוּ (שיר השירים ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וְגוֹ'. וְכָתוּב (שם ח) שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ כַּחוֹתָם עַל זְרוֹעֶךְ. וַהֲרֵי בֵּאַרְנוּ. וְזֶהוּ הַמַּעֲשֶׂה שֶׁבַּתְּחִלָּה.</p>\n<p>אַחַר כָּךְ, בְּשָׁעָה שֶׁאָדָם נִכְנָס לְבֵית הַכְּנֶסֶת, יְטַהֵר עַצְמוֹ בַּתְּחִלָּה בַּקָּרְבָּנוֹת, בְּדִבּוּר הַפֶּה. אַחַר כָּךְ יְקַבֵּל עָלָיו עֹל מַלְכוּת זֶה, לִפְרֹשׂ עַל רֹאשׁוֹ (פרישת מצוה) בְּשִׁבְחֵי דָּוִד הַמֶּלֶךְ, כְּמוֹ הַמַּעֲשֶׂה שֶׁפּוֹרֵס עַל רֹאשׁוֹ פְּרִישַׂת מִצְוָה. אַחַר כָּךְ תְּפִלַּת מִיֹּשֶׁב כְּנֶגֶד תְּפִלִּין שֶׁל יָד, וְאַחַר כָּךְ תְּפִלַּת מֵעֹמֶד שֶׁהִיא כְּנֶגֶד תְּפִלִּין שֶׁל רֹאשׁ. וְזֶה כְּמוֹ זֶה. מַעֲשֶׂה כְּמוֹ דִבּוּר. וַדַּאי בְּמַעֲשֶׂה וְדִבּוּר תְּלוּיָה הַתְּפִלָּה.</p>\n<p>וְאִם פּוֹגֵם אֶת הַמַּעֲשֶׂה, הַדִּבּוּר לֹא מוֹצֵא מָקוֹם שֶׁשּׁוֹרֶה בּוֹ, וְזוֹ לֹא תְפִלָּה, וְנִפְגָּם הָאִישׁ הַהוּא לְמַעְלָה וּלְמַטָּה, (ולא עוד, אלא) שֶׁצָּרִיךְ לְהַרְאוֹת מַעֲשֶׂה וּלְמַלֵּל דִּבּוּר עָלָיו, וְזוֹהִי תְּפִלָּה שְׁלֵמָה. אוֹי לָאִישׁ שֶׁפּוֹגֵם בִּתְפִלָּתוֹ, עֲבוֹדַת רִבּוֹנוֹ, עָלָיו כָּתוּב (ישעיה א) כי תבאו לראות פני וגו'. גם כי תרבו תפלה אינני שמע. שהרי במעשה ודבור הדבר תלוי.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁאָדָם עוֹשֶׂה תְפִלּוֹת כָּךְ, בְּמַעֲשֶׂה וּבְדִבּוּר, וְקוֹשֵׁר קֶשֶׁר הַיִּחוּד, נִמְצָא שֶׁעַל יָדוֹ מִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים. וְאָז צָרִיךְ הָאָדָם לְהַרְאוֹת עַצְמוֹ, אַחֲרֵי שֶׁסִּיֵּם תְּפִלַּת עֲמִידָה, כְּאִלּוּ נִפְטָר מִן הָעוֹלָם, שֶׁהֲרֵי נִפְרָד מֵעֵץ הַחַיִּים וְכִנֵּס רַגְלָיו לְאוֹתוֹ עֵץ הַמָּוֶת, שֶׁהֶחֱזִיר לוֹ פִּקְדוֹנוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מט) וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה, שֶׁהֲרֵי הוֹדָה עַל חֲטָאָיו וְהִתְפַּלֵּל עֲלֵיהֶם. עַכְשָׁו צָרִיךְ לְהִתְכַּנֵּס לְאוֹתוֹ עֵץ הַמָּוֶת, וְלִנְפֹּל וְלוֹמַר אֵלָיו, אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. בַּהַתְחָלָה נָתַתִּי לְךְ בְּפִקָּדוֹן. כָּעֵת שֶׁקָּשַׁרְתִּי אֶת הַיִּחוּד וְעָשִׂיתִי מַעֲשֶׂה וְדִבּוּר כָּרָאוּי וְהוֹדֵיתִי עַל חֲטָאַי, הֲרֵי נַפְשִׁי מָסַרְתִּי לְךְ בְּוַדַּאי.</p>\n<p>וְיִרְאֶה אָדָם עַצְמוֹ כְּאִלּוּ נִפְטַר מֵהָעוֹלָם, שֶׁנַּפְשׁוֹ מָסַר לִמְקוֹם הַמָּוֶת הַזֶּה, מִשּׁוּם כָּךְ אֵין בּוֹ וָא\"ו, שֶׁוָּא\"ו עֵץ הַחַיִּים הוּא, וְזֶה עֵץ הַמָּוֶת הוּא. וְזֶה בָּא לְהַשְׁמִיעֵנוּ, שֶׁסּוֹד הַדָּבָר (מה בא להשמיענו סוד הדבר) - שֶׁיֵּשׁ חֲטָאִים שֶׁלֹּא מִתְכַּפְּרִים עַד שֶׁנִּפְטָר הָאָדָם מֵהָעוֹלָם, זֶהוּ שֶׁכָּתוּב (ישעיהכב) אִם יְכֻפַּר הֶעָון הַזֶּה לָכֶם עַד תְּמֻתוּן. וְזֶה נָתַן עַצְמוֹ וַדַּאי לָמוּת וּמָסַר נַפְשׁוֹ לְמָקוֹם זֶה, לֹא בְּפִקָּדוֹן כְּמוֹ בַּלַּיְלָה, אֶלָּא כְּמִי שֶׁנִּפְטָר מֵהָעוֹלָם וַדַּאי.</p>\n<p>וְתִקּוּן זֶה צָרִיךְ בְּכַוָּנַת הַלֵּב, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עָלָיו וּמְכַפֵּר לוֹ עַל חֲטָאָיו. אַשְׁרֵי הָאִישׁ שֶׁיּוֹדֵעַ לְפַתּוֹתוֹ וְלַעֲבֹד לְרִבּוֹנוֹ בְּרָצוֹן וּבְכַוָּנַת הַלֵּב. אוֹי לְמִי שֶׁבָּא לְפַתּוֹת לְרִבּוֹנוֹ בְּלֵב רָחוֹק, וְלֹא בְרָצוֹן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים עח) וַיְפַתּוּהוּ בְּפִיהֶם וּבִלְשׁוֹנָם יְכַזְּבוֹ לוֹ וְלִבָּם לֹא נָכוֹן עִמּוֹ. הוּא אוֹמֵר (שם כה) אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא, וְלֹא כָּל דְּבָרָיו, אֶלָּא בְּלֵב רָחוֹק, זֶה גּוֹרֵם עָלָיו לְהִסְתַּלֵּק מֵהָעוֹלָם טֶרֶם שֶׁלֹּא הִגִּיעוּ יָמָיו, בִּזְמַן שֶׁאִילָן זֶה מִתִעוֹרֵר בָּעוֹלָם לַעֲשׂוֹת דִּין.</p>\n<p>וְלָכֵןֹ צָרִיךְ אָדָם לְהַדְבִּיק נַפְשׁוֹ וּרְצוֹנוֹ בְּרִבּוֹנוֹ, וְלֹא יָבא אֵלָיו בְּרָצוֹן כּוֹזֵב, מִשּׁוּם שֶׁכָּתוּב (שם קא) דֹּבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי. מַה זֶּה לֹא יִכּוֹן? בְּשָׁעָה שֶׁהוּא מַתְקִין עַצְמוֹ לָזֶה וְלִבּוֹ רָחַק מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, קוֹל יוֹצֵא וְאוֹמֵר: לֹא יִכּוֹן לְנֶגֶד עֵינָי. (למה) זֶה צָרִיךְ לְתַקֵּן אֶת עַצְמוֹ, לֹא יִכּוֹן, אֵינוֹ רוֹצֶה שֶׁיִּתְתַּקֵּן. כָּל שֶׁכֵּן אִם הוּא בָּא לְיַחֵד שֵׁם הַקָּדוֹשׁ וְלֹא מְיַחֲדוֹ כָּרָאוּי.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (ישעיה סו) וּבָאוּ וְרָאוּ אֶת כְּבוֹדִי וְגוֹ'. וְכָתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ וְגוֹ'. בָּא רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ וְאָמַר, אִלְמָלֵא לֹא בָאתִי לָעוֹלָם רַק לִשְׁמֹעַ דְּבָרִים אֵלּוּ - דַּי לִי. אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקִי וְאַשְׁרֵי חֵלֶק יִשְׂרָאֵל, שֶׁנִּדְבָּקִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים וְגוֹ'. (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. בָּרוּךָ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן</p>"],[9522012274,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר נָשֹׂא אֶת רֹאשׁ בְּנֵי גֵרְשׁוֹן וְגוֹ'. רַבִּי אַבָּא פָּתַח, (תהלים לב) אַשְׁרֵי אָדָם לֹא יַחְשּב ה' לוֹ עָון וְאֵין בְּרוּחוֹ רְמִיָּה. הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ. וְיֵשׁ לְהִסְתַּכֵּל בּוֹ, וְכָךְ פֵּרְשׁוּהוּ.</p>\n<p>בֹּא רְאֵה, בִּשְׁעַת תְּפִלַּת מִנְחָה הַדִּין שׁוֹרֶה בָּעוֹלָם, וְיִצְחָק תִּקֵּן תְּפִלַּת מִנְחָה, וּגְבוּרָה עֶלְיוֹנָה שׁוֹלֶטֶת בָּעוֹלָם, עַד שֶׁבָּא וְנִכְנָס הַלַּיְלָה, בִּשְׁבִיל לְקַבֵּל אוֹתוֹ (ללילה). וּמִזְּמַן שֶׁשּׁוֹרָה תְפִלַּת מִנְחָה, נִפְרָד הַשְּׂמֹאל לְקַבֵּל (אותו) וּמִתְעוֹרֵר הַלַּיְלָה.</p>\n<p>אַחַר שֶׁמִּתְעוֹרְרִים כָּל אוֹתָם שׁוֹמְרֵי הַפְּתָחִים שֶׁבַּחוּץ, כֻּלָּם מִתְעוֹרְרִים בָּעוֹלָם וּמִתְפַּשְּׁטִים, וְכָל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם מָוֶת.</p>\n<p>וַהֲרֵי נִתְבָּאֵר. בַּחֲצוֹת הַלַּיְלָה מַמָּשׁ מִתְעוֹרֵר הַשְּׂמֹאל כְּמִקֹּדֶם, וְשׁוֹשַׁנָּה הַקְּדוֹשָׁה מַעֲלָה רֵיחוֹת וּמְשַׁבַּחַת וּמְרִימָה קוֹל, וְאָז עוֹלֶה וְשׁוֹרֶה הָרֹאשׁ לְמַעְלָה בַּשְּׂמֹאל, וְהַשְּׂמֹאל אָז מְקַבְּלָהּ.</p>\n<p>אָז הַכָּרוֹז קוֹרֵא בָעוֹלָם, שֶׁהֲרֵי זְמַן הוּא לְהִתְעוֹרֵר לְשַׁבֵּחַ לַמֶּלֶךְ. וְאָז תִּשְׁבָּחוֹת מִתְעוֹרְרוֹת, וְנִמְצֵאת הִתְבַּשְּׂמוּת הַכֹּל. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּתְעוֹרֵר לְזַוֵּג זִוּוּג זֶה כְּשֶׁבָּא הַבּקֶר, וְהַיָּמִין מִתְעוֹרֵר וּמְחַבְּקָהּ, וְאָז זִוּוּג הַכֹּל נִמְצָא כְאֶחָד. (למלך, כשבא הבקר והימין מתעורר ומחבק אותה, אז נמצא זווג הכל כאחד, ואז התשבחות מתעוררות ונמצאת התבשמות הכל. אשרי חלקו של מי שמעורר לזוג זווג זה).</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁבְּנֵי אָדָם יְשֵׁנִים וְטוֹעֲמִים טַעַם מָוֶת וְהַנְּשָׁמָה עוֹלָה לְמַעְלָה - עוֹמֶדֶת בְּמָקוֹם שֶׁעוֹמֶדֶת, וְנִבְחֶנֶת עַל מַעֲשֶׂיהָ שֶׁעָשְׂתָה כָּל הַיּוֹם, וְכוֹתְבִים אוֹתָם עַל פֶּתֶק. מַדּוּעַ? מִשּׁוּם שֶׁהַנְּשָׁמָה עוֹלָה לְמַעְלָה וּמְעִידָה עַל מַעֲשֵׂי הָאָדָם וְעַל כָּל דִּבּוּר וְדִבּוּר שֶׁיּוֹצֵא מִפִּיו.</p>\n<p>וּכְשֶׁאוֹתוֹ דִבּוּר שֶׁהוֹצִיא הָאִישׁ מִפִּיו הוּא כָּרָאוּי, דִּבּוּר קָדוֹשׁ שֶׁל תְּפִלָּה וְתוֹרָה - אוֹתוֹ דִבּוּר עוֹלֶה וּבוֹקֵעַ רְקִיעִים, וְעוֹמֵד בְּמָקוֹם שֶׁעוֹמֵד, עַד שֶׁנִּכְנָס הַלַּיְלָה, וְהַנְּשָׁמָה עוֹלָה וְאוֹחֶזֶת אוֹתוֹ הַדִּבּוּר וּמַכְנִיסָתוֹ לִפְנֵי הַמֶּלֶךְ.</p>\n<p>וּכְשֶׁאוֹתוֹ דִבּוּר אֵינוֹ כָרָאוּי, וְהוּא דִּבּוּר מִדִּבּוּרִים רָעִים, מִלָּשׁוֹן הָרָע - אוֹתוֹ הַדִּבּוּר עוֹלֶה לְמָקוֹם שֶׁעוֹלֶה, וְנִרְשָׁם אוֹתוֹ דִבּוּר וְאוֹתוֹ חֵטְא עַל הָאָדָם. זֶהוּ שֶׁכָּתוּב (מיכה ז) מִשֹּׁכֶבֶת חֵיקֶךְ שְׁמֹר פִּתְחֵי פִיךְ. וְלָכֵן אַשְׁרֵי אָדָם לֹא יַחְשֹׁב ה' לוֹ עָון, אֵימָתַי? כְּשֶׁאֵין בְּרוּחוֹ רְמִיָּה.</p>"],[9522012275,"<p>מִבֶּן שְׁלֹשִׁים שָׁנָה וָמַעְלָה וְעַד בֶּן חֲמִשִּׁים שָׁנָה כָּל הַבָּא לַעֲבֹד עֲבֹדַת עֲבֹדָה וַעֲבֹדַת מַשָּׂא בְּאֹהֶל מוֹעֵד. מִצְוָה זוֹ לִהְיוֹת הַלְוִיִּם מְשׁוֹרְרִים בַּמִּקְדָּשׁ. וְאַף עַל גַּב שֶׁבֵּאַרְנוּ לְמַעְלָה, כָּאן צָרִיךְ לְחַדֵּשׁ דְּבָרִים, שֶׁהֲרֵי הַכֹּהֵן מַקְרִיב קָרְבָּן, וְהוּא מִיכָאֵל. לֵוִי הוּא גַּבְרִיאֵל, הוּא צָרִיךְ לְנַגֵּן.</p>\n<p>וְסוֹד הַדָּבָר - (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ, זֶה חֶסֶד כֹּהֵן גָּדוֹל, שֶׁמִּיכָאֵל הוּא כֹּהֵן הֶדְיוֹט לְגַבֵּי רִבּוֹנוֹ, וְעִם כָּל זֶה שֶׁהֶדְיוֹט הוּא אֵצֶל רִבּוֹנוֹ - הוּא מֶלֶךְ חַיּוֹת הַקֹּדֶשׁ. וּבִרְכַּת הֶדְיוֹט אַל תְּהִי קַלָּה בְּעֵינֶיךְ, וְזֶהוּ יוֹמָם יְצַוֶּה ה' חַסְדּוֹ.</p>\n<p>וּבַלַּיְלָה שִׁירֹה עִמִּי - זוֹ גְבוּרָה. שִׁירֹה - (דברים לג) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. (יחזקאל א) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. וְגַבְרִיאֵל שְׁלוּחוֹ, וְצָרִיךְ לְשׁוֹרֵר וּלְנַגֵּן בְּחֶדְוָה בְּיֵין הַתּוֹרָה, (להתעסק לשלח קרבות לפני המלך בשמחה. ומי שאין לו רשות) לְהִתְעַסֵּק בַּתּוֹרָה, יְקַיֵּם (איכה ב) קוּמִי רֹנִּי בַלַּיְלָ לְרֹאשׁ אַשְׁמֻרוֹת.</p>\n<p>וְיֹאמַר בְּאַשְׁמוּרוֹת כַּמָּה סְלִיחוֹת וְתַחֲנוּנִים וּבַקָּשׁוֹת בְּכָל מִינֵי רִנָּה בִּגְרוֹנוֹ, שֶׁהוּא כִּנּוֹר לְהוֹצִיא בּוֹ קוֹל בְּשֵׁשׁ כַּנְפֵי רֵאָה עִם וְרָדִים בְּשֵׁשֶׁת צִנּוֹרוֹת הַקָּנֶה, וְזוֹ ו'. וְיוֹצִיאוֹ מֵהַלֵּב, שֶׁשָּׁם בִּינָה, כְּמוֹ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, הַלֵּב מֵבִין. יוֹצִיא בֵּן מִבִּינָה, מִבֶּן יָהּ, שֶׁהוּא ו', שֶׁהוּא אֶפְרוֹחַ בְּשֵׁשׁ כְּנָפַיִם, וְיַעֲלֶה בְּשֵׁשֶׁת צִנּוֹרוֹת הַקָּנֶה, שֶׁהֵם (מלכים אי) שֵׁשׁ מַעֲלוֹת לַכִּסֵּה.</p>\n<p>וּשְׁנֵי כִסְאוֹת הֵם, (ירמיה יז) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן, וְהֵם הַלֵּב וְהַפֶּה. לֵ\"ב, (שמות יז) וַיּאמֶר כִּי יָד עַל כֵּס יָהּ מִלְחָמָה לַה' בַּעֲמָלֵק. כָּבֵד, סָמָאֵ\"ל, פֶּה הַכִּסֵּ\"ה, כֵּס ה', זֶהוּ שֶׁכָּתוּב (תהלים פא) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר וְגוֹ'.</p>\n<p>מַהוּ שׁוֹפָר? קָנֶה, ו', קוֹל שֶׁעוֹלֶה מִן הַקָּנֶה אֶל הַפֶּה, שֶׁשָּׁם ה', בַּחֲמִשָּׁה מִינֵי תִּקּוּנֵי דִבּוּר, שֶׁהֵם: הַשְּׂפָתַיִם וְשִׁנַּיִם וְחֵךְ. שְׂפָתַיִם שְׁנַיִם. שִׁנַּיִם וְטוֹחֲנוֹת שְׁנֵי מִינִים. וְחֵךְ - הֲרֵי חֲמִשָּׁה. שֶׁטּוֹחֲנִים כְּנָהָר, שֶׁהוּא קוֹל, כְּמוֹ שֶׁטּוֹחֲנִים הָרֵחַיִם. לְהוֹצִיא קוֹל וְדִבּוּר שֶׁיּוֹצֵא מֵהַבִּינָה שֶׁל הַלֵּב בְּמַחֲשָׁבָה.</p>\n<p>שֶׁהוּא שֵׁם מְפֹרָשׁ בַּעֲשָׂרָה מִינֵי תִלִּים. וּבְשׁוֹפָר, אֵין פּוֹחֲתִין מֵעֲשָׂרָה שׁוֹפָרוֹת. וְהַתּוֹרָה - הַקּוֹל שֶׁלָּהּ, הַדִּבּוּר שֶׁלָּהּ, הַבִּינָה שֶׁלָּהּ, שֶׁפֵּרְשׁוּהָ, אֵיזֶהוּ חָכָם? הַמֵּבִין דָּבָר מִתּוֹךְ דָּבָר. מַחֲשָׁבָה שֶׁלּוֹ חֲשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל קָרְבָּנוֹת וְעוֹלוֹת. זֶהוּ שֶׁכָּתוּב (ויקרא ז) זֹּאת הַתּוֹרָה לָעֹלָה (ו) לַמִּנְחָה.</p>"],[9522012276,"<p>אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ מִכָּל חַ את הָאָדָם וְגוֹ' (במדבר ה). בֹּא רְאֵה, כָּתוּב (שופטים ד) וְחֶבֶר הַקֵּינִי נִפְרָד מִקַּיִן מִבְּנֵי חֹבָב חֹתֵן מֹשֶׁה וְגוֹ'. וְחֶבֶר הַקֵּינִי מִבְּנֵי בָנָיו שֶׁל יִתְרוֹ הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א טו) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי וְגוֹ'. לָמָּה נִקְרָא קֵינִי? וַהֲרֵי פֵּרְשׁוּהָ. וְכָתוּב (בראשית טו) אֶת הַקֵּינִי וְאֶת הַקְּנִזִּי. וְנִתְבָּאֵר שֶׁעָשָׂה קֵן בַּמִּדְבָּר כְּעוֹף זֶה, כְּדֵי לַעֲסֹק בַּתּוֹרָה, וְנִפְרַד מִן הָעִיר. נִפְרָד מִקַּיִן, נִפְרָד מֵאוֹתוֹ עַם שֶׁהָיָה שָׁם קֹדֶם וְנִדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, נִפְרָד מִקַּיִן.</p>\n<p>אַשְׁרֵי הָאִישׁ שֶׁזּוֹכֶה בַּתּוֹרָה לָלֶכֶת וּלְהִתְדַּבֵּק בִּדְרָכָיו. שֶׁכְּשֶׁאָדָם הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, מוֹשֵׁךְ עָלָיו רוּחַ קְדוֹשָׁה עֶלְיוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לב) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם. וּכְשֶׁאָדָם סוֹטֶה בִּדְרָכָיו, מוֹשֵׁךְ עָלָיו רוּחַ אַחֶרֶת מִצַּד אַחֵר, שֶׁהוּא צַד טֻמְאָה, וְצַד הַטֻּמְאָה מִתְעוֹרֵר מִצַּד נֶקֶב תְּהוֹם רַבָּה, שֶׁשָּׁם מְדוֹרֵי רוּחוֹת רָעוֹת שֶׁמַּזִּיקִים לָאֲנָשִׁים שֶׁנִּקְרָאִים מַזִּיקֵי הָעוֹלָם, שֶׁהֲרֵי מִצַּד קַיִן הָרִאשׁוֹן נִמְצְאוּ.</p>\n<p>וְיִתְרוֹ בַּהַתְחָלָה הָיָה כֹּמֶר לַעֲבוֹדָה זָרָה, וּלְאוֹתוֹ צַד עָבַד, וּמָשַׁךְ עָלָיו רוּחַ מֵאוֹתוֹ מָקוֹם, וְלָכֵן נִקְרָא קֵינִי, אַחַר שֶׁנִּפְרַד מִקַּיִן (ודאי) וְנִדְבַּק (נ\"א והתחבר) בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. (מה משמיענו, ') שֶׁכָּל מִי שֶׁנִּדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וְעוֹשֶׂה מִצְווֹת הַתּוֹרָה, כִּבְיָכוֹל הוּא מַעֲמִיד עוֹלָמוֹת, עוֹלָם הָעֶלְיוֹן וְעוֹלָם הַתַּחְתּוֹן. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב וַעֲשִׂיתֶם אֹתָם.</p>\n<p>וְכָל מִי שֶׁעוֹבֵר עַל מִצְווֹת הַתּוֹרָה, כִּבְיָכוֹל פּוֹגֵם לְמַעְלָה, פּוֹגֵם לְמַטָּה, פּוֹגֵם אֶת עַצְמוֹ, פּוֹגֵם בְּכָל הָעוֹלָמוֹת. מָשָׁל לְאוֹתָם סַפָּנִים שֶׁבַּיָּם שֶׁשָּׁטִים בָּאֳנִיָּה, קָם שׁוֹטֶה אֶחָד בֵּינֵיהֶם וְרָצָה לַעֲשׂוֹת חוֹר בַּסְּפִינָה וכו'.</p>\n<p>וְלָכֵן, אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ וְגוֹ', הָאָדָם וְגוֹ'. (בא ראה) (הושע ו) וְהֵמָּה כְּאָדָם עָבְרוּ בְרִית. אָדָם עָבַר מִצְוָה אַחַת שֶׁל הַתּוֹרָה - גָּרַם לְעַצְמוֹ מִיתָה, וְגָרַם לְכָל הָעוֹלָם, פָּגַם לְמַעְלָה, פָּגַם לְמַטָּה. וְאוֹתוֹ חֵטְא תָלוּי עַד שֶׁיַּעֲמִיד הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם כְּמִקֹּדֶם וְיַעֲבֹר אוֹתוֹ פְּגָם מֵהָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגוֹ'. וְלָכֵן כִּי יַעֲשׂוּ מִכָּל חַטֹּאת הָאָדָם. (כתוב) הָאָדָם - אָדָם הָרִאשׁוֹן.</p>\n<p>לִמְעֹל מַעַל בַּה', שֶׁמִּי שֶׁיּוֹצֵא מֵרַחֲמִים וְיוֹנֵק מִדִּין, גּוֹרֵם פְּגָם. וְלָכֵן הָרַחֲמָן יַצִּילֵנוּ מֵרִשְׁעֵי הָעוֹלָם הַזֶּה וּמִפְּגָמֵיהֶם. כַּמָּה צַדִּיקִים מִסְתַּלְּקִים בִּגְלָלָם, מִלְּבַד לְכָל מַה שֶּׁגּוֹרְמִים לְמַעְלָה וּלְמַטָּה.</p>"],[9522012277,"<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים מֵאוּשָׁא לְלוֹד. אָמַר רַבִּי יְהוּדָה (יצחק), נֹאמַר דִּבְרֵי תוֹרָה וְנֵלֵךְ. פָּתַח רַבִּי יְהוּדָה (יצחק) וְאָמַר, (שמות כא) כִּי יִפְתַּח אִישׁ בּוֹר אוֹ כִּי יִכְרֶה אִישׁ בֹּר וְגוֹ'. מַה כָּתוּב אַחֲרָיו? בַּעַל הַבּוֹר יְשַׁלֵּם וְגוֹ'. וּמָה עַל זֶה כָּךְ - מִי שֶׁגּוֹרֵם לְהַסְרִיחַ הָעוֹלָם בַּחֲטָאָיו עַל אַחַת כַּמָּה וְכַמָּה. אֶלָּא תָּמַהְנוּ, שֶׁאַף עַל גַּב שֶׁמַּסְרִיחַ הָעוֹלָם, לָמָּה יֵשׁ לוֹ תְּשׁוּבָה, כְּמוֹ שֶׁכָּתוּב אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ וְגוֹ' וְהִתְוַדּוּ אֶת חַטָּאתָם וְהֵשִׁיב?</p>\n<p>אֶלָּא וַדַּאי זֶה מוֹעִיל לָהֶם מִשּׁוּם שֶׁעָשָׂה תְשׁוּבָה, כִּבְיָכוֹל הוּא עוֹשֶׂה אוֹתוֹ מַמָּשׁ. שֶׁהֲרֵי מַה שֶּׁפָּגַם לְמַעְלָה - תִּקֵּן, וּבַמֶּה? בִּתְשׁוּבָה, שֶׁכָּתוּב אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ וְגוֹ', וְהִתְוַדּוּ אֶת חַטָּאתָם וְהֵשִׁיב, וּתְשׁוּבָה מְתַקֶּנֶת הַכֹּל, מְתַקֶּנֶת לְמַעְלָה - מְתַקֶּנֶת לְמַטָּה, מְתַקֶּנֶת עַצְמוֹ - מְתַקֶּנֶת לְכָל הָעוֹלָם.</p>\n<p>פָּתַח רַבִּי יִצְחָק (יהודה) אַחֲרָיו וְאָמַר, (דברים ד) בַּצַּר לְךְ וּמְצָאוּךְ כֹּל הַדְּבָרִים הָאֵלֶּה וְגוֹ'. בַּצַּר לְךְ - מִכָּאן שֶׁתְּשׁוּבָה מְעֻלָּה מֵהַכֹּל עַד שֶׁלֹּא יִשְׁרֶה הַדִּין בָּעוֹלָם. שֶׁאַחַר שֶׁשּׁוֹרֶה הַדִּין מִתְחַזֵּק כֹּחוֹ, מִי יַעֲבִירוֹ מֵהָעוֹלָם וִיסַלְּקוֹ? שֶׁהֲרֵי כֵּיוָן שֶׁשּׁוֹרֶה הַדִּין, לֹא מִסְתַּלֵּק עַד שֶׁנִּשְׁלָם. אַחַר שֶׁנִּשְׁלַם וְעָשָׂה תְשׁוּבָה, מְתַקֵּן כָּל הָעוֹלָמוֹת. מַשְׁמָע שֶׁכָּתוּב וּמְצָאוּךְ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים, וְכָתוּב וְשַׁבְתָּ עַד ה' אֱלֹהֶיךְ וְגוֹ'. כִּי אֵל רַחוּם ה' אֱלֹהֶיךְ וְגוֹ'.</p>\n<p>בְּאַחֲרִית הַיָּמִים, מַה יֵּשׁ כָּאן? אֶלָּא לְהַכְלִיל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא בַּגָּלוּת וְנִמְצֵאת בְּצָרָתָם, וְלֹא עוֹזֶבֶת אוֹתָם לְעוֹלָמִים. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף עַל גַּב שֶׁמַּשְׁרֶה דִין בָּעוֹלָם, רוֹצֶה שֶׁיַּחְזְרוּ יִשְׂרָאֵל בִּתְשׁוּבָה לְהֵיטִיב לָהֶם בָּעוֹלם הַזֶּה וּבָעוֹלָם הַבָּא, וְאֵין לְךְ מִי שֶׁיַּעֲמֹד בִּפְנֵי הַתְּשׁוּבָה.</p>\n<p>בֹּא רְאֵה, אֲפִלּוּ כְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת תְּשׁוּבָה. וְאִם תֹּאמַר, (תשובה) עֶלְיוֹנָה (מעלה) (ואות עליונה) מִכָּל מָקוֹם לֹא נִמְצֵאת - אֶלָּא זוֹ נִקְרֵאת תְּשׁוּבָה, כְּשֶׁחוֹזֵר רַחֲמִים לְמוּלָהּ, וְהִיא חוֹזֶרֶת עַל כָּל אוֹתָם אוּכְלוּסִים וּמֵינִיקָתָם. וּתְשׁוּבָה מְעֻלָּה - כְּשֶׁנִּמְסֶרֶת הַנֶּפֶשׁ אֵלֶיהָ וְלוֹקַחַת אוֹתָהּ בִּזְמַן שֶׁהִיא בִּתְשׁוּבָה, אָז הַכֹּל מִתְתַּקֵּן לְמַעְלָה וּלְמַטָּה, וּמִתְתַּקֵּן הוּא וְכָל הָעוֹלָם.</p>\n<p>רָשָׁע אֶחָד בָּעוֹלָם - בִּגְלָלוֹ יֵשׁ קִלְקוּל לְכַמָּה אֲחֵרִים. אוֹי לָרָשָׁע, אוֹי לִשְׁכֵנוֹ! בּא רְאֵה, יוֹנָה, מִשּׁוּם שֶׁלֹּא רָצָה לָלֶכֶת בִּשְׁלִיחוּת רִבּוֹנוֹ, כַּמָּה אֲנָשִׁים הָיוּ אוֹבְדִים בִּגְלָלוֹ בַּיָּם, עַד שֶׁכֻּלָּם חָזְרוּ עָלָיו וְדָנוּ אוֹתוֹ בְּדִין בַּיָּם, וְאָז נִצְּלוּ כֻלָּם, וְאַחַר כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא רִחֵם עָלָיו, וְהִצִּיל כַּמָּה אוּכְלוּסִים בָּעוֹלָם. מָתַי? כְּשֶׁחָזַר לְרִבּוֹנוֹ מִתּוֹךְ צָרָתוֹ. זֶהוּ שֶׁכָּתוּב (יונה ב) קָרָאתִי מִצָּרָה לִי אֶל ה' וַיַּעֲנֵנִי. וְכָתוּב (תהלים קיח) מִן הַמֵּצַר קָרָאתִי יָּהּ עָנָנִי בַמֶּרְחָב יָהּ וְגוֹ'.</p>\n<p>מִצְוָה זוֹ הִיא מִצְוַת תְּשׁוּבָה, וְזוֹהִי בִּינָה. וּבַעֲונוֹתֵינוּ, מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ, לֹא נִשְׁאָר לָנוּ אֶלָּא וִדּוּי דְּבָרִים לְבַד, וְזוֹ מַלְכוּת. וּמַה זֶּה בִּינָה? בֶּן יָ\"הּ. וּבֵן זֶה הוּא ו' בְּוַדַּאי. וְכָל מִי שֶׁחוֹזֵר בִּתְשׁוּבָה, כְּאִלּוּ הֶחֱזִיר ה' לָאוֹת ו', שֶׁהִיא בֶּן יָ\"הּ, וְנִשְׁלָם בּוֹ יְהֹוָ\"ה. וְזוֹהִי תְּשׁוּבָה - תָּשׁוּב ה' וַדַּאי לְו'.</p>\n<p>שֶׁאוֹת ה' וַדַּאי הִיא וִדּוּי דְּבָרִים, וְסוֹד הַדָּבָר - (הושע יד) קְחוּ עִמָּכֶם דְּבָרִים וְשׁוּבוּ אֶל ה' אִמְרוּ אֵלָיו וְגוֹ' וּנְשַׁלְּמָה פָרִים שְׂפָתֵינוּ. שֶׁוַּדַּאי כְּשֶׁאָדָם חוֹטֵא, גּוֹרֵם לְהַרְחִיק ה' מֵאוֹת ו'. שֶׁמִּסְתַּלֵּק בֶּן יָ\"הּ, זֶה יה\"ו, מֵאוֹת ה'. וְלָכֵן חָרַב בֵּית הַמִּקְדָּשׁ, וְהִתְרַחֲקוּ יִשְׂרָאֵל מִשָּׁם וְגָלוּ לְבֵין הָעַמִּים. וּמִשּׁוּם זֶה, כָּל מִי שֶׁעוֹשֶׂה תְשׁוּבָה, גּוֹרֵם לְהַחֲזִיר ה' לָאוֹת ו', וְהַגְּאֻלָּה תְלוּיָה בָּזֶה. וּמִשּׁוּם זֶה הַכֹּל תָּלוּי בִּתְשׁוּבָה. שֶׁכָּךְ אָמְרוּ הָרִאשׁוֹנִים, כָּל הַקִּצִּים כָּלוּ, וְאֵין הַדָּבָר תָּלוּי אֶלָּא בִּתְשׁוּבָה, שֶׁהוּא שְׁלֵמוּת שְׁמוֹ.</p>\n<p>וְעַל כָּךְ, (יחזקאל כ) וָאֶעֱשֶׂה לְמַעַן שְׁמִי. וְעוֹד, (ישעיה מח) לְמַעֲנִי לְמַעֲנִי אֶעֱשֶׂה. וְאִם לֹא חוֹזְרִים, אֲנִי אַעֲמִיד לָהֶם מֶלֶךְ שֶׁקָּשִׁים גְּזֵרוֹתָיו מִשֶּׁל פַּרְעֹה, וְיַחְזְרוּ בְּעַל כָּרְחָם. זֶהוּ שֶׁכָּתוּב (דברים ד) וְשַׁבְתָּ עַד ה' אֱלֹהֶיךְ, עַד יְהֹוָ\"ה וַדַּאי.</p>\n<p>וּתְשׁוּבָה זוֹ נִקְרֵאת חַיִּים, (משלי ד) כִּי מִמֶּנּוּ תּוֹצְאוֹת חַיִּים, שֶׁהֵם נִשְׁמוֹת יִשְׂרָאֵל. וְהוּא הֶבֶל שֶׁיּוֹצֵא וְנִכְנָס בְּפִי הָאָדָם בְּלֹא עָמָל וּבְלֹא יְגִיעָה, ה' שֶׁל הִבָּרְאָם, וְעָלָיו נֶאֱמַר (דברים ח) כִּי עַל כָּל מוֹצָא פִי ה' יִחְיֶה הָאָדָם. וְהִיא עַל רֹאשׁ הָאִישׁ, עָלֶיהָ נֶאֱמַר (במדבר יב) וּתְמוּנַת ה' יַבִּיט. (תהלים לט) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ.</p>\n<p>וּמִשּׁוּם שֶׁהִיא עַל רֹאשׁ הָאִישׁ, אָסוּר לוֹ לָאָדָם לָלֶכֶת אַרְבַּע אַמּוֹת בְּגִלּוּי רֹאשׁ, שֶׁאִם הִיא מִסְתַּלֶּקֶת מֵעַל רֹאשׁוֹ שֶׁל הָאָדָם, מִיָּד מִסְתַּלְּקִים מִמֶּנּוּ הַחַיִּים.</p>\n<p>וְאִם תֹּאמַר שֶׁכָּךְ שׁוֹרֶה עַל רֹאשׁ אֻמּוֹת הָעוֹלָם, אַף עַל גַּב שֶׁלֹּא נִבְרְאוּ בָהֶם שָׁמַיִם וָאָרֶץ וְכָל תּוֹלְדוֹתֵיהֶם - לֹא שׁוֹרֶה וַדַּאי. שֶׁמֹּשֶׁה בִּקֵּשׁ מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא תִשְׁרֶה שְׁכִינָה עַל אֻמּוֹת הָעוֹלָם, וְנָתַן לוֹ. הַהֶבֶל הָעוֹמֵד עַל אֻמּוֹת הָעוֹלָם מֵאֵיפֹה יוֹצֵא? אוֹ עַל הָרְשָׁעִים שֶׁהֵם עֵרֶב רַב, מְעֹרָבִים עִם יִשְׂרָאֵל? אֶלָּא וַדַּאי לֹא כָּל הַפָּנִים שָׁוִים. אֲפִלּוּ יִשְׂרָאֵל אֵינָם שָׁוִים, כָּל שֶׁכֵּן אֲחֵרִים.</p>\n<p>אֶלָּא וַדַּאי עַל דְּמוּת זוֹ שֶׁל אוֹת ה' פֵּרְשׁוּהָ, מַתָּנָה טוֹבָה יֵשׁ לִי בְּבֵית גְּנָזַי וְשַׁבָּת שְׁמָהּ. וּכְשֶׁהִיא שׁוֹרָה עַל יִשְׂרָאֵל, אֵין לָהֶם יְגִיעָה וְלֹא שִׁעְבּוּד, וּבָהּ נֶפֶשׁ עֲמֵלָה וִיגֵעָה (שמות לב) שָׁבַת וַיִּנָּפַשׁ.</p>\n<p>שֶׁנֶּפֶשׁ אַחֶרֶת יֵשׁ עַל רֹאשׁ הָאָדָם, שֶׁנִּקְרֵאת עֶבֶד, וְהִיא דְּמוּת עַל הָאִישׁ, וְהוּא עֶבֶד הַמֶּלֶךְ, שֶׁמְּנַעְנַעַת כָּל אֵיבְרֵי הָאָדָם לָלֶכֶת בִּדְרָכִים טוֹבוֹת וּלְקַיֵּם בָּהֶם רמ\"ח מִצְווֹת, לְהַשְׁרוֹת עֲלֵיהֶם ה' שֶׁל בְּהִבָּרְאָם, שֶׁכָּךְ עוֹלֶה הִבָּרְאָם לְרמ\"ח.</p>\n<p>וּדְיוֹקָן אַחֵר עַל רֹאשׁוֹ, שֶׁנִּקְרָא יִרְאָה, וְזֶה י'. וַעֲלֵיהֶם נֶאֱמַר, וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים. שְׁתֵּי דְמֻיּוֹת טוֹבוֹת, שֶׁהֵם זָכָר וּנְקֵבָה. זָכָר מִצַּד הָאוֹת י', נְקֵבָה מִצַּד הָאוֹת ה'.</p>\n<p>וּשְׁתֵּי אוֹתִיּוֹת מְעוֹרְרוֹת אֶת הָאָדָם לַתּוֹרָה וְלַמִּצְוָה. י' יִרְאָה, וְזוֹהִי עַל רֹאשׁ הָאָדָם, וּמִמֶּנָּה תִּכָּנֵס יִרְאָה לְלֵב הָאָדָם לִירָא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וְלִשְׁמֹר אֶת עַצְמוֹ שֶׁלֹּא יַעֲבֹר עַל מִצְווֹת לֹא תַעֲשֶׂה. ה' אַהֲבָה עַל רֹאשׁוֹ שֶׁל הָאָדָם, וּמִמֶּנָּה נִכְנֶסֶת אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא עַל רמ\"ח אֵיבָרָיו לְקַיֵּם בָּהֶם מִצְווֹת עֲשֵׂה. ו' הִיא עַל רֹאשׁ הָאָדָם, וּמִמֶּנָּה יִכָּנֵס עַל פֶּה הָאָדָם דִּבּוּרִים לִלְמֹד בַּתּוֹרָה.</p>\n<p>וּבָזְהִ קְחוּ עִמָּכֶם דְּבָרִים וְשׁוּבוּ אֶל ה'. וּבְזֶה שֶׁתִּהְיֶה בָּכֶם הַיִּרְאָה וְהָאַהֲבָה וְהַתּוֹרָה, יַחֲזֹּר יְהֹוָ\"ה שֶׁהוּא בִּינָה, תְּשׁוּבָה, ו' תָּשׁוּב לְה', שֶׁהִיא מַעֲשֵׂה בְרֵאשִׁית, וְהִיא ל\"ב אֱלֹהִים. וְיִשְׁתַּלֵּם יְהֹוָה, וּבָהּ תִּהְיֶה לָכֶם מְנוּחָה וְנַחַת מֵהַכֹּל, וּבָהּ שָׁבַת וַיִּנָּפַשׁ.</p>\n<p>וּבָהּ יִכָּלֵל יה\"ו, וּמִשּׁוּם זֶה וַיְכֻלּוּ - שְׁלֵמוּת הַכֹּל. בָּהּ נִבְרָא כָּל הָעוֹלָם, וְעָלֶיהָ עוֹמְדִים שָׁמַיִם וָאָרֶץ וְהַיָּם וְכָל הַבְּרִיּוֹת שֶׁנִּבְרְאוּ, שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. וְאִם הִיא תִּתְרַחֵק מֵהָעוֹלָם אֲפִלּוּ רֶגַע, הַכֹּל יֶחֱרַב וְיִתְבַּטֵּל, וְלֹא תִהְיֶה עֲמִידָה לָעוֹלָם.</p>\n<p>ה' זֹּאת לֹא תֵלֵךְ מֵהַגּוּף, וּבוֹ הוּא עוֹמֵד. וּכְשֶׁהִיא תֵּלֵךְ מִמֶּנּוּ, הוּא סַם הַמָּוֶת יָבֹא וְיִשְׁרֶה עָלָיו, שֶׁתִּקָּרֵא טֻמְאָה, נְבֵלָה, פְּסוּלָה, מַלְאַךְ הַמָּוֶת, חֹשֶׁךְ, אֲפֵלָה, וְשׁוֹרָה עַל גּוּף הָאִישׁ. וּבְאוֹתוֹ זְמַן נִקְרָא הָאָדָם מֵת, וְסוֹד הַדָּבָר - (יחזקאל יח) כִּי לֹא אֶחְפֹּץ בְּמוֹת הַמֵּת נְאֻם ה' אֱלהִים וְהָשִׁיבוּ וִחְיוּ.</p>\n<p>כָּל מִצְווֹת עֲשֵׂה שֶׁהָיוּ עֲתִידוֹת לִשְׁרוֹת בְּרמ\"ח אֵיבָרָיו, כֻּלָּן מִתְאַבְּלוֹת עָלָיו, וְסוֹד הַדָּבָר - (ישעיה נז) דְּרָכָיו רָאִיתִי וְאֶרְפָּאֵהוּ וְגוֹ', וְלַאֲבֵלָיו. מַה זֶּה וְלַאֲבֵלָיו? אֵלּוּ רמ\"ח אֵיבָרִים שֶׁמִּתְאַבְּלִים עָלָיו, שֶׁהֵם דְּמוּת עֶלְיוֹנָה שֶׁשּׁוֹרָה עַל רֹאשׁוֹ, שֶׁבָּהּ שׁוֹרֶה הֲוָיָ\"ה. שֶׁכְּמוֹ שֶׁיֵּשׁ דְּמוּת טוֹבָה עַל צַדִּיק וּמַנְהִיגָה אוֹתוֹ לְכָל מַעֲשִׂים טוֹבִים לְזַכּוֹתוֹ לָעוֹלָם הַבָּא, כָּךְ יֵשׁ דְּמוּת רָעָה עַל רֹאשׁ הָרְשָׁעִים לְהַנְהִיגָם בְּמַעֲשִׂים רָעִים, שֶׁיָּרְשׁוּ גֵיהִנֹּם. וּמִשּׁוּם זֶה יֵשׁ הֶבֶל וְיֵשׁ הֶבֶל. יֵשׁ הֶבֶל טוֹב, שֶׁנֶּאֱמַר בּוֹ כִּי עַל כָּל מוֹצָא פִי ה' יִחְיֶה הָאָדָם. וְיֵשׁ הֶבֶל רָע, שֶׁנֶּאֱמַר בּוֹ גַּם זֶה הֶבֶל וּרְעוּת רוּחַ.</p>\n<p>וּבֹא וּרְאֵה, בְּמַעֲשֵׂי הָאָדָם נוֹדָע הַפַּרְצוּף שֶׁעָלָיו וּפַרְצוּף פָּנָיו. זֶהוּ שֶׁכָּתוּב (שם ג) הַכָּרַת פְּנֵיהֶם עָנְתָה בָּם. בַּדְּמוּת נוֹדָע פַּרְצוּף הַחַיָּה שֶׁשּׁוֹרָה עָלָיו, אִם הוּא אַרְיֵה, אוֹ שׁוֹר, אוֹ נֶשֶׁר, אוֹ אָדָם. מִמֶּרְכֶּבֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, אוֹ מִמֶּרְכֶּבֶת מַלְאָךְ שַׂר הַפְּנִים, אוֹ מִמֶּרְכָּבָה רָעָה שֶׁל סָמָאֵ\"ל, אוֹ מִמֶּרְכֶּבֶת אַרְבָּעָה יְסוֹדוֹת שֶׁל הָעוֹלָם. וְאֵין בָּהֶם לֹא הַיֵּצֶר הַטּוֹב, וְלֹא הַיֵּצֶר הָרָע, אֶלָּא כְּבַהֲמוֹת הָעוֹלָם. וּמִשּׁוּם זֶה כַּמָּה הֲבָלִים יֵשׁ בִּבְנֵי אָדָם, כָּל אֶחָד לְמִינוֹ. וְסוֹד הַדָּבָר - (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. וּמִשּׁוּם זֶה, בְּמִדָּה שֶׁאָדָם מוֹדֵד - בָּהּ מוֹדְדִים לוֹ. וּלְכָל פַּרְצוּף יֵשׁ מְמֻנֶּה עָלָיו.</p>\n<p>בֹּא רְאֵה, לְשֵׁשֶׁת יְמֵי בְרֵאשִׁית, לְכָל אֶחָד יֵשׁ אֶת פַּרְצוּפוֹ שֶׁל אוֹתָהּ דַּרְגָּה שֶׁמַּנְהִיגָה אוֹתוֹ, וְלֹא תִמְצָא יוֹם שֶׁאֵין בּוֹ טוֹב. וְאַף עַל גַּב שֶׁבַּיּוֹם הַשֵּׁנִי אֵין בּוֹ טוֹב, תִּמְצָאֶנּוּ בַּיּוֹם הַשְּׁלִישִׁי. וּמִשּׁוּם זֶה נֶאֱמַר בּוֹ פַּעֲמַיִם כִּי טוֹב.</p>\n<p>וּלְכָל יוֹם יֵשׁ גָּדֵר מִבַּחוּץ שֶׁלֹּא יִכָּנֵס כָּל אָדָם לְאוֹתוֹ טוֹב, כְּמוֹ חֹשֶׁךְ שֶׁמְּכַסֶּה אֶת הָאוֹר. שֶׁתִּמְצָא בְּיוֹם רִאשׁוֹן אוֹר, וְתִמְצָא בּוֹ חֹשֶׁךְ. בְּכָל יוֹם תִּמְצָא שְׁמִירָה, וְאוֹתָם שׁוֹמְרִים הֵם כְּמוֹ קוֹצִים לַכֶּרֶם. וְיֵשׁ שׁוֹמְרִים אֲחֵרִים, כְּמוֹ נְחָשִׁים וְעַקְרַבִּים וּשְׂרָפִים, וְשׁוֹמְרִים אוֹתוֹ טוֹב שֶׁלֹּא יִכָּנֵס לְשָׁם מִי שֶׁאֵינוֹ רָאוּי לְהִכָּנֵס. וְאִם לא - כָּל הָרְשָׁעִים הָיוּ נִכְנָסִים! בְּסוֹדוֹת הַתּוֹרָה.</p>\n<p>וּמִשּׁוּם זֶה, מִי שֶׁהוּא רָשָׁע וְיִכָּנֵס לָדַעַת סוֹדוֹת הַתּוֹרָה, כַּמָּה מַלְאֲכֵי חַבָּלָה שֶׁנִּקְרָאִים חֹשֶׁךְ וַאֲפֵלָה, נְחָשִׁים וְעַקְרַבִּים, חַיּוֹת בָּר נִקְרָאִים, וּמְבַלְבְּלִים מַחֲשַׁבְתּוֹ שֶׁלֹּא יִכָּנֵס לְמָקוֹם שֶׁאֵינוֹ שֶׁלּוֹ.</p>\n<p>אֲבָל מִי שֶׁהוּא טוֹב, כָּל הַשּׁוֹמְרִים הֵם לְמָרוּתוֹ, וְקָטֵגוֹר נַעֲשֶׂה סָנֵגוֹר, וְיַכְנִיסוּ (אותו) לַטּוֹב הַגָּנוּז, וְיֹאמְרוּ לוֹ: מוֹרֵנוּ, אִישׁ זֶה הוּא טוֹב וְצַדִּיק, יְרֵא שָׁמַיִם, רוֹצֶה לְהִכָּנֵס לְפָנֶיךְ, אָמַר לָנוּ (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. אוֹתוֹ טוֹב הַגָּנוּז יֹאמַר לָהֶם: פִּתְחוּ לוֹ בְּשַׁעַר זֶה שֶׁנִּקְרָא אַהֲבָה, אוֹ בְּשַׁעַר זֶה שֶׁנִּקְרָא תְּשׁוּבָה. כָּל צַדִּיק יִכָּנֵס כְּפִי דַרְגָּתוֹ, וְסוֹד הַדָּבָר - (ישעיה כו) פִּתְחוּ שְׁעָרִים וְיָבֹא גוֹי צַדִּיק וְגוֹ'.</p>\n<p>כָּעֵת צָרִיךְ לַחֲזֹּר עַל פֶּתַח הַתְּשׁוּבָה. וְכִי מִכַּמָּה מִינִים הִיא הַתְּשׁוּבָה שֶׁעוֹשִׂים בְּנֵי אָדָם? כֻּלָּם טוֹבִים, אֲבָל לֹא כָּל הַפָּנִים שָׁוִים. יֵשׁ אָדָם שֶׁהוּא רָשָׁע גָּמוּר כָּל יָמָיו, וְהוּא עוֹבֵר עַל כַּמָּה מִצְווֹת לֹא תַעֲשֶׂה, וּמִתְחָרֵט וּמוֹדֶה עֲלֵיהֶם, וְאַחַר כָּךְ לֹא עוֹשֶׂה לֹא טוֹב וְלֹא רַע - לָזֶה בְּוַדַּאי יִמְחֹל הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲבָל לֹא יִזְכֶּה לִתְשׁוּבָה עֶלְיוֹנָה. יֵשׁ אָדָם שֶׁלְּאַחַר שֶׁיָּשׁוּב מֵחֲטָאָיו וּמִתְכַּפֵּר לוֹ, הוּא הוֹלֵךְ בְּדֶרֶךְ מִצְוָה וּמִתְעַסֵּק בְּכָל כֹּחוֹ בְּיִרְאָה וְאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא - זֶה זוֹכֶה לִתְשׁוּבָה תַחְתּוֹנָה שֶׁנִּקְרֵאת ה', וְזוֹ הִיא תְּשׁוּבָה תַחְתּוֹנָה.</p>\n<p>וְיִשִׁ אָדָם שֶׁלְּאַחַר שֶׁהִתְחָרֵט עַל חֲטָאָיו וְעָשָׂה תְשׁוּבָה, וְיִתְעַסֵּק בַּתּוֹרָה בְּיִרְאָה וְאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא עַל מְנָת לְקַבֵּל פְּרָס - זֶה זוֹכֶה לָאוֹת ו', וְהוּא בֶּן יָ\"הּ, וְעַל שְׁמוֹ נִקְרֵאת בִּינָה, וְזֶה גּוֹרֵם שֶׁתָּשׁוּב ו' לְה'. וּמִלַּת תְּשׁוּבָה כָּךְ הִיא, תָּשׁוּב ו' לְה'.</p>\n<p>וּלְעוֹלָם לֹא שׁוֹרָה ה' בְּאִישׁ, וְלֹא ו', לְלֹא יִרְאָה וּלְלֹא אַהֲבָה, שֶׁהֵם יָ\"הּ, יִרְאָה וְאַהֲבָה נִקְרָאִים בְּוַדַּאי. וּמִשָּׁם נִתְּנוּ הַתּוֹרָה וְהַמִּצְוָה, שֶׁהֵם בֵּן וּבַת. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל מְקַיְּמִים הַתּוֹרָה וְהַמִּצְוָה, נִקְרְאוּ בָּנִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב (דברים יב) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם.</p>\n<p>הַנִּסְתָּרֹת (דברים כט) - יִרְאָה וְאַהֲבָה, שֶׁהֵם בַּמֹּחַ וּבַלֵּב, בַּחֲלַל הַגּוּף וּבָרֹאשׁ. וְהַנִּגְלֹת - הַתּוֹרָה וְהַמִּצְוָה, שֶׁהֵם בַּגּוּף וּבָרֹאשׁ מִבַּחוּץ. וְסוֹד הַדָּבָר כָּךְ הוּא וַדַּאי, שֶׁאִם הָאָדָם פּוֹחֵד מֵהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹ אוֹהֵב אוֹתוֹ - אֶת זֶה לֹא יוֹדֵעַ אָדָם אַחֵר, מִשּׁוּם שֶׁזֶּהוּ דָּבָר שֶׁלֹּא הִתְגַּלָּה אֶלָּא בֵּינוֹ לְבֵין קוֹנוֹ.</p>\n<p>אֲבָל אָדָם שֶׁמִּתְעַסֵּק בַּתּוֹרָה וּמִתְעַסֵּק בְּמִצְות עֲשֵׂה - זֶה גָּלוּי לְכָל אָדָם, כִּי הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה לוֹ פֶּה בְּגִלּוּי לְהִתְעַסֵּק בַּתּוֹרָה, וְעֵינַיִם לְהִסְתַּכֵּל בָּהּ, וְאָזְנַיִם לִשְׁמֹעַ אוֹתָהּ, וְעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא יָדַיִם וְרַגְלַיִם וְגוּף לַעֲשׂוֹת בָּהּ מִצְווֹת עֲשֵׂה.</p>\n<p>אִם כָּךְ, חֹטֶם לָמָּה צָרִיךְ? (בראשית ב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, זוֹהִי דְּמוּת שֶׁעַל הָאָדָם, שֶׁנֶּאֱמַר בָּהּ (שם כח) וַיַּחֲלֹם וְהִנֵּה סֻלָּם. סֻלָּם וַדַּאי הִיא נִשְׁמַת חַיִּים, כִּסֵּא לְשֵׁם יְהֹוָ\"ה, שֶׁהוּא הַיִּרְאָה וְהָאַהֲבָה, הַתּוֹרָה וְהַמִּצְוָה, וּבוֹ שׁוֹרֶה. וְכִסֵּא זֶה, מִמֶּנּוּ גְּזוּרוֹת כָּל נִשְׁמוֹת יִשְׂרָאֵל, וְהִיא דְּמוּת עַל רֹאשׁ הָאָדָם.</p>\n<p>וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ - אֵלּוּ הֲבָלִים שֶׁעוֹלִים וְיוֹצְאִים בַּגּוּף בְּסֻלָּם זֶה. הוּא אֶחָד, שְׁבִיעִי שֶׁל הַכֹּל. וְהוּא מֻצָּב אַרְצָה - שְׁנַיִם. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה - שְׁלֹשָׁה. וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים - שְׁנַיִם. וְיֹרְדִים - שְׁנַיִם. אֵלֶּה כְּנֶגֶד אַרְבַּע רוּחוֹת וְהַשָּׁמַיִם וְהָאָרֶץ. וְסוֹד הַדָּבָר - (קהלתא) הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת הֲבֵל הֲבָלִים הַכֹּל הָבֶל. הֵם שִׁבְעָה כְּנֶגֶד הַכִּסֵּא, שֶׁהוּא הַסֻּלָּם, וְהַשָּׁמַיִם וְהָאָרֶץ, וְאַרְבָּעָה יְסוֹדוֹת הָעוֹלָם, וְהֵם שִׁבְעָה כְּנֶגֶד שִׁבְעַת יְמֵי בְרֵאשִׁית. יֵשׁ כָּל בְּרִיּוֹת הַשָּׁמַיִם וְהַיָּם וְהָאָרֶץ, כְּמוֹ חַיּוֹת, עוֹפוֹת, בְּהֵמוֹת וְדָגִים, וְכַמָּה תוֹלָדוֹת שֶׁתְּלוּיוֹת מִמֶּנּוּ.</p>\n<p>וּמִשּׁוּם שֶׁהַכֹּל נִבְרָא בַּצֶּלֶם הַזֶּה שֶׁעַל כָּל יִשְׂרָאֵל, שֶׁהוּא צַדִּיק, נֶאֱמַר בָּהֶם (בראשית ט) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמָיִם וְגוֹ'. וְזֶה מְדַבֵּר עַל בְּנֵי אָדָם שֶׁמְּשׁוּלִים לְחַיּוֹת הַשָּׂדֶה, לִבְהֵמוֹת וּלְעוֹפוֹת וְלִדְגֵי הַיָּם. שֶׁיֵּשׁ אָדָם שֶׁמַּזָּלוֹ שׁוֹר, וּמַזָּלוֹ אַרְיֵה, וּמַזָּלוֹ נֶשֶׁר, וּמַזָּלוֹ אָדָם.</p>\n<p>וְכָל אֵלֶּה לָמָּה מִתְפַּחֲדִים מִדְּמוּת זוֹ שֶׁהֵם נִבְרְאוּ מִשָּׁם? אֶלָּא מִשּׁוּם שֶׁשֵּׁם ה' שׁוֹרֶה עָלָיו. סוֹד הַדָּבָר - (דברים כח) וְרָאוּ כָּל עַמֵּי הָאָרֶץ וְגוֹ'. וְכָל מִי שֶׁפּוֹגֵם מַעֲשָׂיו, נִפְגֶּמֶת דְּמוּתוֹ, וְשֵׁם ה' לֹא שׁוֹרֶה בְּמָקוֹם פָּגוּם. וּבְאוֹתוֹ פְגָם שׁוֹרֶה חֹשֶׁךְ, בִּגְלַל פְּגִימַת הַלְּבָנָה שֶׁהַחֹשֶׁךְ שׁוֹרֶה בָּהּ. וְאָדָם זֶה, כְּמוֹ שֶׁהוּא פָּגַם דְּמוּתוֹ - כָּךְ נִפְגָּם הוּא לְמַטָּה, אוֹ שֶׁנַּעֲשֶׂה אִלֵּם, אוֹ חֵרֵשׁ, אוֹ סוּמָא, אוֹ חִגֵּר, בִּשְׁבִיל שֶׁיִּהְיֶה רָשׁוּם לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְאוֹתוֹ חֹשֶׁךְ שׁוֹרֶה בַּפְּגָם שֶׁלּוֹ, וּמִיָּד יוֹדְעִים בּוֹ דְּרָגוֹת הַקְּדוֹשׁוֹת, שֶׁהֵם כֹּחוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְרַחֲקִים מִמֶּנּוּ, שֶׁכְּבָר יוֹדְעִים שֶׁבְּאוֹתוֹ פְּגָם לֹא שׁוֹרֶה הַמֶּלֶךְ. וּמִשּׁוּם זֶה חַיּוֹת הַמֶּלֶךְ מִתְרַחֲקוֹת מִמֶּנּוּ, שֶׁחֵילוֹת הַמֶּלֶךְ לֹא שׁוֹרִים וְלֹא מִתְקָרְבִים, אֶלָּא בְּמָקוֹם שֶׁהַמֶּלֶךְ שׁוֹרֶה. שֶׁכָּךְ הֵם מִתְנַהֲגִים אַחֲרָיו, כְּאֵיבָרִים אַחַר הַגּוּף.</p>\n<p>וּבְאוֹתוֹ מָקוֹם שֶׁשּׁוֹרֶה אוֹתוֹ חֹשֶׁךְ, כַּמָּה מַלְאֲכֵי חַבָּלָה, שֶׁנִּקְרָאִים נְחָשִׁים וְעַקְרַבִּים, מִתְקָרְבִים אֵלָיו, וְנוֹתְנִים לוֹ כַּמָּה נְשִׁיכוֹת, וְאֵלֶּה אוֹתָם יִסּוּרִים. וְאִם יֵשׁ לוֹ מָמוֹן שֶׁל מַעֲשִׂים טוֹבִים שֶׁעָשָׂה - יִתְמַעֲטוּ מִמֶּנּוּ. וְאֵיךְ יִתְמַעֲטוּ מִמֶּנּוּ? אֶלָּא כָּל זְכוּת שֶׁיּוֹרֶדֶת לוֹ מִלְמַעְלָה, נוֹתְנִים אוֹתָהּ לְאוֹתָם מַלְאֲכֵי חַבָּלָה, וּמְבַטְּלִים מִמֶּנּוּ יִסּוּרִים. וְאִם אֵין לוֹ זְכוּת וְלֹא חוֹבָה לְמַעְלָה, אֶלָּא הַכֹּל לְמַטָּה - בְּכָל זְכוּת שֶׁעוֹשֶׂה, יוֹרֵד לוֹ מָמוֹנוֹת, וְאֻמּוֹת הָעוֹלָם מִתְקָרְבִים אֵלָיו כְּנֶגֶד מַלְאֲכֵי הַחַבָּלָה, וְנוֹתֵן לָהֶם מָמוֹן וְנִצָּל מֵהֶם.</p>\n<p>וּמִשּׁוּם זֶה הָיוּ יִשְׂרָאֵל מַקְרִיבִים לַעֲזָאזֵל אֵצֶל אוֹתוֹ הַחֹשֶׁךְ. וְשִׁבְעִים פָּרִים כְּנֶגֶד שִׁבְעִים אֻמּוֹת, לְקַיֵּם הַפָּסוּק (משלי כה) אִם רָעֵב שּנַאֲךְ הַאֲכִילֵהוּ לָחֶם וְאִם צָמֵא הַשְׁקֵהוּ מָיִם. וּמִיָּד שֶׁחוֹזְרִים בִּתְשׁוּבָה, עוֹבֵר אוֹתוֹ חֹשֶׁךְ מֵאוֹתוֹ פְגָם וְנִשְׁלָם. וְסוֹד הַדָּבָר - (שמואל ב יב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. וּמִיָּד חוֹזֵר בּוֹ שֵׁם ה' וּמִתְרַצֶּה (ומתרפא) בּוֹ מֵאוֹתָן נְשִׁיכוֹת שֶׁל הַיִּסּוּרִים, זֶהוּ שֶׁכָּתוּב (ישעיה ו) וְשָׁב וְרָפָא לוֹ. וּמִנַּיִן שֶׁחוֹזֵר הַקָּדוֹשׁ בָּרוּךְ הוּא מִיָּד כְּשֶׁחָזַר בִּתְשׁוּבָה וְנִשְׁלָם אוֹתוֹ הַפְּגָם? זֶהוּ שֶׁכָּתוּב (מלאכי ג) שׁוּבוּ אֵלַי וְאָשׁוּבָה אֲלֵיכֶם.</p>\n<p>וְזוֹהִי תְּשׁוּבָה גְמוּרָה שֶׁגּוֹרֶמֶת לְהַחֲזִיר בִּינָה, שֶׁהִיא יה\"ו, לְגַבֵּי ה' שֶׁהִיא מַלְכוּת. שֶׁהוֹלֶכֶת וְנוֹדֶדֶת מִקִּנָּהּ, שֶׁהִיא אוֹתָהּ דְּמוּת שֶׁנִּקְשָׁרוֹת בָּהּ כָּל הַמִּצְווֹת, וּבָהּ נִקְשָׁרוֹת עֶשֶׂר סְפִירוֹת. כְּשֶׁאָדָם עוֹשֶׂה מִצְוָה אַחַת וְלֹא יוֹתֵר, וְעוֹשֶׂה אוֹתָהּ בְּיִרְאָה וְאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, בִּגְלָלָהּ שׁוֹרוֹת עָלָיו עֶשֶׂר סְפִירוֹת. וְכָל מִי שֶׁקִּיֵּם מִצְוָה אַחַת כָּרָאוּי, כְּאִלּוּ מְקַיֵּם רמ\"ח מִצְווֹת עֲשֵׂה, שֶׁאֵין מִצְוָה שֶׁאֵינָהּ כְּלוּלָה מִכָּל הָרמ\"ח.</p>"],[9522012278,"<p>אִישׁ אִישׁ כִּי תִשְׂטֶה אִשְׁתּוֹ וְגוֹ'. מַה זֶּה לְגַבֵּי זֶה. אֶלָּא כְּמוֹ שֶׁכָּתוּב, לִמְעֹל מַעַל בַּה'. רַבִּי אֶלְעָזָר אָמַר, אִישׁ אִישׁ, מַה זֶּה אִישׁ אִישׁ, שֶׁהֲרֵי בְּאֶחָד מַסְפִּיק? אֶלָּא הֲרֵי פֵּרְשׁוּהָ, אֲבָל אִישׁ אִישׁ, מַשְׁמָע אִישׁ שֶׁהוּא אִישׁ, וְקִיֵּם פָּסוּק שֶׁכָּתוּב (משלי ה) שְׁתֵה מַיִם מִבּוֹרֶךְ וְגוֹ', אָז הוּא אִישׁ בָּעוֹלָם, אִישׁ לְגַבֵּי אִשְׁתּוֹ. וּמָעֲלָה בוֹ מָעַל, הֲרֵי בְּאֶחָד מַסְפִּיק, לָמָּה שְׁנַיִם? אֶלָּא אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה, אֶחָד לִכְנֶסֶת יִשְׂרָאֵל לְאֶחָד לְבַעְלָהּ. בִּגְלַל זֶה, וְהֵבִיא הָאִישׁ אֶת אִשְׁתּוֹ.</p>\n<p>לָמָּה אֶל הַכֹּהֵן? סוֹד הַדָּבָר - מִשּׁוּם שֶׁהַכֹּהֵן הוּא שׁוֹשְׁבִין הַמַּלְכָּה. כָּאן יֵשׁ לְהִסְתַּכֵּל, הֲרֵי כָּתוּב (ויקראא) וְשָׁחַט אֶת בֶּן הַבָּקָר, וְשָׁחַט אַחֵר וְלֹא הַכֹּהֵן, שֶׁהַכֹּהֵן אָסוּר לוֹ בְּדִין בִּשְׁבִיל שֶׁלֹּא יִפְגֹּם אוֹתוֹ מָקוֹם שֶׁהוּא אָחוּז בּוֹ, וְאַתָּה אָמַרְתָּ וְהֵבִיא הָאִישׁ אֶת אִשְׁתּוֹ אֶל הַכֹּהֵן, לָדוּן דִּינָהּ? אֶלָּא וַדַּאי כֹּהֵן לָזֶה רָאוּי, מִשּׁוּם שֶׁהוּא שׁוֹשְׁבִין הַמַּלְכָּה, וְכָל נְשׁוֹת הָעוֹלָם מִתְבָּרְכוֹת (נאחזת) בִּכְנֶסֶת יִשְׂרָאֵל, וְעַל זֶה הָאִשָּׁה שֶׁלְּמַטָּה מִתְבָּרֶכֶת בְּשֶׁבַע בְּרָכוֹת, שֶׁאֲחוּזָה בָּהּ בִּכְנֶסֶת יִשְׂרָאֵל, וְהַכֹּהֵן עוֹמֵד לְתַקֵּן דִּבְרֵי הַמַּלְכָּה וּלְעַיֵּן בְּכָל מַה שֶּׁצָּרִיךְ, וּמִשּׁוּם זֶה הַכֹּהֵן לָזֶה, וְלֹא אַחֵר.</p>\n<p>וְאִם תֹּאמַר שֶׁהוּא עוֹשֶׂה דִּין - לֹא כָּךְ, אֶלָּא כְּדֵי לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם הוּא מִשְׁתַּדֵּל בָּזֶה, וּלְהַגְדִּיל חֶסֶד. שֶׁאִם אוֹתָהּ אִשָּׁה תִּמָּצֵא צַדֶּקֶת וְזַכָּאִית, הַכֹּהֵן מַגְדִּיל שְׁלוֹמָם, וְלֹא עוֹד, אֶלָּא שֶׁמִּתְעַבֶּרֶת בְּבֵן זָכָר, וְנַעֲשֶׂה שָׁלוֹם עַל יָדוֹ. וְאִם לֹא תִמָּצֵא צַדֶּקֶת, הוּא לֹא עוֹשֶׂה דִּין, אֶלָּא אוֹתוֹ שֵׁם קָדוֹשׁ שֶׁהִיא מְשַׁקֶּרֶת בּוֹ, הוּא עוֹשֶׂה אֶת הַדִּין וְהוּא בּוֹדֵק אוֹתָהּ.</p>\n<p>בֹּא רְאֵה, הַכֹּהֵן לֹא מַכְנִיס אֶת עַצְמוֹ לָזֶה, רַק כְּשֶׁהִיא נוֹתֶנֶת אֶת עַצְמָהּ לְפָנָיו לְכַסּוֹת (להזדכות), פַּעַם וּפַעֲמַיִם שׁוֹאֵל אוֹתָהּ. כֵּיוָן שֶׁהִיא רוֹצָה לְהִמָּצֵא זַכָּאִית, אָז הַכֹּהֵן עוֹשֶׂה מַעֲשֶׂה כְּדֵי לְהַרְבּוֹת שָׁלוֹם.</p>\n<p>הַכֹּהֵן כּוֹתֵב אֶת הַשֵּׁם הַקָּדוֹשׁ פַּעַם בְּדֶרֶךְ יָשָׁר, אַחַר כָּךְ כּוֹתְבוֹ לְמַפְרֵעַ אוֹתִיּוֹת (רשומות) מְהֻפָּכוֹת בְּאוֹרוֹתֵיהֶן, דִּין בְּדִין, רַחֲמִים בְּרַחֲמִים, רַחֲמִים בְּדִין, וְדִין בְּרַחֲמִים. נִמְצְאָה זַכָּאִית - אוֹתִיּוֹת הָרַחֲמִים נִמְצָאִים, וְהַדִּינִים מִסְתַּלְּקִים. לֹא נִמְצֵאת כָּרָאוּי - הָרַחֲמִים מִסְתַּלְּקִים, וְנִשְׁאָרִים הַדִּינִים, וְאָז נַעֲשֶׂה הַדִּין.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (שמות טו) וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם, הֲרֵי פֵּרְשׁוּהָ. אָמַר, תּוֹהֶה אֲנִי אֵיךְ בְּנֵי אָדָם לֹא מִסְתַּכְּלִים וְלֹא מִשְׁתַּדְּלִים בְּדִבְרֵי תוֹרָה. כָּאן יֵשׁ לְהִסְתַּכֵּל, לָמָּה כָּתוּב כָּאן, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ?</p>\n<p>אֲבָל וַדַּאי סוֹד הַדָּבָר, שֶׁכָּאן עַל מַיִם זֶה הָיָה, מִשּׁוּם שֶׁהַמִּצְרִים הָיוּ אוֹמְרִים, שֶׁבָּנִים שֶׁל יִשְׂרָאֵל הָיוּ מֵהֶם, וְהָיוּ כַּמָּה בְּיִשְׂרָאֵל שֶׁחָשְׁדוּ בָזֶה בִּנְשׁוֹתֵיהֶם, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֱבִיאָם לְמָקוֹם זֶה וְרָצָה לְבָדְקָם. מַה כָּתוּב? וַיָּבאוּ מָרָתָה וְגוֹ'. וַיִּצְעַק אֶל ה' וְגוֹ'.</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, מֹשֶׁה, מָה אַתָּה רוֹצֶה? הֲרֵי כַּמָּה חֲבִילוֹת עוֹמְדוֹת עֲלֵיכֶם כָּאן, וַאֲנִי רוֹצֶה לִבְדּק כָּאן אֶת נְשׁוֹת יִשְׂרָאֵל. כְּתֹב שֵׁם קָדוֹשׁ וּזְרֹק אוֹתוֹ לַמַּיִם, וְיִבָּדְקוּ כֻלָּם, נָשִׁים וּגְבָרִים, וְלֹא יִשָּׁאֵר לַעַז עַל בָּנַי. וְעַד שֶׁיִּבָּדְקוּ כֻלָּם כָּאן, לֹא אַשְׁרֶה אֶת שְׁמִי עֲלֵיהֶם. מִיָּד - וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶת הַמַּיִם, זֶה הַשֵּׁם הַקָּדוֹשׁ, אוֹתוֹ שֶׁהַכֹּהֵן הָיָה כּוֹתֵב לִבְדֹּק אֶת נְשׁוֹת יִשְׂרָאֵל, וְאָז - שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ.</p>\n<p>וְאִם תֹּאמַר, נְשׁוֹת יִשְׂרָאֵל רָאוּי, הֵם לָמָּה? אֶלָּא גַּם הֵם צְרִיכִים, שֶׁלֹּא נִטְמְאוּ בִּנְשׁוֹת מִצְרַיִם. וּנְשׁוֹת יִשְׂרָאֵל לֹא נִטְמְאוּ בַמִּצְרִים כָּל אוֹתָן שָׁנִים שֶׁהָיוּ בֵינֵיהֶם, וְכֻלָּם יָצְאוּ, גְּבָרִים וְנָשִׁים, זַכָּאִים, וְנִמְצְאוּ זֶרַע יִשְׂרָאֵל קְדוֹשִׁים וְזַכָּאִים. אָז הַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁרָה שְׁמוֹ בֵּינֵיהֶם, וְעַל זֶה עַל מַיִם וַדַּאי, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. גַּם כָּאן בְּמַים בּוֹדֵק הַכֹּהֵן אֶת הָאִשָּׁה, וּבַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>וּמִן הֶעָפָר אֲשֶׁר יִהְיֶה בְּקַרְקַע הַמִּשְׁכָּן. אֵיזֶה עָפָר? הֲרֵי לָמַדְנוּ, כָּתוּב (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. הַכֹּל הָיָה מִן הֶעָפָר - אֲפִלּוּ גַּלְגַּל חַמָּה, כָּל שֶׁכֵּן בֶּן אָדָם שֶׁנִּמְצָא מִמֶּנּוּ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אִלּוּ כָּתוּב וּמִן הֶעָפָר וְלֹא יוֹתֵר - הָיִיתִי אוֹמֵר כָּךְ. אֲבָל כֵּיוָן שֶׁכָּתוּב וּמִן הֶעָפָר אֲשֶׁר יִהְיֶה בְּקַרְקַע הַמִּשְׁכָּן, מַשְׁמָע שֶׁאַחֵר הוּא. אֶלָּא כָּתוּב (ישעיה מא) יִתֵּן כֶּעָפָר חַרְבּוֹ, אֵלֶּה בַּעֲלֵי כְּלֵי זַיִן וּבַלִּיסְטְרָאוֹת, בַּעֲלֵי דִּין הַקָּשֶׁה. מַשְׁמָע שֶׁכָּתוּב בְּקַרְקַע הַמִּשְׁכָּן, שֶׁאֲחוּזִים לְמַטָּה. וְעַל זֶה, יִקַּח הַכֹּהֵן וְנָתַן אֶל הַמָּיִם.</p>\n<p>מֵי הַמָּרִים הַמְאָרֲרִים - אֵלֶּה מֵי יָם שֶׁהֵם מְרִירִים. מַהוּ? זֶה שֵׁם הַקָּדוֹשׁ בְּשָׁעָה שֶׁנִּמְצָא בְדִין, אָז נִקְרָאִים מֵי הַמָּרִים הַמְאָרֲרִים. וּמִשּׁוּם זֶה מֵי הַיָּם שֶׁלְּמַטָּה כֻּלָּם מְ רִירִים.</p>\n<p>בֹּא רְאֵה, יָם קָדוֹשׁ זֶה, כַּמָּה נְהָרוֹת מְתוּקִים נִכְנָסִים בְּתוֹכוֹ, וּמִשּׁוּם שֶׁהוּא דִּין הָעוֹלָם, מֵימָיו מְרִירִים, מִשּׁוּם שֶׁאָחוּז בָּהֶם הַמָּוֶת לְכָל בְּנֵי הָעוֹלָם. וְאַף עַל גַּב שֶׁהֵם מְרִירִים, כְּשֶׁמִּתְפַּשְּׁטִים הֵם מְתוּקִים. לִפְעָמִים מֵי הַיָּם מְרִירִים. לִפְעָמִים הַיָּם שֶׁבּוֹלֵעַ לְכָל שְׁאָר הַמַּיִם, וְנִקְרָא יָם קָפוּא, וּבוֹלֵעַ כָּל אוֹתָם אֲחֵרִים וְשׁוֹאֵב אוֹתָם לְתוֹכוֹ, וְלֹא נִגָּרִים הַחוּצָה. לִפְעָמִים שׁוֹרִים הַמַּיִם וּמַשְׁפִּיעִים מֵאוֹתוֹ הַיָּם כָּל מַה שֶּׁשּׁוֹפֵעַ לַתַּחְתּוֹנִים. וּבְכַמָּה גְוָנִים עָמַד יָם זֶה. הַמַּיִם הַמְאָרַרִים, בְּשָׁעָה שֶׁבָּא הַנָּחָשׁ וְהִטִּיל זֻהֲמָה, אָז הַמַּיִם הַמְאָרַרִים, וְעַל כָּךְ הַכֹּהֵן עוֹשֶׂה מַעֲשֶׂה לְמַטָּה, וְנִשְׁבָּע שְׁבוּעָה, וְנַעֲשֶׂה דִין.</p>\n<p>בֹּא רְאֵה, אִם הָאִשָּׁה נִמְצֵאת זַכָּאִית, מַיִם אֵלֶּה נִכְנָסִים בְּתוֹכָהּ וְנֶהְפָּכִים לִמְתוּקִים, וּמְנַקִּים עַצְמָהּ, וְעוֹמְדִים בְּתוֹכָהּ עַד שֶׁמִּתְעַבֶּרֶת. כֵּיוָן שֶׁמִּתְעַבֶּרֶת, הָיוּ מְיַפִּים בְּיֹפִי לָעֻבָּר שֶׁבְּמֵעֶיהָ, וְיוֹצֵא בֵּן יָפֶה, נָקִי בְּלִי מוּם שֶׁל הָעוֹלָם. וְאִם לֹא - הַמַּיִם הָאֵלֶּה נִכְנָסִים בְּתוֹכָהּ, וּמְרִיחָה רֵיחַ זֻהֲמָה, וְאוֹתָם מַיִם מִתְהַפְּכִים לְנָחָשׁ בְּמֵעֶיהָ. בְּמַה שֶּׁקִּלְקְלָה נִתְפֶּסֶת, וְנִרְאֶה קָלוֹן לַכֹּל, וְכָךְ פֵּרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>בֹּא רְאֵה, כָּל נְשׁוֹת הָעוֹלָם עוֹמְדוֹת בִּמְקוֹמָן וְנִדּוֹנוֹת, וְעַל כָּךְ, אוֹתוֹ מָקוֹם מַמָּשׁ שֶׁהֵן עוֹמְדוֹת, שָׁם נִדּוֹנוֹת. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶם וְרוֹצֶה לְזַכּוֹתָם.</p>\n<p>רַבִּי חִזְקִיָּה פָּתַח, (תהלים קכח) אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה וְגוֹ'. מַה גֶּפֶן לֹא מְקַבֶּלֶת עָלֶיהָ אֶלָּא מִשֶּׁלָּהּ - כָּךְ אֵשֶׁת יִשְׂרָאֵל עוֹמֶדֶת בִּכְגוֹן זֶה, שֶׁלֹּא מְקַבֶּלֶת עָלֶיהָ אֶלָּא אוֹתוֹ בֶּן זוּגָהּ, כְּמוֹ הַיּוֹנָה (כיונה) הַזּוֹ שֶׁלֹּא מְקַבֶּלֶת עָלֶיהָ אֶלָּא אוֹתוֹ בֶּן זוּגָהּ. וְעַל כֵּן, כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ. מַה זֶּה פֹּרִיָּה? כְּמוֹ שֶׁנֶּאֱמַר (דברים כט) פֹּרֶה רֹאשׁ. פֹּרִיָּה - פּוֹרַחַת, שֶׁמּוֹצִיאָה עֲנָפִים לְכָל צַד. וְאֵיפֹה? בְּיַרְכְּתֵי בֵיתֶךְ, וְלֹא לַחוּץ בַּשּׁוּק, מִשּׁוּם שֶׁלֹּא תָבֹא לְשַׁקֵּר בִּבְרִית עֶלְיוֹנָה.</p>\n<p>וּשְׁלֹמֹה אָמַר, (משלי ב) הַעֹזֶבֶת אַלּוּף נְעוּרֶיהָ וְאֶת בְּרִית אֱלֹהֶיהָ שָׁכֵחָה. מַה זֶּה בְּרִית אֱלֹהֶיהָ? אוֹתוֹ מָקוֹם שֶׁנִּקְרָא בְּרִית וְהִיא הִתְקַשְּׁרָה בּוֹ, בִּגְלַל כָּךְ בְּיַרְכְּתֵי בֵיתֶךְ.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, קְלָלָה תָּבֹא עַל אוֹתוֹ אִישׁ שֶׁמַּשְׁאִיר אֶת אִשְׁתּוֹ לְהֵרָאוֹת עִם שַׂעֲרוֹת רֹאשָׁהּ בַּחוּץ, וְזֶה אֶחָד מֵאוֹתָם צְנִיעֻיּוֹת שֶׁל הַבַּיִת. וְאִשָּׁה שֶׁמּוֹצִיאָה מִשַּׂעֲרוֹת רֹאשָׁהּ הַחוּצָה לְהִתְתַּקֵּן בּוֹ, גּוֹרֶמֶת עֹנִי לַבַּיִת, וְגוֹרֶמֶת לְבָנֶיהָ שֶׁלֹּא יֵחָשְׁבוּ בַּדּוֹר, וְגוֹרֶמֶת דָּבָר אַחֵר שֶׁשּׁוֹרֶה בַּבַּיִת. מִי גָרַם זֶה? אוֹתוֹ שֵׂעָר שֶׁנִּרְאֶה מֵרֹאשָׁהּ הַחוּצָה. וּמַה בַּבַּיִת כָּךְ - כָּל שֶׁכֵּן בַּשּׁוּק, וְכָל שֶׁכֵּן חֲצִיפוּת אַחֶרֶת. וּמִשּׁוּם זֶה, אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, שְׂעַר רֹאשׁ הָאִשָּׁה שֶׁמִּתְגַּלֶּה, גּוֹרֵם לְשֵׂעָר אַחֵר לְהִתְגַּלּוֹת וְלִפְגֹּם אוֹתָהּ. מִשּׁוּם כָּךְ צְרִיכָה אִשָּׁה שֶׁאֲפִלּוּ קוֹרוֹת בֵּיתָהּ לֹא יִירְאוּ שַׂעֲרָה אַחַת מֵרֹאשָׁהּ, וְכָל שֶׁכֵּן בַּחוּץ.</p>\n<p>בֹּא רְאֵה, כְּמוֹ שֶׁבַּזָּכָר הַשֵּׂעָר הוּא חֻמְרַת הַכֹּל - כָּךְ גַּם לַנְּקֵבָה. צֵא וּרְאֵה כַּמָּה פְגָם גּוֹרֵם אוֹתוֹ שְׂעַר הָאִשָּׁה: גּוֹרֵם לְמַעְלָה וְגוֹרֵם לְמַטָּה, גּוֹרֵם לְבַעְלָהּ לְהִתְקַלֵּל, גּוֹרֵם עֹנִי, וְגוֹרֵם דָּבָר אַחֵר בַּבַּיִת, גּוֹרֵם שֶׁתִּסְתַּלֵּק חֲשִׁיבוּת מִבָּנֶיהָ. הָרַחֲמָן יַצִּילֵנוּ מֵחֲצִיפוּתָן.</p>\n<p>וְעַל כָּךְ צְרִיכָה אִשָּׁה לְהִתְכַּסּוֹת בְּזָוִיּוֹת בֵּיתָהּ. וְאִם עוֹשָׂה כָּךְ, מַה כָּתוּב? (תהלים קכח) בָּנֶיךְ כִּשְׁתִלֵי זֵיתִים. מַה זֶּה כִּשְׁתִלֵי זֵיתִים? מַה זַּיִת זֶה, בֵּין בַּסְּתָו בֵּין בַּקַּיִץ לֹא אוֹבְדִים עָלָיו, וְתָמִיד נִמְצֵאת בּוֹ חֲשִׁיבוּת יְתֵרָה עַל שְׁאָר הָאִילָנוֹת - כָּךְ בָּנֶיהָ יַעֲלוּ בַחֲשִׁיבוּת עַל שְׁאָר בְּנֵי הָעוֹלָם. וְלֹא עוֹד, אֶלָּא שֶׁבַּעְלָהּ מִתְבָּרֵךְ בַּכֹּל: בַּבְּרָכוֹת שֶׁלְּמַעְלָה, בַּבְּרָכוֹת שֶׁלְּמַטָּה, בְּעֹשֶׁר, בְּבָנִים וּבִבְנֵי בָנִים. זֶהוּ שֶׁכָּתוּב (שם) הִנֵּה כִּי כֵן יְבֹרַךְ גָּבֶר יְרֵא ה'. וְכָתוּב, יְבָרֶכְךְ ה' מִצִּיּוֹן וּרְאֵה בְּטוּב יְרוּשָׁלם כֹּל יְמֵי חַיֶּיךְ וּרְאֵה בָנִים לְבָנֶיךְ שָׁלוֹם עַל יִשְׂרָאֵל. (ישראל הזקן הקדוש)</p>\n<p>אֵלִיָּהוּ, קוּם פְּתַח אִתִּי בְּמִצְווֹת, שֶׁאַתָּה הוּא עוֹזֵר לִי בְּכָל צַד, שֶׁהֲרֵי עָלֶיךְ נֶאֱמַר בַּתְּחִלָּה, (במדבר כה) פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן. וּבֶן אַהֲרֹן הוּא וַדַּאי אָח שֶׁלִּי, אָח לְצָרָה יִוָּלֵד.</p>\n<p>פָּתַח וְאָמַר, מִצְוָה לָדוּן בְּדִינֵי סוֹטָה, זֶהוּ שֶׁכָּתוּב וְעָבַר עָלָיו רוּחַ קִנְאָה וְקִנֵּא וְגוֹ'. וַדַּאי רוּחַ קִנְאָה נִמְצֵאת בִּשְׁנֵי צְדָדִים, אֶחָד בְּשֶׁקֶר וְאֶחָד בֶּאֱמֶת, בִּגְלַל זֶה, בְּרוּחַ שֶׁקֶר - וְקִנֵּא אֶת אִשְׁתּוֹ, וְהִיא לֹא נִטְמָאָה. וְלָמַדְנוּ, וְעָבַר עָלָיו וְגוֹ', וְקִנֵּא אֶת אִשְׁתּוֹ וְהִיא נִטְמָאָה.</p>\n<p>וְכִי יֵשׁ אֱמֶת בְּרוּחַ טֻמְאָה? אֶלָּא בָּאָדָם מִצַּד עֵץ טוֹב וָרָע, שָׁם יֵצֶר הָרָע, נָחָשׁ. בִּזְמַן שֶׁיֵּשׁ לָאָדָם אִשָּׁה יָפָה בְּכָל מַעֲשִׂים טוֹבִים, שֶׁנֶּאֱמַר בָּהּ (משלי יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ, לַיֵּצֶר הָרָע יֵשׁ קִנְאָה, כְּמוֹ שֶׁלָּמַדְנוּ שֶׁקִּנֵּא אָדָם עַל אִשְׁתּוֹ, עַד שֶׁפִּתָּה אוֹתָהּ וְגָרַם לָהּ מִיתָה. וְלִפְעָמִים שׁוֹלֵט עָלֶיהָ בַּעֲבֵרוֹת וּמְטַמֵּא אוֹתָהּ וְנַעֲשֵׂית נְבֵלָה.</p>\n<p>וְיֵצֶר הָרָע מִצַּד יָמִין שֶׁלּוֹ, דַּרְגַּת יִשְׁמָעֵאל, נִקְרָא נָחָשׁ. וּמִצַּד שְׂמֹאלוֹ דַּרְגַּת עֵשָׂו, סָמָאֵ\"ל, נִקְרָא כֶּלֶב, מְמֻנֶּה שֶׁל גֵּיהִנֹּם שֶׁצּוֹוֵחַ הַב הַב. זֶהוּ שֶׁכָּתוּב (משלי ל) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. וּבִרְצוֹנוֹ לֶאֱכֹל נְשָׁמָה טְמֵאָה בָּאֵשׁ שֶׁלּוֹ, גֵּיהִנֹּם. וְעָבַר עָלָיו רוּחַ טֻמְאָה וְקִנֵּא אֶת אִשְׁתּוֹ בֶּאֱמֶת, וְהִיא נִטְמָאָה.</p>\n<p>וּבִגְלָלָהּ נֶאֱמַר, (ויקרא כא) וּבַת אִישׁ כֹּהֵן - זֶה מִיכָאֵל - כִּי תֵחֵל לִזְנוֹת אֶת אָבִיהָ הִיא מְחַלֶּלֶת בָּאֵשׁ תִּשָּׂרֵף. וְשָׁם נִשְׂרֶפֶת אוֹתָהּ זֻהֲמָא, וּמִתְלַבֶּנֶת הִיא מִמֶּנּוּ כְּכֶסֶף שֶׁמִּתְלַבֵּן בָּאֵשׁ, וְאוֹתָהּ עֹפֶרֶת שֶׁל זֻהֲמָא נִשְׂרֶפֶת, וְנַעֲשֵׂית עָפָר וְנֶאֱבֶדֶת.</p>\n<p>כְּמוֹ זֶה יִשְׂרָאֵל, כְּשֶׁהֵם מְחַלְּלִים אֶת הַתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְנִיס אוֹתָם לְגָלוּת בְּנֵי עֵשָׂו וּבְנֵי יִשְׁמָעֵאל שֶׁתַּחַת שִׁעְבּוּדָם, שֶׁדַּרְגָּתָם כֶּלֶ\"ב וְנָחָ\"שׁ, וְנִדּוֹנִים שָׁם, וּבָהֶם יִתְבָּרְרוּ וְיִתְלַבְּנוּ וִיצֹרְפוּ כִּצְרֹף הַכֶּסֶף וְכִבְחֹן הַזָּהָב. זֶהוּ שֶׁכָּתוּב (זכריה יג) וּצְרַפְתִּים כִּצְרֹף אֶת הַכֶּסֶף וּבְחַנְתִּים כִּבְחֹן אֶת הַזָּהָב, עַד שֶׁיִּתְקַיֵּם בָּהֶם, (ישעיה א) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ.</p>\n<p>וְעֵץ טוֹב וָרָע, בִּגְלָלוֹ נֶאֱמַר (שמות טו) וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם וְגוֹ'. מִשּׁוּם שֶׁהָיוּ יִשְׂרָאֵל עִם עֵרֶב רַב, כֻּלָּם הָיוּ עֵץ שֶׁל טוֹב וָרָע, וְעַל זֶה חֶצְיוֹ מָתוֹק מִצַּד יָמִין, וְחֶצְיוֹ מַר מִצַּד שְׂמֹאל. וּבִזְמַן שֶׁעֵרֶב רַב הָיוּ מַחֲטִיאִים אֶת יִשְׂרָאֵל, הָיָה כְּאִלּוּ הָיוּ כֻלָּם מִצַּד הָרָע, וְהַמַּיִם חָזְרוּ לִהְיוֹת מְרִירִים כְּמוֹ אוֹתוֹ עֵץ מַר בַּמַּיִם. זֶהוּ שֶׁכָּתוּב וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם.</p>\n<p>וְעֵץ מַר זֶה הוּא כְּמוֹ נִסְיוֹן הַסּוֹטָה. אִם סָטְתָה תַּחַת בַּעְלָהּ, אוֹתָם מַיִם שֶׁמַּשְׁקִים אוֹתָם חוֹזְרִים לִהְיוֹת מְרִירִים, וּבָהֶם צָבְתָה בִטְנָהּ וְנָפְלָה יְרֵכָהּ. וְאִם לֹא סָטְתָה, מַה כָּתוּב? וְנִקְּתָה וְנִזְרְעָה זָרַע, וּמוֹלִידָה בֵּן. אַף כָּאן וַיִּמְתְּקוּ הַמָּיִם.</p>\n<p>כְּמוֹ זֶה יַעֲשֶׂה לְנַסּוֹת אֶת יִשְׂרָאֵל בַּגְּאֻלָּה הָאַחֲרוֹנָה, זֶהוּ שֶׁכָּתוּב (דניאל יב) יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצָּרְפוּ רַבִּים - שֶׁהֵם מִצַּד הַטּוֹב, וְעוֹמְדִים בַּנִּסָּיוֹן. וְהִרְשִׁיעוּ רְשָׁעִים - הֵם מִצַּד הָרָע, וְיִתְקַיֵּם בָּהֶם (יחזקאל יג) וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבאוּ, וְהוֹרֵג אוֹתָם.</p>"],[9522012279,"<p>וְהַמַּשְׂכִּילִים יָבִינוּ - מִצַּד הַבִּינָה, שֶׁהוּא עֵץ הַחַיִּים, בִּגְלָלָם נֶאֱמַר (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹּהַר הָרָקִיעַ, בְּחִבּוּר זֶה שֶׁלְּךְ, שֶׁהוּא סֵפֶר הַזֹּהַר, מִזֹּהַר הָאֵם הָעֶלְיוֹנָה תְּשׁוּבָה. בְּאֵלֶּה לֹא צָרִיךְ נִסָּיוֹן, וּמִשּׁוּם שֶׁעֲתִידִים יִשְׂרָאֵל לִטְעֹם מֵעֵץ הַחַיִּים, שֶׁהוּא סֵפֶר הַזֹּהַר הַזֶה, יֵצְאוּ בוֹ מֵהַגָּלוּת, וְיִתְקַיֵּם בָּהֶם (דברים לב) ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר.</p>\n<p>וְעֵץ טוֹב וָרָע, שֶׁהוּא אִסּוּר וְהֶתֵּר, טֻמְאָה וְטָהֳרָה, לֹא שׁוֹלֵט יוֹתֵר עַל יִשְׂרָאֵל, שֶׁהֲרֵי פַּרְנָסָתֵנוּ לֹא תִהְיֶה אֶלָּא מִצַּד עֵץ הַחַיִּים, שֶׁאֵין שָׁם לֹא קֹשִׁי מִצַּד הָרָע, וְלֹא מַחֲלֹקֶת מֵרוּחַ הַטֻּמְאָה, שֶׁכָּתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ.</p>\n<p>שֶׁלֹּא יִתְפַּרְנְסוּ תַּלְמִידֵי חֲכָמִים מֵעַמֵּי הָאָרֶץ אֶלָּא מִצַּד הַטּוֹב, שֶׁאוֹכְלִים טָהֳרָה, כָּשֵׁר, הֶתֵּר, וְלֹא מֵעֵרֶב רַב שֶׁאוֹכְלִים טֻמְאָה, פָּסוּל, אִסּוּר. שֶׁהֵם טְמֵאִים, שֶׁמְּטַמְּאִים עַצְמָם בְּנִדָּה שִׁפְחָה גּוֹיָה זוֹנָה, מִשּׁוּם שֶׁהֵם בְּנֵי לִילִית, שֶׁהִיא נִדָּה שִׁפְחָה גּוֹיָה זוֹנָה, חוֹזְרִים לְשָׁרְשָׁם, וַעֲלֵיהֶם נֶאֱמַר (ישעיהיד) כִּי מִשֹּׁרֶשׁ נָחָשׁ יֵצֵא צֶפַע.</p>\n<p>וּבִזְמַן שֶׁעֵץ טוֹב וָרָע שׁוֹלֵט, שֶׁהוּא חֻלִּין שֶׁל טָהֳרָה וְחֻלִּין שֶׁל טֻמְאָה, הֵם חֲכָמִים שֶׁדּוֹמִים לְשַׁבָּתוֹת וְיָמִים טוֹבִים, אֵין לָהֶם אֶלָּא מַה שֶּׁנּוֹתְנִים לָהֶם אוֹתָם חֻלִּין, כְּמוֹ יוֹם הַשַּׁבָּת שֶׁאֵין לוֹ אֶלָּא מַה שֶּׁמְּתַקְּנִים לוֹ בִּימוֹת הַחֹל.</p>\n<p>וּבִזְמַן שֶׁשּׁוֹלֵט עֵץ הַחַיִּים, נִכְפֶּה עֵץ טוֹב וָרָע, וְלֹא יִהְיֶה לְעַמֵּי הָאָרֶץ, רַק מַה שֶּׁנּוֹתְנִים לָהֶם תַּלְמִידֵי חֲכָמִים, וְנִכְפִּים תַּחְתֵּיהֶם, וּכְאִלּוּ לֹא הָיוּ בָעוֹלָם.</p>\n<p>וְכֵן אִסּוּר וְהֶתֵּר, טֻמְאָה וְטָהֳרָה, לֹא עוֹבֵר מֵעַמֵּי הָאָרֶץ, שֶׁמִּצִּדָּם אֵין בֵּין גָּלוּת לִימוֹת הַמָּשִׁיחַ (אליהם) אֶלָּא שִׁעְבּוּד מַלְכֻיּוֹת בִּלְבַד, שֶׁהֵם לֹא טוֹעֲמִים מֵעֵץ הַחַיִּים, וְצָרִיךְ לָהֶם מִשְׁנָה בְּאִסּוּר וְהֶתֵּר, טֻמְאָה וְטָהֳרָה. אֶלָּא יִהְיוּ מְבֻזִּים לִפְנֵי תַּלְמִידֵי חֲכָמִים כְּמוֹ חֹשֶׁךְ לִפְנֵי הָאוֹר, שֶׁעֵרֶב רַב הֵם עַמֵּי הָאָרֶץ, הֵם חֲשׁוּכִים. וְלֹא נִקְרְאוּ יִשְׂרָאֵל, אֶלָּא עֲבָדִים מְכוּרִים לְיִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם כִּבְהֵמוֹת, וְכָךְ פֵּרְשׁוּהָ.</p>\n<p>וְיִשְׂרָאֵל נִקְרְאוּ אָדָם. וּמִנַּיִן שֶׁיֵּשׁ בָּהֶם בְּהֵמָה וְאָדָם? זֶהוּ שֶׁכָּתוּב (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם. וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי - הֵם עַמֵּי אֲרָצוֹת טוֹבִים מִצַּד הַטּוֹב. אָדָם אַתֶּם - תַּלְמִידֵי חֲכָמִים.</p>\n<p>וּבְפָסוּק זֶה גַּם רָמוּז לוֹ, (תהלים פא) לוּ עַמִּי שׁוֹמֵעַ לִי יִשְׂרָאֵל וְגוֹ'. אַחַר שֶׁאָמַר עַמִּי, לָמָּה אָמַר יִשְׂרָאֵל? אֶלָא עַמִּי - עַמֵּי הָאֲרָצוֹת. יִשְׂרָאֵל - תַּלְמִידֵי חֲכָמִים וּבִגְלָלוֹ נֶאֱמַר (שמות יד) וּבְנֵי יִשְׂרָאֵל יצְאִים בְּיָד רָמָה.</p>\n<p>כְּמוֹ שֶׁחִלְּקָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּהַר סִינַי, כָּךְ חִלְּקָם בַּגְּאֻלָּה הָאַחֲרוֹנָה, שֶׁיִּשְׂרָאֵל שֶׁנֶּאֱמַר בָּהֶם (שם יג) וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם, מִצַּד עֵץ הַחַיִּים, שֶׁהֵם חֲמִשִּׁים שְׁנוֹת יוֹבֵל, נֶאֱמַר בָּהֶם (שם יט) הֵמָּה יַעֲלוּ בָהָר. וּבָהֶם (שם יד) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל. וְלָהֶם נֶאֱמַר (שם יט) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים, שֶׁהֵם עַנְנֵי כָבוֹד, וָאָבִא אֶתְכֶם אֵלָי. וּבְנֵי יִשְׂרָאֵל יֹצְאִים בְּיָד רָמָה, כָּךְ יוֹצִיא אֶת הַתַּלְמִידֵי חֲכָמִים בְּכָל הַכָּבוֹד הַזֶּה.</p>\n<p>וּכְמוֹ שֶׁנֶּאֱמַר בְּעַמֵּי הָאָרֶץ מִצַּד הַטּוֹב, (שם) וַיִּתְיַצְּבוּ בְּתַחְתִּית הָהָר - כָּךְ יִהְיֶה בַיְצִיאָה הָאַחֲרוֹנָה תַּחַת תַּלְמִידֵי חֲכָמִים, כְּעֶבֶד שֶׁהוֹלֵךְ לְרַגְלֵי סוּס בְּעָלָיו, וּכְמוֹ שֶׁאָמַר לָהֶם בְּתַחְתִּית הָהָר: אִם תְּקַבְּלוּ תוֹרָתִי - מוּטָב, וְאִם לָאו - שָׁם תְּהֵא קְבוּרַתְכֶם. כָּךְ יִהְיֶה בִּיצִיאַת גְּאֻלָּה אַחֲרוֹנָה: אִם תְּקַבְּלוּ עֲלֵיכֶם תַּלְמִידֵי חֲכָמִים בִּיצִיאַת הַגָּלוּת, כְּאָדָם שֶׁרוֹכֵב עַל סוּס וְעֶבֶד שֶׁמְּשַׁמְּשׁוֹ - מוּטָב. וְאִם לֹא - שָׁם תְּהֵא קְבוּרַתְכֶם בַּגָּלוּת.</p>"],[9522012280,"<p>וְעֵרֶב רַב, כְּמוֹ שֶׁנֶּאֱמַר בָּהֶם, (שמות כ) וַיַּרְא הָעָם וַיָּנֻעוּ וַיַּעַמְדוּ מֵרָחֹק. כָּךְ יִהְיוּ רְחוֹקִים מִן הַגְּאֻלָּה, וְיִרְאוּ תַלְמִידֵי חֲכָמִים וְהָעָם הַקָּדוֹשׁ בְּכָל הַכָּבוֹד הַזֶּה, וְהֵם רְחוֹקִים מֵהֶם. וְאִם יֵרְדוּ לְהִתְחַבֵּר אִתָּם, מַה כָּתוּב בָּהֶם? (שם יט) לֹא תִגַּע בּוֹ יָד כִּי סָקוֹל יִסָּקֵל אוֹ יָרֹה יִיָּרֶה. בְּאוֹתוֹ זְמַן יִתְקַיֵּם בְּיִשְׂרָאֵל, (דברים לב) ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר, וַהֲרֵי פֵּרְשׁוּהָ, אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ. (שמואל א ב) וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ - הֵם עֵרֶב רַב. וּמִשּׁוּם זֶה אָמַר עֲלֵיהֶם הַנָּבִיא, (יחזקאל יג) וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבֹאוּ.</p>\n<p>אָמַר אֵלִיָּהוּ, רוֹעֶה הַנֶּאֱמָן, הֲרֵי שָׁעָה הִיא לַעֲלוֹת לְמַעְלָה, בִּשְׁבוּעָה אֱמֹר אַתָּה, שֶׁהֲרֵי בִּגְלָלְךְ אֲנִי רוֹצֶה לַעֲלוֹת. שֶׁנָּתַן לִי הַקָּדוֹשׁ בָּרוּךְ הוּא רְשׁוּת לְהִתְגַּלּוֹת לְךְ בְּבֵית הָאֲסוּרִים שֶׁלְּךְ, בִּקְבוּרָתְךְ, וְלַעֲשׂוֹת עִמְּךְ טוֹב, שֶׁאַתָּה מְחוֹלָל בַּחֲטָאֵי הָעָם. זֶהוּ שֶׁכָּתוּב (ישעיה נג) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ.</p>\n<p>אָמַר לוֹ רוֹעֶה הַנֶּאֱמָן, בִּשְׁבוּעָה עָלֶיךְ בְּשֵׁם ה', אַל תְּאַחַר בְּכָל יְכָלְתְּךְ, שֶׁהֲרֵי אֲנִי בְּצַעַר רַב. (שמות ב) וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ, עוֹזֵר לִי, לְהוֹצִיאֵנִי מִצַּעַר זֶה, בִּקְבוּרָה זוֹ שֶׁנֶּאֱמַר עָלַי, (ישעיה נג) וַיִּתֵּן אֶת הָרְשָׁעִים קִבְרוֹ, וְלֹא נוֹדָע בִּי, וַאֲנִ חָשׁוּב בְּעֵינֵיהֶם, בֵּין עֵרֶב רַב הָרְשָׁעִים, כְּכֶלֶב מֵת שֶׁסָּרַח בֵּינֵיהֶם, שֶׁחָכְמַת סוֹפְרִים תִּסְרַח בֵּינֵיהֶם בְּכָל עִיר וָעִיר וּבְכָל מָקוֹם שֶׁיִּשְׂרָאֵל מְפֻזָּרִים בֵּינֵיהֶם בֵּין הַמְּלָכִים. וְחָזְרוּ אוֹתָם עֵרֶב רַב רוֹעִים עַל יִשְׂרָאֵל, צֹאן הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר בָּהֶם (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, וְאֵין לָהֶם יְכֹלֶת לַעֲשׂוֹת טוֹב עִם תַּלְמִידֵי חֲכָמִים.</p>\n<p>וְאַנְשֵׁי חַיִל וְיִרְאֵי חֵטְא מְסוֹבְבִים מֵעִיר לְעִיר וְלֹא יְחוֹנָנוּ, וּמַחֲרִימִים עֵרֶב רַב בֵּינֵיהֶם. וְלֹא נוֹתְנִים לָהֶם בִּמְקוֹמוֹת רַבִּים, אֶלָּא דָּבָר קָצוּב, שֶׁלֹּא תִהְיֶה תְקוּמָה לִנְפִילָתָם, וַאֲפִלּוּ חַיֵּי שָׁעָה. וְכָל הַחֲכָמִים וְאַנְשֵׁי חַיִל וְיִרְאֵי חֵטְא בְּדחַק וְיָגוֹן, חֲשׁוּבִים כִּכְלָבִים, בָּנִים הַמְסֻלָּאִים בַּפָּז אֵיכָה נֶחְשְׁבוּ לְנִבְלֵי חֶרֶשׂ בְּרֹאשׁ כָּל חוּצוֹת. שֶׁלֹּא מָצְאוּ אַכְסַנְיָה בֵּינֵיהֶם.</p>\n<p>וְאוֹתָם עֵרֶב רַב הֵם עֲשִׁירִים בְּשַׁלְוָה, בְּשִׂמְחָה, בְּלִי צַעַר, בְּלֹא יָגוֹן כְּלָל, גַּזְלָנִים, בַּעֲלֵי שֹׁחַד, שֶׁהֵם דַּיָּנִים רָאשֵׁי הָעָם. (בראשית ז) כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. עֲלֵיהֶם נֶאֱמַר (איכה א) הָיוּ צָרֶיהָ לְרֹאשׁ. בִּשְׁבוּעָה עָלֶיךְ פַּעַם שְׁנִיָּה, בְּחַי ה' צְבָאוֹת אֱלֹהֵי יִשְׂרָאֵל יוֹשֵׁב הַכְּרוּבִים, שֶׁכָּל הַדְּבָרִים הָאֵלֶּה לֹא יִפְּלוּ מִפִּיךְ, בְּכָל יְכָלְתְּךְ לְדַבֵּר אוֹתָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהַרְאוֹת אֶת הַדּחַק שֶׁלָּהֶם.</p>"],[9522012281,"<p>אִישׁ כִּי יַפְלִא לִנְדֹּר וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (ישעיה נ) מַדּוּעַ בָּאתִי וְאֵין אִישׁ וְגוֹ'. מַדּוּעַ בָּאתִי. כַּמָּה חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבְּכָל מָקוֹם בּוֹ הֵם שׁוֹרִים, הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בֵינֵיהֶם, מִשּׁוּם שֶׁלֹּא מַעֲבִיר אַהֲבָתוֹ מֵהֶם. מַה כָּתוּב? (שמות כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם. וְעָשׂוּ לִי מִקְדָּשׁ סְתָם. שֶׁכָּל בֵּית כְּנֶסֶת בָּעוֹלָם נִקְרָא מִקְדָּשׁ, וַהֲרֵי פֵּרְשׁוּהָ. וְהַשְּׁכִינָה מַקְדִּימָה לְבֵית הַכְּנֶסֶת.</p>\n<p>אַשְׁרֵי הָאִישׁ שֶׁנִּמְצָא מֵעֲשָׂרָה הָרִאשׁוֹנִים בְּבֵית הַכְּנֶסֶת, מִשּׁוּם שֶׁבּוֹ נִשְׁלָם מַה שֶּׁנִּשְׁלָם, וְהֵם מִתְקַדְּשִׁים בַּהַתְחָלָה בַּשְּׁכִינָה, וַהֲרֵי נִתְבָּאֵר. וַהֲרֵי צָרִיךְ שֶׁיִּמָּצְאוּ עֲשָׂרָה בִּזְמַן אֶחָד בְּבֵית הַכְּנֶסֶת, וְלֹא יָבֹאוּ קְבוּצוֹת קְבוּצוֹת, שֶׁלֹּא תִתְעַכֵּב שְׁלֵמוּת הָאֵיבָרִים, שֶׁהֲרֵי הָאָדָם בִּזְמַן אֶחָד עֲשָׂאוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִתְקִינוֹ כְאֶחָד כָּל הָאֵיבָרִים. זֶהוּ שֶׁכָּתוּב (דברים לב) הוּא עָשְׂךְ וַיְכֹנֲנֶךְ.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁנִּשְׁלְמוּ אֵיבְרֵי הָאָדָם, בְּאוֹתוֹ זְמַן הִתְתַּקֵּן לְכָל אֵיבָר וְאֵיבָר כָּרָאוּי. כְּמוֹ זֶה, כֵּיוָן שֶׁשְּׁכִינָה מַקְדִּימָה לְבֵית הַכְּנֶסֶת, צָרִיךְ עֲשָׂרָה שֶׁיִּמָּצְאוּ שָׁם כְּאֶחָד, וְיִשְׁתַּלֵּם מַה שֶּׁיִּשְׁתַּלֵּם. וְאַחַר שֶׁמִּתְתַּקֵּן הַכֹּל. וּבַמָּה הוּא תִּקּוּן הַכֹּל? כְּמוֹ שֶׁנֶּאֱמַר (משלי יד) בְּרָב עָם הַדְרַת מֶלֶךְ. וְעַל זֶה הָעָם שֶׁבָּא אַחַר כָּךְ, כֻּלָּם תִּקּוּן הַגּוּף.</p>\n<p>וּכְשֶׁבָּאָה וּמַקְדִּימָה שְׁכִינָה, וּבְנֵי אָדָם לֹא בָאִים כָּרָאוּי - הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא, מַדּוּעַ בָּאתִי וְאֵין אִישׁ. מַה זֶּה וְאֵין אִישׁ? שֶׁלֹּא מְתֻקָּנִים הָאֵיבָרִים וְלֹא הֻשְׁלַם הַגּוּף. שֶׁכְּשֶׁגּוּף לֹא מֻשְׁלָם, אֵין אִישׁ. וּמִשּׁוּם זֶה, וְאֵין אִישׁ דַּוְקָא. וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁהַגּוּף הֻשְׁלַם לְמַטָּה, קְדֻשָּׁה עֶלְיוֹנָה בָּאָה וְנִכְנֶסֶת בְּגוּף זֶה, וְנַעֲשֶׂה לְמַטָּה כְּמוֹ לְמַעְלָה מַמָּשׁ, וְאָז הַכֹּל צְרִיכִים שֶׁלֹּא יִפְתְּחוּ פֶּה בְּדִבְרֵי הָעוֹלָם. מִשּׁוּם שֶׁהֲרֵי עוֹמְדִים יִשְׂרָאֵל בִּשְׁלֵמוּת עֶלְיוֹנָה וּמִתְקַדְּשִׁים בִּקְדֻשָּׁה עֶלְיוֹנָה, אַשְׁרֵי חֶלְקָם.</p>"],[9522012282,"<p>אִישׁ כִּי יַפְלִא וְגוֹ'. מַה זֶּה כִּי יַפְלִא? שֶׁנִּפְרָד מִשְּׁאָר בְּנֵי הָעוֹלָם לְהִתְקַדֵּשׁ כְּמוֹ שֶׁלְּמַעְלָה וּלְהִמָּצֵא שָׁלֵם. בְּשָׁעָה שֶׁבָּא אָדָם לִטָּהֵר - מְטַהֲרִים אוֹתוֹ. אָדָם שֶׁרוֹצֶה לְהִתְקַדֵּשׁ - מְקַדְּשִׁים אוֹתוֹ, וּפוֹרְסִים עָלָיו קְדֻשָּׁה עֶלְיוֹנָה, קְדֻשָּׁה שֶׁהִתְקַדֵּשׁ בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>רַבִּי אַבָּא פָּתַח, (תהלים קג) לְדָוִד בָּרְכִי נַפְשִׁי אֶת ה' וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ. כַּמָּה יֵשׁ לוֹ לָאָדָם לְהִסְתַּכֵּל וְלָדַעַת בַּעֲבוֹדַת רִבּוֹנוֹ, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם הַכָּרוֹז קוֹרֵא וְאוֹמֵר: (משלי א) עַד מָתַי פְּתָיִם תְּאֵהֲבוּ פֶתִי וְגוֹ'. (ירמיה ג) שׁוּבוּ בָּנִים שׁוֹבָבִים אֶרְפָּה מְשׁוּבֹתֵיכֶם. וְאֵין מִי שֶׁיַּרְכִּין אָזְנָיו. הַתּוֹרָה מַכְרִיזָה לִפְנֵיהֶם, וְאֵין מִי שֶׁיַּשְׁגִּיחַ.</p>\n<p>בֹּא רְאֵה, בֶּן אָדָם הוֹלֵךְ בָּעוֹלָם הַזֶּה וְחוֹשֵׁב שֶׁשֶּׁלּוֹ הוּא תָּמִיד וְיִשָּׁאֵר בְּתוֹכוֹ לְדוֹרֵי דוֹרוֹת. עַד שֶׁהוּא הוֹלֵךְ בָּעוֹלָם, נוֹתְנִים אוֹתוֹ בְּקוֹלָר. עַד שֶׁהוּא יוֹשֵׁב, דָּנִים אוֹתוֹ בְּמוֹשַׁב הַדַּיָּנִים עִם שְׁאָר בְּנֵי הַדִּין. אִם נִמְצָא לוֹ סָנֵגוֹר - הֲרֵי נִצּוֹל מֵהַדִּין. זֶהוּ שֶׁכָּתוּב (איוב לג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ וַיְחֻנֶּנּוּ וַיֹּאמֶר וְגוֹ'. מִי הוּא הַסָּנֵגוֹר? אֵלֶּה מַעֲשִׂים כְּשֵׁרִים שֶׁעוֹמְדִים עַל הָאָדָם בְּשָׁעָה שֶׁמִּצְטָרֵךְ לָהֶם.</p>\n<p>וְאִם לֹא יִמָּצֵא עָלָיו סָנֵגוֹר - הֲרֵי הִתְחַיֵּב מֵהַדִּין לְהִסְתַּלֵּק מֵהָעוֹלָם. בְּאוֹתָהּ שָׁעָה כְּשֶׁשּׁוֹכֵב בְּקוֹלַר הַמֶּלֶךְ, עַד שֶׁמֵּרִים עֵינָיו, רוֹאֶה שֶׁבָּאִים אֵלָיו שְׁנַיִם שֶׁכּוֹתְבִים לְפָנָיו כָּל מַה שֶּׁעָשָׂה בָּעוֹלָם הַזֶּה, וְכָל מַה שֶּׁהוֹצִיא מִפִּיו, וְנוֹתֵן דִּין (חשבון) עַל הַכֹּל וְכוֹתְבִים לְפָנָיו. זֶהוּ שֶׁכָּתוּב (עמוס ד) כִּי הִנֵּה יוֹצֵר הָרִים וּבֹרֵא רוּחַ וּמַגִּיד לְאָדָם מַה שֵּׂחוֹ וְגוֹ'. וְהוּא מוֹדֶה עֲלֵיהֶם.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתוֹ מַעֲשֶׂה שֶׁעָשָׂה, עוֹלֶה וְעוֹמֵד עָלָיו לְהָעִיד בּוֹ, וְעוֹמְדִים לְהָעִיד עָלָיו, וְכֻלָּם יוֹרְדִים וְנִרְשָׁמִים לְפָנָיו וְעוֹמְדִים לְפָנָיו, וְלֹא עוֹבְרִים מִמֶּנּוּ עַד שָׁעָה שֶׁנִּדּוֹן בָּהֶם בְּאוֹתוֹ עוֹלָם. בּא רְאֵה, כָּל אוֹתָם דְּבָרִים שֶׁעָשָׂה בֶּן אָדָם בָּעוֹלָם הַזֶּה, כֻּלָּם זְמִינִים וְעוֹמְדִים לְהָעִיד בּוֹ, וְלֹא נֶאֶבְדוּ מִמֶּנּוּ. וּבְשָׁעָה שֶׁמּוֹצִיאִים אוֹתוֹ לַקֶּבֶר, כֻּלָּם מִזְדַּמְּנִים וְהוֹלְכִים לְפָנָיו. וּשְׁלֹשָׁה כָרוֹזִים מַכְרִיזִים., אֶחָד לְפָנָיו, וְאֶחָד מִימִינוֹ, וְאֶחָד מִשְּׂמֹאלוֹ, וְאוֹמְרִים: זֶה פְּלוֹנִי שֶׁמָּרַד בְּרִבּוֹנוֹ., מָרַד לְמַעְלָה, מָרַד לְמַטָּה, מָרַד בַּתּוֹרָה, מָרַד בְּמִצְווֹתָיו. רְאוּ מַעֲשָׂיו! רְאוּ דְבָרָיו! טוֹב לוֹ שֶׁלֹּא נִבְרָא!</p>\n<p>עֵד שֶׁמַּגִּיעַ לַקֶּבֶר, כָּל הַמֵּתִים רוֹגְזִים עָלָיו מִמְּקוֹמָם וְאוֹמְרִים: אוֹי אוֹי שֶׁזֶּה נִקְבָּר בְּתוֹכֵנוּ! מַעֲשָׂיו וּדְבָרָיו מַקְדִּימִים וְנִכְנָסִים לַקֶּבֶר, וְעוֹמְדִים עַל אוֹתוֹ גּוּף, וְרוּחוֹ הוֹלֶכֶת וְשָׁטָה וּמִתְאַבֶּלֶת עַל הַגּוּף. כֵּיוָן שֶׁהָאָדָם נִטְמָן בְּבֵית הַקְּבָרוֹת, דּוּמָ\"ה מַקְדִּים וְיוֹצֵא תַּחַת יָדָיו שְׁלֹשָׁה בָּתֵּי דִינִים שֶׁמְּמֻנִּים עַל דִּין הַקֶּבֶר, וּשְׁלֹשָׁה שַׁרְבִיטֵי אֵשׁ בִּידֵיהֶם, וְדָנִים רוּחַ וָנֶפֶשׁ כְּאֶחָד. אוֹי עַל אוֹתוֹ הַדִּין! אוֹי עַל מַעֲשָׂיו!</p>\n<p>בְּשָׁעָה שֶׁהוּא תָּפוּס בְּקוֹלַר הַמֶּלֶךְ וְנִדּוֹן דִּינוֹ וְנִשְׁלָם, שֶׁלֹּא נִמְצָא עָלָיו סָנֵגוֹר, וְשׁוֹטֵר הַמֶּלֶךְ נוֹחֵת, וְעוֹמֵד לְפָנָיו לְרַגְלָיו, וְחֶרֶב שְׁנוּנָה אַחַת בְּיָדוֹ.</p>\n<p>מֵרִים הָאִישׁ אֶת עֵינָיו, וְרוֹאֶה כָּתְלֵי הַבַּיִת לוֹהֲטִים בְּאֵשׁ (הזיו) מִמֶּנּוּ. וּבֵין כָּךְ רוֹאֶה אוֹתוֹ לְפָנָיו כֻּלּוֹ מָלֵא עֵינַיִם, לְבוּשׁוֹ אֵשׁ לוֹהֵט לִפְנֵי הָאָדָם. כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי כַּמָּה בְּנֵי אָדָם רָאוּ מַלְאָךְ בַּשּׁוּק וְעָמְדוּ לְפָנָיו, וּשְׁאָר בְּנֵי אָדָם לֹא רָאוּ אוֹתוֹ.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ', אֵיךְ יָכוֹל לְהֵרָאוֹת בָּאָרֶץ? אֶלָּא דָּבָר זֶה כָּךְ בֵּאֲרוּהוּ: שֶׁכֵּיוָן שֶׁיּוֹרֵד מַלְאָךְ לָאָרֶץ, מִתְלַבֵּשׁ בְּגוּף, וְנִרְאֶה לְמִי שֶׁנִּרְאֶה בְּאוֹתוֹ לְבוּשׁ שֶׁהוּא לָבוּשׁ בּוֹ. וְאִם לֹא, לֹא יָכוֹל הָעוֹלָם לְסָבְלוֹ וּלְהֵרָאוֹת בּוֹ. כָּל שֶׁכֵּן וְכָל שֶׁכֵּן זֶה שֶׁכָּל בְּנֵי הָעוֹלָם צְרִיכִים אוֹתוֹ.</p>\n<p>שָׁלֹש טִפּוֹת בְּחַרְבּוֹ, וַהֲרֵי בֵּאֲרוּהוּ הַחֲבֵרִים. כֵּיוָן שֶׁרוֹאֵהוּ, מִזְדַּעֲזֵעַ כָּל גּוּפוֹ וְרוּחוֹ, וְלִבּוֹ לֹא שׁוֹכֵךְ, מִשּׁוּם שֶׁהוּא הַמֶּלֶךְ שֶׁל כָּל הַגּוּף. וְרוּחוֹ הוֹלֶכֶת בְּכָל אֵיבְרֵי הַגּוּף, וְנִפְרֶדֶת מֵהֶם, כְּמוֹ בֶּן אָדָם שֶׁנִּפְרָד מֵחֲבֵרוֹ לָלֶכֶת לְמָקוֹם אַחֵר. אָז הוּא אוֹמֵר אוֹי עַל מַה שֶּׁעָשָׂה - וְלֹא עוֹזֵר לוֹ, אֶלָּא אִם הִקְדִּים רְפוּאַת הַתְּשׁוּבָה עַד שֶׁלֹּא הִגִּיעָה אוֹתָהּ שָׁעָה.</p>\n<p>פּוֹחֵד אוֹתוֹ הָאִישׁ וְרוֹצֶה לְהִסְתַּתֵּר וְלֹא יָכוֹל. כֵּיוָן שֶׁרוֹאֶה שֶׁאֵינוֹ יָכוֹל, הוּא פּוֹתֵחַ עֵינָיו, וְיֵשׁ לוֹ לְהִסְתַּכֵּל בּוֹ, וּמִסְתַּכֵּל בּוֹ בְּעֵינַיִם פְּקוּחוֹת. וְאָז הוּא מוֹסֵר עַצְמוֹ וְנַפְשׁוֹ. וְאוֹתָהּ שָׁעָה הוּא זְמַן דִּין הַגָּדוֹל שֶׁהָאָדָם נִדּוֹן בּוֹ בָּעוֹלָם הַזֶּה, וְאָז הָרוּחַ הוֹלֶכֶת בְּכָל הָאֵיבָרִים שֶׁל הַגּוּף וְנִפְרֶדֶת מֵהֶם, וּמְשׁוֹטֶטֶת בְּכָל הָאֵיבָרִים וּמִזְדַּעֲזַעַת לְכָל הַצְּדָדִים, וְכָל אֵיבְרֵי הַגּוּף כֻּלָּם מִזְדַּעְזְעִים.</p>\n<p>כְּשֶׁמַּגִּיעָה הָרוּחַ לְכָל אֵיבָר וְאֵיבָר וְנִפְרֶדֶת מִמֶּנּוּ, נוֹפֶלֶת זֵיעָה עַל אוֹתוֹ אֵיבָר, וְהָרוּחַ מִסְתַּלֶּקֶת מִמֶּנּוּ, וּמִיָּד מֵת אוֹתוֹ אֵיבָר, וְכֵן בְּכֻלָּם.</p>\n<p>כֵּיוָן שֶׁמַּגִּיעָה הָרוּחַ לָצֵאת, שֶׁהֲרֵי נִפְרְדָה מִכָּל הַגּוּף, אָז הַשְּׁכִינָה עוֹמֶדֶת עָלָיו, וּמִיָּד פּוֹרַחַת מֵהַגּוּף. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּדְבָּק בָּהּ! אוֹי לְאוֹתָם רְשָׁעִים שֶׁרְחוֹקִים מִמֶּנָּה וְלֹא מִתְדַּבְּקִים בָּהּ!</p>\n<p>וְכַמָּה בָּתֵּי דִינִים עוֹבֵר הָאִישׁ כְּשֶׁיּוֹצֵא מֵהָעוֹלָם הַזֶּה? אֶחָד - אוֹתוֹ דִּין עֶלְיוֹן שֶׁאָמַרְנוּ כְּשֶׁיּוֹצֵאת הָרוּחַ מֵהַגּוּף. וְאֶחָד דִּין, כְּשֶׁמַּעֲשָׂיו וּדְבָרָיו הוֹלְכִים לְפָנָיו וְהַכָּרוֹזִים מַכְרִיזִים עָלָיו. וְאֶחָד דִּין כְּשֶׁנִּכְנָס לַקֶּבֶר. וְאֶחָד דִּין הַקֶּבֶר. וְאֶחָד דִּין הַתּוֹלַעַת. וְאֶחָד דִּין הַגֵּיהִנֹּם. וְאֶחָד דִּין הָרוּחַ שֶׁהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם וְלֹא מוֹצֵאת מָקוֹם עַד שֶׁיִּשְׁתַּלְּמוּ מַעֲשָׂיו. וַדַּאי שִׁבְעָה עִדָּנִים יַחְלְפוּ עָלָיו. בִּגְלַל זֶה צָרִיךְ הָאָדָם כְּשֶׁהוּא נִמְצָא בָּעוֹלָם הַזֶּה לִירָא מֵרִבּוֹנוֹ וּלְהִסְתַּכֵּל בְּכָל יוֹם וָיוֹם בְּמַעֲשָׂיו, וְיָשׁוּב מֵהֶם לִפְנֵי רִבּוֹנוֹ.</p>\n<p>כְּשֶׁהִסְתַּכֵּל דָּוִד הַמֶּלֶךְ בְּאוֹתָם דִּינֵי הָאָדָם כְּשֶׁמִּסְתַּלֵּק מֵהָעוֹלָם הַזֶּה, הִקְדִּים וְאָמַר, (תהלים קג) בָּרְכִי נַפְשִׁי אֶת ה', עַד שֶׁלֹּא תֵצֵא מֵהָעוֹלָם, כָּעֵת שֶׁאַתְּ נִמְצֵאת עִם הַגּוּף. וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ, אַתֶּם הָאֵיבָרִים שֶׁמִּשְׁתַּתְּפִים בָּרוּחַ, כָּעֵת שֶׁהִיא נִמְצֵאת אִתְּכֶם, הַקְדִּימוּ לְבָרֵךְ אֶת הַשֵּׁם הַקָּדוֹשׁ עַד שֶׁלֹּא יַגִּיעַ זְמַן שֶׁלֹּא תוּכְלוּ לְבָרְכוֹ וּלְהוֹדוֹת עֲלֵיכֶם.</p>"],[9522012283,"<p>בֹּא רְאֵה, אִישׁ כִּי יַפְלִא לִנְדֹּר נֶדֶר. נָזִיר שֶׁהִקְדִּים בָּעוֹלָם הַזֶּה לְהִתְקַדֵּשׁ בִּקְדֻשַּׁת רִבּוֹנוֹ, מִיַּיִן וְשֵׁכָר יַזִּיר חֹמֶץ יַיִן וְגוֹ'. כָּאן יֵשׁ לְהִסְתַּכֵּל, כֵּיוָן שֶׁאָסוּר לוֹ יַיִן - עֲנָבִים לָמָּה? שֶׁהֲרֵי בַּכֹּהֲנִים כָּתוּב (ויקרא י) יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ וְגוֹ'. יָכוֹל גַּם עֲנָבִים? לֹא. בַּעֲנָבִים מֻתָּר. כָּאן לַנָּזִיר, מָה הַטַּעַם אָסוּר לוֹ עֲנָבִים?</p>\n<p>אֶלָּא מַעֲשֶׂה זֶה וְדָבָר זֶה סוֹד עֶלְיוֹן הוּא לְהִפָּרֵד מֵהַדִּין בַּכֹּל. וַהֲרֵי יָדוּעַ אוֹתוֹ עֵץ שֶׁחָטָא בּוֹ אָדָם הָרִאשׁוֹן, עֲנָבִים הָיוּ. וְזֶהוּ סוֹד הַדָּבָר, שֶׁהֲרֵי יַיִן וְשֵׁכָר וַעֲנָבִים בְּצַד אֶחָד נֶאֶחְזוּ. יַיִן לְמַעְלָה, וּפֵרְשׁוּהָ. שֵׁכָר לִשְׂמֹאל, שֶׁהֲרֵי שֵׁכָר יוֹצֵא מִיַּיִן. עֲנָבִים, שֶׁכּוֹנְסִים כֻּלָּם אֲלֵיהֶם, וְזֶהוּ עֵץ שֶׁחָטָא בּוֹ אָדָם הָרִאשׁוֹן. בִּגְלַל זֶה הַכֹּל נֶאֱחָז בְּצַד אֶחָד. וְאִם תֹּאמַר שֶׁנָּזִיר זֶה עָזַב אֱמוּנָה עֶלְיוֹנָה - (כלום) לֹא כָּךְ, אֶלָּא לֹא נִרְאָה בּוֹ מַעֲשֶׂה מִצַּד שְׂמֹאל כְּלוּם.</p>"],[9522012284,"<p>בֹּא רְאֵה, שֶׁהֲרֵי לָמַדְנוּ מִסִּפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, וְכָךְ הוּא: כָּתוּב גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ, צָרִיךְ שֶׁיִּתְרַבֶּה שְׂעַר רֹאשׁוֹ וּזְקָנוֹ, וְיִפְרשׁ מִיַּיִן וְשֵׁכָר וַעֲנָבִים, מִשּׁוּם שֶׁכֻּלָּם צַד שְׂמֹאל, וְהַשְּׂעָרוֹת לֹא תְלוּיוֹת. יַיִן - הָאֵם הָעֶלְיוֹנָה (בינה). שֵׁכָר - צַד שֶׁאֲחוּזִים בּוֹ לְוִיִּם, וְיוֹצֵא מִיַּיִן עֶלְיוֹן, וְלֹא תָלוּי הַשֵּׂעָר. וּמִשּׁוּם כָּךְ עוֹלִים הַלְוִיִּם לְאוֹתוֹ מָקוֹם, צָרִיךְ לְהַעֲבִיר כָּל שְׂעָרָם, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ח) וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם.</p>\n<p>עָנָבִים - הָאֵם הַתַּחְתּוֹנָה, שֶׁכּוֹנֶסֶת יַיִן וְשֵׁכָר לְתוֹכָהּ, וְעַל כָּךְ נִפְרָד מִכָּל צַד שְׂמֹאל, שֶׁלֹּא לְהַרְאוֹת מַעֲשֶׂה שֶׁלָּהֶם אֵלָיו. עֲנָבִים זֶה לֹא תוֹלֶה שֵׂעָר וְזָקָן, שֶׁהֲרֵי הַנְּקֵבָה צְרִיכָה לְסַפֵּר שְׂעָרָהּ כְּשֶׁבָּאָה לְהִזְדַּוֵּג בְּזָכָר, וַהֲרֵי זָקָן לֹא נִמְצָא בָּהּ. בִּגְלַל זֶה הוּא תּוֹלֶה שְׂעַר הָרֹאשׁ וְהַזָּקָן, וְסוֹד הַדָּבָר - נְזִיר אֱלֹהִים (שופטים יג) נִקְרָא, וְלֹא נְזִיר ה', פָּרוּשׁ מֵהַדִּין כֻּלּוֹ.</p>"],[9522012285,"<p>בֹּא רְאֵה, עַל זֶה כָּתוּב, וְכִפֶּר עָלָיו מֵאֲשֶׁר חָטָא עַל הַנָּפֶשׁ וְגוֹ'. עַל נַפְשׁוֹ לֹא כָתוּב, אֶלָּא עַל הַנָּפֶשׁ סְתָם. וּמַהוּ? זֶה עֲנָבִים, שֶׁנִּקְרָא נֶפֶשׁ. וְלָכֵן כָּתוּב חָטָא, מִשּׁוּם שֶׁצַּד שֶׁלּוֹ יַיִן וְשֵׁכָר הוּא, וְגָרַע מִמֶּנּוּ מְקוֹם דִּין. חָטָא, מַה זֶּה חָטָא? אֶלָּא גָּרַע דִּין הַנֶּפֶשׁ.</p>\n<p>אִם כָּךְ, לָמָּה וְכִפֶּר עָלָיו? מִשּׁוּם שֶׁעַכְשָׁו בָּא לְהִתְחַבֵּר אִתָּם, וְלֹא מְקַבְּלִים אוֹתוֹ מְקוֹמוֹת אֵלֶּה, עַד שֶׁיִּמָּלֵךְ בַּכֹּהֵן וִיכַפֵּר עָלָיו. מִשּׁוּם שֶׁהוּא זָרַק אוֹתָם הַחוּצָה בַּהַתְחָלָה, כֵּיוָן שֶׁכָּעֵת בָּא אֲלֵיהֶם, צָרִיךְ לְהִתְחַבֵּר תִּקּוּן שֶׁל כַּפָּרָה וִיקַבְּלוּהוּ, וְזֶהוּ סוֹד הַדָּבָר. (ודאי בכל).</p>\n<p>וְאִם תֹּאמַר, שִׁמְשׁוֹן נְזִיר אֱלֹהִים הָיָה, לָמָּה נֶעֱנַשׁ? אֶלָּא נָאֶה הוּא הַדָּבָר, שֶׁבָּעַל בַּת אֵל נֵכָר, וְהָיָה לוֹ לְהִתְחַבֵּר בְּשֶׁלּוֹ, בְּמַה שֶּׁרָאוּי לוֹ. וְהוּא, שֶׁהָיָה קָדוֹשׁ, עֵרַב אוֹתָהּ קְדֻשָּׁה בְּבַת אֵל נֵכָר, וְעָזַב מְקוֹמוֹ שֶׁרָאוּי לְאוֹתָהּ קְדֻשָּׁה, וְלָכֵן נֶעֱנַשׁ.</p>\n<p>וְיִשִׁ מִי שֶׁאוֹמֵר, שֶׁאֵין לוֹ חֵלֶק בְּאוֹתוֹ עוֹלָם. מָה הַטַּעַם? מִשּׁוּם שֶׁאָמַר (שופטים טז) תָּמֹת נַפְשִׁי עִם פְּלִשְׁתִּים, וּמָסַר חֶלְקוֹ בְּחֵלֶק פְּלִשְׁתִּים, שֶׁתָּמוּת נַפְשׁוֹ אִתָּם בָּעוֹלָם הַהוּא. כָּךְ הָיוּ מַכְרִיזִים עַל הַנָּזִיר: לֵךְ לֵךְ, אוֹמְרִים לְנָזִיר, סָבִיב סָבִיב, וְלַכֶּרֶם אַל תִקְרַב. וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>לְוִיִּם, מַה כָּתוּב בָּהֶם? (במדבר ח) וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם הַזֵּה עֲלֵיהֶם מֵי חַטָּאת וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם. כֵּיוָן שֶׁהֶעֱבִירוּ שֵׂעָר וְעָשׂוּ כָּל זֶה, אָז נִקְרָאִים הַלְוִיִּם טָהוֹר, וְלֹא קָדוֹשׁ. אֲבָל נָזִיר הַזֶּה, מִשּׁוּם שֶׁנִּפְרָד מִצַּד זֶה, נִקְרָא קָדוֹשׁ, וְלֹא טָהוֹר. בִּגְלַל כָּךְ כָּתוּב, כָּל יְמֵי נֶדֶר נִזְרוֹ וְגוֹ' אֲשֶׁר יַזִּיר לַה' קָדשׁ יִהְיֶה וְגוֹ'.</p>\n<p>גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ, מִשּׁוּם זֶה שֶׁכָּתוּב (דניאל ז) וּשְׂעַר רֹאשׁוֹ כְּצֶמֶר נָקִי, שֶׁבָּזֶה דּוֹמֶה לַגָּוֶן הָעֶלְיוֹן. אָמַר רַבִּי יְהוּדָה בַּר רַב, בַּשְּׂעָרוֹת מַמָּשׁ נוֹדָע שֶׁהוּא קָדוֹשׁ, שֶׁכָּתוּב (שיר השירים ה) ק1ְוֵצּוֹתָיו תַּלְתַּלִּים.</p>\n<p>שָׁנָה רַבִּי שִׁמְעוֹן, אִלְמָלֵא יָדְעוּ בְּנֵי אָדָם מָה אוֹמְרִים בַּשֵּׂעָר הַזֶּה וּבְסוֹדוֹ (באלו השערות ובאלו הדברים) כְּמוֹ שֶׁהוּא בְּסוֹד הַסּוֹדוֹת, יִוָּדְעוּ לְרִבּוֹנָם בְּחָכְמָה עֶלְיוֹנָה. עַד כָּאן סוֹדוֹת הַתּוֹרָה. מִכָּאן וָהָלְאָה כִּתְרֵי (סתרי) תוֹרָה, (ישעיה כג) סַחְרָהּ וְאֶתְנַנָּהּ קֹדֶשׁ לַה'.</p>"],[9522012286,"<p>דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ וְגוֹ'. רַבִּי יִצְחָק פָּתַח וְאָמַר, (תהלים קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו וְצִדְקָתוֹ לִבְנֵי בָנִים. כַּמָּה גְדוֹלָה הַיִּרְאָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבִּכְלַל הַיִּרְאָה עֲנָוָה, וּבִכְלַל הָעֲנָוָה חֲסִידוּת. נִמְצָא שֶׁכָּל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת חֵטְא, יֶשְׁנוֹ בְכֻלָּן. וּמִי שֶׁאֵינוֹ יְרֵא שָׁמַיִם, אֵין בּוֹ לֹא עֲנָוָה וְלֹא חֲסִידוּת.</p>\n<p>לָמַדְנוּ, מִי שֶׁיָּצָא מִן הַיִּרְאָה וְנִתְלַבֵּשׁ בַּעֲנָוָה - עֲנָוָה עָדִיף, וְנִכְלָל בְּכֻלָּם. זֶהוּ שֶׁכָּתוּב (משלי כח) עֵקֶב עֲנָוָה יִרְאַת ה'. כָּל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת שָׁמַיִם, זוֹכֶה לַעֲנָוָה. כָּל מִי שֶׁיֵּשׁ בּוֹ עֲנָוָה, זוֹכֶה לַחֲסִידוּת. וְכָל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת שָׁמַיִם, זוֹכֶה לְכֻלָּם. לַעֲנָוָה - שֶׁכָּתוּב עֵקֶב עֲנָוָה יִרְאַת ה'. לַחֲסִידוּת - שֶׁכָּתוּב (תהלים קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו.</p>\n<p>לָמַדְנוּ, כָּל אָדָם שֶׁיֵּשׁ בּוֹ חֲסִידוּת, נִקְרָא מַלְאַךְ ה' צְבָאוֹת. זֶהוּ שֶׁכָּתוּב (מלאכי ב) כִּי שִׂפְתֵי כֹהֵן יִשְׁמְרוּ דַעַת וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ כִּי מַלְאַךְ ה' צְבָאוֹת הוּא. מִפְּנֵי מָה זָכָה כֹּהֵן לְהִקָּרֵא מַלְאַךְ ה' צְבָאוֹת? אָמַר רַבִּי יְהוּדָה, מַה מַּלְאַךְ ה' צְבָאוֹת כֹּהֵן לְמַעְלָה, אַף כֹּהֵן מַלְאַךְ ה' צְבָאוֹת לְמַטָּה.</p>\n<p>וּמִי הוּא מַלְאַךְ ה' צְבָאוֹת לְמַעְלָה? (דניאל יב) זֶה מִיכָאֵ\"ל הַשַּׂר הַגָּדוֹל, שֶׁבָּא מֵחֶסֶד שֶׁל מַעְלָה, וְהוּא כֹּהֵן גָּדוֹל שֶׁל מַעְלָה. כִּבְיָכוֹל כֹּהֵן גָּדוֹל שֶׁלְּמַטָּה נִקְרָא מַלְאַךְ ה' צְבָאוֹת, מִשּׁוּם שֶׁבָּא מִצַּד הַחֶסֶד. מַהוּ חֶסֶד? רַחֲמִים תּוֹךְ רַחֲמִים. וּמִשּׁוּם כָּךְ כֹּהֵן לֹא נִמְצָא מִצַּד הַדִּין. מָה הַטַּעַם זָכָה כֹּהֵן לְחֶסֶד? בִּגְלַל הַיִּרְאָה. זֶהוּ שֶׁכָּתוּב (תהלים קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו.</p>\n<p>מַהוּ עוֹלָם וְעוֹלָם? אָמַר רַבִּי יִצְחָק, כְּמוֹ שֶׁהֻתְקַן בַּחֶדֶר הַקָּדוֹשׁ, עוֹלָם אֶחָד, וְעוֹלָם שְׁנַיִם. אָמַר רַבִּי חִיָּיא, אִם כָּךְ, מִן הָעוֹלָם וְעַד הָעוֹלָם צָרִיךְ לוֹ לִהְיוֹת! אָמַר לוֹ, שְׁנֵי עוֹלָמוֹת הֵם, וְחָזְרוּ לִהְיוֹת אֶחָד. אָמַר רַבִּי אֶלְעָזָר לְרַבִּי יִצְחָק, עַד מָתַי תִּסְתֹּם דְּבָרֶיךְ? מִן הָעוֹלָם וְעַד הָעוֹלָם כְּלָל שֶׁל סוֹד עֶלְיוֹן, אָדָם שֶׁלְּמַעְלָה וְאָדָם שֶׁלְּמַטָּה, וְהַיְנוּ עוֹלָם וְעוֹלָם. וְכָתוּב יְמֵי עוֹלָם, וְכָתוּב שְׁנוֹת עוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ בַּחֶדֶר הַקָּדוֹשׁ הָעֶלְיוֹן.</p>\n<p>עַל יְרֵאָיו - שֶׁכָּל מִי שֶׁהוּא יְרֵא חֵטְא, נִקְרָא אָדָם. מָתַי? אָמַר רַבִּי אֶלְעָזָר, שֶׁיֵּשׁ בּוֹ יִרְאָה, עֲנָוָה, חֲסִידוּת, כְּלָל שֶׁל הַכֹּל.</p>\n<p>אָמַר רַבִּי יְהוּדָה, וַהֲרֵי שָׁנִינוּ, אָדָם כְּלַל זָכָר וּנְקֵבָה. אָמַר לוֹ, וַדַּאי כָּךְ זֶה בִּכְלָל שֶׁל אָדָם, שֶׁמִּי שֶׁמִּתְחַבֵּר זָכָר וּנְקֵבָה, נִקְרָא אָדָם, וְאָז יְרֵא חֵטְא. וְלֹא עוֹד, אֶלָּא שֶׁשּׁוֹרָה בּוֹ עֲנָוָה. וְלֹא עוֹד, אֶלָּא שֶׁשּׁוֹרֶה בּוֹ חֶסֶד. וּמִי שֶׁלֹּא נִמְצָא זָכָר וּנְקֵבָה, אֵין בּוֹ לֹא יִרְאָה וְלֹא עֲנָוָה וְלֹא חֲסִידוּת. וּמִשּׁוּם כָּךְ נִקְרָא אָדָם כְּלַל הַכֹּל. וְכֵיוָן שֶׁנִּקְרָא אָדָם, שׁוֹרֶה בּוֹ חֶסֶד, שֶׁכָּתוּב (שם פט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה וְגוֹ'. וְלֹא יָכוֹל לְהִבָּנוֹת אִם לֹא נִמְצָא זָכָר וּנְקֵבָה.</p>\n<p>וְכָתוּב (תהלים קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו. יְרֵאָיו - כְּלָל שֶׁל אָדָם. דָּבָר אַחֵר וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם - אֵלֶּה אוֹתָם כֹּהֲנִים שֶׁבָּאוּ מִצַּד הַחֶסֶד, וְיָרְשׁוּ יְרֻשָּׁה זוֹ שֶׁיָּרְדָה מֵעוֹלָם שֶׁלְּמַעְלָה לָעוֹלָם שֶׁלְּמַטָּה. עַל יְרֵאָיו - כֹּהֲנִים שֶׁלְּמַטָּה, שֶׁכָּתוּב (ויקרא טז) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ, לְהִתְכַּלֵּל בִּכְלָל שֶׁל אָדָם. (שם) וְצִדְקָתוֹ לִבְנֵי בָנִים, מִשּׁוּם שֶׁזָּכָה לִבְנֵי בָנִים. אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, מַהוּ וְצִדְקָתוֹ? וְחַסְדּוֹ הָיָה צָרִיךְ לוֹ לִהְיוֹת!</p>"],[9522012287,"<p>אָמַר רַבִּי אֶלְעָזָר, הַיְנוּ סוֹד שֶׁשָּׁנִינוּ בְּזֹּאת, (בראשית ב) כִּי מֵאִישׁ לֻקֳחָה זֹּאת. וְכָתוּב לְזֹּאת יִקָּרֵא אִשָּׁה. וְזֹּאת נִכְלְלָה בָּאִישׁ, שֶׁהַיְנוּ חֶסֶד, וְזֹּאת נְקֵבָה. חֶסֶד זָכָר. וּמִשּׁוּם כָּךְ זָכָר שֶׁבָּא מִצַּד הַלָּבָן הַזֶּה, נִקְרָא חֶסֶד. וְזֹּאת נִקְרֵאת צֶדֶק, שֶׁבָּאָה מִצַּד אָדם, וּמִשּׁוּם כָּךְ נִקְרֵאת אִשָּׁה. וְהַיְנוּ מַה שֶּׁכָּתוּב וְצִדְקָתוֹ. מַה זֶּה וְצִדְקָתוֹ? צִדְקָתוֹ שֶׁל חֶסֶד, בַּת זוּגוֹ, לְהִתְבַּשֵּׂם זֶה בָּזֶה. וּמִשּׁוּם כָּךְ לָמַדְנוּ, כָּל כֹּהֵן שֶׁאֵין לוֹ בַּת זוּג, אָסוּר בָּעֲבוֹדָה, שֶׁכָּתוּב וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, מִשּׁוּם שֶׁאֵין שְׁכִינָה שׁוֹרָה בְּמִי שֶׁלֹּא נָשָׂא אִשָּׁה, וְכֹהֲנִים צְרִיכִים יוֹתֵר מִכָּל שְׁאָר הָעָם לְהַשְׁרוֹת בָּהֶם שְׁכִינָה. וְכֵיוָן שֶׁשּׁוֹרָה בָהֶם שְׁכִינָה, שׁוֹרֶה בָהֶם חֶסֶד, וְנִקְרָאִים חֲסִידִים, וּצְרִיכִים לְבָרֵךְ אֶת הָעָם. זֶהוּ שֶׁכָּתוּב (תהלים קמה) וַחֲסִידֶיךְ יְבָרְכוּכָה. וְכָתוּב (דברים לג) תֻּמֶּיךְ וְאוּרֶיךְ לְאִישׁ חֲסִידֶךְ. וּמִשּׁוּם שֶׁכֹּהֵן נִקְרָא חָסִיד, צָרִיךְ לְבָרֵךְ. וּמִשּׁוּם כָּךְ כָּתוּב, דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁנִּקְרָאִים חֲסִידִים, וְכָתוּב וַחֲסִידֶיךְ יְבָרְכוּכָה.</p>"]]});
